INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "理论家是指系统掌握并阐述某种理论、学说的人。", "primary_collocate": null, "pronunciation": "lǐ lùn jiā", "ipa": "/li˨˩ lwən˥˩ tɕja˥/", "syllable_count": 3, "sentences": [{"text": "这位理论家在台上主讲。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位理论家写了一本新书。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的理论家。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理论家认为，语言会影响思想。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位理论家提出了新的看法。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学生去听理论家的讲座。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理论家需要读很多书。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位理论家研究音乐的历史。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理论家和作曲家常常讨论这个问题。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位理论家的观点影响了许多人。", "target_word": "理论家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "理论", "label": "复合"}], "register": "书面", "sense_fingerprint": "系统掌握并阐述某种理论、学说的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f432ec0-4827-4655-ae2d-bca2ba58dc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理论家", "is_correct": true, "explanation": "正确：理论家是人，能在台上主讲，与句意相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是物件，不能在台上主讲，“这位”也只指人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是人，不能在台上主讲。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有讲述能力，不能在台上主讲。"}], "explanations": {"理论家": "正确：理论家是人，能在台上主讲，与句意相符。", "乐器": "语义：乐器是物件，不能在台上主讲，“这位”也只指人。", "窗户": "语义：窗户不是人，不能在台上主讲。", "石头": "语义：石头没有讲述能力，不能在台上主讲。"}, "sentence_index": 0, "correct_answer": "理论家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家的电脑坏了，请了一位理论家来修。", "explanation": "这里应该用〈专家〉。修电脑需要懂技术的人，“理论家”指系统阐述理论的人。"}, {"text": "这位理论家每天早上带队训练，球员都很努力。", "explanation": "这里应该用〈教练〉。带队训练是教练的工作，“理论家”不做这件事。"}, {"text": "这桌菜是一位理论家做的，很好吃。", "explanation": "这里应该用〈厨师〉。做菜要靠厨师，“理论家”指研究理论的人，不做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理论家", "is_correct": true, "explanation": "正确：理论家需要广泛阅读，“需要读很多书”的主语正是人，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会读书，“需要读很多书”只能用于人。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木没有阅读能力，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "配价：“需要读”要求有阅读能力的主语，窗帘不能作主语。"}], "explanations": {"理论家": "正确：理论家需要广泛阅读，“需要读很多书”的主语正是人，符合句意。", "汽车": "语义：汽车不会读书，“需要读很多书”只能用于人。", "树木": "语义：树木没有阅读能力，句意不通。", "窗帘": "配价：“需要读”要求有阅读能力的主语，窗帘不能作主语。"}, "sentence_index": 6, "correct_answer": "理论家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班来了一只理论家，很有意思。", "explanation": "量词错误：〈只〉多用于动物，指人要用〈位〉，“一只理论家”不成立。"}, {"text": "这条理论家是我们学校请来的。", "explanation": "量词错误：〈条〉用于长条形事物，指人的理论家应用〈位〉。"}, {"text": "我们学校请来了一棵理论家。", "explanation": "量词错误：〈棵〉用于树木和植物，指人的理论家应用〈位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位理论家们在大学教书。", "corrected_sentence": "那位理论家在大学教书。", "error_description": "量词与复数词缀冲突：“那位”是单数量词，不能与“们”同用，应去掉“们”，改为“那位理论家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请了一只理论家来学校演讲。", "corrected_sentence": "我们请了一位理论家来学校演讲。", "error_description": "量词错误：“理论家”指人，应用量词“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc3866cd-50b2-4a65-ad2d-a32933313adb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
