INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐或艺术作品的组织框架，允许灵活演绎", "primary_collocate": null, "pronunciation": "jié gòu", "ipa": "tɕjɛ˧˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这首曲子的结构很自由，演奏者可以改变顺序。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爵士乐的结构给了乐手很多发挥的空间。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的结构很特别，没有明显的中心。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲家只写了曲子的结构，细节让演奏者决定。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首交响乐的结构分为四个部分。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不出这段音乐的结构，它好像没有开头。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇小说的结构很松，读者可以自由理解。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队重新安排了曲子的结构，把结尾放到了开头。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的结构是前奏、两段歌词和尾声。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的结构像一首乐曲，一段接着一段。", "target_word": "结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "結構", "label": "繁体"}, {"form": "结构图", "label": "复合"}], "register": "中性", "sense_fingerprint": "音乐或艺术作品各部分的组织安排与框架", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 前奏 (Zipf 3.1), 两段 (Zipf 3.53), 尾声 (Zipf 3.63)']::text[], '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构", "is_correct": true, "explanation": "“结构”指作品各部分的组织框架，与“演奏者可以改变顺序”相合。"}, {"text": "规范", "is_correct": false, "explanation": "语义：“规范”是约束和标准，与“很自由”矛盾。"}, {"text": "标准", "is_correct": false, "explanation": "语义：“标准”是限定好的要求，不能“很自由”，与句意冲突。"}, {"text": "秩序", "is_correct": false, "explanation": "搭配：“秩序”多与“维持”“良好”搭配，不说“自由的秩序”。"}], "explanations": {"结构": "“结构”指作品各部分的组织框架，与“演奏者可以改变顺序”相合。", "规范": "语义：“规范”是约束和标准，与“很自由”矛盾。", "标准": "语义：“标准”是限定好的要求，不能“很自由”，与句意冲突。", "秩序": "搭配：“秩序”多与“维持”“良好”搭配，不说“自由的秩序”。"}, "sentence_index": 0, "correct_answer": "结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首曲子的结构很快，演奏者很难跟上。", "explanation": "这里应该用〈节奏〉。说快慢用“节奏”，“结构”指作品各部分的组织安排，不说快慢。"}, {"text": "这首曲子的结构很甜，听完让人想吃糖。", "explanation": "这里应该用〈旋律〉。说曲子好听、甜美用“旋律”，“结构”指作品各部分的组织安排，不能说甜。"}, {"text": "我们分析了这首曲子的一朵结构，很有意思。", "explanation": "这里应该用〈种〉。“朵”用于花、云等，不用于结构，结构常用“种”或“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构", "is_correct": true, "explanation": "“结构”指作品各部分的组织，“很松”说的正是组织松散，与句意相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能说“很松”，与小说的组织安排无关。"}, {"text": "标题", "is_correct": false, "explanation": "搭配：“松”不用来形容标题，句中说不通。"}, {"text": "字体", "is_correct": false, "explanation": "体貌：“字体”形容字形的样子，“很松”不合，也与小说的组织无关。"}], "explanations": {"结构": "“结构”指作品各部分的组织，“很松”说的正是组织松散，与句意相合。", "价格": "语义：“价格”指钱数，不能说“很松”，与小说的组织安排无关。", "标题": "搭配：“松”不用来形容标题，句中说不通。", "字体": "体貌：“字体”形容字形的样子，“很松”不合，也与小说的组织无关。"}, "sentence_index": 6, "correct_answer": "结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首结构很清楚，分成了三个部分。", "explanation": "这里应该用〈种〉或〈个〉。“首”是量词，用于诗、歌、曲子，不用于结构。"}, {"text": "这部电影的结构是喜剧。", "explanation": "这里应该用〈体裁〉。说作品属于哪一类用“体裁”，“结构”指各部分的组织安排，不能说它是哪一类。"}, {"text": "这首曲子的结构很响亮，传得很远。", "explanation": "这里应该用〈音量〉。说声音大小用“音量”，“结构”指组织安排，不能说响亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我分析了这首曲子的一只结构。", "corrected_sentence": "我分析了这首曲子的一种结构。", "error_description": "“结构”的量词应用“种”，“只”用于动物或成对的东西，不用于结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部协奏曲的很结构分为三个乐章。", "corrected_sentence": "这部协奏曲的结构分为三个乐章。", "error_description": "“很”只修饰形容词，不能修饰名词“结构”，应说“协奏曲的结构”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
