INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "演奏者指在音乐表演中实际演奏乐器或演唱的人。", "primary_collocate": null, "pronunciation": "yǎn zòu zhě", "ipa": "jɛn˨˩˦ tsou˥˩ tʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "与此同时，约翰·凯奇等先锋派作曲家质疑传统记谱的权威性，发展出图形谱、文字谱乃至机会音乐的开放式结构，强调演奏者的再创造权。", "target_word": "演奏者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "演奏者坐在台上，手里拿着一把小提琴。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演奏者已经弹了三十年钢琴。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演奏者先走上舞台，观众都安静了。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的演奏者不但手快，还要懂得音乐。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首曲子很难，演奏者要练习很长时间。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队里有二十位演奏者，有的拉琴，有的吹号。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众给演奏者送了一大束花。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一首曲子，不同的演奏者会弹出不同的感觉。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位年轻的演奏者是第一次在这里表演。", "target_word": "演奏者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钢琴演奏者", "label": "复合"}], "register": "中性", "sense_fingerprint": "在音乐表演中实际演奏乐器或演唱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者指实际演奏乐器或演唱的人。“强调演奏者的再创造权”指演奏者可以按自己的理解再创作，句意通顺。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，不是能够行使“再创造权”的主体。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“再创造权”要由人来行使，乐器不能成为这种权利的持有者。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆是保存和展示物品的场所，与“演奏”和“再创造”无关。"}], "explanations": {"演奏者": "演奏者指实际演奏乐器或演唱的人。“强调演奏者的再创造权”指演奏者可以按自己的理解再创作，句意通顺。", "乐谱": "语义：乐谱是记录音乐的符号，不是能够行使“再创造权”的主体。", "乐器": "搭配：“再创造权”要由人来行使，乐器不能成为这种权利的持有者。", "博物馆": "语义：博物馆是保存和展示物品的场所，与“演奏”和“再创造”无关。"}, "sentence_index": 0, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影的演奏者都很有名。", "explanation": "这里应该用〈演员〉。演奏者指实际演奏乐器或演唱的人，电影里表演的人应称演员。"}, {"text": "这位演奏者在晚会上负责检票。", "explanation": "这里应该用〈检票员〉。演奏者指演奏乐器或演唱的人，负责检票的是检票员。"}, {"text": "演奏者用指挥棒带领乐队。", "explanation": "这里表达的是〈掌控全队节奏的人〉这一角色，不能用“演奏者”。演奏者指实际演奏乐器或演唱的人，不负责统领全队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演奏者", "is_correct": true, "explanation": "演奏者指实际拉琴、吹号的人，与句中“有的拉琴，有的吹号”呼应。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是听音乐的人，不会拉琴吹号，与“有的拉琴，有的吹号”不符。"}, {"text": "指挥", "is_correct": false, "explanation": "语义：指挥挥动指挥棒，不亲自拉琴吹号，与“有的拉琴，有的吹号”矛盾。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“二十位”是指人的量词，乐器应用“件”或“把”来计量。"}], "explanations": {"演奏者": "演奏者指实际拉琴、吹号的人，与句中“有的拉琴，有的吹号”呼应。", "观众": "语义：观众是听音乐的人，不会拉琴吹号，与“有的拉琴，有的吹号”不符。", "指挥": "语义：指挥挥动指挥棒，不亲自拉琴吹号，与“有的拉琴，有的吹号”矛盾。", "乐器": "搭配：“二十位”是指人的量词，乐器应用“件”或“把”来计量。"}, "sentence_index": 6, "correct_answer": "演奏者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位演奏者把鸽子变没了，观众惊叫起来。", "explanation": "这里应该用〈表演者〉。演奏者专指演奏乐器或演唱的人，变魔术的人不能称演奏者。"}, {"text": "那位演奏者在厨房里做了一桌好菜。", "explanation": "这里应该用〈厨师〉。演奏者指演奏乐器或演唱的人，在厨房做菜的是厨师。"}, {"text": "这部电影的演奏者是李安。", "explanation": "这里应该用〈导演〉。演奏者指表演音乐的人，拍电影的人是导演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只演奏者在台上拉小提琴。", "corrected_sentence": "那位演奏者在台上拉小提琴。", "error_description": "量词错误：“演奏者”指人，量词应用“位”，“只”多用于动物或小件物品。应把“那只”改为“那位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很有名演奏者今晚会来。", "corrected_sentence": "这位很有名的演奏者今晚会来。", "error_description": "修饰语与中心语之间漏了“的”：“很有名”修饰“演奏者”时要加“的”，应为“很有名的演奏者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
