INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电子音乐是指使用电子乐器、电子设备或电脑技术创作和演奏的音乐。", "primary_collocate": null, "pronunciation": "diàn zǐ yīn yuè", "ipa": "tjɛn˥˩ tsɨ˨˩˦ in˥ ɥɛ˥˩", "syllable_count": 4, "sentences": [{"text": "我最喜欢听电子音乐。", "target_word": "电子音乐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位歌手用电脑做电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电子音乐常常用电子乐器演奏。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习怎么创作电子音乐。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的派对上一直放着电子音乐。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子音乐的节奏很快，让大家都想跳舞。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听过很多国家的电子音乐。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个音乐节有很多电子音乐表演。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做电子音乐需要电脑和专门的软件。", "target_word": "电子音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐想把她的电子音乐放到网上。", "target_word": "电子音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一首电子音乐", "label": "量词"}, {"form": "一段电子音乐", "label": "量词"}, {"form": "電子音樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用电子乐器、设备或电脑技术创作演奏的音乐类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是用电子乐器或电脑制作的音乐，可以用“听”来欣赏，句意通顺。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是可以“听”的对象。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“听”的对象应是声音或音乐，电脑不能被“听”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，不能用“听”来欣赏。"}], "explanations": {"电子音乐": "电子音乐是用电子乐器或电脑制作的音乐，可以用“听”来欣赏，句意通顺。", "水果": "语义：水果是食物，不是可以“听”的对象。", "电脑": "搭配：“听”的对象应是声音或音乐，电脑不能被“听”。", "房子": "语义：房子是建筑，不能用“听”来欣赏。"}, "sentence_index": 0, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天睡前读一本电子音乐。", "explanation": "这里应该用〈电子书〉。电子音乐是音乐，不能用来“读”，读的是电子书。"}, {"text": "他用这台电脑修理了一台电子音乐。", "explanation": "这里应该用〈电子产品〉。电子音乐指音乐作品，不是可以修理的设备。"}, {"text": "他用电子音乐弹了一首钢琴曲。", "explanation": "这里应该用〈电子乐器〉。电子音乐是音乐作品，不能用来弹奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电子音乐", "is_correct": true, "explanation": "电子音乐是可以听的音乐，与“听过很多国家的”搭配，句意通顺。"}, {"text": "美食", "is_correct": false, "explanation": "搭配：“听过”的对象应是音乐或声音，美食不能被“听过”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能被“听过”。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是图像或纸质的资料，不能用“听”来接触。"}], "explanations": {"电子音乐": "电子音乐是可以听的音乐，与“听过很多国家的”搭配，句意通顺。", "美食": "搭配：“听过”的对象应是音乐或声音，美食不能被“听过”。", "汽车": "语义：汽车是交通工具，不能被“听过”。", "地图": "语义：地图是图像或纸质的资料，不能用“听”来接触。"}, "sentence_index": 6, "correct_answer": "电子音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上喝一杯电子音乐。", "explanation": "这里应该用〈饮料〉。电子音乐是音乐，不是能喝的东西，喝的是饮料。"}, {"text": "他在手机上玩了一局电子音乐。", "explanation": "这里应该用〈游戏〉。电子音乐是音乐，不是可以“玩一局”的游戏。"}, {"text": "这台电子音乐能录下老师的声音。", "explanation": "这里应该用〈录音机〉。电子音乐是音乐作品，不是能录音的设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只电子音乐很好听。", "corrected_sentence": "这首电子音乐很好听。", "error_description": "量词错误：音乐作品应用“首”，“只”多用于动物或小件物品，应把“这只”改为“这首”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个音乐节上有一场很有名电子音乐表演。", "corrected_sentence": "这个音乐节上有一场很有名的电子音乐表演。", "error_description": "修饰语与中心语之间漏了“的”：“很有名”修饰“电子音乐表演”时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陈旧", "is_correct": true, "explanation": "反义：陈旧指旧的、过时的，与“全新”相对。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：复杂与全新不构成反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：寒冷与全新不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：安静与全新不构成反义关系。"}], "correct_answer": "陈旧", "explanations": {"陈旧": "反义：陈旧指旧的、过时的，与“全新”相对。", "复杂": "无关：复杂与全新不构成反义关系。", "寒冷": "无关：寒冷与全新不构成反义关系。", "安静": "无关：安静与全新不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "旧", "is_correct": true, "explanation": "反义：旧指从前的、不新的，与“全新”相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "无关：缓慢与全新不构成反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：漂亮与全新不构成反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "无关：冷淡与全新不构成反义关系。"}], "correct_answer": "旧", "explanations": {"旧": "反义：旧指从前的、不新的，与“全新”相对。", "缓慢": "无关：缓慢与全新不构成反义关系。", "漂亮": "无关：漂亮与全新不构成反义关系。", "冷淡": "无关：冷淡与全新不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指事物之前没有出现过，完全是新的。", "primary_collocate": null, "pronunciation": "quán xīn", "ipa": "tɕʰɥɛn˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这是一个全新的想法。", "target_word": "全新", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司推出了全新的产品。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种全新的技术以前没有过。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想开始全新的生活。", "target_word": "全新", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书给我们带来全新的看法。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家发现了一种全新的动物。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏有全新的玩法，以前没人见过。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们设计了全新的汽车，样子和以前完全不同。", "target_word": "全新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家创造了全新的风格。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议让大家有了全新的认识。", "target_word": "全新", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "全新的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "以前从未出现过、前所未有的新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新表示从未出现过，与“想法”搭配，符合句意。"}, {"text": "红色", "is_correct": false, "explanation": "语义：想法没有颜色，“红色的想法”不成立。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体的质地，不能修饰“想法”。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体的状态，不能用来形容“想法”。"}], "explanations": {"全新": "正确：全新表示从未出现过，与“想法”搭配，符合句意。", "红色": "语义：想法没有颜色，“红色的想法”不成立。", "坚硬": "搭配：“坚硬”形容物体的质地，不能修饰“想法”。", "潮湿": "搭配：“潮湿”形容空气或物体的状态，不能用来形容“想法”。"}, "sentence_index": 0, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些鸡蛋很全新，可以放心吃。", "explanation": "这里应该用〈新鲜〉。全新指从未出现或从未使用过，说食物的鲜度要用新鲜。"}, {"text": "我的妹妹很全新，今年已经十五岁了。", "explanation": "这里应该用〈年轻〉。全新指事物全部是新的、从未用过，形容人的年龄要用年轻。"}, {"text": "这张桌子很全新，桌面上已经有很多划痕。", "explanation": "这里应该用〈旧〉。全新指从未用过；桌面已有很多划痕，说明桌子已经用过，应该说旧，不能说全新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全新", "is_correct": true, "explanation": "正确：全新表示以前从未有过，与“玩法”搭配，并与“以前没人见过”呼应。"}, {"text": "古老", "is_correct": false, "explanation": "语义：“古老”指存在很久，与“以前没人见过”矛盾。"}, {"text": "常见", "is_correct": false, "explanation": "语义：“常见”指经常出现，与“以前没人见过”矛盾。"}, {"text": "苦涩", "is_correct": false, "explanation": "搭配：“苦涩”形容味道，不能修饰“玩法”。"}], "explanations": {"全新": "正确：全新表示以前从未有过，与“玩法”搭配，并与“以前没人见过”呼应。", "古老": "语义：“古老”指存在很久，与“以前没人见过”矛盾。", "常见": "语义：“常见”指经常出现，与“以前没人见过”矛盾。", "苦涩": "搭配：“苦涩”形容味道，不能修饰“玩法”。"}, "sentence_index": 6, "correct_answer": "全新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱用了五年，现在看起来还很全新。", "explanation": "这里应该用〈新〉。全新指从未用过；用了五年的冰箱只能说还很新，不能说全新。"}, {"text": "这位老教授很全新，他已经教书四十年了。", "explanation": "这里应该用〈资深〉。全新指从未用过的事物，形容有经验的人要用资深，不能用全新。"}, {"text": "我们家的旧沙发坐了十年，现在仍然很全新。", "explanation": "这里应该用〈完好〉。全新指从未用过；旧沙发用了十年，只能说保存完好，不能说全新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司推出的是全新了系统。", "corrected_sentence": "这家公司推出的是全新的系统。", "error_description": "错误：“全新”后面接了“了”。正确：应为“全新的系统”。“全新”是形容词，修饰名词时要用“的”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家换了全新地窗帘。", "corrected_sentence": "他家换了全新的窗帘。", "error_description": "错误：“全新”修饰名词时，结构助词用了“地”。正确：应为“全新的窗帘”。“地”用于修饰动词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
