INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "频谱是指信号（如光、声音）在频率上的分布情况，展示了不同频率成分的强度。", "primary_collocate": null, "pronunciation": "pín pǔ", "ipa": "pʰin˧˥ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "电子音乐的兴起更带来全新维度：频谱分析、波形图、算法生成乐谱等技术手段，使记谱超越五线谱的视觉范式，进入数据化表达领域。", "target_word": "频谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这张图是声音的频谱。", "target_word": "频谱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在屏幕上给我们看频谱。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从频谱可以看出低音很强。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用软件画出了这首歌的频谱。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看频谱就知道这段声音的高低。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光的频谱里有红色、蓝色和别的颜色。", "target_word": "频谱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生要看这个信号的频谱才能做判断。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把声音的频谱放在电脑上检查。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "频谱上最高的地方，说明那个频率最强。", "target_word": "频谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "频谱图", "label": "复合"}, {"form": "频谱分析", "label": "复合"}, {"form": "頻譜", "label": "繁体"}], "register": "书面", "sense_fingerprint": "信号在各个频率上的强度分布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71584119-e87a-4451-ae5e-3e7d6f74b1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10825, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频谱", "is_correct": true, "explanation": "正确：“频谱分析”指分析信号频率分布的技术，符合句意。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：“饺子分析”与电子音乐和信号分析的语境无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是音乐技术手段，“冰箱分析”与语境不符。"}, {"text": "朋友", "is_correct": false, "explanation": "搭配：“分析”的对象多为数据或事物，“朋友”不能用作“分析”的修饰语。"}], "explanations": {"频谱": "正确：“频谱分析”指分析信号频率分布的技术，符合句意。", "饺子": "语义：“饺子分析”与电子音乐和信号分析的语境无关。", "冰箱": "语义：冰箱不是音乐技术手段，“冰箱分析”与语境不符。", "朋友": "搭配：“分析”的对象多为数据或事物，“朋友”不能用作“分析”的修饰语。"}, "sentence_index": 0, "correct_answer": "频谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的操作方法写在频谱上。", "explanation": "这里应该用〈说明书〉。操作方法写在说明书上，频谱是信号的频率分布，不记录操作步骤。"}, {"text": "我在屏幕上看到一本频谱，上面画着很多线。", "explanation": "量词用错：频谱是图像，应用“张”或“幅”，“本”用于书册，不能用于频谱。"}, {"text": "我看着频谱学钢琴。", "explanation": "这里应该用〈乐谱〉。乐谱记录音符，用于演奏；频谱是信号的频率分布，不用于学琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频谱", "is_correct": true, "explanation": "正确：光的频谱指光按波长分开后的分布，与“红色、蓝色”搭配，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：光没有味道，“味道”与“红色、蓝色”不相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：光不是声音，“光的声音里有红色”与常识矛盾。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能用于光。"}], "explanations": {"频谱": "正确：光的频谱指光按波长分开后的分布，与“红色、蓝色”搭配，符合句意。", "味道": "语义：光没有味道，“味道”与“红色、蓝色”不相符。", "声音": "语义：光不是声音，“光的声音里有红色”与常识矛盾。", "体重": "搭配：“体重”用于人或动物，不能用于光。"}, "sentence_index": 6, "correct_answer": "频谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们按照频谱判断明天会不会下雨。", "explanation": "这里应该用〈天气预报〉。判断明天天气要看天气预报，频谱表示信号的频率分布，不能用来预报降雨。"}, {"text": "我手里拿着一把频谱，上面画满了线条。", "explanation": "量词用错：频谱是平面图像，应用“张”；“把”用于有柄的东西，不能用于频谱。"}, {"text": "这张频谱上最高的地方是山顶。", "explanation": "这里应该用〈地图〉。地图标出山顶的高度，频谱表示信号在频率上的强度，不能用来标注山顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把一只频谱挂在墙上。", "corrected_sentence": "老师把一张频谱挂在墙上。", "error_description": "错误：“频谱”的量词用了“只”。正确：应为“一张频谱”。“只”用于动物或成对物品中的单个，“频谱”是图像，应用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生看了一把频谱，决定下一步治疗。", "corrected_sentence": "医生看了一张频谱，决定下一步治疗。", "error_description": "错误：“频谱”的量词用了“把”。正确：应为“一张频谱”。“把”用于有柄的东西，频谱是图像，应用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50a6a7f9-2eba-4e3b-bf22-043c963084a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
