INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "波形图是一种以图形方式展示信号（如声音、电流）随时间变化的图表，横轴通常表示时间，纵轴表示幅度。", "primary_collocate": null, "pronunciation": "bō xíng tú", "ipa": "pwo˥ ɕiŋ˧˥ tʰu˧˥", "syllable_count": 3, "sentences": [{"text": "电子音乐的兴起更带来全新维度：频谱分析、波形图、算法生成乐谱等技术手段，使记谱超越五线谱的视觉范式，进入数据化表达领域。", "target_word": "波形图", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "屏幕上的波形图显示声音越来越大。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看这张波形图，说说信号怎么变化。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "波形图的横轴表示时间，纵轴表示幅度。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师用软件画出了电流的波形图。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个波形图上的线忽高忽低，说明声音很不稳定。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把录音导入电脑，就能看到它的波形图。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从波形图可以看出，这段音乐的声音很大。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上比较两个波形图的不同。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把声音的波形图发给了同事。", "target_word": "波形图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "波形圖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "波形图：展示信号随时间变化的图表", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "波形图", "is_correct": true, "explanation": "正确：“波形图”是与“频谱分析”并列的技术手段，符合句意。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：电影院是场所，不是技术手段，无法与“频谱分析”并列。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，不适合这段书面论述。"}, {"text": "作曲家", "is_correct": false, "explanation": "语义：作曲家是人，不是技术手段，与前后的名词不并列。"}], "explanations": {"波形图": "正确：“波形图”是与“频谱分析”并列的技术手段，符合句意。", "电影院": "语义：电影院是场所，不是技术手段，无法与“频谱分析”并列。", "玩意儿": "语域：“玩意儿”是口语说法，不适合这段书面论述。", "作曲家": "语义：作曲家是人，不是技术手段，与前后的名词不并列。"}, "sentence_index": 0, "correct_answer": "波形图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家房子的波形图已经画好了。", "explanation": "这里应该用〈设计图〉。波形图只表示声音、电流等信号随时间的变化，房子的结构要用设计图。"}, {"text": "这张波形图标出了去车站的路。", "explanation": "这里应该用〈地图〉。波形图不标示地点和路线，指路要用地图。"}, {"text": "这幅波形图是他画的小狗。", "explanation": "这里应该用〈图画〉。波形图是表示信号变化的图表，不用来画动物等形象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "波形图", "is_correct": true, "explanation": "正确：录音导入电脑后，看到的是它的波形图，符合句意。"}, {"text": "实物", "is_correct": false, "explanation": "语义：录音导入电脑后是数字文件，看到的不会是实物。"}, {"text": "标本", "is_correct": false, "explanation": "语义：标本是实体物品，与导入电脑后的数字录音不相符。"}, {"text": "容貌", "is_correct": false, "explanation": "体貌：“容貌”指人的外观，不能用来形容录音。"}], "explanations": {"波形图": "正确：录音导入电脑后，看到的是它的波形图，符合句意。", "实物": "语义：录音导入电脑后是数字文件，看到的不会是实物。", "标本": "语义：标本是实体物品，与导入电脑后的数字录音不相符。", "容貌": "体貌：“容貌”指人的外观，不能用来形容录音。"}, "sentence_index": 6, "correct_answer": "波形图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只波形图。", "explanation": "这里应该用〈张〉。“只”多用于动物或成对物品中的一个，波形图是图，要用“张”。"}, {"text": "老师在黑板上写了一首波形图。", "explanation": "这里应该用〈张〉。“首”用于诗歌、歌曲，波形图是图，要用“张”。"}, {"text": "他养了一头波形图。", "explanation": "这里应该用〈张〉。“头”用于牲畜，波形图是图，要用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这只波形图打印出来了。", "corrected_sentence": "我把这张波形图打印出来了。", "error_description": "量词错误：“波形图”是图，应用“张”，不能用“只”（“只”用于动物或成对物品中的一个）。正确说法是“这张波形图”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些波形图们都很清楚。", "corrected_sentence": "这些波形图都很清楚。", "error_description": "“们”只能加在指人的名词或代词后面，“波形图”是事物，不能加“们”。错误形式：这些波形图们；正确形式：这些波形图。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
