INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "算法是解决问题或完成计算的一系列明确步骤，常用于数学和计算机编程。", "primary_collocate": null, "pronunciation": "suàn fǎ", "ipa": "swan˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个算法能很快找到最短的路。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们一种简单的算法。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的算法让搜索更快。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的算法有错，结果不对。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的算法可以节省很多时间。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学排序的算法，再学别的。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题有两种算法，第二种更快。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师改进了算法，程序跑得更快了。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算法太复杂，电脑要算很久。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个算法的步骤写在纸上。", "target_word": "算法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "排序算法", "label": "复合词"}], "register": "书面", "sense_fingerprint": "算法：解决问题的一系列明确步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：“算法”是一系列明确的步骤，能够找到最短的路，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能找路，与“找到最短的路”无关。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“找到”需要能寻找路线的施事，“天气”不能作施事。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，无法“找到最短的路”。"}], "explanations": {"算法": "正确：“算法”是一系列明确的步骤，能够找到最短的路，符合句意。", "蛋糕": "语义：蛋糕是食物，不能找路，与“找到最短的路”无关。", "天气": "配价：“找到”需要能寻找路线的施事，“天气”不能作施事。", "花瓶": "语义：花瓶是器物，无法“找到最短的路”。"}, "sentence_index": 0, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找到了治感冒的好算法。", "explanation": "这里应该用〈方法〉。“算法”指计算或解题的明确步骤，治感冒要用“方法”。"}, {"text": "学校新定了一条算法，每天要背单词。", "explanation": "这里应该用〈规则〉。“算法”指解决问题的计算步骤，学校的规定要用“规则”。"}, {"text": "他养成了早起的好算法。", "explanation": "这里应该用〈习惯〉。“养成”搭配“习惯”，“算法”是计算步骤，不能养成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "算法", "is_correct": true, "explanation": "正确：“两种算法”指两种解题方法，“第二种更快”与之呼应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是解题的方式，“第二种更快”也说不通。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外观，不用来指解题的方法。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度是结果，不是可以选择的解题方式，“第二种更快”重复且不通。"}], "explanations": {"算法": "正确：“两种算法”指两种解题方法，“第二种更快”与之呼应。", "颜色": "语义：颜色不是解题的方式，“第二种更快”也说不通。", "长相": "体貌：“长相”指外观，不用来指解题的方法。", "速度": "语义：速度是结果，不是可以选择的解题方式，“第二种更快”重复且不通。"}, "sentence_index": 6, "correct_answer": "算法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一双算法。", "explanation": "这里应该用〈种〉或〈个〉。“双”用于成对的东西，“算法”不是成对的。"}, {"text": "花园里开着一朵算法。", "explanation": "这里应该用〈种〉或〈个〉。“朵”用于花、云等，“算法”不能用“朵”来计量。"}, {"text": "他拿出了一块算法。", "explanation": "这里应该用〈种〉或〈个〉。“块”用于块状物，“算法”是抽象的步骤，不是块状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学完了一台算法。", "corrected_sentence": "我学完了一种算法。", "error_description": "量词错误：“算法”应用“种”，“台”用于机器、设备，算法不是器械，不能用“台”。错误形式：学完了一台算法；正确形式：学完了一种算法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把算法的步骤请写在纸上。", "corrected_sentence": "这个算法的步骤请写在纸上。", "error_description": "量词错误：“把”用于有柄的器具，不能用于“算法”，应说“这个算法”。错误形式：这把算法；正确形式：这个算法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
