INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10829, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过某种过程或方式使事物形成、产生。", "primary_collocate": null, "pronunciation": "shēng chéng", "ipa": "ʂɤŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "值得注意的是，人工智能介入音乐创作后，机器生成的乐谱常融合符号逻辑与概率模型，引发关于“可读性”与“可演性”的新讨论。", "target_word": "生成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "软件可以自动生成一张图片。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点一下按钮，系统就生成了报告。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑根据你的话生成了一首歌。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发酵过程中会生成二氧化碳。", "target_word": "生成", "complexity_tier": "T3", "furigana": "fā jiào guò chéng zhōng huì shēng chéng èr yǎng huà tàn", "sentence_source": "generated"}, {"text": "这个程序生成的文字很自然。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用软件生成了三个新名字。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器没有生成正确的结果。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统每天都会生成一份数据表。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让电脑生成了一道新题。", "target_word": "生成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生成了", "label": "完成体"}, {"form": "生成过", "label": "经历体"}, {"form": "自动生成", "label": "复合词"}], "register": "书面", "sense_fingerprint": "生成：通过某种过程使事物形成、产生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10829, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：shēng chéng，通过某种过程或方式使事物形成、产生。"}, {"text": "声称", "is_correct": false, "explanation": "第二个音节 chēng（第一声）与 chéng（第二声）声调不同，意思是宣称、断言。"}, {"text": "圣城", "is_correct": false, "explanation": "第一个音节 shèng（第四声）与 shēng（第一声）声调不同，意思是圣城、圣地。"}, {"text": "省城", "is_correct": false, "explanation": "第一个音节 shěng（第三声）与 shēng（第一声）声调不同，意思是省会城市。"}, {"text": "生辰", "is_correct": false, "explanation": "第二个音节 chén 与 chéng 韵尾不同（n 与 ng），声调相同，意思是出生的时辰或生日。"}], "explanations": {"生成": "生成：shēng chéng，通过某种过程或方式使事物形成、产生。", "声称": "第二个音节 chēng（第一声）与 chéng（第二声）声调不同，意思是宣称、断言。", "圣城": "第一个音节 shèng（第四声）与 shēng（第一声）声调不同，意思是圣城、圣地。", "省城": "第一个音节 shěng（第三声）与 shēng（第一声）声调不同，意思是省会城市。", "生辰": "第二个音节 chén 与 chéng 韵尾不同（n 与 ng），声调相同，意思是出生的时辰或生日。"}, "sentence_index": null, "correct_answer": "生成"}, "level_3": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：机器按程序制作出乐谱，与“机器”的主语相合。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐曲，不说“演奏的乐谱”，乐谱是用来读的。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是弄坏纸张，与“机器……的乐谱”指产出的乐谱不符，也与融合符号逻辑的语境相反。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是去掉已有的内容，不能描述机器产出的乐谱，也与句中“融合符号逻辑与概率模型”的产出语境不符。"}], "explanations": {"生成": "生成：机器按程序制作出乐谱，与“机器”的主语相合。", "演奏": "搭配：“演奏”的对象是乐曲，不说“演奏的乐谱”，乐谱是用来读的。", "撕": "语义：撕是弄坏纸张，与“机器……的乐谱”指产出的乐谱不符，也与融合符号逻辑的语境相反。", "删除": "语义：“删除”是去掉已有的内容，不能描述机器产出的乐谱，也与句中“融合符号逻辑与概率模型”的产出语境不符。"}, "sentence_index": 0, "correct_answer": "生成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事生成了很大的争议。", "explanation": "这里应该用〈产生〉。生成多指按过程制作出具体的事物或结果，“争议”这类抽象的事情要用产生。"}, {"text": "学校今天生成了一场运动会。", "explanation": "这里应该用〈举办〉。生成侧重通过程序或过程产出结果，组织运动会这类大型活动要用举办。"}, {"text": "昨天下午这里生成了一次停电。", "explanation": "这里应该用〈发生〉。生成指制作出新的东西，突发的停电、事故等要用发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生成", "is_correct": true, "explanation": "生成：用软件制作出三个名字，与句中的“软件”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，名字不能吃。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”搭配衣物、身体等，不说洗名字。"}, {"text": "请", "is_correct": false, "explanation": "配价：“请”要求人作宾语，“名字”不能作“请”的宾语。"}], "explanations": {"生成": "生成：用软件制作出三个名字，与句中的“软件”相合。", "吃": "语义：“吃”的对象是食物，名字不能吃。", "洗": "搭配：“洗”搭配衣物、身体等，不说洗名字。", "请": "配价：“请”要求人作宾语，“名字”不能作“请”的宾语。"}, "sentence_index": 6, "correct_answer": "生成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂生成了一千台电脑。", "explanation": "这里应该用〈生产〉。生成指通过程序或过程产出结果，工厂批量制造的产品要用生产。"}, {"text": "妈妈生成了一锅粥。", "explanation": "这里应该用〈煮〉。生成不用于烹饪，煮粥要用煮。"}, {"text": "施工队生成了一条隧道。", "explanation": "这里应该用〈建造〉。生成多用于产出抽象或数字内容，修建隧道、桥梁等大型工程要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序生成地很快。", "corrected_sentence": "这个程序生成得很快。", "error_description": "补语标记错误：动词“生成”后接程度补语，要用“得”，不能用“地”。错误形式：生成地很快；正确形式：生成得很快。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次运行没生成了任何图片。", "corrected_sentence": "这次运行没生成任何图片。", "error_description": "“没”否定已完成的动作时不加“了”，应直接说“没生成”。错误形式：没生成了任何图片；正确形式：没生成任何图片。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
