INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "记录音乐旋律和节奏的符号系统", "primary_collocate": null, "pronunciation": "yuè pǔ", "ipa": "ɥe˥˩ pʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "电子音乐的兴起更带来全新维度：频谱分析、波形图、算法生成乐谱等技术手段，使记谱超越五线谱的视觉范式，进入数据化表达领域。", "target_word": "乐谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "值得注意的是，人工智能介入音乐创作后，机器生成的乐谱常融合符号逻辑与概率模型，引发关于“可读性”与“可演性”的新讨论。", "target_word": "乐谱", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "乐谱用符号记下音乐的旋律和节奏。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看懂乐谱以后，她才能自己弹这首曲子。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五线谱是世界上最常见的乐谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐谱上的小黑点表示不同的音高。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学习怎么读乐谱上的节奏符号。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国古代的乐谱和现在的乐谱写法不一样。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不懂乐谱就很难学好作曲。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用数字记录音高的乐谱叫简谱。", "target_word": "乐谱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份乐谱", "label": "量词"}, {"form": "樂譜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用符号记录旋律和节奏的记谱系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：记录音乐旋律与节奏的符号系统，算法可以生成它，与句中的技术语境相合。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不是算法可以生成的技术成果，与“记谱”的语境无关。"}, {"text": "掌声", "is_correct": false, "explanation": "搭配：“生成”不搭配“掌声”，掌声不是可以由算法制作出来的成果。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，算法生成钢琴不符合“记谱”和“数据化表达”的语境。"}], "explanations": {"乐谱": "乐谱：记录音乐旋律与节奏的符号系统，算法可以生成它，与句中的技术语境相合。", "早餐": "语义：早餐是食物，不是算法可以生成的技术成果，与“记谱”的语境无关。", "掌声": "搭配：“生成”不搭配“掌声”，掌声不是可以由算法制作出来的成果。", "钢琴": "语义：钢琴是乐器，算法生成钢琴不符合“记谱”和“数据化表达”的语境。"}, "sentence_index": 0, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她买了一根乐谱，才学会了弹这首曲子。", "explanation": "这里应该用〈份〉。乐谱作为纸本常用“份”计量，“根”用于细长的条状物，不能用于乐谱。"}, {"text": "她买了一把乐谱，才学会了弹这首曲子。", "explanation": "这里应该用〈份〉。“把”用于有柄的器具，不能用于乐谱。"}, {"text": "她买了一棵乐谱，才学会了弹这首曲子。", "explanation": "这里应该用〈份〉。“棵”用于植物，不能用于乐谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐谱", "is_correct": true, "explanation": "乐谱：印有节奏符号的记谱材料，可以“读”。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸上没有节奏符号，读报纸学不到节奏。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单上列的是菜品，不印节奏符号。"}, {"text": "手表", "is_correct": false, "explanation": "搭配：“手表”上不印节奏符号，“读手表上的节奏符号”不成立。"}], "explanations": {"乐谱": "乐谱：印有节奏符号的记谱材料，可以“读”。", "报纸": "语义：报纸上没有节奏符号，读报纸学不到节奏。", "菜单": "语义：菜单上列的是菜品，不印节奏符号。", "手表": "搭配：“手表”上不印节奏符号，“读手表上的节奏符号”不成立。"}, "sentence_index": 6, "correct_answer": "乐谱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师给了我一只乐谱，我学会了记录音高。", "explanation": "这里应该用〈份〉。乐谱作为纸本常用“份”计量，“只”用于动物或成对物品中的一个，不能用于乐谱。"}, {"text": "我把那台乐谱拿给老师看。", "explanation": "这里应该用〈份〉。“台”用于机器、电器等，不能用于乐谱。"}, {"text": "妈妈把那块乐谱收进了抽屉。", "explanation": "这里应该用〈份〉。“块”多用于块状物，乐谱不能用“块”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天下载了一只乐谱。", "corrected_sentence": "我昨天下载了一份乐谱。", "error_description": "量词错误：“乐谱”应用“份”，“只”多用于动物或成对物品中的一个，不能用于乐谱。错误形式：下载了一只乐谱；正确形式：下载了一份乐谱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们发了一双乐谱。", "corrected_sentence": "老师给我们发了一份乐谱。", "error_description": "量词错误：“乐谱”应用“份”，“双”指成对的东西，不能用于乐谱。错误形式：发了一双乐谱；正确形式：发了一份乐谱。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
