INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了实现某个目的而采用的具体方法或工具。", "primary_collocate": null, "pronunciation": "jì shù shǒu duàn", "ipa": "tɕi˥˩ ʂu˥˩ ʂoʊ˨˩˦ twan˥˩", "syllable_count": 4, "sentences": [{"text": "值得注意的是，透明度实践亦存在边界——过度披露可能引发模型逆向工程或恶意攻击，故企业应在安全与开放间寻求动态平衡，采用差分隐私、联邦学习等技术手段实现“有限透明”。", "target_word": "技术手段", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警察用技术手段找到了丢失的手机。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用技术手段保护客户的资料。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不能只靠技术手段解决。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校采用新的技术手段检查作业。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用先进的技术手段治疗这种病。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想用技术手段减少浪费。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂换了几种技术手段提高产量。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站用技术手段阻止了假账号。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些技术手段让农民省了很多力气。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "技術手段", "label": "繁体"}], "register": "中性", "sense_fingerprint": "技术手段：为达到某个目的而采用的具体技术方法或工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术手段", "is_correct": true, "explanation": "技术手段：句中的差分隐私、联邦学习等就是具体的技术方法。"}, {"text": "道德准则", "is_correct": false, "explanation": "语义：差分隐私、联邦学习是技术方法，不属于道德准则。"}, {"text": "资金预算", "is_correct": false, "explanation": "搭配：“采用”后接方法或工具，不能接资金预算。"}, {"text": "人员规模", "is_correct": false, "explanation": "搭配：“采用”后接方法或工具，不能接人员规模。"}], "explanations": {"技术手段": "技术手段：句中的差分隐私、联邦学习等就是具体的技术方法。", "道德准则": "语义：差分隐私、联邦学习是技术方法，不属于道德准则。", "资金预算": "搭配：“采用”后接方法或工具，不能接资金预算。", "人员规模": "搭配：“采用”后接方法或工具，不能接人员规模。"}, "sentence_index": 0, "correct_answer": "技术手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用幽默的技术手段讲故事。", "explanation": "这里应该用〈语言〉。技术手段指技术性的具体方法，讲故事用语言，不用技术手段。"}, {"text": "妈妈用温柔的技术手段安慰了我。", "explanation": "这里应该用〈方式〉。技术手段指技术性方法，安慰人用温柔的方式，不用技术手段。"}, {"text": "她吃掉了那个技术手段。", "explanation": "这里应该用〈蛋糕〉。技术手段指方法或工具，不能被吃掉，吃东西要用蛋糕之类的食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术手段", "is_correct": true, "explanation": "技术手段：采用技术性方法来减少浪费，符合句意。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水是化妆用品，与减少浪费的方法无关，不能用来达成减少浪费的目的。"}, {"text": "健身器材", "is_correct": false, "explanation": "语义：健身器材与减少浪费无关，不能作为减少浪费的方法。"}, {"text": "高级轿车", "is_correct": false, "explanation": "搭配：“用……减少浪费”需要能够节约资源的办法，高级轿车不能这样使用。"}], "explanations": {"技术手段": "技术手段：采用技术性方法来减少浪费，符合句意。", "香水": "语义：香水是化妆用品，与减少浪费的方法无关，不能用来达成减少浪费的目的。", "健身器材": "语义：健身器材与减少浪费无关，不能作为减少浪费的方法。", "高级轿车": "搭配：“用……减少浪费”需要能够节约资源的办法，高级轿车不能这样使用。"}, "sentence_index": 6, "correct_answer": "技术手段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题需要一只技术手段。", "explanation": "这里应该用〈种〉。“技术手段”的量词是“种”，不用“只”。"}, {"text": "她用技术手段害羞了。", "explanation": "这里应该用〈脸红〉。技术手段指方法或工具，害羞是情绪反应，不能用技术手段。"}, {"text": "他的技术手段很和善。", "explanation": "这里应该用〈为人〉。“和善”形容人的性情，技术手段是方法或工具，不能说和善。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师用两只技术手段修复了这个漏洞。", "corrected_sentence": "工程师用两种技术手段修复了这个漏洞。", "error_description": "错误：“两只技术手段”；正确：“两种技术手段”。“技术手段”的量词是“种”，“只”不能用于这类抽象名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂用新的技术手段的降低了成本。", "corrected_sentence": "工厂用新的技术手段降低了成本。", "error_description": "错误：“技术手段的降低”；正确：“技术手段降低”。“技术手段”作“用”的宾语，“降低”是谓语，两者之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由多种乐器演奏者组成的大型音乐团体，通常包括弦乐、管乐、打击乐等乐器组。", "primary_collocate": null, "pronunciation": "jiāo xiǎng yuè tuán", "ipa": "tɕjɑʊ˥ ɕjɑŋ˨˩˦ ɥe˥˩ tʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "交响乐团", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个交响乐团有一百多位乐手。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去音乐厅听交响乐团的演出。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团的指挥站在舞台中间。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她十岁开始学小提琴，现在是交响乐团的成员。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支交响乐团明年要去欧洲演出。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团里有小提琴、大提琴和长笛。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里新成立了一个交响乐团。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交响乐团正在台上调音，观众都安静下来。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想考进国家交响乐团当小号手。", "target_word": "交响乐团", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一支交响乐团", "label": "量词"}, {"form": "交響樂團", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由弦乐、管乐、打击乐等乐手组成的大型音乐团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交响乐团", "is_correct": true, "explanation": "交响乐团是成建制的乐团，与歌剧制作、作曲教学并列，都是音乐机构的一部分，句意通顺。"}, {"text": "交通", "is_correct": false, "explanation": "语义：交通指运输，与乐团和音乐教学无关，“支撑着交通”放在这里句意不通。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业是生产农作物的行业，与音乐制作和教学无关，不能与“歌剧制作”并列。"}, {"text": "药品", "is_correct": false, "explanation": "语义：药品与音乐记谱和作曲教学无关，并列在音乐机构之后句意不通。"}], "explanations": {"交响乐团": "交响乐团是成建制的乐团，与歌剧制作、作曲教学并列，都是音乐机构的一部分，句意通顺。", "交通": "语义：交通指运输，与乐团和音乐教学无关，“支撑着交通”放在这里句意不通。", "农业": "语义：农业是生产农作物的行业，与音乐制作和教学无关，不能与“歌剧制作”并列。", "药品": "语义：药品与音乐记谱和作曲教学无关，并列在音乐机构之后句意不通。"}, "sentence_index": 0, "correct_answer": "交响乐团"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个交响乐团的演员每晚在剧场演出话剧。", "explanation": "这里应该用〈剧团〉。交响乐团的成员是演奏乐器的乐手，不是演员，演出话剧要用剧团。"}, {"text": "这个交响乐团的成员都能唱高音。", "explanation": "这里应该用〈合唱团〉。交响乐团以器乐演奏为主，成员靠乐器而不是歌唱，说成员能唱高音要用合唱团。"}, {"text": "这支交响乐团的主唱声音很好，观众一直在跟着唱。", "explanation": "这里应该用〈乐队〉。交响乐团是古典管弦乐编制，没有主唱这一角色，流行乐队才有主唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交响乐团", "is_correct": true, "explanation": "交响乐团由多名乐手组成，里面有小提琴、大提琴和长笛，“交响乐团里有”句意成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里放的是食物，不会有小提琴、大提琴这类乐器和演奏者。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不是乐器，也没有演奏者，“蔬菜里有小提琴”说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“里有”前接能容纳乐器的场所或团体，地铁一般不说里面有这些乐器。"}], "explanations": {"交响乐团": "交响乐团由多名乐手组成，里面有小提琴、大提琴和长笛，“交响乐团里有”句意成立。", "冰箱": "语义：冰箱里放的是食物，不会有小提琴、大提琴这类乐器和演奏者。", "蔬菜": "语义：蔬菜不是乐器，也没有演奏者，“蔬菜里有小提琴”说不通。", "地铁": "搭配：“里有”前接能容纳乐器的场所或团体，地铁一般不说里面有这些乐器。"}, "sentence_index": 6, "correct_answer": "交响乐团"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个交响乐团的导游每天带着游客逛博物馆。", "explanation": "这里应该用〈旅行团〉。交响乐团是演奏乐器的乐团，没有导游带游客逛景点；带团逛博物馆要用旅行团。"}, {"text": "这个交响乐团的队员每周六在球场上踢球。", "explanation": "这里应该用〈球队〉。交响乐团的成员是演奏乐器的乐手，不在球场踢球；踢球比赛的队伍要用球队。"}, {"text": "这个交响乐团的舞者每晚在剧场跳舞。", "explanation": "这里应该用〈歌舞团〉。交响乐团的成员是演奏乐器的乐手，不跳舞；舞者要在歌舞团里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天学校请来了一只交响乐团。", "corrected_sentence": "昨天学校请来了一支交响乐团。", "error_description": "量词错误：“交响乐团”是团体，应该用“支”；“只”用于动物或单个器物，不能用来数乐团。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市里新成立了一条交响乐团，招了很多年轻乐手。", "corrected_sentence": "市里新成立了一个交响乐团，招了很多年轻乐手。", "error_description": "量词错误：“交响乐团”是团体，应该用“个”或“支”；“条”用于细长的东西，不能用来数乐团。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
