INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种以歌唱为主要表现手段，融合音乐、戏剧、舞蹈等元素的综合舞台艺术形式。", "primary_collocate": null, "pronunciation": "gē jù", "ipa": "kɤ˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "歌剧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "歌剧主要靠唱歌来讲故事。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们昨晚在剧院看了一场歌剧。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌剧里有音乐、戏剧，也有舞蹈。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "意大利是歌剧的故乡。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱听歌剧，后来当了歌唱家。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部歌剧讲的是一对年轻人的爱情故事。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看歌剧的时候，大家都要保持安静。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国也有自己的歌剧，比如《白毛女》。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌剧的演员不但要唱得好，还要会表演。", "target_word": "歌剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部歌剧", "label": "量词"}, {"form": "一场歌剧", "label": "量词"}, {"form": "歌劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以歌唱为主、融合音乐戏剧舞蹈的综合舞台艺术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '287b9723-6463-4642-964d-9dfe8f414a1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌剧", "is_correct": true, "explanation": "歌剧是以歌唱为主的舞台艺术，“歌剧制作”指舞台作品的制作，与交响乐团、作曲教学并列，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被制作，“支撑着空气制作”与前面的音乐机构并列，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为制作的对象。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“制作”后接具体的成品，“时间”不能被制作。"}], "explanations": {"歌剧": "歌剧是以歌唱为主的舞台艺术，“歌剧制作”指舞台作品的制作，与交响乐团、作曲教学并列，句意通顺。", "空气": "语义：空气不能被制作，“支撑着空气制作”与前面的音乐机构并列，句意不通。", "天气": "语义：天气是自然现象，不能作为制作的对象。", "时间": "搭配：“制作”后接具体的成品，“时间”不能被制作。"}, "sentence_index": 0, "correct_answer": "歌剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歌剧演员主要用说话来表现人物。", "explanation": "这里应该用〈话剧〉。歌剧以唱为主，人物主要靠歌唱表现，不靠说话。"}, {"text": "歌剧主要靠舞蹈来讲故事。", "explanation": "这里应该用〈舞剧〉。歌剧主要靠歌唱讲故事，舞蹈不是它的主要手段。"}, {"text": "歌剧演员靠一张嘴说笑，观众笑个不停。", "explanation": "这里应该用〈相声〉。相声靠说笑逗乐，歌剧以歌唱为主，不以说笑为主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌剧", "is_correct": true, "explanation": "歌剧是有情节的舞台作品，用“部”计数，讲的是一对年轻人的爱情故事，句意通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是有情节的作品，“这部冰箱讲的是爱情故事”说不通。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不能讲故事。"}, {"text": "高楼", "is_correct": false, "explanation": "搭配：“部”用于书、影视等作品，不用于楼房，“高楼讲故事”也不通。"}], "explanations": {"歌剧": "歌剧是有情节的舞台作品，用“部”计数，讲的是一对年轻人的爱情故事，句意通顺。", "冰箱": "语义：冰箱不是有情节的作品，“这部冰箱讲的是爱情故事”说不通。", "面条": "语义：面条是食物，不能讲故事。", "高楼": "搭配：“部”用于书、影视等作品，不用于楼房，“高楼讲故事”也不通。"}, "sentence_index": 6, "correct_answer": "歌剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场歌剧的运动员在泳池里奋力划水，争夺金牌。", "explanation": "这里应该用〈游泳比赛〉。歌剧是舞台上以唱为主的表演，在泳池里争金牌要用游泳比赛。"}, {"text": "这场歌剧的球迷一直在呐喊，球员们跑得满头大汗。", "explanation": "这里应该用〈足球赛〉。歌剧没有球员跑动比赛；球迷呐喊、球员满场跑要用足球赛。"}, {"text": "这场歌剧的学生在教室里认真地做数学卷子。", "explanation": "这里应该用〈考试〉。歌剧是舞台上的演唱表演，学生在教室里做数学卷子要用考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候看了过歌剧。", "corrected_sentence": "我小时候看过歌剧。", "error_description": "体标错误：“看过”里的“过”已表示经历，前面不能再加“了”，应说“看过歌剧”，不能说“看了过歌剧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班上周去看了一座歌剧。", "corrected_sentence": "我们班上周去看了一场歌剧。", "error_description": "量词错误：“歌剧”应该用“场”或“部”；“座”用于山、楼这类大型固定物，不能用来数歌剧。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c95adb1-5764-4daa-8be1-f51aaf37e867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
