INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指大学或研究机构中遵循传统学术规范、注重理论体系的学者或流派。", "primary_collocate": null, "pronunciation": "xué yuàn pài", "ipa": "ɕɥɛ˧˥ ɥɛn˥˩ pʰaɪ˥˩", "syllable_count": 3, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "学院派", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位学院派教授很重视理论，不太喜欢新办法。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是典型的学院派，写文章总是先谈理论。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派画家画得很准，但有人说太死板。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派批评家认为，这部电影缺少严格的结构。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈学院派学者常常按传统规范做研究。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人喜欢新想法，学院派却更相信老规矩。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究方法很学院派，每一步都有理论根据。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院派的音乐家一般先学理论，再练演奏。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这所研究院里，学院派的影响一直很大。", "target_word": "学院派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學院派", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学院派|学术传统与理论体系|学者流派", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学院派", "is_correct": true, "explanation": "正确。“学院派作曲教学”指学院派的作曲教学，与句中“传统五线谱仍是全球通行的技术语言”所支撑的教学语境相符。"}, {"text": "实验派", "is_correct": false, "explanation": "语义：实验派以探索新手法为主，与“传统五线谱”支撑教学的语境相悖，且与句中“而在实验音乐领域”的新记谱重复。"}, {"text": "烹饪派", "is_correct": false, "explanation": "语义：烹饪派与“交响乐团、歌剧制作”所代表的音乐教学语境无关，句意不通。"}, {"text": "书法派", "is_correct": false, "explanation": "语义：书法派属于书画流派，与“交响乐团、歌剧制作”的音乐教学语境无关，句意不通。"}], "explanations": {"学院派": "正确。“学院派作曲教学”指学院派的作曲教学，与句中“传统五线谱仍是全球通行的技术语言”所支撑的教学语境相符。", "实验派": "语义：实验派以探索新手法为主，与“传统五线谱”支撑教学的语境相悖，且与句中“而在实验音乐领域”的新记谱重复。", "烹饪派": "语义：烹饪派与“交响乐团、歌剧制作”所代表的音乐教学语境无关，句意不通。", "书法派": "语义：书法派属于书画流派，与“交响乐团、歌剧制作”的音乐教学语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "学院派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学院派的音乐家只用即兴演奏，不看乐谱。", "explanation": "这里应该用〈即兴派〉。学院派注重乐谱与理论体系，“只用即兴演奏，不看乐谱”应说即兴派。"}, {"text": "学院派的诗人很少遵守老规矩。", "explanation": "这里应该用〈先锋派〉。学院派恪守传统规范，“很少遵守老规矩”应说先锋派。"}, {"text": "学院派艺人没有学过理论，凭经验创作。", "explanation": "这里应该用〈民间〉。学院派注重理论体系，“没有学过理论，凭经验创作”应说民间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学院派", "is_correct": true, "explanation": "正确。“却更相信老规矩”与“学院派”恪守传统的特点相符，句中“却”表示与“年轻人喜欢新想法”形成对比。"}, {"text": "先锋派", "is_correct": false, "explanation": "语义：先锋派与“年轻人喜欢新想法”同向，不能用“却”来转折，句意不通。"}, {"text": "科学", "is_correct": false, "explanation": "搭配：“相信老规矩”的主语应是人或群体，“科学”不能说相信老规矩。"}, {"text": "新派", "is_correct": false, "explanation": "语义：新派同样喜欢新想法，与“却更相信老规矩”的转折不合。"}], "explanations": {"学院派": "正确。“却更相信老规矩”与“学院派”恪守传统的特点相符，句中“却”表示与“年轻人喜欢新想法”形成对比。", "先锋派": "语义：先锋派与“年轻人喜欢新想法”同向，不能用“却”来转折，句意不通。", "科学": "搭配：“相信老规矩”的主语应是人或群体，“科学”不能说相信老规矩。", "新派": "语义：新派同样喜欢新想法，与“却更相信老规矩”的转折不合。"}, "sentence_index": 6, "correct_answer": "学院派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位学院派学者喜欢用街头俚语写文章。", "explanation": "这里应该用〈草根〉。学院派指遵循传统学术规范的学者，“用街头俚语写文章”应说草根。"}, {"text": "这位学院派编辑只关心销量。", "explanation": "这里应该用〈商业派〉。学院派注重理论体系，“只关心销量”应说商业派。"}, {"text": "这位学院派画家没有受过任何训练。", "explanation": "这里应该用〈业余〉。学院派遵循系统的学术规范，“没有受过任何训练”应说业余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用学院派地方法画画。", "corrected_sentence": "他用学院派的方法画画。", "error_description": "结构错误：“学院派”修饰名词“方法”时应用“的”，不用“地”（“地”修饰动词或形容词）。应改为“他用学院派的方法画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一只学院派，常年研究乐理。", "corrected_sentence": "他是一位学院派，常年研究乐理。", "error_description": "量词错误：“学院派”在此指人，量词应用“位”，不能用“只”（“只”多用于动物）。应改为“他是一位学院派，常年研究乐理。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
