INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10838, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "创作乐曲，指把音符和节奏组合成一首完整的音乐作品。", "primary_collocate": null, "pronunciation": "zuò qǔ", "ipa": "tswɔ˥˩ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "作曲", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他从十岁开始学作曲，现在已经写了很多歌。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻人在音乐学院学作曲，不学演奏。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢在安静的晚上弹琴作曲。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲需要耐心，一首乐曲常常要改很多次。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首电影主题曲是一位老先生作曲的。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边弹钢琴，一边作曲。", "target_word": "作曲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎样用节奏和音符作曲。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师为这部歌剧作曲，用了两年时间。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他作曲了二十年，写过几百首乐曲。", "target_word": "作曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "作曲家", "label": "复合"}, {"form": "作曲了", "label": "体标"}, {"form": "作曲过", "label": "体标"}], "register": "中性", "sense_fingerprint": "作曲|把音符和节奏组合成完整乐曲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "正确。“学院派作曲教学”指学院派的作曲教学，与句中“交响乐团、歌剧制作”的音乐语境相符。"}, {"text": "作画", "is_correct": false, "explanation": "语义：五线谱是音乐记谱，支撑的是音乐教学，不能用于绘画教学。"}, {"text": "写诗", "is_correct": false, "explanation": "语义：“写诗”属于文学创作，与句中“交响乐团、歌剧制作”的音乐语境不合。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与句中“交响乐团、歌剧制作”所代表的音乐教学语境无关，句意不通。"}], "explanations": {"作曲": "正确。“学院派作曲教学”指学院派的作曲教学，与句中“交响乐团、歌剧制作”的音乐语境相符。", "作画": "语义：五线谱是音乐记谱，支撑的是音乐教学，不能用于绘画教学。", "写诗": "语义：“写诗”属于文学创作，与句中“交响乐团、歌剧制作”的音乐语境不合。", "烹饪": "语义：烹饪与句中“交响乐团、歌剧制作”所代表的音乐教学语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在音乐会上作曲了一首很有名的老曲子。", "explanation": "这里应该用〈演奏〉。作曲是创作新乐曲，不能用于已经很有名的老曲子。"}, {"text": "她在台上作曲了一首老歌。", "explanation": "这里应该用〈唱〉。作曲指创作新作品，“老歌”已经存在，不能用“作曲”。"}, {"text": "她每天作曲一篇日记。", "explanation": "这里应该用〈写〉。作曲的对象是乐曲，日记不是乐曲，不能用“作曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲", "is_correct": true, "explanation": "正确。“一边弹钢琴，一边作曲”描述同时进行的两件事，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：弹钢琴与睡觉不能同时进行，句意不通。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：弹钢琴与洗碗不能同时进行，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：弹钢琴与游泳不能同时进行，句意不通。"}], "explanations": {"作曲": "正确。“一边弹钢琴，一边作曲”描述同时进行的两件事，符合句意。", "睡觉": "语义：弹钢琴与睡觉不能同时进行，句意不通。", "洗碗": "语义：弹钢琴与洗碗不能同时进行，句意不通。", "游泳": "语义：弹钢琴与游泳不能同时进行，句意不通。"}, "sentence_index": 6, "correct_answer": "作曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她作曲了一道很好吃的菜。", "explanation": "这里应该用〈做〉。作曲的对象是乐曲，不能用于菜。"}, {"text": "她作曲了一封信。", "explanation": "这里应该用〈写〉。作曲的对象是乐曲，信件不是乐曲，不能用“作曲”。"}, {"text": "她作曲了一间漂亮的房子。", "explanation": "这里应该用〈盖〉。作曲的对象是乐曲，房子不能用“作曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他作曲得很好。", "corrected_sentence": "他作曲作得很好。", "error_description": "补语错误：“作曲”是动宾式结构，带“得”字补语时需重复动词“作”，应说“他作曲作得很好”，不说“他作曲得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌是他作曲了的。", "corrected_sentence": "这首歌是他作曲的。", "error_description": "体标错误：“是……的”结构强调已完成的动作，其中不能再加“了”，应说“这首歌是他作曲的”，不说“这首歌是他作曲了的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
