INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指教师传授知识和学生学习的过程，也泛指一切传授和学习的活动。", "primary_collocate": null, "pronunciation": "jiào xué", "ipa": "tɕjɑʊ˥˩ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "教学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这所学校的教学很认真，学生进步很快。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师每天都要认真准备教学。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有十年教学经验。", "target_word": "教学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网上教学让学生在家也能上课。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对教学很有兴趣，想当老师。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用新方法改进教学。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的教学要让学生愿意思考。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的教学很有意思，大家都爱听。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教学和考试不一样，老师更关心学生是否理解。", "target_word": "教学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教學", "label": "繁体"}, {"form": "教学法", "label": "复合"}, {"form": "教学楼", "label": "复合"}], "register": "中性", "sense_fingerprint": "教学|教师传授与学生学习的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "票房", "is_correct": false, "explanation": "语义：票房指演出或电影的售票收入，与学院派作曲的教学不是同一领域，不能与“作曲”并列。"}, {"text": "教学", "is_correct": true, "explanation": "“教学”指学院里教授作曲的活动，与前面的“交响乐团、歌剧制作”并列，句意通顺。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏工具，不是可以被“支撑”的教育或创作领域，与“歌剧制作”并列不通。"}, {"text": "广告", "is_correct": false, "explanation": "搭配：“学院派作曲”不与“广告”搭配，二者不能并列作为被支撑的领域。"}], "explanations": {"票房": "语义：票房指演出或电影的售票收入，与学院派作曲的教学不是同一领域，不能与“作曲”并列。", "教学": "“教学”指学院里教授作曲的活动，与前面的“交响乐团、歌剧制作”并列，句意通顺。", "乐器": "语义：乐器是演奏工具，不是可以被“支撑”的教育或创作领域，与“歌剧制作”并列不通。", "广告": "搭配：“学院派作曲”不与“广告”搭配，二者不能并列作为被支撑的领域。"}, "sentence_index": 0, "correct_answer": "教学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在医院做教学，负责给病人开药。", "explanation": "这里应该用〈医疗〉。教学指传授与学习的活动，给病人开药属于医疗，不能说“做教学”。"}, {"text": "这家餐厅的教学很好吃，客人都喜欢。", "explanation": "这里应该用〈菜〉。教学指传授与学习的活动，不指食物；“很好吃”说的是菜，应说“这家餐厅的菜很好吃”。"}, {"text": "我在家没有老师，只能自己教学。", "explanation": "这里应该用〈自学〉。教学需要教的一方和学的一方同时存在，没有老师时只能说自学，不能说“自己教学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以靠新方法改进的对象，“改进天气”说不通。"}, {"text": "教学", "is_correct": true, "explanation": "“教学”是可以用新方法改进的活动，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“改进”不与“体重”搭配，体重应说“增加”或“减少”。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节是自然时段，不能被“学校用新方法”改进。"}], "explanations": {"天气": "语义：天气不是可以靠新方法改进的对象，“改进天气”说不通。", "教学": "“教学”是可以用新方法改进的活动，与句意相符。", "体重": "搭配：“改进”不与“体重”搭配，体重应说“增加”或“减少”。", "季节": "语义：季节是自然时段，不能被“学校用新方法”改进。"}, "sentence_index": 6, "correct_answer": "教学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教学很大，能坐下八十个学生。", "explanation": "这里应该用〈教室〉。教室指上课的房间，教学指老师教、学生学的活动，不能指地点，“教学很大”不通。"}, {"text": "教学带队训练，很有经验。", "explanation": "这里应该用〈教练〉。教练指带领队员训练的人，教学是活动，不能做主语指人。"}, {"text": "这次失败给了我很大的教学。", "explanation": "这里应该用〈教训〉。教训指从失败中得到的经验，教学指课堂上的教与学，不能用来指失败带来的收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校重视一个教学。", "corrected_sentence": "学校重视教学。", "error_description": "量词错误：“教学”是抽象活动，不能用“个”计量，应说“学校重视教学”，不说“学校重视一个教学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校地教学方法很新，学生都很喜欢。", "corrected_sentence": "学校的教学方法很新，学生都很喜欢。", "error_description": "结构助词错误：“学校”是名词，修饰“教学方法”时应用“的”，不能用“地”（“地”只用于动词、形容词之前）。应改为“学校的教学方法很新，学生都很喜欢。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
