INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了验证某种科学理论或假设而进行的一系列操作或观察。", "primary_collocate": null, "pronunciation": "shí yàn", "ipa": "ʂɻ̩ jɛn", "syllable_count": 2, "sentences": [{"text": "研究团队为检验这一假设，专门设计了一项精密的实验，并严格记录了每一步的数据。", "target_word": "实验", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "老师在课上做了一个化学实验。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验证明了他的想法是对的。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要按步骤做实验，不能随便改。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验的结果和书上说的一样。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了三次实验，结果都不一样。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用实验来检验这个理论。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验很简单，小学生也能做。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，一定要戴上眼镜。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验数据要认真记下来。", "target_word": "实验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个实验", "label": "量词"}, {"form": "一项实验", "label": "量词"}, {"form": "一次实验", "label": "量词"}, {"form": "實驗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为验证科学理论或假设而做的一系列操作和观察", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0347f031-0355-40d8-bc8c-c972af0e07eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确答案：实验（shí yàn），指为验证科学理论或假设而进行的操作。"}, {"text": "食盐", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是食用的盐。"}, {"text": "失言", "is_correct": false, "explanation": "两个音节声调都不同（shī，第一声；yán，第二声），意思是说错话。"}, {"text": "食言", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。"}, {"text": "时延", "is_correct": false, "explanation": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。"}], "explanations": {"实验": "正确答案：实验（shí yàn），指为验证科学理论或假设而进行的操作。", "食盐": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是食用的盐。", "失言": "两个音节声调都不同（shī，第一声；yán，第二声），意思是说错话。", "食言": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是不守诺言。", "时延": "与“实验”只有第二音节声调不同（yán，第二声；yàn，第四声），意思是信号传输的延迟。"}, "sentence_index": null, "correct_answer": "实验"}, "level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确：“精密的实验”指为检验假设而设计的科学操作，与“记录每一步的数据”相符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能作为检验假设的“精密的”操作。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱指菜肴的做法，与检验科学假设无关。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：“作文”指写的文章，不能说“精密的作文”。"}], "explanations": {"实验": "正确：“精密的实验”指为检验假设而设计的科学操作，与“记录每一步的数据”相符。", "小说": "语义：小说是文学作品，不能作为检验假设的“精密的”操作。", "菜谱": "语义：菜谱指菜肴的做法，与检验科学假设无关。", "作文": "搭配：“作文”指写的文章，不能说“精密的作文”。"}, "sentence_index": 0, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行给了我很多实验。", "explanation": "这里应该用〈经验〉。实验指为验证假设而进行的操作，不指亲身经历后得到的体会。"}, {"text": "这次长途旅行给他的意志带来了很大的实验。", "explanation": "这里应该用〈考验〉。实验指科学上的验证操作，不能用来指对意志的磨练。"}, {"text": "这次失败给了他一个很大的实验。", "explanation": "这里应该用〈教训〉。实验指科学上的验证操作，不能指从失败中得到的教训。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实验", "is_correct": true, "explanation": "正确：“用实验来检验理论”是科学研究的常见做法，“实验”是检验理论的手段。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：玩笑不能用来检验科学理论，科学家需要用科学方法来检验。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”不能作为检验理论的手段，“检验”不与“感情”搭配。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能用来检验科学理论。"}], "explanations": {"实验": "正确：“用实验来检验理论”是科学研究的常见做法，“实验”是检验理论的手段。", "玩笑": "语义：玩笑不能用来检验科学理论，科学家需要用科学方法来检验。", "感情": "搭配：“感情”不能作为检验理论的手段，“检验”不与“感情”搭配。", "小说": "语义：小说是文学作品，不能用来检验科学理论。"}, "sentence_index": 6, "correct_answer": "实验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的童年实验很幸福。", "explanation": "这里应该用〈经历〉。实验指科学上的验证操作，不能指一个人的生活过程。"}, {"text": "这次调查给了我们很有力的实验。", "explanation": "这里应该用〈证据〉。实验指验证操作本身，不能指用来证明观点的材料。"}, {"text": "这本书对我的学习有很大的实验。", "explanation": "这里应该用〈启示〉。实验指科学上的验证操作，不能指给人带来的启发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们明天要做一只新的实验。", "corrected_sentence": "他们明天要做一个新的实验。", "error_description": "量词错误：“实验”应搭配量词“个”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先写实验，再写报告。", "corrected_sentence": "我们先做实验，再写报告。", "error_description": "搭配错误：“实验”应与“做”搭配，说“做实验”，不说“写实验”。“写”用于文字类对象，如“写报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23e663ea-358d-453a-a4ef-eb088c2e2768') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
