INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的东西搅在一起。", "primary_collocate": null, "pronunciation": "hùn hé", "ipa": "xuən˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "混合", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "孩子们把沙子和泥土混合在一起玩。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师把几种香料混合好了。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯饮料是用果汁和汽水混合的。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的颜料混合以后，颜色会变。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把咖啡和牛奶混合着喝。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用勺子把鸡蛋和面粉混合。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水泥和沙子混合起来。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶是红茶和花茶混合的。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别把两种清洁剂混合。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把红色和白色的颜料混合在一起，调出了粉色。", "target_word": "混合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混合了", "label": "体标"}, {"form": "混合物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把不同的东西搅在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混合", "is_correct": true, "explanation": "正确：「混合」指把红色和白色的颜料拌在一起，调出新颜色，符合句意。"}, {"text": "切开", "is_correct": false, "explanation": "语义：「切开」是把整体分割，颜料不能被切开，句意不通。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：「烘干」是去除水分，与调出粉色无关，句意不通。"}, {"text": "擦干", "is_correct": false, "explanation": "语义：「擦干」是擦去水分，与调色无关，句意不通。"}], "explanations": {"混合": "正确：「混合」指把红色和白色的颜料拌在一起，调出新颜色，符合句意。", "切开": "语义：「切开」是把整体分割，颜料不能被切开，句意不通。", "烘干": "语义：「烘干」是去除水分，与调出粉色无关，句意不通。", "擦干": "语义：「擦干」是擦去水分，与调色无关，句意不通。"}, "sentence_index": 0, "correct_answer": "混合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水在通电后混合成了氢和氧。", "explanation": "这里应该用〈分解〉。混合只是把东西拌在一起；水通电后变成氢和氧是化学变化，要用分解。"}, {"text": "他的思路很混合，讲了半天也说不清。", "explanation": "这里应该用〈混乱〉。混合指把不同的东西搅在一起；形容思路乱而无条理要用混乱。"}, {"text": "把两块布混合起来。", "explanation": "这里应该用〈拼接〉。混合用于不同物质拌在一起；把两块布接在一起要用拼接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混合", "is_correct": true, "explanation": "“混合”指用勺子把鸡蛋和面粉拌在一起，符合句子的动作。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下，鸡蛋和面粉不能被吞下，句意不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“用勺子把……”的加工动作不相符。"}, {"text": "切开", "is_correct": false, "explanation": "搭配：“切开”要用刀等工具，而且面粉不能切开，不能用勺子完成。"}], "explanations": {"混合": "“混合”指用勺子把鸡蛋和面粉拌在一起，符合句子的动作。", "吞": "语义：“吞”是咽下，鸡蛋和面粉不能被吞下，句意不通。", "扔": "语义：“扔”是丢弃，与“用勺子把……”的加工动作不相符。", "切开": "搭配：“切开”要用刀等工具，而且面粉不能切开，不能用勺子完成。"}, "sentence_index": 6, "correct_answer": "混合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个力相互混合了。", "explanation": "这里应该用〈抵消〉。混合用于实物拌在一起；作用相反而互相消除要用抵消。"}, {"text": "把病人混合起来，免得传染。", "explanation": "这里应该用〈隔离〉。混合是把东西拌在一起；为防止传染而把人分开要用隔离。"}, {"text": "他总把这两个词混合，经常用错。", "explanation": "这里应该用〈混淆〉。混合用于把东西拌在一起；把词语或概念弄错、分不清要用混淆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们已经把果汁和汽水混合。", "corrected_sentence": "他们已经把果汁和汽水混合了。", "error_description": "错误：表示动作已完成的“了”漏掉了，句子停在“混合”上，没有完成义。正确：“混合了”，“了”放在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前混合了过这种颜料。", "corrected_sentence": "我们以前混合过这种颜料。", "error_description": "错误：“了”与“过”不能同时用在动词“混合”后面。正确：“混合过这种颜料”，表示经历只用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
