INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指双方互相联系、互相作用或彼此沟通。", "primary_collocate": null, "pronunciation": "jiāo hù", "ipa": "tɕjɑʊ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "交互", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这款软件可以和用户实时交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款机器人能和孩子们交互，很受欢迎。", "target_word": "交互", "complexity_tier": "T3", "furigana": "jiāohù", "sentence_source": "generated"}, {"text": "好的网站设计让用户和页面更容易交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统能和手机应用自动交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞之间通过化学信号交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个程序需要通过接口交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里的角色可以和玩家交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语音助手能和主人用声音交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究药物如何与蛋白质交互。", "target_word": "交互", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交互式", "label": "复合"}, {"form": "交互性", "label": "复合"}], "register": "书面", "sense_fingerprint": "双方互相联系、作用、沟通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻译", "is_correct": false, "explanation": "语义：翻译是把一种语言转换成另一种语言，与记谱无关，“实时翻译记谱”说不通。"}, {"text": "交互", "is_correct": true, "explanation": "“实时交互记谱”指实时相互作用的记谱方式，“交互”修饰“记谱”，句意通顺。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭，与记谱这一音乐记录活动无关。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“实时”修饰的是信息交换类动作，“种植”不能用来修饰“记谱”。"}], "explanations": {"翻译": "语义：翻译是把一种语言转换成另一种语言，与记谱无关，“实时翻译记谱”说不通。", "交互": "“实时交互记谱”指实时相互作用的记谱方式，“交互”修饰“记谱”，句意通顺。", "烹饪": "语义：烹饪是做饭，与记谱这一音乐记录活动无关。", "种植": "搭配：“实时”修饰的是信息交换类动作，“种植”不能用来修饰“记谱”。"}, "sentence_index": 0, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气交互了三碗米饭。", "explanation": "这里应该用〈吃〉。交互指双方相互作用或彼此沟通，不能用于吃饭这类个人动作。"}, {"text": "妈妈正在交互我的衣服。", "explanation": "这里应该用〈叠〉。交互指双方相互作用，不能用于折叠衣物这类单方面动作。"}, {"text": "他把钱交互给了朋友。", "explanation": "这里应该用〈交给〉。交给指把东西递送给别人，交互指双方相互作用，不能表示物品转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张装成册，不用于程序之间，与“通过接口”不相容。"}, {"text": "交互", "is_correct": true, "explanation": "“通过接口交互”指两个程序借助接口相互作用，与句意相符。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做面包、点心，与程序之间的关系无关。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：程序之间不说“通过接口生产”，“生产”与“通过接口”不搭配。"}], "explanations": {"装订": "语义：装订是把纸张装成册，不用于程序之间，与“通过接口”不相容。", "交互": "“通过接口交互”指两个程序借助接口相互作用，与句意相符。", "烘焙": "语义：烘焙是做面包、点心，与程序之间的关系无关。", "生产": "搭配：程序之间不说“通过接口生产”，“生产”与“通过接口”不搭配。"}, "sentence_index": 6, "correct_answer": "交互"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "交互高峰时，马路上车很多。", "explanation": "这里应该用〈交通〉。交通指车辆和行人的往来，交互指双方相互联系、作用，不能用来指道路的高峰时段。"}, {"text": "乐团今晚演奏交互乐，观众很多。", "explanation": "这里应该用〈交响〉。交响乐是一种音乐形式，“交互乐”不是词，交互指双方相互作用。"}, {"text": "两条铁路在这里交互。", "explanation": "这里应该用〈交叉〉。交叉指线路相遇穿过，交互指双方相互作用，铁路不能说“交互”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个系统能够其他设备交互。", "corrected_sentence": "这个系统能够和其他设备交互。", "error_description": "介词遗漏：“交互”的对象前要加介词“和”，应说“能够和其他设备交互”，不能省略“和”直接把“其他设备”放在“交互”前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个智能音箱能和家里人很交互。", "corrected_sentence": "这个智能音箱能和家里人交互。", "error_description": "副词错误：“交互”是动词，前面不能直接加程度副词“很”，应删去“很”，说“能和家里人交互”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
