INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指周围的地方或条件，包括自然和生活中的各种事物。", "primary_collocate": null, "pronunciation": "huán jìng", "ipa": "xu̯an˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这里的环境很美，空气也很新鲜。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的水会破坏环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该保护环境，少用塑料袋。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的环境很干净，每年都有很多游客。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾太多会污染环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小鸟只能在安静的环境里生活。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林对环境很重要，不能随便砍树。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的环境越来越好，天也常常是蓝的。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物搬了家，因为原来的环境变差了。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去公园，学习怎么爱护环境。", "target_word": "环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "环境保护", "label": "复合"}, {"form": "环境污染", "label": "复合"}], "register": "中性", "sense_fingerprint": "自然和生活中周围的事物，如空气、水、森林、城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：环境指周围的自然和生活事物，与“很美，空气也很新鲜”相符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“美”不能修饰价格，“这里的价格很美”说不通。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩不是地方周围的事物，不能用“很美”或“空气新鲜”来描述。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试不是周围的自然或生活环境，与“空气也很新鲜”的语境不符。"}], "explanations": {"环境": "正确：环境指周围的自然和生活事物，与“很美，空气也很新鲜”相符。", "价格": "搭配：“美”不能修饰价格，“这里的价格很美”说不通。", "成绩": "语义：成绩不是地方周围的事物，不能用“很美”或“空气新鲜”来描述。", "考试": "语义：考试不是周围的自然或生活环境，与“空气也很新鲜”的语境不符。"}, "sentence_index": 0, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间里的环境很高，我们都出了很多汗。", "explanation": "这里应该用〈温度〉。环境指周围的地方和条件，不用“高”形容温度高低；说温度高才自然。"}, {"text": "会场里的环境很热烈，大家都很兴奋。", "explanation": "这里应该用〈气氛〉。环境指周围的地方和条件，不用“热烈”形容；说气氛热烈才自然。"}, {"text": "这间屋子的环境很大，很适合练舞。", "explanation": "这里应该用〈空间〉。环境指周围的自然或生活条件，不用来说面积大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "环境", "is_correct": true, "explanation": "正确：森林对环境很重要，与“不能随便砍树”的保护语境相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资与森林没有这种关系，“森林对工资很重要”说不通。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说不是森林能影响的事物，“森林对小说很重要”与语境不符。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“对……很重要，不能随便砍树”的对象应是生态或生存条件，“房价”无法构成这种搭配。"}], "explanations": {"环境": "正确：森林对环境很重要，与“不能随便砍树”的保护语境相符。", "工资": "语义：工资与森林没有这种关系，“森林对工资很重要”说不通。", "小说": "语义：小说不是森林能影响的事物，“森林对小说很重要”与语境不符。", "房价": "搭配：“对……很重要，不能随便砍树”的对象应是生态或生存条件，“房价”无法构成这种搭配。"}, "sentence_index": 6, "correct_answer": "环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的环境很周到，大家都很满意。", "explanation": "这里应该用〈服务〉。环境指周围的地方和条件，不用“周到”形容；说服务周到才自然。"}, {"text": "这套房子的环境很大，采光也好。", "explanation": "这里应该用〈面积〉。环境指周围的自然或生活条件，不说面积大小。"}, {"text": "他的环境很幽默，大家都爱听。", "explanation": "这里应该用〈讲话〉。环境指周围的地方和条件，不用来形容人的讲话风格；说讲话幽默才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座环境很美，适合人们散步。", "corrected_sentence": "这种环境很美，适合人们散步。", "error_description": "错误：“座”用于山、楼、桥等大型固定事物，不能修饰环境；正确的量词是“种”，应说“这种环境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里地环境很干净，大家都愿意来。", "corrected_sentence": "这里的环境很干净，大家都愿意来。", "error_description": "错误：修饰名词“环境”应用“的”，“地”用于修饰动词或形容词，不能修饰名词；应说“这里的环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
