INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指示和命令，通常指计算机或上级发出的要求执行的命令。", "primary_collocate": null, "pronunciation": "zhǐ lìng", "ipa": "ʈʂɨ˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "传统五线谱仍是全球通行的技术语言，支撑着交响乐团、歌剧制作与学院派作曲教学；而在实验音乐领域，混合媒介记谱、实时交互记谱（如Max/MSP环境下的视觉指令）正不断拓展边界。", "target_word": "指令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电脑只会按指令做事。", "target_word": "指令", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "程序员给机器输入了一条新指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机收到指令后，马上打开了灯。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器人听懂了我的语音指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台电脑没有执行你的指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在屏幕上输入指令。", "target_word": "指令", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "指令太长，机器处理得很慢。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏里的每个动作都由一条指令控制。", "target_word": "指令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写错了一条指令，程序停了下来。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条指令", "label": "量词"}, {"form": "语音指令", "label": "复合"}, {"form": "指令集", "label": "复合"}], "register": "中性", "sense_fingerprint": "指令：计算机等设备接收并执行的命令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3370b77-fb49-4e42-b46b-5b0a583e1654') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：视觉指令指软件环境中可见的执行命令，与“Max/MSP环境”相合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能作为软件环境中的视觉命令。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，与软件环境和记谱无关。"}, {"text": "湖泊", "is_correct": false, "explanation": "搭配：“视觉”后面不能接“湖泊”这类自然景观，词组说不通。"}], "explanations": {"指令": "正确：视觉指令指软件环境中可见的执行命令，与“Max/MSP环境”相合。", "蛋糕": "语义：蛋糕是食物，不能作为软件环境中的视觉命令。", "雨伞": "语义：雨伞是日用品，与软件环境和记谱无关。", "湖泊": "搭配：“视觉”后面不能接“湖泊”这类自然景观，词组说不通。"}, "sentence_index": 0, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "程序员写了一只指令，程序就能运行。", "explanation": "这里应该用〈条〉。〈只〉用于动物和成对的物品，指令不能用〈只〉来计量。"}, {"text": "手机收到一条指令，说明天停电。", "explanation": "这里应该用〈通知〉。指令是设备接收并执行的命令，不是用来告知消息的；告知停电要用〈通知〉。"}, {"text": "手机发来一条指令，提醒我带伞。", "explanation": "这里应该用〈提示〉。指令是设备接收并执行的命令，不是用来对人发出的提示；告诉人带伞要用〈提示〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：在屏幕上输入的是计算机能执行的指令，与“输入”相合。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘是输入工具，本身不是可以输入到屏幕上的内容。"}, {"text": "鼠标", "is_correct": false, "explanation": "语义：鼠标是输入工具，本身不是可以输入到屏幕上的内容。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景观，不能作为在屏幕上输入的内容。"}], "explanations": {"指令": "正确：在屏幕上输入的是计算机能执行的指令，与“输入”相合。", "键盘": "语义：键盘是输入工具，本身不是可以输入到屏幕上的内容。", "鼠标": "语义：鼠标是输入工具，本身不是可以输入到屏幕上的内容。", "天空": "语义：天空是自然景观，不能作为在屏幕上输入的内容。"}, "sentence_index": 6, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写了一把指令，程序就停了下来。", "explanation": "这里应该用〈条〉。〈把〉用于有柄的器具，指令不能用〈把〉计量。"}, {"text": "他向老师提出了一个指令，希望延期交作业。", "explanation": "这里应该用〈请求〉。指令是计算机或上级发出、必须执行的命令，学生向老师提出的希望属于〈请求〉。"}, {"text": "他给同事提了一个指令，希望他们改进程序。", "explanation": "这里应该用〈建议〉。指令必须执行，同事之间提出改进意见要用〈建议〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师给机器写了一把新指令。", "corrected_sentence": "工程师给机器写了一条新指令。", "error_description": "量词错误：“指令”应用“条”计量。“把”用于有柄的器具，应改为“一条新指令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "程序员检查了这只指令。", "corrected_sentence": "程序员检查了这条指令。", "error_description": "量词错误：“指令”应用“条”计量。“只”用于动物等，应改为“这条指令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13ab7b39-29ac-4c7b-9c96-7e4f274fce82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
