INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10846, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示恰好、刚好，多指时间、位置或数量上正好吻合。", "primary_collocate": null, "pronunciation": "zhèng", "ipa": "ʈʂɤŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这件衣服大小正合适。", "target_word": "正", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你来得正是时候，饭刚做好。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我正想给你打电话，你就来了。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的话正是我心里想的。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我正需要一支笔，你就借给我了。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间的灯光不亮不暗，正适合看书。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他伸手一接，球正落在他手里。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问的问题，正是昨天讲的内容。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我正愁没有人帮忙，你就来了。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些菜的分量正够我们三个人吃。", "target_word": "正", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示恰好、刚好（正合适、正是、正想）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd15d400-ff1c-4929-b18e-ebdd0160fea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正", "is_correct": true, "explanation": "正（zhèng）：副词，表示恰好、刚好。"}, {"text": "整", "is_correct": false, "explanation": "整（zhěng，第三声）与 zhèng（第四声）声调不同，意思是完整。"}, {"text": "争", "is_correct": false, "explanation": "争（zhēng，第一声）与 zhèng 声调不同，意思是争夺。"}, {"text": "阵", "is_correct": false, "explanation": "阵（zhèn）与 zhèng 韵母不同（en 与 eng），意思是一阵子。"}, {"text": "账", "is_correct": false, "explanation": "账（zhàng）与 zhèng 韵母不同（ang 与 eng），意思是账目。"}], "explanations": {"正": "正（zhèng）：副词，表示恰好、刚好。", "整": "整（zhěng，第三声）与 zhèng（第四声）声调不同，意思是完整。", "争": "争（zhēng，第一声）与 zhèng 声调不同，意思是争夺。", "阵": "阵（zhèn）与 zhèng 韵母不同（en 与 eng），意思是一阵子。", "账": "账（zhàng）与 zhèng 韵母不同（ang 与 eng），意思是账目。"}, "sentence_index": null, "correct_answer": "正"}, "level_3": {"options": [{"text": "正", "is_correct": true, "explanation": "正：副词，表示恰好，与“大小”搭配说明尺寸刚好合适。"}, {"text": "老是", "is_correct": false, "explanation": "语义：“老是”多带抱怨、重复的负面语气，与“合适”这种正面评价不协调。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时候，而衣服的大小是稳定状态，不能时有时无。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”否定“合适”，句意变为衣服大小不合适，与原句的肯定评价相反。"}], "explanations": {"正": "正：副词，表示恰好，与“大小”搭配说明尺寸刚好合适。", "老是": "语义：“老是”多带抱怨、重复的负面语气，与“合适”这种正面评价不协调。", "偶尔": "语义：“偶尔”表示有时候，而衣服的大小是稳定状态，不能时有时无。", "不": "语义：“不”否定“合适”，句意变为衣服大小不合适，与原句的肯定评价相反。"}, "sentence_index": 0, "correct_answer": "正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的管理很正。", "explanation": "这里应该用〈正规〉。正规指合乎标准规范，应说“管理很正规”；〈正〉单用时不表示规范义，这里不能这样说。"}, {"text": "这份文件要用正的格式写。", "explanation": "这里应该用〈正式〉。正式指符合规定的标准形式，“正的格式”不这么说；〈正〉在此不表示正式义。"}, {"text": "他对这次改革持正态度。", "explanation": "这里应该用〈公正〉。〈正〉在此表示公正（持正），属另一义项，不是恰好义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正", "is_correct": true, "explanation": "正（zhèng）：副词，表示恰好、刚好。"}, {"text": "蒸", "is_correct": false, "explanation": "蒸（zhēng，第一声）与 zhèng 声调不同，意思是蒸煮。"}, {"text": "镇", "is_correct": false, "explanation": "镇（zhèn）与 zhèng 韵母不同（en 与 eng），意思是城镇。"}, {"text": "撑", "is_correct": false, "explanation": "撑（chēng）与 zhèng 声母不同（ch 与 zh），声调也不同，意思是支撑。"}, {"text": "盛", "is_correct": false, "explanation": "盛（shèng）与 zhèng 声母不同（sh 与 zh），声调相同，意思是兴盛。"}], "explanations": {"正": "正（zhèng）：副词，表示恰好、刚好。", "蒸": "蒸（zhēng，第一声）与 zhèng 声调不同，意思是蒸煮。", "镇": "镇（zhèn）与 zhèng 韵母不同（en 与 eng），意思是城镇。", "撑": "撑（chēng）与 zhèng 声母不同（ch 与 zh），声调也不同，意思是支撑。", "盛": "盛（shèng）与 zhèng 声母不同（sh 与 zh），声调相同，意思是兴盛。"}, "sentence_index": null, "correct_answer": "正"}, "level_3": {"options": [{"text": "正", "is_correct": true, "explanation": "正：副词，表示恰好，说明球刚好落在他手中。"}, {"text": "必须", "is_correct": false, "explanation": "搭配：“必须”用于表示人的义务或必要性，球的落点不受人控制，搭配不当。"}, {"text": "没", "is_correct": false, "explanation": "语义：“没”否定动作，球没落在他手里与“伸手一接”的结果相反。"}, {"text": "也许", "is_correct": false, "explanation": "语义：“也许”表示推测，而“伸手一接”描述已经发生的事实，语义冲突。"}], "explanations": {"正": "正：副词，表示恰好，说明球刚好落在他手中。", "必须": "搭配：“必须”用于表示人的义务或必要性，球的落点不受人控制，搭配不当。", "没": "语义：“没”否定动作，球没落在他手里与“伸手一接”的结果相反。", "也许": "语义：“也许”表示推测，而“伸手一接”描述已经发生的事实，语义冲突。"}, "sentence_index": 6, "correct_answer": "正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的体温很正，没有发烧。", "explanation": "这里应该用〈正常〉。正常指符合一般标准，应说“体温正常”；〈正〉不表示正常义，这里不能这样说。"}, {"text": "这家店的烤鸭是正的北京风味。", "explanation": "这里应该用〈正宗〉。正宗指地道、纯正，“正的风味”不这么说；〈正〉在此不表示地道义。"}, {"text": "他是个正的人，从不说假话。", "explanation": "这里应该用〈正直〉。〈正〉在此表示正直，属另一义项，不是恰好义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋大小正很合适。", "corrected_sentence": "这双鞋大小正合适。", "error_description": "“正”是副词，修饰形容词“合适”时不能再与副词“很”叠用，应去掉“很”，说“大小正合适”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一到家，饭正的做好了。", "corrected_sentence": "我一到家，饭正做好了。", "error_description": "“正”是副词，修饰动词，后面不能加结构助词“的”，应说“饭正做好了”，不能说“饭正的做好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
