INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用符号和规则研究推理和论证的学科，是数学和逻辑学的基础。", "primary_collocate": null, "pronunciation": "fú hào luó jí", "ipa": "fu˧˥ xɑʊ˥˩ lwo˧˥ tɕi˧˥", "syllable_count": 4, "sentences": [{"text": "值得注意的是，人工智能介入音乐创作后，机器生成的乐谱常融合符号逻辑与概率模型，引发关于“可读性”与“可演性”的新讨论。", "target_word": "符号逻辑", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大学的数学系开了一门符号逻辑课。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑用符号和规则研究推理。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里主修符号逻辑。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学符号逻辑要先认识各种符号。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "符号逻辑帮助人们检查论证对不对。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了符号逻辑的基本规则。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好符号逻辑，对写程序很有帮助。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用符号逻辑证明了这个结论。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计算机科学也要用到符号逻辑。", "target_word": "符号逻辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "符號邏輯", "label": "繁体"}, {"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "用符号和规则研究推理论证的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是用符号和规则研究推理的学科，与概率模型并列，正是乐谱融合的两种理论工具。"}, {"text": "画面", "is_correct": false, "explanation": "语义：乐谱融合的是符号逻辑与概率模型这类理论工具，“画面”属于视觉内容，与人工智能音乐创作的语境不符。"}, {"text": "厨艺", "is_correct": false, "explanation": "语义：厨艺是烹饪技能，与乐谱、音乐创作和概率模型的语境完全无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语体不协调，也不指可以融合进乐谱的理论。"}], "explanations": {"符号逻辑": "符号逻辑是用符号和规则研究推理的学科，与概率模型并列，正是乐谱融合的两种理论工具。", "画面": "语义：乐谱融合的是符号逻辑与概率模型这类理论工具，“画面”属于视觉内容，与人工智能音乐创作的语境不符。", "厨艺": "语义：厨艺是烹饪技能，与乐谱、音乐创作和概率模型的语境完全无关。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语体不协调，也不指可以融合进乐谱的理论。"}, "sentence_index": 0, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很有符号逻辑。", "explanation": "这里应该用〈道理〉：“很有道理”指说话有根据、合情理；符号逻辑是研究符号推理的学科，不能用来形容说话。"}, {"text": "今年大学开了一本符号逻辑。", "explanation": "这里量词用错。符号逻辑是学科，计量用〈门〉（一门符号逻辑课）；“本”用于书籍。"}, {"text": "他是一位符号逻辑。", "explanation": "这里应该用〈学家〉：研究它的人要说“符号逻辑学家”；“符号逻辑”本身是学科，不指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号逻辑", "is_correct": true, "explanation": "符号逻辑是有完整规则体系的学科，书中介绍它的基本规则，搭配正确。"}, {"text": "水稻", "is_correct": false, "explanation": "语义：水稻是农作物，不是有基本规则体系的学科，书中不会介绍它的规则。"}, {"text": "晚霞", "is_correct": false, "explanation": "语义：晚霞是天象，不存在可以被书籍介绍的“基本规则”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形外貌，与“基本规则”搭配不当，整句不通。"}], "explanations": {"符号逻辑": "符号逻辑是有完整规则体系的学科，书中介绍它的基本规则，搭配正确。", "水稻": "语义：水稻是农作物，不是有基本规则体系的学科，书中不会介绍它的规则。", "晚霞": "语义：晚霞是天象，不存在可以被书籍介绍的“基本规则”。", "身材": "体貌：“身材”指人的体形外貌，与“基本规则”搭配不当，整句不通。"}, "sentence_index": 6, "correct_answer": "符号逻辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气跑完了符号逻辑。", "explanation": "这里应该用〈学完〉：“跑完”的对象是路程或比赛，符号逻辑是学科，只能“学完”，不能“跑完”。"}, {"text": "这个符号逻辑很好吃。", "explanation": "这里“符号逻辑”指学科，不能当作食物；“好吃”形容饭菜，应说〈菜〉。"}, {"text": "他用符号逻辑修好了水管。", "explanation": "这里“符号逻辑”指学科，不能当作工具使用，它也不是修理水管的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这学期我选了一本符号逻辑。", "corrected_sentence": "这学期我选了一门符号逻辑。", "error_description": "量词错误：学科应用“门”，“本”用于书籍。应为“选了一门符号逻辑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我符号逻辑分析了这个论证。", "corrected_sentence": "我用符号逻辑分析了这个论证。", "error_description": "介词漏用：表示工具要用“用”引出，应为“用符号逻辑分析”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
