INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用数学公式和规则来表示不确定事件发生可能性的模型。", "primary_collocate": null, "pronunciation": "gài lǜ mó xíng", "ipa": "kaɪ˥˩ ly˥˩ mwo˧˥ ɕiŋ˧˥", "syllable_count": 4, "sentences": [{"text": "值得注意的是，人工智能介入音乐创作后，机器生成的乐谱常融合符号逻辑与概率模型，引发关于“可读性”与“可演性”的新讨论。", "target_word": "概率模型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气预报常用概率模型计算下雨的可能。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型能预测明天的客流量。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在训练一个新的概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "概率模型把不确定的事写成公式。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行用概率模型判断客户是否会还款。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文提出了一种新的概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的概率模型需要大量真实数据。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用概率模型估计病人的风险。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "概率模型的结果和实际情况差不多。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "用公式表示不确定事件可能性的模型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a267b60a-1885-4776-a101-f0f8d7d64538') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "概率模型用数学公式表示不确定事件的可能性，与符号逻辑并列，正是乐谱融合的另一种理论工具。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材是建材，与音乐创作和乐谱融合无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语体不协调。"}, {"text": "黄昏", "is_correct": false, "explanation": "语义：黄昏是一段时间，不能作为与符号逻辑并列的理论工具融合进乐谱。"}], "explanations": {"概率模型": "概率模型用数学公式表示不确定事件的可能性，与符号逻辑并列，正是乐谱融合的另一种理论工具。", "木材": "语义：木材是建材，与音乐创作和乐谱融合无关。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语体不协调。", "黄昏": "语义：黄昏是一段时间，不能作为与符号逻辑并列的理论工具融合进乐谱。"}, "sentence_index": 0, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛我赢的概率模型很高。", "explanation": "这里应该用〈可能性〉：“赢的可能性很高”指胜算大；概率模型是数学工具，不能表示赢的可能。"}, {"text": "工程师做了一次概率模型。", "explanation": "这里量词用错。概率模型是可以建立的工具，计量用〈个〉；“次”用于动作或事件。"}, {"text": "妈妈把概率模型放进了冰箱。", "explanation": "这里“概率模型”是数学方法，是抽象的工具，不是实物，放不进冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "概率模型是数学工具，论文可以提出一种新的概率模型，搭配正确。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，论文不会提出一种白菜。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是地理实体，不是论文能够提出的理论或方法。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，论文提出的是理论或方法，两者不搭配。"}], "explanations": {"概率模型": "概率模型是数学工具，论文可以提出一种新的概率模型，搭配正确。", "白菜": "语义：白菜是蔬菜，论文不会提出一种白菜。", "河流": "语义：河流是地理实体，不是论文能够提出的理论或方法。", "身材": "体貌：“身材”指人的体形，论文提出的是理论或方法，两者不搭配。"}, "sentence_index": 6, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病人的概率模型很严重。", "explanation": "这里应该用〈病情〉。“很严重”形容病况；概率模型是数学工具，不能描述病人。"}, {"text": "这部电影的概率模型很精彩。", "explanation": "这里应该用〈剧情〉：“很精彩”形容电影的剧情；概率模型是数学工具，不能用来评价电影。"}, {"text": "这个概率模型在超市里免费送。", "explanation": "这里“概率模型”指数学方法，不是可以在超市派送的商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们建了一只概率模型。", "corrected_sentence": "我们建了一个概率模型。", "error_description": "量词错误：模型应用“个”，“只”用于动物。应为“建了一个概率模型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识那位研究概率模型老师。", "corrected_sentence": "我认识那位研究概率模型的老师。", "error_description": "“的”漏用：“研究概率模型”修饰“老师”时需要“的”，应为“研究概率模型的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47ad4767-8d50-4f59-aa84-f650a055e637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
