INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指文字作品容易理解和吸引人的程度。", "primary_collocate": null, "pronunciation": "kě dú xìng", "ipa": "kʰɤ˨˩ tu˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "值得注意的是，人工智能介入写作后，机器生成的文本常融合符号逻辑与概率模型，引发关于“可读性”与“准确性”的新讨论。", "target_word": "可读性", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这篇文章的可读性很高，我一口气读完了。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写文章要注意可读性。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本小说语言生动，可读性很强。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "句子太长会影响文章的可读性。", "target_word": "可读性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编辑建议作者删掉难懂的词，提高可读性。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告图表清楚，可读性比上一份好。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的新闻稿既要准确，又要有可读性。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的博客故事有趣，可读性很好，读者很多。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译不但要准确，也要考虑译文的可读性。", "target_word": "可读性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可讀性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "文字作品容易理解、吸引读者的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可读性", "is_correct": true, "explanation": "正确。“可读性”指文字作品容易理解、吸引人的程度，与句中的“准确性”并列，正好放进“关于……的新讨论”。"}, {"text": "可燃性", "is_correct": false, "explanation": "语义：“可燃性”说的是物质能不能燃烧，与文本和写作的讨论毫无关系。"}, {"text": "可溶性", "is_correct": false, "explanation": "语域：“可溶性”是化学术语，不适合这段谈论音乐创作的书面语。"}, {"text": "可食性", "is_correct": false, "explanation": "语义：“可食性”指能否食用，与文本的符号逻辑、概率模型无关。"}], "explanations": {"可读性": "正确。“可读性”指文字作品容易理解、吸引人的程度，与句中的“准确性”并列，正好放进“关于……的新讨论”。", "可燃性": "语义：“可燃性”说的是物质能不能燃烧，与文本和写作的讨论毫无关系。", "可溶性": "语域：“可溶性”是化学术语，不适合这段谈论音乐创作的书面语。", "可食性": "语义：“可食性”指能否食用，与文本的符号逻辑、概率模型无关。"}, "sentence_index": 0, "correct_answer": "可读性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片的可读性很高，远处的人脸都看得很清楚。", "explanation": "这里应该用〈清晰度〉。可读性只用于文字作品，照片、图像的清楚程度要说清晰度。"}, {"text": "这段录音的可读性很好，连细小的声音都听得见。", "explanation": "这里应该用〈音质〉。可读性只说文字作品，录音的好坏要用音质。"}, {"text": "这台机器的可读性很高，用了十年都没有坏过。", "explanation": "这里应该用〈可靠性〉。可读性只用于文字作品，机器能否长期稳定工作要说可靠性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可读性", "is_correct": true, "explanation": "正确。句中说报告图表清楚，所以比较的是报告的“可读性”，即文字作品容易看懂的程度。"}, {"text": "导电性", "is_correct": false, "explanation": "语义：“导电性”指导电的能力，报告图表清楚与否不谈导电，句意不通。"}, {"text": "放射性", "is_correct": false, "explanation": "搭配：“比上一份好”评价的是易读这类品质，不与“放射性”搭配。"}, {"text": "可塑性", "is_correct": false, "explanation": "语义：“可塑性”指材料能否塑形，用来比较两份报告没有意义。"}], "explanations": {"可读性": "正确。句中说报告图表清楚，所以比较的是报告的“可读性”，即文字作品容易看懂的程度。", "导电性": "语义：“导电性”指导电的能力，报告图表清楚与否不谈导电，句意不通。", "放射性": "搭配：“比上一份好”评价的是易读这类品质，不与“放射性”搭配。", "可塑性": "语义：“可塑性”指材料能否塑形，用来比较两份报告没有意义。"}, "sentence_index": 6, "correct_answer": "可读性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章有一把很强的可读性，大家都愿意读。", "explanation": "这里不能用量词〈把〉。〈把〉用于有柄的器具，可读性是抽象名词，不能这样计量，应直接说“很强的可读性”。"}, {"text": "这份报告有一张很好的可读性，看起来很舒服。", "explanation": "这里不能用量词〈张〉。〈张〉用于纸、图片等平面的东西，可读性不能用它计量。"}, {"text": "这本词典有一只很高的可读性，查起来很方便。", "explanation": "这里不能用量词〈只〉。〈只〉用于动物或成对器物中的一个，可读性不能用它计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本教材的可读性高很，学生都能看懂。", "corrected_sentence": "这本教材的可读性很高，学生都能看懂。", "error_description": "“高很”语序错误，应说“很高”。形容词作谓语时前面要加“很”，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典的可读性好很，初学者也能用。", "corrected_sentence": "这本词典的可读性很好，初学者也能用。", "error_description": "语序错误。形容词“好”作谓语时，“很”要放在前面，应说“很好”，不能说“好很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物本身，区别于它的表现、作用或关系。", "primary_collocate": null, "pronunciation": "běn tǐ", "ipa": "pən˨˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "从历史维度审视，记谱不仅是技术工具的演进，更是音乐本体观念变迁的镜像——它既塑造了作曲家的想象方式，也重构了听觉经验的文化编码。", "target_word": "本体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "讨论一个现象时，先要分清它的本体和表面的变化。", "target_word": "本体", "complexity_tier": "T3", "furigana": "tǎo lùn yí ge xiàn xiàng shí, xiān yào fēn qīng tā de běn tǐ hé biǎo miàn de biàn huà.", "sentence_source": "generated"}, {"text": "哲学课上，老师讲什么是事物的本体。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子里的像不是本体，只是它的影子。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究艺术时，不能只看作品的作用，也要看它的本体。", "target_word": "本体", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "哲学家把事物的本体和它的表现分开来谈。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影子会变，可是物体的本体不会变。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章只谈社会关系，没有谈人的本体。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者问：声音的本体到底是什么？", "target_word": "本体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究的不是音乐的作用，而是音乐本体。", "target_word": "本体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本體", "label": "繁体"}, {"form": "本体论", "label": "复合"}], "register": "书面语", "sense_fingerprint": "事物本身，区别于表现、作用、关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“音乐本体观念”指音乐作为事物本身的观念，与句中的“表现”“作用”相对。"}, {"text": "体能", "is_correct": false, "explanation": "语义：“体能”指身体的力量和耐力，与音乐观念的变迁无关。"}, {"text": "血压", "is_correct": false, "explanation": "语义：“血压”是人体的生理指标，音乐观念不说血压。"}, {"text": "本钱", "is_correct": false, "explanation": "语义：“本钱”指资本、本金，“音乐本钱观念”说不通。"}], "explanations": {"本体": "正确。“音乐本体观念”指音乐作为事物本身的观念，与句中的“表现”“作用”相对。", "体能": "语义：“体能”指身体的力量和耐力，与音乐观念的变迁无关。", "血压": "语义：“血压”是人体的生理指标，音乐观念不说血压。", "本钱": "语义：“本钱”指资本、本金，“音乐本钱观念”说不通。"}, "sentence_index": 0, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的本体很善良，大家都喜欢他。", "explanation": "这里应该用〈本质〉。本体偏重哲学上事物本身的存在，说人的根本性格要用本质。"}, {"text": "这次谈判的本体是利益分配的问题。", "explanation": "这里应该用〈实质〉。本体指事物本身的存在，说事情的根本内容要用实质。"}, {"text": "这篇文章的本体是作者的童年经历。", "explanation": "这里应该用〈核心〉。本体用于哲学上的存在本身，说文章的中心内容要用核心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本体", "is_correct": true, "explanation": "正确。“物体的本体”指物体本身，不随影子的变化而变化，正好与“影子会变”形成对比。"}, {"text": "心情", "is_correct": false, "explanation": "语义：物体没有心情，句中说的是物体本身的属性。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄会随时间变化，与“不会变”的句意直接矛盾。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物，不能与“物体”搭配。"}], "explanations": {"本体": "正确。“物体的本体”指物体本身，不随影子的变化而变化，正好与“影子会变”形成对比。", "心情": "语义：物体没有心情，句中说的是物体本身的属性。", "年龄": "语义：年龄会随时间变化，与“不会变”的句意直接矛盾。", "口味": "搭配：“口味”用于食物，不能与“物体”搭配。"}, "sentence_index": 6, "correct_answer": "本体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学者写了一块本体，讨论得很仔细。", "explanation": "这里不能用量词〈块〉。〈块〉用于有形的块状物，本体是抽象概念，不能这样计量，应直接说“本体”。"}, {"text": "哲学课上讲了一张本体，大家都没听懂。", "explanation": "这里不能用量词〈张〉。〈张〉用于纸、桌子等平面的东西，本体是抽象概念，不能用它计量。"}, {"text": "他研究了一股本体，写了很长的论文。", "explanation": "这里不能用量词〈股〉。〈股〉用于气味、力量等，本体是抽象概念，不能用它计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "分析一件事，要先找出它的本体论。", "corrected_sentence": "分析一件事，要先找出它的本体。", "error_description": "“本体论”是哲学学科的名称，指关于存在的理论，不指事物本身；这里应说“本体”，多了“论”就错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书只讨论事物的本体们，不谈现象。", "corrected_sentence": "这本书只讨论事物的本体，不谈现象。", "error_description": "“本体们”错误。“本体”是抽象名词，不能加“们”表示复数，这里应直接说“事物的本体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
