INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指声音刺激耳朵引起的感觉，即听力。", "primary_collocate": null, "pronunciation": "tīng jué", "ipa": "tʰiŋ˥ tɕyɛ˧˥", "syllable_count": 2, "sentences": [{"text": "从历史维度审视，记谱不仅是技术工具的演进，更是音乐本体观念变迁的镜像——它既塑造了作曲家的想象方式，也重构了听觉经验的文化编码。", "target_word": "听觉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "狗的听觉比人好得多。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年纪大了，听觉不如以前好。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间戴耳机会伤害听觉。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盲人的听觉往往很灵敏。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生检查了我的听觉，一切正常。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会不但是听觉的享受，也是心灵的享受。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝙蝠靠听觉在黑夜里飞行。", "target_word": "听觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "视觉和听觉都是人认识世界的方式。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音太大会让孩子的听觉变差。", "target_word": "听觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "聽覺", "label": "繁体"}, {"form": "听觉器官", "label": "复合"}, {"form": "听觉神经", "label": "复合"}], "register": "通用", "sense_fingerprint": "声音刺激耳朵引起的感觉，即听力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味觉", "is_correct": false, "explanation": "语义：句子谈的是音乐记谱与作曲想象，“味觉”指舌头尝味道的感觉，与音乐的文化编码不相合。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉经验”指听音乐时的感受，与记谱、作曲想象的语境相合。"}, {"text": "嗅觉", "is_correct": false, "explanation": "语义：“嗅觉”指鼻子闻气味的能力，与句中讲的音乐经验不符。"}, {"text": "触觉", "is_correct": false, "explanation": "搭配：“触觉经验”多指皮肤接触的感受，不宜与“音乐本体观念”的文化编码搭配。"}], "explanations": {"味觉": "语义：句子谈的是音乐记谱与作曲想象，“味觉”指舌头尝味道的感觉，与音乐的文化编码不相合。", "听觉": "正确：“听觉经验”指听音乐时的感受，与记谱、作曲想象的语境相合。", "嗅觉": "语义：“嗅觉”指鼻子闻气味的能力，与句中讲的音乐经验不符。", "触觉": "搭配：“触觉经验”多指皮肤接触的感受，不宜与“音乐本体观念”的文化编码搭配。"}, "sentence_index": 0, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次期末考试的听觉部分我没答好。", "explanation": "这里应该用〈听力〉。考试的“听力部分”指听录音作答，“听觉”指耳朵感知声音的能力，不能用来指考题。"}, {"text": "我对这个小镇的听觉很好。", "explanation": "这里应该用〈感觉〉。对地方的印象要说“感觉”，“听觉”只指听声音的能力，不能表示对小镇的印象。"}, {"text": "这首交响曲给我带来了很深的听觉。", "explanation": "这里应该用〈感受〉。对作品的体会要说“感受”，“听觉”指感知声音的能力，不能指这种体会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，音乐会不是可以称重的东西，“体重的享受”句意不通。"}, {"text": "听觉", "is_correct": true, "explanation": "正确：“听觉的享受”与音乐会的内容相合，与“心灵的享受”形成对应。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“享受”不与“价格”搭配，票价高低不能说成享受的价格，句意不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，与音乐会的享受无关，“温度的享受”说不通。"}], "explanations": {"体重": "语义：“体重”指人或物的重量，音乐会不是可以称重的东西，“体重的享受”句意不通。", "听觉": "正确：“听觉的享受”与音乐会的内容相合，与“心灵的享受”形成对应。", "价格": "搭配：“享受”不与“价格”搭配，票价高低不能说成享受的价格，句意不通。", "温度": "语义：“温度”指冷热程度，与音乐会的享受无关，“温度的享受”说不通。"}, "sentence_index": 6, "correct_answer": "听觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一颗很灵敏的听觉。", "explanation": "这里应该用〈种〉。听觉是抽象的能力，不用“颗”来计量；“颗”多用于小而圆的东西。"}, {"text": "她有一座很灵的听觉，能听出远处的脚步声。", "explanation": "这里应该用〈种〉。“座”用于山、桥等大型建筑，不能用来计量听觉。"}, {"text": "妈妈有一条很好的听觉。", "explanation": "这里应该用〈种〉。“条”多用于细长的东西，计量听觉要用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的听觉变很灵敏。", "corrected_sentence": "他的听觉变得很灵敏。", "error_description": "错误：“变”与后面的形容词之间要用“得”连接，应说“变得很灵敏”，不能省去“得”而说“变很灵敏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹有一把很灵的听觉。", "corrected_sentence": "我妹妹有一种很灵的听觉。", "error_description": "错误：“听觉”前的量词用了“把”。“把”多用于有手柄的器具，计量抽象的听觉要用“种”。正确形式是“有一种很灵的听觉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
