INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按照预先设定的规则，把文字、数字或信息转换成特定符号或信号的过程；也指由此形成的一套符号规则。", "primary_collocate": null, "pronunciation": "biān mǎ", "ipa": "piɛn˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "这套老程序使用的编码，新系统已经无法识别。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频文件的编码需要一些时间。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的编码方式会影响图片的大小。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段文字出现乱码，是因为编码不对。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑先完成编码，再把信息传出去。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站使用统一的编码，所以每个字都能看清。", "target_word": "编码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查音乐文件的编码。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "编码的规则要先定好，别人才能读懂。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "通过编码，声音变成了一串数字。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机发送照片前，会先对照片进行编码。", "target_word": "编码", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "編碼", "label": "繁体"}, {"form": "编码器", "label": "复合"}, {"form": "套", "label": "量词"}], "register": "书面语", "sense_fingerprint": "按规则把信息转换成符号或信号的过程，或所用的一套符号规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”指烹饪的菜单，不能作为程序所用的规则。"}, {"text": "编码", "is_correct": true, "explanation": "正确：“编码”指程序所用的一套符号规则，与“新系统无法识别”的语境相合。"}, {"text": "血型", "is_correct": false, "explanation": "语义：“血型”是人体的生理分类，不能作为程序所用的规则。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“程序所用的体重”不成词，“体重”不能修饰“程序”。"}], "explanations": {"食谱": "语义：“食谱”指烹饪的菜单，不能作为程序所用的规则。", "编码": "正确：“编码”指程序所用的一套符号规则，与“新系统无法识别”的语境相合。", "血型": "语义：“血型”是人体的生理分类，不能作为程序所用的规则。", "体重": "搭配：“程序所用的体重”不成词，“体重”不能修饰“程序”。"}, "sentence_index": 0, "correct_answer": "编码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个程序用了一朵新的编码。", "explanation": "这里应该用〈套〉。“朵”用于花朵，不能计量编码规则；编码指一整套规则，量词用“套”。"}, {"text": "我们公司采用了一封统一的编码。", "explanation": "这里应该用〈套〉。“封”用于信件，不能计量编码；计量编码规则要用“套”。"}, {"text": "他设计了一座新的编码。", "explanation": "这里应该用〈套〉。“座”用于大型建筑或山桥，不能用来计量编码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“音乐文件的颜色”说不通，颜色不是音乐文件的编码属性。"}, {"text": "编码", "is_correct": true, "explanation": "正确：检查音乐文件时，要看的是文件所用的编码方式，与句意相合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或动物的高度，不能用来描述音乐文件。"}, {"text": "字号", "is_correct": false, "explanation": "搭配：“字号”只用来说文字的大小，不宜修饰“音乐文件”的属性。"}], "explanations": {"颜色": "语义：“音乐文件的颜色”说不通，颜色不是音乐文件的编码属性。", "编码": "正确：检查音乐文件时，要看的是文件所用的编码方式，与句意相合。", "身高": "语义：“身高”指人或动物的高度，不能用来描述音乐文件。", "字号": "搭配：“字号”只用来说文字的大小，不宜修饰“音乐文件”的属性。"}, "sentence_index": 6, "correct_answer": "编码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一句话编码了全文的内容。", "explanation": "这里应该用〈概括〉。概括是提炼要点；编码是用符号代表信息，不能用来指提炼全文。"}, {"text": "我把这封英文信编码成中文，给母亲看。", "explanation": "这里应该用〈翻译〉。翻译是把一种语言转成另一种语言；编码是用符号代表信息，不用于语言之间的转换。"}, {"text": "妈妈把行李编码好，准备出发。", "explanation": "这里应该用〈打包〉。打包是把物品装起来；编码是用符号代表信息，不能用于装行李。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司发布了一颗新的编码。", "corrected_sentence": "这家公司发布了一套新的编码。", "error_description": "错误：“编码”的量词用了“颗”。“颗”用于小而圆的东西，编码是一整套规则，应说“一套新的编码”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们设计了一扇新编码。", "corrected_sentence": "我们设计了一套新编码。", "error_description": "错误：“编码”的量词用了“扇”。“扇”用于门窗，不能计量编码。正确形式是“一套新编码”，“套”用于成套的规则。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物能够发生或成为现实的性质。", "primary_collocate": null, "pronunciation": "kě néng xìng", "ipa": "kʰɤ˨˩˦ nəŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "记谱法的发展，本质上是人类试图以有限符号系统捕捉无限音响可能性的永恒努力，其演变轨迹，正是音乐理论与实践互动共生的深层见证。", "target_word": "可能性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "明天下雨的可能性很大。", "target_word": "可能性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事有成功的可能性吗？", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，生病的可能性不高。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一构想在现实中具有实现的可能性。", "target_word": "可能性", "complexity_tier": "T3", "furigana": "zhè yī gòuxiǎng zài xiànshí zhōng jùyǒu shíxiàn de kěnéngxìng", "sentence_source": "generated"}, {"text": "这种材料有广泛应用的可能性。", "target_word": "可能性", "complexity_tier": "T3", "furigana": "zhè zhǒng cáiliào yǒu guǎngfàn yìngyòng de kěnéngxìng", "sentence_source": "generated"}, {"text": "天气这么好，下雪的可能性很小。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛，我们赢的可能性不小。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车的可能性，你想过吗？", "target_word": "可能性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出现问题的可能性已经降低了。", "target_word": "可能性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "事物能够发生或成为现实的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf388ec-18fe-4bd8-8a47-45cf8777f83f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "语义：音响没有香味，“捕捉无限音响香味”不成立，“香味”不能作为音响被捕捉的对象。"}, {"text": "可能性", "is_correct": true, "explanation": "正确：“可能性”指音响能够出现的性质，与“捕捉无限音响”的语境相符。"}, {"text": "胡同", "is_correct": false, "explanation": "语义：“胡同”是地点，与无限的音响无关，不能被捕捉。"}, {"text": "手段", "is_correct": false, "explanation": "配价：“捕捉”的宾语应是可被捕捉的现象或事物，“手段”是方式，不能作“捕捉”的宾语。"}], "explanations": {"香味": "语义：音响没有香味，“捕捉无限音响香味”不成立，“香味”不能作为音响被捕捉的对象。", "可能性": "正确：“可能性”指音响能够出现的性质，与“捕捉无限音响”的语境相符。", "胡同": "语义：“胡同”是地点，与无限的音响无关，不能被捕捉。", "手段": "配价：“捕捉”的宾语应是可被捕捉的现象或事物，“手段”是方式，不能作“捕捉”的宾语。"}, "sentence_index": 0, "correct_answer": "可能性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的可能性很好听，大家都爱唱。", "explanation": "这里应该用〈旋律〉。可能性指事情能否发生，不能用来形容歌曲好听；说歌曲动听要用「旋律」。"}, {"text": "这种材料的可能性很稳定，不容易变化。", "explanation": "这里应该用〈性质〉。可能性指事情能否发生，不能用来描述材料本身的特点；说材料的特点要用「性质」。"}, {"text": "这幅画的可能性很鲜艳，一眼就能看出来。", "explanation": "这里应该用〈颜色〉。可能性指事物能否发生的性质，不能形容画面的色彩；说颜色鲜艳要用「颜色」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：下雪的天气不能用“味道”来衡量，“味道”与“下雪”无关。"}, {"text": "可能性", "is_correct": true, "explanation": "正确：“下雪的可能性很小”指下雪发生的性质，与“很小”搭配。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“很小”不能修饰“心情”，不说“心情很小”。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：形容温度低用“很低”，不说“很小”。"}], "explanations": {"味道": "语义：下雪的天气不能用“味道”来衡量，“味道”与“下雪”无关。", "可能性": "正确：“下雪的可能性很小”指下雪发生的性质，与“很小”搭配。", "心情": "搭配：“很小”不能修饰“心情”，不说“心情很小”。", "温度": "搭配：形容温度低用“很低”，不说“很小”。"}, "sentence_index": 6, "correct_answer": "可能性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作可能性很高，每天都能完成很多任务。", "explanation": "这里应该用〈效率〉。可能性指事情发生的性质，不指做事的快慢，说工作快慢要用「效率」。"}, {"text": "他的可能性很开朗，大家都喜欢他。", "explanation": "这里应该用〈性格〉。可能性指事物能否发生的性质，不能形容人的性情；说性格开朗要用「性格」。"}, {"text": "这道菜的可能性很辣，我吃不了。", "explanation": "这里应该用〈味道〉。可能性指事物能否发生的性质，不能描述菜的口感；说辣的口感要用「味道」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天没有风，出门可能性很小。", "corrected_sentence": "今天没有风，出门的可能性很小。", "error_description": "错误形式为“出门可能性很小”，正确形式为“出门的可能性很小”。“出门”是动词短语修饰“可能性”，中间须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划存在一条失败的可能性。", "corrected_sentence": "这个计划存在一种失败的可能性。", "error_description": "错误形式为“一条”，正确形式为“一种”。“可能性”是抽象名词，量词应用「种」；「条」用于细长的东西，不用于“可能性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c57be106-f2aa-4a48-b25e-66fd41be3f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理论", "is_correct": true, "explanation": "正确。“理论”与“实践”是反义词，指书本上的知识与付诸行动相对。"}, {"text": "天气", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}, {"text": "椅子", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}, {"text": "河流", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}], "correct_answer": "理论", "explanations": {"理论": "正确。“理论”与“实践”是反义词，指书本上的知识与付诸行动相对。", "天气": "与“实践”没有反义关系，只是同为名词。", "椅子": "与“实践”没有反义关系，只是同为名词。", "河流": "与“实践”没有反义关系，只是同为名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理论", "is_correct": true, "explanation": "正确。“理论”与“实践”是反义词，指书本上的知识与付诸行动相对。"}, {"text": "手套", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}, {"text": "雨水", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}, {"text": "窗帘", "is_correct": false, "explanation": "与“实践”没有反义关系，只是同为名词。"}], "correct_answer": "理论", "explanations": {"理论": "正确。“理论”与“实践”是反义词，指书本上的知识与付诸行动相对。", "手套": "与“实践”没有反义关系，只是同为名词。", "雨水": "与“实践”没有反义关系，只是同为名词。", "窗帘": "与“实践”没有反义关系，只是同为名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们实际去做的活动；把理论、想法付诸行动。", "primary_collocate": null, "pronunciation": "shí jiàn", "ipa": "ʂɻ̩˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "记谱法的发展，本质上是人类试图以有限符号系统捕捉无限音响可能性的永恒努力，其演变轨迹，正是音乐理论与实践互动共生的深层见证。", "target_word": "实践", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "理论要和实践结合起来。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了很多理论，但是缺少实践。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实践是检验真理的唯一标准。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课有很多实践的机会。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在实践中学会了做饭。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作实践中学到了很多。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有通过实践，你才能学会开车。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把想法用到实践里。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的知识要在实践中检验。", "target_word": "实践", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實踐", "label": "繁体"}, {"form": "社会实践", "label": "复合词"}, {"form": "实践活动", "label": "复合词"}], "register": "书面", "sense_fingerprint": "名词，与理论相对，指实际去做的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1a16da-10f9-4386-9fa4-b1d4f0773c09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确答案。实践（shí jiàn）指人们实际去做的活动，与理论相对。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。"}, {"text": "事件", "is_correct": false, "explanation": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。"}, {"text": "实现", "is_correct": false, "explanation": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。"}, {"text": "石匠", "is_correct": false, "explanation": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}], "explanations": {"实践": "正确答案。实践（shí jiàn）指人们实际去做的活动，与理论相对。", "时间": "“时间”（shí jiān）与“实践”（shí jiàn）只有第二个音节声调不同（jiān 第一声，jiàn 第四声），意思是时间。", "事件": "“事件”（shì jiàn）与“实践”（shí jiàn）只有第一个音节声调不同（shì 第四声，shí 第二声），意思是事件。", "实现": "“实现”（shí xiàn）与“实践”（shí jiàn）只有第二个音节声母不同（x 与 j），意思是变成现实。", "石匠": "“石匠”（shí jiàng）与“实践”（shí jiàn）只有第二个音节韵尾不同（-ng 与 -n），意思是石匠。"}, "sentence_index": null, "correct_answer": "实践"}, "level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“理论与实践互动共生”是通行说法，指理论与实际行动相互作用。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“互动共生”说的是理论与实践，天气不能与理论互动共生。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”口语色彩很重，不适合这句书面语。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能与音乐理论互动共生，句子不通。"}], "explanations": {"实践": "正确。“理论与实践互动共生”是通行说法，指理论与实际行动相互作用。", "天气": "语义：“互动共生”说的是理论与实践，天气不能与理论互动共生。", "玩意儿": "语域：“玩意儿”口语色彩很重，不适合这句书面语。", "椅子": "语义：椅子是家具，不能与音乐理论互动共生，句子不通。"}, "sentence_index": 0, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都要花一个小时实践钢琴。", "explanation": "这里应该用〈练习〉。“实践”指人们实际去做、把想法付诸行动的活动，不用来指乐器的反复操练；弹钢琴要用“练习”。"}, {"text": "大家围绕这个问题实践了很久。", "explanation": "这里应该用〈讨论〉。“实践”指人们实际去做的活动，不是对问题发表意见；围绕问题交换看法要用“讨论”。"}, {"text": "妈妈的实践很温和。", "explanation": "这里应该用〈脾气〉。“实践”指人们实际去做的活动，不用来形容人的性格和脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实践", "is_correct": true, "explanation": "正确。“在工作实践中”是常见说法，指在实际做事的过程中。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：“在……中”后面接的是活动或过程，“花朵”不是学习的场合，句子不通。"}, {"text": "胡同", "is_correct": false, "explanation": "语义：“胡同”是地点，不能说在胡同里“学到经验”，句子不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "搭配：“在……中”一般接活动、过程类名词，“工作蔬菜中”不是习惯搭配。"}], "explanations": {"实践": "正确。“在工作实践中”是常见说法，指在实际做事的过程中。", "花朵": "语义：“在……中”后面接的是活动或过程，“花朵”不是学习的场合，句子不通。", "胡同": "语义：“胡同”是地点，不能说在胡同里“学到经验”，句子不通。", "蔬菜": "搭配：“在……中”一般接活动、过程类名词，“工作蔬菜中”不是习惯搭配。"}, "sentence_index": 6, "correct_answer": "实践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子的实践很大，有五个房间。", "explanation": "这里应该用〈面积〉。“实践”指人们实际去做的活动，不用来描述房子的大小；说房子大要用“面积”。"}, {"text": "我每天都要实践教室。", "explanation": "这里应该用〈打扫〉。“实践”指人们实际去做的活动，不能拿来指打扫教室这类动作；本题要的是“打扫”。"}, {"text": "他每天早上都实践课文。", "explanation": "这里应该用〈背诵〉。“实践”指人们实际去做的活动，不用来指把课文记在脑中；背课文要用“背诵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要一只真正的实践。", "corrected_sentence": "我们需要一次真正的实践。", "error_description": "“实践”是名词，计量单位应用“次”，不能用“只”（“只”多用于动物或单个物品）。正确说法是“一次真正的实践”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要在实践里中检验理论。", "corrected_sentence": "我们要在实践中检验理论。", "error_description": "方位词重复：“里”与“中”不能同时使用，应只用“在实践中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f4f7e8d-c413-4eda-a3cb-9d6023198cfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
