INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事先约定时间、地点的见面。", "primary_collocate": null, "pronunciation": "yuē huì", "ipa": "ɥe˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "约会或上课，他们早早到。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "人们觉得开会或约会迟到是不礼貌的。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我今天下午有一个约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了和客户的约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天上午我有重要的约会，不能来。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她取消了今晚的约会。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "约会的时间是下午三点。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理打电话改了约会的地点。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，他们的约会推迟了半小时。", "target_word": "约会", "complexity_tier": "T3", "furigana": "yīnwèi xiàyǔ, tāmen de yuēhuì tuīchí le bàn xiǎoshí.", "sentence_source": "generated"}, {"text": "他每天都有很多约会，一直很忙。", "target_word": "约会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "約會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事先约好时间和地点的见面安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约会", "is_correct": true, "explanation": "“约会”指事先约好的见面，与“上课”并列为需要准时到场的场合，句意通顺。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是要完成的任务，不是需要准时到场的场合，与“早早到”不搭。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能“早早到”，与前后语义不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是需要准时到场的场合，“天气或上课，他们早早到”说不通。"}], "explanations": {"约会": "“约会”指事先约好的见面，与“上课”并列为需要准时到场的场合，句意通顺。", "作业": "语义：作业是要完成的任务，不是需要准时到场的场合，与“早早到”不搭。", "手机": "语义：手机是物品，不能“早早到”，与前后语义不符。", "天气": "语义：天气是气象状况，不是需要准时到场的场合，“天气或上课，他们早早到”说不通。"}, "sentence_index": 0, "correct_answer": "约会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份约会写得很详细，老师打了高分。", "explanation": "“约会”指事先约好的见面，不指文章或书面材料，这里的词义用错了。"}, {"text": "我们公司下午三点有一个约会，全体员工都要参加。", "explanation": "这里应该用〈会议〉。约会多指两人或少数人事先约好的见面，全体员工参加的正式活动要用会议。"}, {"text": "两国领导人在下午三点举行约会，签订了和平协议。", "explanation": "这里应该用〈会晤〉。约会多指私人或业务上的见面，两国领导人的正式会面要用会晤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约会", "is_correct": true, "explanation": "“约会”指约好的见面，句中“约会的时间是下午三点”指见面的时间，符合语境。"}, {"text": "地点", "is_correct": false, "explanation": "语义：地点是场所，不能说“地点的时间是下午三点”，句意说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不能有“的时间是下午三点”这样的安排。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：体温是身体指标，不能与“的时间是下午三点”搭配。"}], "explanations": {"约会": "“约会”指约好的见面，句中“约会的时间是下午三点”指见面的时间，符合语境。", "地点": "语义：地点是场所，不能说“地点的时间是下午三点”，句意说不通。", "天气": "语义：天气是气象状况，不能有“的时间是下午三点”这样的安排。", "体温": "搭配：体温是身体指标，不能与“的时间是下午三点”搭配。"}, "sentence_index": 6, "correct_answer": "约会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张地图上的约会标得很清楚，一眼就能看见。", "explanation": "这里把〈约会〉用成了地图上的标记，它指的是事先约好的见面，不是可以标注的内容，应用〈标记〉或〈标注〉。"}, {"text": "这次比赛的约会很精彩，观众很多。", "explanation": "“约会”指两人或几人事先约好的见面，比赛和演出不叫约会，这里误用了词义。"}, {"text": "妈妈每天早上做的约会很好吃。", "explanation": "“约会”不是食物，不能用来指做的菜，这里的词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天上午有一本约会。", "corrected_sentence": "我明天上午有一个约会。", "error_description": "“约会”的量词应用“个”，说“一个约会”，不说“一本约会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他取消了明天的约会的。", "corrected_sentence": "他取消了明天的约会。", "error_description": "名词“约会”后不应再加“的”，正确说“取消了明天的约会”；句末多出的“的”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下课", "is_correct": true, "explanation": "“下课”与“上课”是一对反义词：上课指开始听课或讲课，下课指课程结束。"}, {"text": "散步", "is_correct": false, "explanation": "散步与上课没有反义关系，二者意义上并不对立。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与上课没有反义关系，不能构成一对反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与上课没有反义关系，只是两种不同的活动。"}], "correct_answer": "下课", "explanations": {"下课": "“下课”与“上课”是一对反义词：上课指开始听课或讲课，下课指课程结束。", "散步": "散步与上课没有反义关系，二者意义上并不对立。", "游泳": "游泳与上课没有反义关系，不能构成一对反义词。", "唱歌": "唱歌与上课没有反义关系，只是两种不同的活动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下课", "is_correct": true, "explanation": "“下课”与“上课”是一对反义词：上课指开始听课或讲课，下课指课程结束。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭与上课没有反义关系，二者意义上并不对立。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与上课没有反义关系，不能构成一对反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉与上课没有反义关系，只是两种不同的状态或活动。"}], "correct_answer": "下课", "explanations": {"下课": "“下课”与“上课”是一对反义词：上课指开始听课或讲课，下课指课程结束。", "吃饭": "吃饭与上课没有反义关系，二者意义上并不对立。", "跑步": "跑步与上课没有反义关系，不能构成一对反义词。", "睡觉": "睡觉与上课没有反义关系，只是两种不同的状态或活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指学生到教室听老师讲课，或老师给学生讲课。", "primary_collocate": null, "pronunciation": "shàng kè", "ipa": "ʂɑŋ˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "约会或上课，他们早早到。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "在中国，上课或开会要准时。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们每天早上八点上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天老师不在，我们不上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在教室里给学生上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午下雨了，学生们还是来上课。", "target_word": "上课", "complexity_tier": "T3", "furigana": "jīntiān xiàwǔ xiàyǔ le, xuéshengmen háishi lái shàngkè.", "sentence_source": "generated"}, {"text": "他每个星期一、三、五上课。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课的时候，请关上手机。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师正在三楼上课，你等一下。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡过头了，上课迟到了。", "target_word": "上课", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了课", "label": "体标"}, {"form": "上过课", "label": "体标"}, {"form": "上課", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上课：学生听课或老师讲课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上课", "is_correct": true, "explanation": "“上课”指学生到教室听课，句中“早早到”正好描述赴课的情形，与“约会或”并列合理。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是休息的活动，不是需要早早赶到的场合，与“他们早早到”冲突。"}, {"text": "下班", "is_correct": false, "explanation": "语义：下班指结束工作离开单位，“约会或下班，他们早早到”说不通。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是正式书面语，多用于尊贵客人到场，与口语句子不协调，与约会并列也不合理。"}], "explanations": {"上课": "“上课”指学生到教室听课，句中“早早到”正好描述赴课的情形，与“约会或”并列合理。", "睡觉": "语义：睡觉是休息的活动，不是需要早早赶到的场合，与“他们早早到”冲突。", "下班": "语义：下班指结束工作离开单位，“约会或下班，他们早早到”说不通。", "莅临": "语域：莅临是正式书面语，多用于尊贵客人到场，与口语句子不协调，与约会并列也不合理。"}, "sentence_index": 0, "correct_answer": "上课"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从六岁起就上课，直到大学毕业。", "explanation": "这里应该用〈上学〉。上学指长期在学校读书，多用于整个求学阶段；上课只指一节或一天的课程，不能说“上课直到大学毕业”。"}, {"text": "会议期间，他坐在台下认真上课，做了很多笔记。", "explanation": "这里应该用〈听课〉。上课指学生或老师在课堂上的活动，在会议或讲座上听报告要用听课。"}, {"text": "他每天早上八点去公司上课。", "explanation": "这里应该用〈上班〉。上课是学生听课或老师讲课，到公司工作要用上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上课", "is_correct": true, "explanation": "“上课”指学生或老师的课堂活动，符合“他每个星期一、三、五”的日程语境。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是按星期安排的固定活动，说“每个星期一、三、五生病”说不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚是一次性的重大事件，不能按星期重复安排。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是正式书面语，多指尊贵客人到场，与口语的日程句不协调。"}], "explanations": {"上课": "“上课”指学生或老师的课堂活动，符合“他每个星期一、三、五”的日程语境。", "生病": "语义：生病不是按星期安排的固定活动，说“每个星期一、三、五生病”说不通。", "结婚": "语义：结婚是一次性的重大事件，不能按星期重复安排。", "莅临": "语域：莅临是正式书面语，多指尊贵客人到场，与口语的日程句不协调。"}, "sentence_index": 6, "correct_answer": "上课"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑每天早上八点准时上课。", "explanation": "这里应该用〈运行〉。上课的主语必须是人，指人听课或讲课；电脑这类机器的工作要用运行。"}, {"text": "我昨天在菜市场上课，挑了很多蔬菜。", "explanation": "这里应该用〈买菜〉。上课指听课或讲课，去菜市场挑选蔬菜要用买菜。"}, {"text": "我昨天在地铁站上课，等了一个小时车。", "explanation": "这里应该用〈候车〉。上课指听课或讲课，在地铁站等车要用候车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天上一只课。", "corrected_sentence": "我们每天上一节课。", "error_description": "量词错误：「课」的量词应为「节」，不能用「只」。「只」多用于动物或单个的小东西，不用于课程，应说「上一节课」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天上课了三节课。", "corrected_sentence": "他昨天上了三节课。", "error_description": "宾语重复错误：「上课」本身已含「课」，后面不能再接宾语「课」，应说「上了三节课」，不说「上课了三节课」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "买", "is_correct": false, "explanation": "与“记得”没有反义关系，“买”是购买的动作。"}, {"text": "吃", "is_correct": false, "explanation": "与“记得”没有反义关系，“吃”是饮食的动作。"}, {"text": "修", "is_correct": false, "explanation": "与“记得”没有反义关系，“修”是修理的动作。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "买": "与“记得”没有反义关系，“买”是购买的动作。", "吃": "与“记得”没有反义关系，“吃”是饮食的动作。", "修": "与“记得”没有反义关系，“修”是修理的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "看见", "is_correct": false, "explanation": "与“记得”没有反义关系，“看见”指用眼睛看到。"}, {"text": "打开", "is_correct": false, "explanation": "与“记得”没有反义关系，“打开”是开启的动作。"}, {"text": "走", "is_correct": false, "explanation": "与“记得”没有反义关系，“走”是移动的动作。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "看见": "与“记得”没有反义关系，“看见”指用眼睛看到。", "打开": "与“记得”没有反义关系，“打开”是开启的动作。", "走": "与“记得”没有反义关系，“走”是移动的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "回忆起来，没有忘记。", "primary_collocate": null, "pronunciation": "jì de", "ipa": "tɕi˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "有些人记得事情，不写字。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "你还记得我们第一次见面吗？", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我记得他的名字叫小林。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不记得钥匙放在哪儿了。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人记得很多小时候的事。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你记得今天几点开会吗？", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我记得去年冬天特别冷。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她记得那条路，不会走错。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我记得把手机放在桌子上了。", "target_word": "记得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你记得他长什么样子吗？", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不记得", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "回想得起来，没有忘记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确答案：记得，表示回想起来、没有忘记。"}, {"text": "急得", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。"}, {"text": "挤得", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。"}, {"text": "积德", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。"}, {"text": "气得", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），意思是生气，「气得」指因生气而……。"}], "explanations": {"记得": "正确答案：记得，表示回想起来、没有忘记。", "急得": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。", "挤得": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。", "积德": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。", "气得": "qì 与 jì 声母不同（q 与 j），意思是生气，「气得」指因生气而……。"}, "sentence_index": null, "correct_answer": "记得"}, "level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示事情还留在记忆中，与“有些人……不写字”的语境相合。"}, {"text": "写下", "is_correct": false, "explanation": "语义：“写下”与后句“不写字”矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物品或机器，不能说修理事情。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能用于“事情”。"}], "explanations": {"记得": "正确：“记得”表示事情还留在记忆中，与“有些人……不写字”的语境相合。", "写下": "语义：“写下”与后句“不写字”矛盾。", "修理": "搭配：“修理”的对象是物品或机器，不能说修理事情。", "购买": "搭配：“购买”的对象是商品，不能用于“事情”。"}, "sentence_index": 0, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在考试前用了一个晚上来记得公式。", "explanation": "这里应该用〈记住〉。记住指把内容牢牢存入记忆这个动作；记得只表示记忆中还有内容，不表示动作。"}, {"text": "妈妈在日历上记得一个红圈，提醒我去医院。", "explanation": "这里应该用〈画〉。在日历上画圈是用笔做记号，记得表示回忆，不能指画圈。"}, {"text": "他在墙上记得一张画。", "explanation": "这里应该用〈贴〉。把画贴在墙上是固定动作，记得表示回忆，不能指把画贴上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示对去年冬天的记忆，与句中的“去年”相合。"}, {"text": "预言", "is_correct": false, "explanation": "语义：“预言”指对未来的预测，与“去年”矛盾。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：“盼望”指对未来的期待，与“去年”的已过时间矛盾。"}, {"text": "体验", "is_correct": false, "explanation": "配价：“体验”的宾语是经历或感受，不能直接接“特别冷”这样的小句。"}], "explanations": {"记得": "正确：“记得”表示对去年冬天的记忆，与句中的“去年”相合。", "预言": "语义：“预言”指对未来的预测，与“去年”矛盾。", "盼望": "语义：“盼望”指对未来的期待，与“去年”的已过时间矛盾。", "体验": "配价：“体验”的宾语是经历或感受，不能直接接“特别冷”这样的小句。"}, "sentence_index": 6, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上记得我的电话号码。", "explanation": "这里应该用〈记下〉。记下指把内容写下来留存；记得只表示记忆中还有内容，不表示写下。"}, {"text": "护士在病历上记得病人的症状。", "explanation": "这里应该用〈记录〉。记录指把症状写在病历上留存，记得表示记忆中有，不表示写下来。"}, {"text": "他去报名，在表格上记得自己的名字。", "explanation": "这里应该用〈登记〉。登记指在表格上填写信息，记得没有登记的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我记得得很清楚。", "corrected_sentence": "这件事我记得很清楚。", "error_description": "错误形式：“记得得很清楚”；正确形式：“记得很清楚”。记得后接补语时“得”只用一次，多写一个“得”是重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在记得那个冬天的雪。", "corrected_sentence": "我还记得那个冬天的雪。", "error_description": "错误形式：“我正在记得”；正确形式：“我还记得”。记得是状态动词，不能与“正在”这类表示进行的副词搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "唱：与“连在一起”没有反义关系，“唱”指用声音演唱歌曲。"}, {"text": "分开", "is_correct": true, "explanation": "分开：与“连在一起”意思相反，指不再接在一起。"}, {"text": "读", "is_correct": false, "explanation": "读：与“连在一起”没有反义关系，“读”指看着文字发出声音或理解文字。"}, {"text": "喝", "is_correct": false, "explanation": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。"}], "correct_answer": "分开", "explanations": {"唱": "唱：与“连在一起”没有反义关系，“唱”指用声音演唱歌曲。", "分开": "分开：与“连在一起”意思相反，指不再接在一起。", "读": "读：与“连在一起”没有反义关系，“读”指看着文字发出声音或理解文字。", "喝": "喝：与“连在一起”没有反义关系，“喝”指把液体咽下去。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "画", "is_correct": false, "explanation": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。"}, {"text": "分开", "is_correct": true, "explanation": "分开：与“连在一起”意思相反，指村子不再连接。"}, {"text": "跳", "is_correct": false, "explanation": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。"}, {"text": "睡", "is_correct": false, "explanation": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}], "correct_answer": "分开", "explanations": {"画": "画：与“连在一起”没有反义关系，“画”指用线条和颜色描绘形象。", "分开": "分开：与“连在一起”意思相反，指村子不再连接。", "跳": "跳：与“连在一起”没有反义关系，“跳”指身体离开地面再落下。", "睡": "睡：与“连在一起”没有反义关系，“睡”指闭眼休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示多个事物相互连接，形成一个整体。", "primary_collocate": null, "pronunciation": "lián zài yì qǐ", "ipa": "ljɛn tsaɪ i tɕʰi", "syllable_count": 4, "sentences": [{"text": "这两条铁路现在连在一起了。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条小河连在一起，变成了一条大河。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山和山连在一起，看起来像一条龙。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们手拉手，连在一起站成一圈。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小房子连在一起，成了一个大院子。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁和公交连在一起，坐车很方便。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个小公园连在一起，好像一个大公园。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几张纸连在一起，做成一张长纸。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小岛连在一起，就像一串珍珠。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个村子连在一起，成了一个小镇。", "target_word": "连在一起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连在一起了", "label": "完成体"}, {"form": "連在一起", "label": "繁体"}], "register": "中性", "sense_fingerprint": "多个事物相互连接成为一个整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbaaaf73-74c4-4217-9399-ec60d52059ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”多用于房间、东西等，不能说“收拾铁路”，句子不通。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：几个事物相互连接成一个整体，与“这两条铁路”的语境相符。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指把书刊印刷发行，与“铁路”无关，这句话说不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要有“送给谁、送什么”两个成分，这里只有主语，缺少宾语。"}], "explanations": {"收拾": "搭配：“收拾”多用于房间、东西等，不能说“收拾铁路”，句子不通。", "连在一起": "连在一起：几个事物相互连接成一个整体，与“这两条铁路”的语境相符。", "出版": "语义：“出版”指把书刊印刷发行，与“铁路”无关，这句话说不通。", "送": "配价：“送”要有“送给谁、送什么”两个成分，这里只有主语，缺少宾语。"}, "sentence_index": 0, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两笔钱连在一起，正好是一万块。", "explanation": "这里应该用〈加在一起〉。“连在一起”指事物相互接合，计算总数要说“加在一起”。"}, {"text": "我们的心连在一起，互相关心。", "explanation": "这里说的是人心相通的感情联系，是“连在一起”的另一个义项，不是多个事物连接成整体。"}, {"text": "他连在一起工作了三天。", "explanation": "这里应该用〈连续〉。“连在一起”指事物相互接合，不表示时间上接连不断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分开", "is_correct": false, "explanation": "语义：“分开”与后面“好像一个大公园”的合并之意相反，句子前后矛盾。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”一般用于人或车等，不能说“公园出发”。"}, {"text": "连在一起", "is_correct": true, "explanation": "连在一起：几个地方相互连接成一个整体，正好与“好像一个大公园”相呼应。"}, {"text": "拆", "is_correct": false, "explanation": "配价：“拆”要带宾语，如“拆房子”，这里缺少宾语，句子不完整。"}], "explanations": {"分开": "语义：“分开”与后面“好像一个大公园”的合并之意相反，句子前后矛盾。", "出发": "搭配：“出发”一般用于人或车等，不能说“公园出发”。", "连在一起": "连在一起：几个地方相互连接成一个整体，正好与“好像一个大公园”相呼应。", "拆": "配价：“拆”要带宾语，如“拆房子”，这里缺少宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "连在一起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种颜料连在一起，调出了绿色。", "explanation": "这里应该用〈混在一起〉。“连在一起”指物体接合成整体，颜料相融要说“混在一起”。"}, {"text": "这两台电脑连在一起，可以共享文件。", "explanation": "这里指用设备联网，是“连在一起”的另一个义项；此处说的并不是物体接合成整体。"}, {"text": "大家都连在一起吃饭。", "explanation": "这里应该用〈聚在一起〉。“连在一起”指物体接合，人们相聚吃饭要说“聚在一起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三块木板把连在一起了，就能做成一张桌子。", "corrected_sentence": "这三块木板连在一起了，就能做成一张桌子。", "error_description": "“把”字句中，“把”后必须带宾语。这里“把”后直接接动词“连”，没有宾语，应去掉“把”，说“这三块木板连在一起了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两根铁丝很连在一起，不会晃动。", "corrected_sentence": "这两根铁丝紧紧连在一起，不会晃动。", "error_description": "“很”是程度副词，一般不修饰“连在一起”这类动词结构。这里应用“紧紧”修饰，表示连接牢固，正确为“紧紧连在一起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
