INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10889, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脸；也指物体的外表面或事物的正面。", "primary_collocate": null, "pronunciation": "miàn", "ipa": "miɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这块木板的一个面有裂缝。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "正方体有六个面。", "target_word": "面", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张纸的两个面都写了字。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把有字的面朝上放好。", "target_word": "面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布一个面是红的，一个面是白的。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玻璃有一个面刮花了。", "target_word": "面", "complexity_tier": "T3", "furigana": "zhè kuài bō li yǒu yí ge miàn guā huā le.", "sentence_source": "generated"}, {"text": "硬币有两个面，一个有花，一个有字。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子的每个面都画了小动物。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块石头的一个面特别平。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子有六个面，这个面朝下，那个面朝上。", "target_word": "面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "表面", "label": "复合"}, {"form": "平面", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体的外表面；事物的一面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10889, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面", "is_correct": true, "explanation": "正确答案：面，指物体的外表面或脸。"}, {"text": "棉", "is_correct": false, "explanation": "mián（第二声）与 miàn（第四声）声调不同，意思是棉花。"}, {"text": "变", "is_correct": false, "explanation": "biàn 与 miàn 声母不同（b 与 m），意思是改变。"}, {"text": "电", "is_correct": false, "explanation": "diàn 与 miàn 声母不同（d 与 m），意思是电力。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 miàn 声母不同（x 与 m），意思是现在或显现。"}, {"text": "见", "is_correct": false, "explanation": "jiàn 与 miàn 声母不同（j 与 m），意思是看见。"}], "explanations": {"面": "正确答案：面，指物体的外表面或脸。", "棉": "mián（第二声）与 miàn（第四声）声调不同，意思是棉花。", "变": "biàn 与 miàn 声母不同（b 与 m），意思是改变。", "电": "diàn 与 miàn 声母不同（d 与 m），意思是电力。", "现": "xiàn 与 miàn 声母不同（x 与 m），意思是现在或显现。", "见": "jiàn 与 miàn 声母不同（j 与 m），意思是看见。"}, "sentence_index": null, "correct_answer": "面"}, "level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "正确：“面”指木板的表面，“一个面有裂缝”与句意相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不是物体的部分，不能有裂缝，句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不能有裂缝，句意不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是物体的部分，不能有裂缝，句意不通。"}], "explanations": {"面": "正确：“面”指木板的表面，“一个面有裂缝”与句意相合。", "味道": "语义：“味道”不是物体的部分，不能有裂缝，句意不通。", "声音": "语义：“声音”不能有裂缝，句意不通。", "名字": "语义：“名字”不是物体的部分，不能有裂缝，句意不通。"}, "sentence_index": 0, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木头的面很尖，小心别碰到。", "explanation": "这里应该用〈角〉。角指物体的尖端，面指平的表面，不能说“面很尖”。"}, {"text": "这个杯子的面断了，只能用一只手拿。", "explanation": "这里应该用〈把手〉。把手是拿杯子时握的部分，面指表面，不能说“面断了”。"}, {"text": "这块布一只面是红的。", "explanation": "这里应该用〈个〉。面作表面时用量词“个”，“只”用于动物或成对物品中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10889, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "面", "is_correct": true, "explanation": "正确答案：面，指物体的外表面或脸。"}, {"text": "免", "is_correct": false, "explanation": "miǎn（第三声）与 miàn（第四声）声调不同，意思是免除。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 miàn 声母不同（p 与 m），意思是片状物。"}, {"text": "眠", "is_correct": false, "explanation": "mián（第二声）与 miàn（第四声）声调不同，意思是睡眠。"}, {"text": "念", "is_correct": false, "explanation": "niàn 与 miàn 声母不同（n 与 m），意思是朗读或想念。"}], "explanations": {"面": "正确答案：面，指物体的外表面或脸。", "免": "miǎn（第三声）与 miàn（第四声）声调不同，意思是免除。", "片": "piàn 与 miàn 声母不同（p 与 m），意思是片状物。", "眠": "mián（第二声）与 miàn（第四声）声调不同，意思是睡眠。", "念": "niàn 与 miàn 声母不同（n 与 m），意思是朗读或想念。"}, "sentence_index": null, "correct_answer": "面"}, "level_3": {"options": [{"text": "面", "is_correct": true, "explanation": "正确：“两个面”指硬币的正面和背面，与句意相合。"}, {"text": "角", "is_correct": false, "explanation": "体貌：硬币是圆形的，没有角，与外形不符。"}, {"text": "页", "is_correct": false, "explanation": "搭配：“页”用于纸张或书本，不用于硬币。"}, {"text": "孔", "is_correct": false, "explanation": "语义：硬币上没有孔，与“有花”“有字”的描述不符。"}], "explanations": {"面": "正确：“两个面”指硬币的正面和背面，与句意相合。", "角": "体貌：硬币是圆形的，没有角，与外形不符。", "页": "搭配：“页”用于纸张或书本，不用于硬币。", "孔": "语义：硬币上没有孔，与“有花”“有字”的描述不符。"}, "sentence_index": 6, "correct_answer": "面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块玻璃的面很锋利，拿的时候要小心。", "explanation": "这里应该用〈边〉。锋利的部位是边缘，面指平的表面。"}, {"text": "这个杯子的面很厚，所以很稳。", "explanation": "这里应该用〈底〉。杯子稳不稳看底部，面指表面。"}, {"text": "这个瓶子的面很小，不好倒水。", "explanation": "这里应该用〈口〉。倒水的地方是瓶口，面指表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板有一张面裂开了。", "corrected_sentence": "这块木板有一个面裂开了。", "error_description": "错误形式：“一张面”；正确形式：“一个面”。“面”指物体的表面，用量词“个”；“张”用于纸、桌子等整体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "盒子的每一面个都是红色的。", "corrected_sentence": "盒子的每一个面都是红色的。", "error_description": "错误形式：“每一面个”；正确形式：“每一个面”。量词“个”要紧接数词“一”，应放在数词与名词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
