INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10893, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "用于劝慰他人不要发怒或感到不满。", "primary_collocate": null, "pronunciation": "bié shēng qì", "ipa": "pjɛ ʂɤŋ tɕʰi", "syllable_count": 3, "sentences": [{"text": "我慢慢来，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "对不起，我来晚了，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气，我马上帮你修好。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不是故意的，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别生气，他只是开玩笑。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道你很累，但是别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈，别生气，我下次一定早点回家。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别生气了，我请你吃饭。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情已经这样了，你别生气。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友迟到了，你别生气，他在路上。", "target_word": "别生气", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "别生气了", "label": "加了"}, {"form": "別生氣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "劝慰别人不要发怒或不满的惯用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbaaaf73-74c4-4217-9399-ec60d52059ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气」是劝慰语，与「我慢慢来」的语境相符；在所给选项中只有它能填入空格。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：「你迟到」不能构成劝慰，与「我慢慢来，你___」的语境矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「你睡觉」与「我慢慢来」的说话语境无关，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}], "explanations": {"别生气": "正确。「别生气」是劝慰语，与「我慢慢来」的语境相符；在所给选项中只有它能填入空格。", "迟到": "语义：「你迟到」不能构成劝慰，与「我慢慢来，你___」的语境矛盾。", "睡觉": "语义：「你睡觉」与「我慢慢来」的说话语境无关，句意不通。", "下雨": "搭配：「慢慢来」用于人的行为，天气不能被要求「慢慢来」，搭配不当。"}, "sentence_index": 0, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他考上了大学，我高兴地对他说：“别生气。”", "explanation": "这里是祝贺的语境。「别生气」是劝人不要发怒，这里应该用「恭喜」。"}, {"text": "同学们正在操场上认真跑步，老师对大家说：“别生气，慢慢跑。”", "explanation": "「别生气」用于劝正在发怒的人，这里大家都很认真，没有人生气，应该用「别着急」，提醒大家不要慌张地跑。"}, {"text": "我把咖啡洒在他的书上，他没有生气，我却说：“别生气。”", "explanation": "「别生气」预设对方正在生气。对方没有生气时不能这样劝，应该用「没关系」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别生气", "is_correct": true, "explanation": "正确。「别生气」是口语中的劝慰语，与「妈妈」的对话语境相符；在所给选项中只有它能填入空格。"}, {"text": "赴约", "is_correct": false, "explanation": "语域：「赴约」是书面语，与家人之间的口语对话不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：「考试」与「我下次一定早点回家」的承诺语境不符，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：「唱歌」与道歉式的承诺无关，前后不接。"}], "explanations": {"别生气": "正确。「别生气」是口语中的劝慰语，与「妈妈」的对话语境相符；在所给选项中只有它能填入空格。", "赴约": "语域：「赴约」是书面语，与家人之间的口语对话不合。", "考试": "语义：「考试」与「我下次一定早点回家」的承诺语境不符，句意不通。", "唱歌": "语义：「唱歌」与道歉式的承诺无关，前后不接。"}, "sentence_index": 6, "correct_answer": "别生气"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雷声很大，弟弟躲在被子里发抖，我对他说：“别生气，快出来。”", "explanation": "「别生气」劝的是正在发怒的人，弟弟是在害怕，这里应该用「别害怕」。"}, {"text": "宝宝正在安静地睡觉，妈妈看着他说：“别生气。”", "explanation": "「别生气」预设对方正在发怒，宝宝睡得很安静，没有生气，这里不能这样劝。"}, {"text": "他请我吃饭，我很高兴，我说：“别生气。”", "explanation": "这里是高兴的语境。「别生气」是劝人不要发怒，这里应该用「别客气」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你别生气了了，我们去吃饭吧。", "corrected_sentence": "你别生气了，我们去吃饭吧。", "error_description": "错误形式「别生气了了」，句末「了」多写了一个。正确形式「别生气了」，「了」只用一次，放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈，别生气过，我马上回来。", "corrected_sentence": "妈妈，别生气了，我马上回来。", "error_description": "错误形式「别生气过」，「过」表示经历过，劝阻的语境要用「了」表示事情的变化。正确形式「别生气了」，「了」应放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "“好”与“不好”意义相对，是“不好”（坏的）的对立面。"}, {"text": "冷", "is_correct": false, "explanation": "「冷」指温度低，与「不好」没有反义关系。"}, {"text": "远", "is_correct": false, "explanation": "「远」指距离大，与「不好」没有反义关系。"}, {"text": "红", "is_correct": false, "explanation": "「红」指颜色，与「不好」没有反义关系。"}], "correct_answer": "好", "explanations": {"好": "“好”与“不好”意义相对，是“不好”（坏的）的对立面。", "冷": "「冷」指温度低，与「不好」没有反义关系。", "远": "「远」指距离大，与「不好」没有反义关系。", "红": "「红」指颜色，与「不好」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "反义：「好」与「不好」相对，指质量好、状况好，词典有此反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "「亮」指光线充足，与「不好」没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”指重量小，与“不好”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "「厚」指物体的宽度大，与「不好」没有反义关系。"}], "correct_answer": "好", "explanations": {"好": "反义：「好」与「不好」相对，指质量好、状况好，词典有此反义关系。", "亮": "「亮」指光线充足，与「不好」没有反义关系。", "轻": "“轻”指重量小，与“不好”没有反义关系。", "厚": "「厚」指物体的宽度大，与「不好」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "质量、状况或水平差，不令人满意。", "primary_collocate": null, "pronunciation": "bù hǎo", "ipa": "pu˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "技术进步是好事，但如果管理不好，也可能带来新的社会问题。", "target_word": "不好", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "昨天他生病了，心情很不好。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶身体不好，不能爬山。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的质量不好，用了一个月就坏了。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天天气不好，我们不去公园了。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩不好，所以每天学习到很晚。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的空气不好，请开一下窗。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脾气不好，常常生气。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的环境不好，又脏又吵。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的汉语不好，请你说慢一点。", "target_word": "不好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不好意思", "label": "复合"}], "register": "中性", "sense_fingerprint": "不好：不好的、坏的，质量或状态差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9da955b2-9cb2-4719-95b9-57d75913c78c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：不好，指坏的、质量差的。"}, {"text": "不早", "is_correct": false, "explanation": "声母不同：「不早」以 z 开头，「不好」以 h 开头，意思是不早。"}, {"text": "不老", "is_correct": false, "explanation": "声母不同：「不老」以 l 开头，意思是不显老。"}, {"text": "不少", "is_correct": false, "explanation": "声母不同：「不少」以 sh 开头，意思是很多、不在少数。"}, {"text": "不考", "is_correct": false, "explanation": "声母不同：「不考」以 k 开头，意思是不参加考试。"}], "explanations": {"不好": "正确：不好，指坏的、质量差的。", "不早": "声母不同：「不早」以 z 开头，「不好」以 h 开头，意思是不早。", "不老": "声母不同：「不老」以 l 开头，意思是不显老。", "不少": "声母不同：「不少」以 sh 开头，意思是很多、不在少数。", "不考": "声母不同：「不考」以 k 开头，意思是不参加考试。"}, "sentence_index": null, "correct_answer": "不好"}, "level_3": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：「如果管理不好」指管理差，只有「不好」与后面的担忧相合。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外貌或事物好看，不能用来形容「管理」。"}, {"text": "甜", "is_correct": false, "explanation": "语义：「甜」指味道，不能用来形容「管理」，句子说不通。"}, {"text": "凉", "is_correct": false, "explanation": "语义：「凉」指温度低，不能用来形容「管理」，句子说不通。"}], "explanations": {"不好": "正确：「如果管理不好」指管理差，只有「不好」与后面的担忧相合。", "漂亮": "搭配：「漂亮」形容外貌或事物好看，不能用来形容「管理」。", "甜": "语义：「甜」指味道，不能用来形容「管理」，句子说不通。", "凉": "语义：「凉」指温度低，不能用来形容「管理」，句子说不通。"}, "sentence_index": 0, "correct_answer": "不好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事我不好说，你问他本人吧。", "explanation": "这里的「不好说」是不便说出口的意思，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "这个问题不好回答，大家都沉默了。", "explanation": "这里的「不好回答」表示难以作答，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "我把你的书弄丢了，真不好意思。", "explanation": "「不好意思」表示难为情，是另一个义项，这里不是指坏的、不好的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：不好，指坏的、质量差的。"}, {"text": "不跑", "is_correct": false, "explanation": "声母不同：「不跑」以 p 开头，意思是不跑步。"}, {"text": "不搞", "is_correct": false, "explanation": "声母不同：「不搞」以 g 开头，意思是不做、不干。"}, {"text": "不倒", "is_correct": false, "explanation": "声母不同：「不倒」以 d 开头，意思是不倒下。"}, {"text": "不扫", "is_correct": false, "explanation": "声母不同：「不扫」以 s 开头，意思是不打扫。"}], "explanations": {"不好": "正确：不好，指坏的、质量差的。", "不跑": "声母不同：「不跑」以 p 开头，意思是不跑步。", "不搞": "声母不同：「不搞」以 g 开头，意思是不做、不干。", "不倒": "声母不同：「不倒」以 d 开头，意思是不倒下。", "不扫": "声母不同：「不扫」以 s 开头，意思是不打扫。"}, "sentence_index": null, "correct_answer": "不好"}, "level_3": {"options": [{"text": "不好", "is_correct": true, "explanation": "正确：「空气不好」才需要「请开一下窗」，只有「不好」与后半句相合。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地坚实，不能用来形容“空气”，句子说不通。"}, {"text": "高", "is_correct": false, "explanation": "搭配：「空气」不能用「高」来形容，搭配不当。"}, {"text": "慢", "is_correct": false, "explanation": "语义：「空气」不能用速度来形容，句子说不通。"}], "explanations": {"不好": "正确：「空气不好」才需要「请开一下窗」，只有「不好」与后半句相合。", "硬": "搭配：“硬”形容质地坚实，不能用来形容“空气”，句子说不通。", "高": "搭配：「空气」不能用「高」来形容，搭配不当。", "慢": "语义：「空气」不能用速度来形容，句子说不通。"}, "sentence_index": 6, "correct_answer": "不好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我不好开口，你去问问老师吧。", "explanation": "这里的「不好开口」表示不便说出口，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "我今天心里不好受，什么都不想吃。", "explanation": "这里的「不好受」表示难受，是另一个义项，与指坏的、不好的意思无关。"}, {"text": "这件事不好办，我们再想想别的办法。", "explanation": "这里的「不好办」表示难以处理，是另一个义项，与指坏的、不好的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑质量得不好，经常出问题。", "corrected_sentence": "这台电脑质量不好，经常出问题。", "error_description": "结构错误：「质量不好」是主谓结构，「得」只用于动词或形容词后引出补语，这里不能加「得」，应说「这台电脑质量不好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店把服务不好，客人很少。", "corrected_sentence": "这家店的服务不好，客人很少。", "error_description": "结构错误：「服务不好」是主谓结构，「服务」作主语，不能用「把」引出，应说「这家店的服务不好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd07a69b8-3c46-4b8c-98d3-4ca5164bc3a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
