INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间单位，等于60分钟。", "primary_collocate": null, "pronunciation": "xiǎo shí", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "朋友聚会，晚到一小时也可以。", "target_word": "小时", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "从我家到学校要走一个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场电影一共演了两个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡八个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机晚点了半个小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每隔一小时就看一次手机。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会开了三个小时，大家都累了。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐高铁去北京只要四个多小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑步跑了一小时，出了很多汗。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店每天营业十二小时。", "target_word": "小时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小时", "label": "量词"}, {"form": "半个小时", "label": "复合"}, {"form": "小时工", "label": "复合"}, {"form": "小時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小时：时间单位，一小时等于六十分钟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：时间单位，等于六十分钟。"}, {"text": "小事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是小事，与时间无关。"}, {"text": "小诗", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是小诗。"}, {"text": "消失", "is_correct": false, "explanation": "xiāo（第一声）与 xiǎo（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是消失。"}, {"text": "小吃", "is_correct": false, "explanation": "chī 与 shí 声母不同（ch 与 sh），意思是小吃。"}], "explanations": {"小时": "小时：时间单位，等于六十分钟。", "小事": "shì（第四声）与 shí（第二声）声调不同，意思是小事，与时间无关。", "小诗": "shī（第一声）与 shí（第二声）声调不同，意思是小诗。", "消失": "xiāo（第一声）与 xiǎo（第三声）、shī（第一声）与 shí（第二声）声调都不同，意思是消失。", "小吃": "chī 与 shí 声母不同（ch 与 sh），意思是小吃。"}, "sentence_index": null, "correct_answer": "小时"}, "level_3": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：晚到一小时约迟到六十分钟，与朋友聚会的语境相符。"}, {"text": "年", "is_correct": false, "explanation": "语义：晚到一年与朋友聚会的语境相冲突，这种说法不成立。"}, {"text": "世纪", "is_correct": false, "explanation": "语义：一世纪是一百年，聚会晚到这么久不合常理。"}, {"text": "米", "is_correct": false, "explanation": "搭配：“晚到”说的是时间，不能用长度单位“米”来计量。"}], "explanations": {"小时": "小时：晚到一小时约迟到六十分钟，与朋友聚会的语境相符。", "年": "语义：晚到一年与朋友聚会的语境相冲突，这种说法不成立。", "世纪": "语义：一世纪是一百年，聚会晚到这么久不合常理。", "米": "搭配：“晚到”说的是时间，不能用长度单位“米”来计量。"}, "sentence_index": 0, "correct_answer": "小时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约在下午三个小时见面。", "explanation": "这里应该用〈三点〉。表示时刻要说“三点”，“小时”只表示一段时长，不能指某个时间点。"}, {"text": "我等了两场小时才看到他。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“场”用于雨、电影、比赛等一次性事件，不能修饰时间长度。"}, {"text": "我买了五小时的苹果。", "explanation": "这里应该用〈斤〉。小时只表示时长，不能用来称量苹果；称重要用“斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：时间单位，等于六十分钟。"}, {"text": "小池", "is_correct": false, "explanation": "chí 与 shí 声母不同（ch 与 sh），意思是小池塘。"}, {"text": "晓事", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是懂事、明白事理。"}, {"text": "小视", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是轻视。"}, {"text": "小室", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，意思是小房间。"}], "explanations": {"小时": "小时：时间单位，等于六十分钟。", "小池": "chí 与 shí 声母不同（ch 与 sh），意思是小池塘。", "晓事": "shì（第四声）与 shí（第二声）声调不同，意思是懂事、明白事理。", "小视": "shì（第四声）与 shí（第二声）声调不同，意思是轻视。", "小室": "shì（第四声）与 shí（第二声）声调不同，意思是小房间。"}, "sentence_index": null, "correct_answer": "小时"}, "level_3": {"options": [{"text": "小时", "is_correct": true, "explanation": "小时：会议持续了三个小时，大家都累了，与语境吻合。"}, {"text": "公里", "is_correct": false, "explanation": "搭配：“开会”的长短只能用时间单位计量，“公里”是长度单位，不能用来说会议时长。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“字”是文字的单位，不能用来计量开会的时间。"}, {"text": "秒", "is_correct": false, "explanation": "语义：三秒钟的会议与“大家都累了”的语境不符，时长太短。"}], "explanations": {"小时": "小时：会议持续了三个小时，大家都累了，与语境吻合。", "公里": "搭配：“开会”的长短只能用时间单位计量，“公里”是长度单位，不能用来说会议时长。", "字": "搭配：“字”是文字的单位，不能用来计量开会的时间。", "秒": "语义：三秒钟的会议与“大家都累了”的语境不符，时长太短。"}, "sentence_index": 6, "correct_answer": "小时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子今年八小时了。", "explanation": "这里应该用〈岁〉。问年龄要用“岁”，“小时”只表示时间长度，不能用来说人的年龄。"}, {"text": "我在超市等了一段小时才结账。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“段”用于时间段或路程，不能直接修饰“小时”。"}, {"text": "这家店我排了两只小时的队。", "explanation": "这里应该用〈个〉。小时作时长的量词是“个”，“只”多用于小动物、成对器官等，不能修饰时间单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天跑步跑一个小时。", "corrected_sentence": "我昨天跑步跑了一个小时。", "error_description": "“跑”后面少了“了”。叙述已经完成的动作和时长，动词后要加“了”，应为“跑步跑了一个小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天在图书馆看书两次小时。", "corrected_sentence": "我每天在图书馆看书两个小时。", "error_description": "“两次小时”用错了量词。“次”计算动作的次数，表示时长要用“个”，应为“两个小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
