INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10906, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过感官或意识察觉到外界事物的存在或变化。", "primary_collocate": null, "pronunciation": "gǎn zhī", "ipa": "kan˨˩ ʈʂɻ̩˥˥", "syllable_count": 2, "sentences": [{"text": "婴儿能感知妈妈的声音。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗能感知主人的心情。", "target_word": "感知", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我感知到房间里有点冷。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一进门，就感知到气氛不对。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盲人用手感知物体的形状。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子能感知大人的情绪变化。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡着的时候，人也能感知周围的声音。", "target_word": "感知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很快感知了这个城市的变化。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他感知到了危险，马上停下了脚步。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在黑暗中，我们靠耳朵感知周围的一切。", "target_word": "感知", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "感知到", "label": "结果补语形式"}, {"form": "感知了", "label": "完成体"}, {"form": "感知力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "用感官或意识察觉外界事物的存在或变化（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "感知：通过感官察觉到妈妈声音的存在，符合语境。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”的对象是可见的事物，不能接“声音”。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”针对味道，不能用来接“声音”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掷的动作，与察觉声音无关。"}], "explanations": {"感知": "感知：通过感官察觉到妈妈声音的存在，符合语境。", "看": "搭配：“看”的对象是可见的事物，不能接“声音”。", "尝": "搭配：“尝”针对味道，不能用来接“声音”。", "扔": "语义：“扔”是抛掷的动作，与察觉声音无关。"}, "sentence_index": 0, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书店感知了一本新书，并付了钱。", "explanation": "这里应该用〈买〉。买书要用“买”，“感知”指通过感官或意识察觉事物的存在或变化，不能表示购买。"}, {"text": "我感知他很多年了。", "explanation": "这里应该用〈认识〉。与人相识要用“认识”，感知不能用于人与人的交往关系。"}, {"text": "这道题的答案我感知了。", "explanation": "这里应该用〈知道〉。知道答案是对事实的了解，感知不能用来表示已经知道的信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感知", "is_correct": true, "explanation": "感知：睡着时仍能察觉周围的声音，符合语境。"}, {"text": "闭", "is_correct": false, "explanation": "语义：“闭”指关闭，“闭周围的声音”与察觉声音的意思不合。"}, {"text": "吞", "is_correct": false, "explanation": "搭配：“吞”的对象是食物或液体，不能接“声音”。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿过、穿戴，“能穿周围的声音”说不通。"}], "explanations": {"感知": "感知：睡着时仍能察觉周围的声音，符合语境。", "闭": "语义：“闭”指关闭，“闭周围的声音”与察觉声音的意思不合。", "吞": "搭配：“吞”的对象是食物或液体，不能接“声音”。", "穿": "语义：“穿”指穿过、穿戴，“能穿周围的声音”说不通。"}, "sentence_index": 6, "correct_answer": "感知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我记住了老师的电话号码，但感知了老师的电话号码。", "explanation": "这里应该用〈记住〉。记住号码要用“记住”，感知只指察觉外界的存在或变化，不能表示记住信息。"}, {"text": "我在邮局感知了一封信，并付了邮费。", "explanation": "这里应该用〈寄〉。寄信要用“寄”，“感知”指察觉外界事物的存在或变化，不能表示把信送出去。"}, {"text": "他很快就感知完了老师布置的作业。", "explanation": "这里应该用〈完成〉。做完作业要用“完成”，“感知”只表示察觉存在或变化，不能表示做完任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子很快就感知了到大人的情绪。", "corrected_sentence": "孩子很快就感知到了大人的情绪。", "error_description": "“了”放错了位置。结果补语“到”要紧跟“感知”，“了”放在“到”之后，应为“感知到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经感知了过这种危险。", "corrected_sentence": "我曾经感知过这种危险。", "error_description": "“了”与“过”不能同时使用。“曾经”表示经历过的事，只用“过”，应去掉“了”，应为“曾经感知过这种危险”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
