INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "墨西哥人指具有墨西哥国籍或来自墨西哥的人。", "primary_collocate": null, "pronunciation": "mò xī gē rén", "ipa": "mwɔ˥˩ ɕi˥ kɤ˥ ʐən˧˥", "syllable_count": 4, "sentences": [{"text": "中国人、美国人、墨西哥人要互相理解。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "中国人可能习惯准时开始，而墨西哥人可能认为稍微迟到没关系。", "target_word": "墨西哥人", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我的邻居是墨西哥人，他很爱吃辣。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位墨西哥人会说西班牙语。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多墨西哥人喜欢在节日里唱歌跳舞。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是墨西哥人，不是美国人。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墨西哥人做的玉米饼又香又好吃。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位墨西哥人，他住在北京。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墨西哥人常常用辣椒做菜。", "target_word": "墨西哥人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的先生是墨西哥人，家在墨西哥城。", "target_word": "墨西哥人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "来自墨西哥或有墨西哥国籍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '411da9e4-51a0-498e-b4c5-a2af973994ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "墨西哥", "is_correct": false, "explanation": "语义：“墨西哥”是国家名，与并列的“中国人、美国人”不是同类，不能并列充当“互相理解”的主语。"}, {"text": "墨西哥语", "is_correct": false, "explanation": "语义：“墨西哥语”指语言，不是人群，与“互相理解”的主语不符。"}, {"text": "墨西哥菜", "is_correct": false, "explanation": "搭配：与“中国人、美国人”并列的应是人群，“墨西哥菜”不能与“互相理解”搭配。"}, {"text": "墨西哥人", "is_correct": true, "explanation": "“墨西哥人”指墨西哥国籍或来自墨西哥的人，与“中国人、美国人”并列，指人群。"}], "explanations": {"墨西哥": "语义：“墨西哥”是国家名，与并列的“中国人、美国人”不是同类，不能并列充当“互相理解”的主语。", "墨西哥语": "语义：“墨西哥语”指语言，不是人群，与“互相理解”的主语不符。", "墨西哥菜": "搭配：与“中国人、美国人”并列的应是人群，“墨西哥菜”不能与“互相理解”搭配。", "墨西哥人": "“墨西哥人”指墨西哥国籍或来自墨西哥的人，与“中国人、美国人”并列，指人群。"}, "sentence_index": 0, "correct_answer": "墨西哥人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去过墨西哥人。", "explanation": "这里应该用〈墨西哥〉。“去过”后接地点，墨西哥人指人。"}, {"text": "我家在墨西哥人。", "explanation": "这里应该用〈墨西哥城〉。“家在”后接地点，墨西哥人指人。"}, {"text": "这艘船要穿过墨西哥人。", "explanation": "这里应该用〈墨西哥湾〉。“穿过”后接水域或地点，墨西哥人指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "墨西哥风", "is_correct": false, "explanation": "配价：“做”需要能动的施事，“墨西哥风”是风格，不能作“做玉米饼”的施事。"}, {"text": "墨西哥语", "is_correct": false, "explanation": "配价：“做”的施事应是人，“墨西哥语”指语言，不能制作玉米饼。"}, {"text": "墨西哥国旗", "is_correct": false, "explanation": "语义：国旗是旗帜，不能制作玉米饼。"}, {"text": "墨西哥人", "is_correct": true, "explanation": "“墨西哥人”是做饼的施事，指人，与“做的玉米饼”相符。"}], "explanations": {"墨西哥风": "配价：“做”需要能动的施事，“墨西哥风”是风格，不能作“做玉米饼”的施事。", "墨西哥语": "配价：“做”的施事应是人，“墨西哥语”指语言，不能制作玉米饼。", "墨西哥国旗": "语义：国旗是旗帜，不能制作玉米饼。", "墨西哥人": "“墨西哥人”是做饼的施事，指人，与“做的玉米饼”相符。"}, "sentence_index": 6, "correct_answer": "墨西哥人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的画带有墨西哥人。", "explanation": "这里应该用〈墨西哥风〉。“带有”后接风格，墨西哥人指人。"}, {"text": "我们去墨西哥人办签证。", "explanation": "这里应该用〈墨西哥大使馆〉。“去……办签证”后接机构或地点，墨西哥人指人。"}, {"text": "他能说一点墨西哥人。", "explanation": "这里应该用〈墨西哥语〉。“说”后接语言，墨西哥人指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只墨西哥人是我的老师。", "corrected_sentence": "那位墨西哥人是我的老师。", "error_description": "错误在量词：“墨西哥人”指人，应用“位”，“只”用于动物。正确说法是“那位墨西哥人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位墨西哥人们住在我家附近。", "corrected_sentence": "两位墨西哥人住在我家附近。", "error_description": "错误在“们”：“两位”已表示确定的人数，“墨西哥人”后面不能再加“们”。正确说法是“两位墨西哥人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
