INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10913, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示在任何时间，无论什么时候。", "primary_collocate": null, "pronunciation": "suí shí", "ipa": "swei˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "有些人先做计划，有些人喜欢随时改变日程安排。", "target_word": "随时", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他喜欢随时调整自己的计划。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机随时都带在身上。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板随时会来检查工作。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你需要帮助，我随时在这里。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的天气变化快，出门要随时看天气。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人的情况，护士要随时记录。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他随时准备着去另一个城市工作。", "target_word": "随时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要随时注意前面的车。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生有问题，可以随时去办公室问老师。", "target_word": "随时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "随时随地", "label": "固定组合"}, {"form": "隨時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不论何时、想做就做或需要就做（副词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示任何时候都可以改变，与“先做计划”形成对比。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“改变日程安排”相矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不与“喜欢……改变”搭配。"}, {"text": "按时", "is_correct": false, "explanation": "语义：“按时”指在约定的时间做事，不表示随时改变日程。"}], "explanations": {"随时": "正确。“随时”表示任何时候都可以改变，与“先做计划”形成对比。", "永远": "语义：“永远”表示持续不变，与“改变日程安排”相矛盾。", "从来": "搭配：“从来”多与否定词连用，不与“喜欢……改变”搭配。", "按时": "语义：“按时”指在约定的时间做事，不表示随时改变日程。"}, "sentence_index": 0, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天随时去了超市。", "explanation": "这里应该删去〈随时〉。随时表示不确定的任何时候，不能与“昨天”这类已过去的确定日期同用，去掉后为“我昨天去了超市。”"}, {"text": "他一听到消息就随时出发了。", "explanation": "这里应该用〈立刻〉。随时表示任何时候都可以，不表示接到消息后马上行动。"}, {"text": "他随时出生在北京。", "explanation": "这里应该删去〈随时〉。随时表示任何时候都可以，不能修饰出生这类只发生一次的确定事件，应为“他出生在北京。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示任何时候都要记录，与“护士要”的要求相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“护士要……记录”的要求相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“随便”多修饰“说”“做”等动作，不常用来修饰“记录”病人情况。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”指杂乱无章，与病人情况需要准确记录的要求相矛盾。"}], "explanations": {"随时": "正确。“随时”表示任何时候都要记录，与“护士要”的要求相符。", "偶尔": "语义：“偶尔”表示不经常，与“护士要……记录”的要求相矛盾。", "随便": "搭配：“随便”多修饰“说”“做”等动作，不常用来修饰“记录”病人情况。", "乱": "语义：“乱”指杂乱无章，与病人情况需要准确记录的要求相矛盾。"}, "sentence_index": 6, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去超市，随时买了牛奶。", "explanation": "这里应该用〈顺便〉。随时表示任何时候都可以，不表示在别的事情之外顺带做某事。"}, {"text": "明天随时要交作业。", "explanation": "这里应该用〈一定〉。随时只表示任何时候都可以，不表示必须或必定。"}, {"text": "他随时迟到了。", "explanation": "这里应该用〈再次〉。随时表示任何时候都可能，不能表示又一次发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "客人随时地可以来我家。", "corrected_sentence": "客人随时可以来我家。", "error_description": "错误形式：“随时地”，给副词“随时”多加了“地”。“随时”是副词，后面不加“地”，应为“随时可以”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们很随时可以去。", "corrected_sentence": "我们随时可以去。", "error_description": "错误形式：“很随时”，副词“随时”前不能加程度副词“很”。应去掉“很”，说“我们随时可以去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“差别”相对，指事物之间没有不同之处。"}, {"text": "速度", "is_correct": false, "explanation": "速度指物体运动的快慢，与“差别”没有反义关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音指由振动产生的声响，与“差别”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热的程度，与“差别”没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“差别”相对，指事物之间没有不同之处。", "速度": "速度指物体运动的快慢，与“差别”没有反义关系。", "声音": "声音指由振动产生的声响，与“差别”没有反义关系。", "温度": "温度指冷热的程度，与“差别”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相同", "is_correct": true, "explanation": "正确。“相同”与“差别”相对，指事物之间没有不同之处。"}, {"text": "高度", "is_correct": false, "explanation": "高度指高低的程度，与“差别”没有反义关系。"}, {"text": "年龄", "is_correct": false, "explanation": "年龄指人或事物存在的时间长短，与“差别”没有反义关系。"}, {"text": "方向", "is_correct": false, "explanation": "方向指物体所朝的位置，与“差别”没有反义关系。"}], "correct_answer": "相同", "explanations": {"相同": "正确。“相同”与“差别”相对，指事物之间没有不同之处。", "高度": "高度指高低的程度，与“差别”没有反义关系。", "年龄": "年龄指人或事物存在的时间长短，与“差别”没有反义关系。", "方向": "方向指物体所朝的位置，与“差别”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物之间不相同的地方；差异。", "primary_collocate": null, "pronunciation": "chā bié", "ipa": "ʈʂʰa˥ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这种差别叫做“时间观念”。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这两个城市的差别很大。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说出这两个词的差别吗？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎之间也有一些小差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方和南方的饮食有很大差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看不出这两件衣服有什么差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种茶的差别在哪里？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年龄不同，想法也有差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了两种说法的差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个差别虽然很小，但是很重要。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物之间在性质、程度等方面的不同之处，即差异", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f5c53d1-4ea1-4d6d-9e6a-58003c554ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。“差别”指事物之间不相同的地方，“这种差别”指代前文的不同之处，并以“时间观念”命名。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的身体高度，不能用来指一种时间观念上的不同。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能被命名为“时间观念”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官属性，与“时间观念”这一抽象概念不相符。"}], "explanations": {"差别": "正确。“差别”指事物之间不相同的地方，“这种差别”指代前文的不同之处，并以“时间观念”命名。", "身高": "体貌：身高指人或动物的身体高度，不能用来指一种时间观念上的不同。", "颜色": "语义：颜色是视觉属性，不能被命名为“时间观念”。", "味道": "语义：味道是感官属性，与“时间观念”这一抽象概念不相符。"}, "sentence_index": 0, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的差别很远，每天要坐一个小时车。", "explanation": "这里应该用〈距离〉。差别是不同之处，不能用来说地点之间的远近；说远近要用“距离”。"}, {"text": "他的差别是画画，很有意思。", "explanation": "这里应该用〈爱好〉。差别指事物之间不同的地方，不能拿来说做的事；表示喜欢做的事要说“爱好”。"}, {"text": "他的差别很高，比我们都高。", "explanation": "这里应该用〈个子〉。差别是抽象的不同之处，不能用来说人的高矮；说高矮要用“个子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。句中问的是这两种茶之间的不同之处在哪里，“差别”与句意相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体型，茶没有身材，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的身体高度，茶没有身高，句子不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人的心理特征，不能用来说两种茶的不同之处。"}], "explanations": {"差别": "正确。句中问的是这两种茶之间的不同之处在哪里，“差别”与句意相符。", "身材": "体貌：身材指人或动物的体型，茶没有身材，句子不通。", "身高": "体貌：身高指人或动物的身体高度，茶没有身高，句子不通。", "性格": "语义：性格属于人的心理特征，不能用来说两种茶的不同之处。"}, "sentence_index": 6, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个差别很短，半小时就能到。", "explanation": "这里应该用〈路线〉。差别指不同之处，不能用来描述走的距离；说路程远近要用“路线”或“路程”。"}, {"text": "这个差别很漂亮。", "explanation": "这里应该用〈大〉或〈小〉。差别指不同之处，不能用“漂亮”来形容。"}, {"text": "我们走过的这段差别很长。", "explanation": "这里应该用〈路程〉。差别指不同之处，不能用来形容走过的距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种茶有一片明显的差别。", "corrected_sentence": "这两种茶有一种明显的差别。", "error_description": "量词错误：“差别”是抽象名词，量词应该用“种”或“点”，不能用“片”。正确说法是“一种明显的差别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两种说法之间是差别。", "corrected_sentence": "两种说法之间有差别。", "error_description": "动词错误：表示事物之间存在差别要用“有”，“是”用于判断，不能说“是差别”。正确说法是“有差别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "粗鲁", "is_correct": true, "explanation": "“粗鲁”指言语动作粗俗、不讲礼节，是“礼貌”的反义词。"}, {"text": "诚恳", "is_correct": false, "explanation": "“诚恳”指态度真诚，与“礼貌”不构成反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”指不怕困难和危险，与“礼貌”的意思无关。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑反应快，与“礼貌”的意思无关。"}], "correct_answer": "粗鲁", "explanations": {"粗鲁": "“粗鲁”指言语动作粗俗、不讲礼节，是“礼貌”的反义词。", "诚恳": "“诚恳”指态度真诚，与“礼貌”不构成反义关系。", "勇敢": "“勇敢”指不怕困难和危险，与“礼貌”的意思无关。", "聪明": "“聪明”指头脑反应快，与“礼貌”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "懒惰", "is_correct": false, "explanation": "“懒惰”指不愿劳动，与“礼貌”的意思无关。"}, {"text": "粗野", "is_correct": true, "explanation": "“粗野”指举止粗鲁、不文雅，是“礼貌”的反义词。"}, {"text": "富有", "is_correct": false, "explanation": "“富有”指财产多或内容丰富，与“礼貌”的意思无关。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”指心地好，是正面评价，与“礼貌”不构成反义关系。"}], "correct_answer": "粗野", "explanations": {"懒惰": "“懒惰”指不愿劳动，与“礼貌”的意思无关。", "粗野": "“粗野”指举止粗鲁、不文雅，是“礼貌”的反义词。", "富有": "“富有”指财产多或内容丰富，与“礼貌”的意思无关。", "善良": "“善良”指心地好，是正面评价，与“礼貌”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "言语动作谦虚、恭敬、友好的表现。", "primary_collocate": null, "pronunciation": "lǐ mào", "ipa": "li˨˩ mau˥˩", "syllable_count": 2, "sentences": [{"text": "人们觉得开会或约会迟到是不礼貌的。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "玩的时候要礼貌，要尊重别人。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他很有礼貌，见到老师先问好。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要从小学会礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要有礼貌，不能大声喊叫。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进别人的房间前先敲门，这是礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对每个客人都很有礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭时看手机不太礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用“请”和“谢谢”是最基本的礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，别人给你东西，要用两只手接，这样更有礼貌。", "target_word": "礼貌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "礼貌用语", "label": "复合词"}, {"form": "不礼貌", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "礼貌：言语和动作上谦虚、恭敬、友好的表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”说场面或气氛，不用来评价迟到这种行为。"}, {"text": "礼貌", "is_correct": true, "explanation": "“不礼貌”指言行不得体，用来评价迟到，符合句意。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”说明白、分明，不用来评价迟到。"}, {"text": "安全", "is_correct": false, "explanation": "语义：“安全”说人身或财物不受威胁，不用来评价迟到这种行为。"}], "explanations": {"热闹": "语义：“热闹”说场面或气氛，不用来评价迟到这种行为。", "礼貌": "“不礼貌”指言行不得体，用来评价迟到，符合句意。", "清楚": "语义：“清楚”说明白、分明，不用来评价迟到。", "安全": "语义：“安全”说人身或财物不受威胁，不用来评价迟到这种行为。"}, "sentence_index": 0, "correct_answer": "礼貌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次婚礼的礼貌很隆重。", "explanation": "这里应该用〈礼仪〉。“礼仪”指隆重的仪式规范，可以说“很隆重”；“礼貌”是待人的态度，不能用来形容仪式隆重。"}, {"text": "这位外宾受到了高规格的礼貌。", "explanation": "这里应该用〈礼遇〉。“礼遇”指给予的优待和接待规格，可以说“高规格”；“礼貌”是待人的态度，不能这样说。"}, {"text": "他看到老人上车，就主动礼貌座位。", "explanation": "这里应该用〈礼让〉。“礼让座位”指主动把座位让给别人；“礼貌”是态度，不能作动词带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钱", "is_correct": false, "explanation": "语义：“很有钱”说的是财富，与对客人的态度无关。"}, {"text": "礼貌", "is_correct": true, "explanation": "“很有礼貌”说的是对待客人的态度，与句意相符。"}, {"text": "力量", "is_correct": false, "explanation": "搭配：“力量”多用于能力或作用，不用来形容对待客人的态度。"}, {"text": "名气", "is_correct": false, "explanation": "语义：“名气”说的是社会知名度，不能说明对客人的态度。"}], "explanations": {"钱": "语义：“很有钱”说的是财富，与对客人的态度无关。", "礼貌": "“很有礼貌”说的是对待客人的态度，与句意相符。", "力量": "搭配：“力量”多用于能力或作用，不用来形容对待客人的态度。", "名气": "语义：“名气”说的是社会知名度，不能说明对客人的态度。"}, "sentence_index": 6, "correct_answer": "礼貌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的话里有一条礼貌，大家都很喜欢听。", "explanation": "这里应该用〈种〉。礼貌是抽象名词，计量时用“种”；“条”用于细长的东西。"}, {"text": "他的态度里有一张礼貌，让人很放心。", "explanation": "这里应该用〈种〉。“张”用于纸张、桌子之类平面的东西，不能用来计量礼貌。"}, {"text": "这个孩子身上有一把礼貌，老师都很喜欢他。", "explanation": "这里应该用〈种〉。“把”用于有柄的器具，不能用来计量礼貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有礼貌的向老师问好。", "corrected_sentence": "他有礼貌地向老师问好。", "error_description": "修饰语用错。“有礼貌”修饰动词“问好”，修饰语要用“地”，应说“有礼貌地向老师问好”；“礼貌的”后接动词是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟老师说话说地很礼貌。", "corrected_sentence": "他跟老师说话说得很礼貌。", "error_description": "补语标记用错。“很礼貌”作“说话”的补语，补语前的标记应用“得”，应说“说得很礼貌”；“说地很礼貌”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
