INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10924, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依照规定或约定的时间。", "primary_collocate": null, "pronunciation": "àn shí", "ipa": "an˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "如果事情没按时开始，有些人会感到不开心。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "请你明天按时来上课。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天按时吃药。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车按时到站了。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业要按时交给老师。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是按时完成工作。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要按时开会，不要迟到。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我按时睡觉。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体好，一定要按时吃饭。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每个月都按时发工资。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "按時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，做事严格依照规定或约定的时间，不早不晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f5c53d1-4ea1-4d6d-9e6a-58003c554ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”修饰不定期重复出现的动作，不能修饰“开始”这样的一次性事件。"}, {"text": "按时", "is_correct": true, "explanation": "按时：依照规定或约定的时间，正好表达“没有按时间开始”。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”说动作的速度，不说是否依照时间开始，与句中的时间要求不符。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”说不讲究、不在意，与“没…开始”所表达的时间要求不通。"}], "explanations": {"偶尔": "搭配：“偶尔”修饰不定期重复出现的动作，不能修饰“开始”这样的一次性事件。", "按时": "按时：依照规定或约定的时间，正好表达“没有按时间开始”。", "慢慢": "语义：“慢慢”说动作的速度，不说是否依照时间开始，与句中的时间要求不符。", "随便": "语义：“随便”说不讲究、不在意，与“没…开始”所表达的时间要求不通。"}, "sentence_index": 0, "correct_answer": "按时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一阵大风按时刮倒了广告牌。", "explanation": "这里应该用〈突然〉。按时指依照规定的时间做事，大风刮倒广告牌是临时发生的，没有规定时间，不能用按时。"}, {"text": "天气按时变暖了。", "explanation": "这里应该用〈逐渐〉。按时说的是依照规定的时间做事，天气变暖是一点一点发生的变化，没有规定的时间，不能用按时。"}, {"text": "他按时喜欢上了这座城市。", "explanation": "这里应该用〈渐渐〉。按时指依照规定或约定的时间做事，“喜欢上”是逐渐产生的心理变化，没有时间表，不能用按时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白白", "is_correct": false, "explanation": "语义：“白白”说徒劳无益，与“我们要…开会”的正常安排相矛盾。"}, {"text": "按时", "is_correct": true, "explanation": "按时：依照规定的时间，与“不要迟到”前后呼应。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：“再三”多用于重复劝告或请求，不修饰“开会”这样的事务。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”说有意而为，与“不要迟到”的要求相悖，不合常理。"}], "explanations": {"白白": "语义：“白白”说徒劳无益，与“我们要…开会”的正常安排相矛盾。", "按时": "按时：依照规定的时间，与“不要迟到”前后呼应。", "再三": "搭配：“再三”多用于重复劝告或请求，不修饰“开会”这样的事务。", "故意": "语义：“故意”说有意而为，与“不要迟到”的要求相悖，不合常理。"}, "sentence_index": 6, "correct_answer": "按时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画画得很按时。", "explanation": "这里应该用〈逼真〉。按时指依照规定或约定的时间做事，描述绘画效果的好坏不是时间问题，不能用按时。"}, {"text": "这道题我按时想明白了。", "explanation": "这里应该用〈终于〉。按时指依照规定或约定的时间做事，“想明白”是思考后得出的结果，不能按时间表完成。"}, {"text": "他按时摔倒在地上。", "explanation": "这里应该用〈不小心〉。按时指依照规定的时间做事，“摔倒”是意外，无法依时间表发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的按时交了报告。", "corrected_sentence": "她按时交了报告。", "error_description": "错误：副词“按时”前不能加“的”，它只能直接作状语。正确说法是“她按时交了报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他了按时回家，妈妈很着急。", "corrected_sentence": "他没按时回家，妈妈很着急。", "error_description": "错误：否定词“没”被换成了“了”。否定“按时回家”要用“没”，说“没按时回家”表示没有按时回家；“了”是完成标记，不能放在主语后、“按时”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7cb747d9-a693-4515-907d-dfb4b8efd201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "紧张", "is_correct": true, "explanation": "与“轻松”构成反义：轻松指心里没有负担，紧张指心里绷着、不放松。"}, {"text": "复杂", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“简单”相对。"}, {"text": "愉快", "is_correct": false, "explanation": "与“轻松”无反义关系，二者语义相近，常连用。"}, {"text": "安静", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“吵闹”相对。"}], "correct_answer": "紧张", "explanations": {"紧张": "与“轻松”构成反义：轻松指心里没有负担，紧张指心里绷着、不放松。", "复杂": "与“轻松”无反义关系，它与“简单”相对。", "愉快": "与“轻松”无反义关系，二者语义相近，常连用。", "安静": "与“轻松”无反义关系，它与“吵闹”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "沉重", "is_correct": true, "explanation": "与“轻松”构成反义：沉重指心情压抑、负担重。"}, {"text": "简单", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“复杂”相对。"}, {"text": "干净", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“脏”相对。"}, {"text": "明显", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“隐蔽”相对。"}], "correct_answer": "沉重", "explanations": {"沉重": "与“轻松”构成反义：沉重指心情压抑、负担重。", "简单": "与“轻松”无反义关系，它与“复杂”相对。", "干净": "与“轻松”无反义关系，它与“脏”相对。", "明显": "与“轻松”无反义关系，它与“隐蔽”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "感到没有负担或压力，不紧张；也指做事情容易，不费力。", "primary_collocate": null, "pronunciation": "qīng sōng", "ipa": "tɕʰiŋ˥ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "但在另一些国家，比如西班牙或巴西，人们对时间的看法更轻松。", "target_word": "轻松", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "考试结束了，我觉得很轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末不用工作，大家的心情都很轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了她的话，我心里轻松多了。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "辞职以后，他的生活比以前轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话很幽默，课堂气氛特别轻松。", "target_word": "轻松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情都做完了，他终于可以轻松地休息一下。", "target_word": "轻松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试前别紧张，放轻松一点。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作不太累，做起来很轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们聊着天，气氛轻松又愉快。", "target_word": "轻松", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻轻松松", "label": "重叠"}, {"form": "轻松愉快", "label": "复合"}, {"form": "輕鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心情或状态没有负担压力；事情做起来不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“更轻松”说人们对时间的看法更放松、不那么紧绷。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“看法”不能用“亮”来形容。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体的厚度，与对时间的看法无关。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”说长短，不能说看法的程度长。"}], "explanations": {"轻松": "正确：“更轻松”说人们对时间的看法更放松、不那么紧绷。", "亮": "搭配：“看法”不能用“亮”来形容。", "厚": "语义：“厚”说物体的厚度，与对时间的看法无关。", "长": "语义：“长”说长短，不能说看法的程度长。"}, "sentence_index": 0, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款手机的屏幕很轻松，颜色也很鲜艳。", "explanation": "这里应该用〈清晰〉。轻松指心理或做事不费力，不用来形容屏幕的效果。"}, {"text": "这场雨下得很轻松，地面几乎没有湿。", "explanation": "这里应该用〈小〉。轻松指心理或做事不费力，不用来形容雨势。"}, {"text": "她的身材很轻松，像一只燕子。", "explanation": "这里应该用〈轻盈〉。轻盈形容身体动作轻巧灵活，“轻松”指做事不费力，不用来形容身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“终于可以轻松地休息一下”中，“轻松”修饰“休息”，表示没有压力地休息。"}, {"text": "匆忙", "is_correct": false, "explanation": "语义：“匆忙”说急急忙忙，与“终于可以休息一下”的从容语境相冲突。"}, {"text": "吃力", "is_correct": false, "explanation": "语义：“吃力”说费劲，与“事情都做完了”后休息的语境不符。"}, {"text": "慌乱", "is_correct": false, "explanation": "搭配：“慌乱”多用于心绪，不能用来修饰“休息”。"}], "explanations": {"轻松": "正确：“终于可以轻松地休息一下”中，“轻松”修饰“休息”，表示没有压力地休息。", "匆忙": "语义：“匆忙”说急急忙忙，与“终于可以休息一下”的从容语境相冲突。", "吃力": "语义：“吃力”说费劲，与“事情都做完了”后休息的语境不符。", "慌乱": "搭配：“慌乱”多用于心绪，不能用来修饰“休息”。"}, "sentence_index": 6, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的声音很轻松，听起来很温柔。", "explanation": "这里应该用〈轻柔〉。轻柔形容声音、动作温和柔和，不用“轻松”形容声音。"}, {"text": "他只受了轻松的伤，休息几天就好了。", "explanation": "这里应该用〈轻微〉。轻微形容伤势、程度轻，“轻松”不修饰“伤”。"}, {"text": "这碗汤的口味很轻松，不咸也不油。", "explanation": "这里应该用〈清淡〉。清淡形容口味不浓，“轻松”不用来形容口味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "期末考试结束后，我心里很轻松地。", "corrected_sentence": "期末考试结束后，我心里很轻松。", "error_description": "错误：“很轻松”后面多加了“地”。“轻松”前有“很”作谓语时不加“地”，应说“心里很轻松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末一到，我的心情比轻松。", "corrected_sentence": "周末一到，我的心情很轻松。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比轻松”不成立。此处应用程度副词“很”，说“心情很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看轻", "is_correct": true, "explanation": "与“看重”构成反义：看轻指认为不重要、不重视。"}, {"text": "批评", "is_correct": false, "explanation": "与“看重”无反义关系，它指指出缺点，并非与“看重”相对。"}, {"text": "欣赏", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面评价。"}, {"text": "寻找", "is_correct": false, "explanation": "与“看重”无反义关系，它指去找寻某物。"}], "correct_answer": "看轻", "explanations": {"看轻": "与“看重”构成反义：看轻指认为不重要、不重视。", "批评": "与“看重”无反义关系，它指指出缺点，并非与“看重”相对。", "欣赏": "与“看重”无反义关系，二者都是正面评价。", "寻找": "与“看重”无反义关系，它指去找寻某物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "与“看重”构成反义：轻视指认为不重要、不当回事。"}, {"text": "信任", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面态度。"}, {"text": "关心", "is_correct": false, "explanation": "与“看重”无反义关系，它表示在意、挂念。"}, {"text": "发现", "is_correct": false, "explanation": "与“看重”无反义关系，它指找到或察觉某事物。"}], "correct_answer": "轻视", "explanations": {"轻视": "与“看重”构成反义：轻视指认为不重要、不当回事。", "信任": "与“看重”无反义关系，二者都是正面态度。", "关心": "与“看重”无反义关系，它表示在意、挂念。", "发现": "与“看重”无反义关系，它指找到或察觉某事物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为重要而认真对待；重视。", "primary_collocate": null, "pronunciation": "kàn zhòng", "ipa": "kʰan˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "大家不觉得这有问题，因为他们更看重人与人的交流，而不是严格遵守时间。", "target_word": "看重", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我很看重这份工作，所以每天都认真做。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司很看重经验，不太看重学历。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母最看重孩子的健康。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看重朋友，从来不会骗朋友。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板看重你的能力，才让你负责这件事。", "target_word": "看重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要看重诚信，说话要算数。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直很看重这次机会，准备了很久。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比起钱，他更看重家人在一起的时间。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人看重外表，可我更看重性格。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看重了", "label": "体标"}, {"form": "看重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把某事或某种品质当作重要的并认真对待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“更看重人与人的交流”表示认为交流更重要，与后半句的对比一致。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能与“人与人的交流”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，与“交流”的语境无关。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清洁，与“人与人的交流”不相干。"}], "explanations": {"看重": "正确：“更看重人与人的交流”表示认为交流更重要，与后半句的对比一致。", "测量": "搭配：“测量”不能与“人与人的交流”搭配。", "修理": "语义：“修理”指修复器物，与“交流”的语境无关。", "打扫": "语义：“打扫”指清洁，与“人与人的交流”不相干。"}, "sentence_index": 0, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一眼就看重了那件大衣，马上买了下来。", "explanation": "这里应该用〈看中〉。看中指选定、喜欢某个具体的东西；看重指认为人或事重要，宾语多是抽象的。"}, {"text": "我在窗边看重了一只飞过的小鸟。", "explanation": "这里应该用〈看见〉。看见指视觉上看到眼前的东西；看重指认为重要，不表示看到。"}, {"text": "周末我去医院看重生病的奶奶。", "explanation": "这里应该用〈看望〉。看望指探望；看重指认为重要，不表示去探望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“看重诚信”表示认为诚信重要，与“说话要算数”的要求一致。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘诚信”与“说话要算数”的要求相反。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”与“说话要算数”的要求相冲突，句子说不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃诚信”与“说话要算数”相矛盾。"}], "explanations": {"看重": "正确：“看重诚信”表示认为诚信重要，与“说话要算数”的要求一致。", "遗忘": "语义：“遗忘诚信”与“说话要算数”的要求相反。", "破坏": "语义：“破坏”与“说话要算数”的要求相冲突，句子说不通。", "放弃": "语义：“放弃诚信”与“说话要算数”相矛盾。"}, "sentence_index": 6, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老狗每天在门口帮我看重门。", "explanation": "这里应该用〈看门〉。看门指守卫门户，是具体的看护动作；看重指认为重要，不指守门。"}, {"text": "警察负责看重犯人，不能让他们逃跑。", "explanation": "这里应该用〈看守〉。看守指监管犯人，不是认为犯人重要。"}, {"text": "他负责看重仓库，每天检查门窗。", "explanation": "这里应该用〈看管〉。看管指照管保护，看重表示认为重要，二者意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他比看重这次面试的机会。", "corrected_sentence": "他很看重这次面试的机会。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比看重”不成立。此处应用程度副词“很”，说“很看重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一定要看重了诚信，诚实守信。", "corrected_sentence": "我们一定要看重诚信，诚实守信。", "error_description": "错误：“看重”后面加了“了”。“要”表示必要，后面不能接“了”，应说“一定要看重诚信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
