INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10934, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指态度认真，完全按照规则或要求去做，不马虎。", "primary_collocate": null, "pronunciation": "yán gé zūn shǒu", "ipa": "jɛn˧˥ kɤ˧˥ tsuən˥ ʂoʊ˨˩˦", "syllable_count": 4, "sentences": [{"text": "大家不觉得这有问题，因为他们更看重人与人的交流，而不是严格遵守时间。", "target_word": "严格遵守", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "开车时要严格遵守交通规则。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生必须严格遵守学校的规定。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生严格遵守工作制度，不能马虎。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，每个人都要严格遵守规则。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要求员工严格遵守上班时间。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直严格遵守自己的承诺。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "进入工厂的人都要严格遵守安全规定。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们严格遵守了合同上的每一条。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机起飞前，乘客要严格遵守机组的指示。", "target_word": "严格遵守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "严格遵守了", "label": "体标"}, {"form": "嚴格遵守", "label": "繁体"}], "register": "书面", "sense_fingerprint": "完全按照规则或要求做，一点也不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严格遵守", "is_correct": true, "explanation": "符合语境：与“看重人与人的交流”形成对比，说明他们不把严格遵守时间放在首位。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用来修理时间。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”需要请求、邀请之类的对象，时间不能被拒绝。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”多接责任、现实，不说逃避时间。"}], "explanations": {"严格遵守": "符合语境：与“看重人与人的交流”形成对比，说明他们不把严格遵守时间放在首位。", "修理": "搭配：“修理”针对器物，不能用来修理时间。", "拒绝": "语义：“拒绝”需要请求、邀请之类的对象，时间不能被拒绝。", "逃避": "搭配：“逃避”多接责任、现实，不说逃避时间。"}, "sentence_index": 0, "correct_answer": "严格遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师严格遵守学生按时交作业。", "explanation": "这里应该用〈严格要求〉。遵守是自己依照规定去做，要求是对别人提出标准，老师应当严格要求学生，不能说老师遵守学生。"}, {"text": "交警严格遵守超速的车辆。", "explanation": "这里应该用〈查处〉。遵守是自己照规定做，交警对超速车辆是执法处理，要说严格查处。"}, {"text": "公司严格遵守成本，每个月都要检查。", "explanation": "这里应该用〈控制〉。遵守用于规定、制度，成本这类数量要说严格控制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严格遵守", "is_correct": true, "explanation": "符合语境：“一直”与“严格”相配，说明他始终信守自己的承诺。"}, {"text": "冒犯", "is_correct": false, "explanation": "搭配：“冒犯”的对象是人，不说冒犯承诺。"}, {"text": "亲近", "is_correct": false, "explanation": "语义：“亲近”指人与人之间感情接近，不能用于承诺。"}, {"text": "抚养", "is_correct": false, "explanation": "语义：“抚养”指照顾孩子或老人，不能用于承诺。"}], "explanations": {"严格遵守": "符合语境：“一直”与“严格”相配，说明他始终信守自己的承诺。", "冒犯": "搭配：“冒犯”的对象是人，不说冒犯承诺。", "亲近": "语义：“亲近”指人与人之间感情接近，不能用于承诺。", "抚养": "语义：“抚养”指照顾孩子或老人，不能用于承诺。"}, "sentence_index": 6, "correct_answer": "严格遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机组要严格遵守行李的重量。", "explanation": "这里应该用〈检查〉。遵守用于规定、指示，检查行李重量要说严格检查。"}, {"text": "乘客要严格遵守机舱的安静。", "explanation": "这里应该用〈保持〉。遵守的对象是规定或指示，安静是一种状态，要说保持机舱的安静。"}, {"text": "机组要严格遵守火灾的发生。", "explanation": "这里应该用〈防止〉。遵守针对规定，火灾的发生要说严格防止。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他了严格遵守了一条规定。", "corrected_sentence": "他严格遵守了一条规定。", "error_description": "多余的“了”：“了”不能放在状语“严格”之前，应删去，说“他严格遵守了一条规定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在严格遵守了公司的考勤规定。", "corrected_sentence": "他严格遵守了公司的考勤规定。", "error_description": "时态冲突：“正在”表示动作进行中，与表示完成的“了”不能同用，应删去“正在”，说“严格遵守了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
