INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10937, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在某件事情中相对的两个方面或两个人物。", "primary_collocate": null, "pronunciation": "shuāng fāng", "ipa": "ʂwɑŋ˥ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "比如，一个中国公司和一个墨西哥公司合作项目，双方对会议时间的理解可能不一样。", "target_word": "双方", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果双方不了解对方的时间观念，就容易产生误会。", "target_word": "双方", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "比赛前，双方球员互相握手。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过三个小时的谈判，双方终于同意了。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份合同对双方都有好处。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方家长第一次见面，都很高兴。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请吵架的双方坐下来慢慢说。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子的时候，双方要先签合同。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家的领导人说，双方会继续合作。", "target_word": "双方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场误会是双方的错，不是一个人的问题。", "target_word": "双方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情中相对的两个方面或两个人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "双方", "is_correct": true, "explanation": "符合语境：指合作的中国公司和墨西哥公司这两方。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”是许多人的集合，不是相对的两方。"}, {"text": "时代", "is_correct": false, "explanation": "语义：“时代”指历史时期，与句中相对的两家公司不对应，句子说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是能够理解的主体，句子说不通。"}], "explanations": {"双方": "符合语境：指合作的中国公司和墨西哥公司这两方。", "人群": "语义：“人群”是许多人的集合，不是相对的两方。", "时代": "语义：“时代”指历史时期，与句中相对的两家公司不对应，句子说不通。", "天空": "语义：“天空”不是能够理解的主体，句子说不通。"}, "sentence_index": 0, "correct_answer": "双方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次谈判中，双方同意了，另一方却拒绝。", "explanation": "这里应该用〈一边〉。“双方”包括相对的两方全部在内，但句中拒绝的那一边也属于双方，前后矛盾，只能说一边同意。"}, {"text": "三家公司的代表都在场，经过讨论，双方终于同意了。", "explanation": "这里应该用〈多方〉。“双方”只指两方，句中有三家公司，应说多方。"}, {"text": "他们是多年的双方。", "explanation": "这里应该用〈伙伴〉。“双方”指事情中相对的两方，不用来称呼长期相处的伙伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "双方", "is_correct": true, "explanation": "符合语境：指吵架的两方，老师请他们坐下来说。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不参与吵架，不能说吵架的观众。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕不能吵架，“吵架的蛋糕”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会吵架，句子的主语与动作不搭。"}], "explanations": {"双方": "符合语境：指吵架的两方，老师请他们坐下来说。", "观众": "语义：观众不参与吵架，不能说吵架的观众。", "蛋糕": "搭配：蛋糕不能吵架，“吵架的蛋糕”说不通。", "作业": "语义：作业不会吵架，句子的主语与动作不搭。"}, "sentence_index": 6, "correct_answer": "双方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的双方红肿，哭了一晚上。", "explanation": "这里应该用〈双眼〉。“双方”指事情中相对的两方，不用于人体的部位。"}, {"text": "这对双方长得很像。", "explanation": "这里应该用〈双胞胎〉。“双方”指事情中相对的两方，不用来指长得很像的一对人。"}, {"text": "这次加班，他拿到了双方的工资。", "explanation": "这里应该用〈双倍〉。“双方”指事情中相对的两方，不表示倍数，工资按倍数计算要说双倍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议结束后，两个双方都很满意。", "corrected_sentence": "会议结束后，双方都很满意。", "error_description": "数量词重复：“双方”本身已经包含两方，前面不能再加“两个”，应直接说“双方都很满意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "都双方同意了这份合同。", "corrected_sentence": "双方同意了这份合同。", "error_description": "副词位置错误：“都”不能放在主语“双方”之前，语序不通，应删去“都”，说“双方同意了这份合同”；需要强调全部时可说“双方都同意了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
