INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或事物有某种看法，做出判断。", "primary_collocate": null, "pronunciation": "rèn wéi", "ipa": "ɻən˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "中国人可能习惯准时开始，而墨西哥人可能认为稍微迟到没关系。", "target_word": "认为", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我认为这个办法很好。", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人认为早睡对身体好。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师认为他这次考得不错。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你认为明天会下雨吗？", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不认为这道题很难。", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈认为孩子应该多运动。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认为自己做对了。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都认为小王是最好的人选。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我认为你应该先去看医生。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对人或事物有看法并做出判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '943f29bc-1364-4bfc-ba32-b020f53aa631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认为", "is_correct": true, "explanation": "认为：表示墨西哥人对“稍微迟到没关系”形成看法，符合句中“可能”的语境。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：“害怕”表达恐惧，与“没关系”的判断相矛盾，句子读起来不通。"}, {"text": "负责", "is_correct": false, "explanation": "搭配：“负责”的对象是工作、事务，不能接“稍微迟到没关系”这样的判断。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开、回避，与“墨西哥人可能……没关系”的判断无关，句子不通。"}], "explanations": {"认为": "认为：表示墨西哥人对“稍微迟到没关系”形成看法，符合句中“可能”的语境。", "害怕": "语义：“害怕”表达恐惧，与“没关系”的判断相矛盾，句子读起来不通。", "负责": "搭配：“负责”的对象是工作、事务，不能接“稍微迟到没关系”这样的判断。", "逃避": "语义：“逃避”指躲开、回避，与“墨西哥人可能……没关系”的判断无关，句子不通。"}, "sentence_index": 0, "correct_answer": "认为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我认为肚子很饿。", "explanation": "这里应该用〈觉得〉。觉得可以表示身体的感受，认为表示对事情的看法和判断，不能用来说自己身体上的感觉。"}, {"text": "他认为很伤心。", "explanation": "这里应该用〈觉得〉。觉得可以表示人的感受，认为表示对事情的判断，不能用来说人的情绪。"}, {"text": "他认为一碗面给我。", "explanation": "这里应该用〈端〉。端表示用手托着送来，认为表示对事情的看法，不能用来说送面的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认为", "is_correct": true, "explanation": "认为：表示妈妈对“孩子应该多运动”形成看法，符合句意。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”的宾语是责任、费用，不能接“孩子应该多运动”这样的主张。"}, {"text": "责备", "is_correct": false, "explanation": "配价：“责备”的对象是被指责的人或行为，不能直接带这样的小句，句子不通。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示对已经发生的恩惠表示谢意，不能表达“应该多运动”这样的规范。"}], "explanations": {"认为": "认为：表示妈妈对“孩子应该多运动”形成看法，符合句意。", "承担": "搭配：“承担”的宾语是责任、费用，不能接“孩子应该多运动”这样的主张。", "责备": "配价：“责备”的对象是被指责的人或行为，不能直接带这样的小句，句子不通。", "感激": "语义：“感激”表示对已经发生的恩惠表示谢意，不能表达“应该多运动”这样的规范。"}, "sentence_index": 6, "correct_answer": "认为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我认为很渴。", "explanation": "这里应该用〈觉得〉。觉得可以表示身体的感受，认为表示对事情的看法，不能用来说自己身体上的感觉。"}, {"text": "我认为一杯茶给你。", "explanation": "这里应该用〈倒〉。倒表示把茶斟进杯中，认为表示对事情的看法，不能用来说倒茶的动作。"}, {"text": "爱迪生认为电灯的时候很用心。", "explanation": "这里应该用〈发明〉。发明指创造新事物，认为表示看法，不能用来表示创造了电灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认为了这个计划可行。", "corrected_sentence": "我认为这个计划可行。", "error_description": "错误在于“认为”后多加了“了”。“认为”表示看法，是不表示完成的动词，不能带“了”；正确说法是“我认为这个计划可行。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不认为了他会迟到。", "corrected_sentence": "我不认为他会迟到。", "error_description": "错误在于“认为”后多加了“了”。“认为”表示看法，是不表示完成的动词，不能带“了”；正确说法是“我不认为他会迟到。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d2a5323-8bfd-4791-8b01-9e493bbb56bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
