INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10940, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度不深或数量不多，常用于动词或形容词前。", "primary_collocate": null, "pronunciation": "shāo wēi", "ipa": "ʂɑʊ̯˥ weɪ̯˥", "syllable_count": 2, "sentences": [{"text": "中国人可能习惯准时开始，而墨西哥人可能认为稍微迟到没关系。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "今天比昨天稍微冷一点。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服稍微有点大。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病稍微好了一些。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把声音稍微调小一点。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜稍微有点咸，但是很好吃。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我稍微有点累，想早点睡。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋稍微贵一点，不过质量很好。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气稍微暖和了一些，我们去公园吧。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话稍微快了点，我没听清楚。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在形容词或动词前，表示程度轻微，如“稍微贵一点”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稍微", "is_correct": true, "explanation": "稍微：表示程度不深，与“迟到没关系”的轻微语境相符。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示程度很高，与“迟到没关系”所说的轻微情况相冲突。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分”表示程度高，不能修饰“迟到没关系”这种轻微情况。"}, {"text": "颇", "is_correct": false, "explanation": "语域：“颇”是书面语，与这句口语化的推断不合，且意为相当，程度也与语境冲突。"}], "explanations": {"稍微": "稍微：表示程度不深，与“迟到没关系”的轻微语境相符。", "特别": "语义：“特别”表示程度很高，与“迟到没关系”所说的轻微情况相冲突。", "十分": "语义：“十分”表示程度高，不能修饰“迟到没关系”这种轻微情况。", "颇": "语域：“颇”是书面语，与这句口语化的推断不合，且意为相当，程度也与语境冲突。"}, "sentence_index": 0, "correct_answer": "稍微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我稍微考了满分。", "explanation": "这里应该用〈完全〉。“稍微”表示程度不深，不能表达“考了满分”那样完全、到顶的程度。"}, {"text": "他稍微把饭全吃光了。", "explanation": "这里应该用〈彻底〉。“稍微”表示程度不深，与把饭全部吃完的彻底程度相矛盾。"}, {"text": "这次旅行我稍微玩得开心极了。", "explanation": "这里应该用〈非常〉。“稍微”表示程度不深，不能与“开心极了”这种程度极高的说法同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稍微", "is_correct": true, "explanation": "稍微：表示程度不深，与“有点累、想早点睡”的轻微疲劳相符。"}, {"text": "非常", "is_correct": false, "explanation": "语义：“非常”表示程度很高，与“有点累”的轻微感受相冲突。"}, {"text": "格外", "is_correct": false, "explanation": "语义：“格外”强调程度特别突出，与“有点累”的轻微程度不符。"}, {"text": "极其", "is_correct": false, "explanation": "语域：“极其”是书面语，与口语句“想早点睡”的语体不合，且程度过高，与“有点”冲突。"}], "explanations": {"稍微": "稍微：表示程度不深，与“有点累、想早点睡”的轻微疲劳相符。", "非常": "语义：“非常”表示程度很高，与“有点累”的轻微感受相冲突。", "格外": "语义：“格外”强调程度特别突出，与“有点累”的轻微程度不符。", "极其": "语域：“极其”是书面语，与口语句“想早点睡”的语体不合，且程度过高，与“有点”冲突。"}, "sentence_index": 6, "correct_answer": "稍微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事稍微弄得清清楚楚。", "explanation": "这里应该用〈十分〉。“稍微”只表示程度不深，与“清清楚楚”所表示的完全清楚不相符，应说十分清楚。"}, {"text": "这道题稍微难得不得了。", "explanation": "这里应该用〈极其〉。“稍微”只表示程度不深，不能修饰“难得不得了”这样程度极深的说法。"}, {"text": "大家稍微都到齐了。", "explanation": "这里应该用〈全部〉。“稍微”只表示程度不深，不能表示全体到齐，应说全部到齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间很稍微有点暗，可以开灯。", "corrected_sentence": "这个房间稍微有点暗，可以开灯。", "error_description": "错误：“稍微”前多加了“很”。“稍微”本身已表示程度不深，与表示程度高的“很”叠用，语义矛盾。正确说法是“这个房间稍微有点暗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包很稍微大一点，我比较喜欢。", "corrected_sentence": "这个包稍微大一点，我比较喜欢。", "error_description": "错误：多加了“很”。“稍微”本身已表示程度不深，与表示程度高的“很”叠用，语义矛盾。正确说法是“这个包稍微大一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
