INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指因为理解不同而出现错误的认识。", "primary_collocate": null, "pronunciation": "chǎn shēng wù huì", "ipa": "tʂʰan˨˩˦ ʂɤŋ˥ u˥˩ xweɪ̯˥˩", "syllable_count": 4, "sentences": [{"text": "如果双方不了解对方的时间观念，就容易产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "说话太快，容易让别人产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不想产生误会，所以先问清楚。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发短信时，句子太短容易产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不产生误会，老师把时间写在黑板上。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕朋友产生误会，马上打电话解释。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言不同的人有时会产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表情很冷，让客人产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人很少见面，就容易产生误会。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家多聊聊，就不会产生误会了。", "target_word": "产生误会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产生了误会", "label": "体标"}, {"form": "产生过误会", "label": "体标"}, {"form": "產生誤會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动宾短语，因沟通或理解不同而出现错误的认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10943, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产生误会", "is_correct": true, "explanation": "产生误会：指因理解不同而出现错误的认识，与“不了解对方”导致的结果相符。"}, {"text": "避免冲突", "is_correct": false, "explanation": "语义：“避免冲突”是防止负面结果，与“容易”引出的消极后果相矛盾。"}, {"text": "增进感情", "is_correct": false, "explanation": "语义：“增进感情”是正面结果，与“不了解对方”的前提相矛盾。"}, {"text": "达成共识", "is_correct": false, "explanation": "语义：“达成共识”是正面结果，与“不了解”导致的消极后果相矛盾。"}], "explanations": {"产生误会": "产生误会：指因理解不同而出现错误的认识，与“不了解对方”导致的结果相符。", "避免冲突": "语义：“避免冲突”是防止负面结果，与“容易”引出的消极后果相矛盾。", "增进感情": "语义：“增进感情”是正面结果，与“不了解对方”的前提相矛盾。", "达成共识": "语义：“达成共识”是正面结果，与“不了解”导致的消极后果相矛盾。"}, "sentence_index": 0, "correct_answer": "产生误会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药很容易产生误会。", "explanation": "这里应该用〈副作用〉。“误会”指人与人之间因理解不同而产生的错误认识，药物引起的不良反应应说副作用。"}, {"text": "这台电脑产生了误会。", "explanation": "这里应该用〈故障〉。“误会”只用于人对事情的理解错误，电脑出问题应说故障。"}, {"text": "这块布料产生了误会。", "explanation": "这里应该用〈起球〉。“误会”不能用于布料，布料表面起小球应说起球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产生误会", "is_correct": true, "explanation": "产生误会：指因理解不同而出现错误的认识，与“语言不同”容易造成的结果相符。"}, {"text": "长出翅膀", "is_correct": false, "explanation": "语义：语言不同不会让人长出翅膀，句意荒谬。"}, {"text": "变成石头", "is_correct": false, "explanation": "语义：语言不同不会让人变成石头，句意荒谬。"}, {"text": "默默无闻", "is_correct": false, "explanation": "语义：“默默无闻”形容没有名气，与“语言不同”导致的人际状况毫无关系。"}], "explanations": {"产生误会": "产生误会：指因理解不同而出现错误的认识，与“语言不同”容易造成的结果相符。", "长出翅膀": "语义：语言不同不会让人长出翅膀，句意荒谬。", "变成石头": "语义：语言不同不会让人变成石头，句意荒谬。", "默默无闻": "语义：“默默无闻”形容没有名气，与“语言不同”导致的人际状况毫无关系。"}, "sentence_index": 6, "correct_answer": "产生误会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个伤口容易产生误会。", "explanation": "这里应该用〈感染〉。“误会”指人对事情理解有误，伤口发炎应说感染。"}, {"text": "这个软件产生了误会。", "explanation": "这里应该用〈漏洞〉。“误会”不能用于软件，软件存在的缺陷应说漏洞。"}, {"text": "她的皮肤产生了误会。", "explanation": "这里应该用〈过敏〉。“误会”不能用于皮肤，皮肤对某物产生反应应说过敏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们之间曾经产生着误会。", "corrected_sentence": "我们之间曾经产生过误会。", "error_description": "错误：“着”用错。“曾经”指已结束的经历，应用表示经历的“过”；“着”表示持续的状态，与“曾经”矛盾。正确说法是“我们之间曾经产生过误会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间把产生误会，后来说清楚了。", "corrected_sentence": "他们之间产生误会，后来说清楚了。", "error_description": "错误：多加了“把”。“产生误会”是动宾结构，没有可以被“把”提前的宾语，“把”放在这里不通。正确说法是“他们之间产生误会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
