INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家与国家之间的交流、合作或往来活动。", "primary_collocate": null, "pronunciation": "guó jì jiāo wǎng", "ipa": "kwo˧˥ tɕi˥˩ tɕjɑʊ̯˥ wɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "在国际交往中，了解别人的文化很重要。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往需要大家互相尊重。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着经济发展，国际交往越来越多。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好外语对国际交往很有帮助。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加国际交往时，要注意礼貌。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学很重视国际交往。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络让国际交往变得更方便。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往中，每个国家都应该得到尊重。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国际交往方面有很多经验。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语是国际交往中常用的语言。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國際交往", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，国家之间的交流、合作和往来活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指国家之间的交流往来，与“了解别人的文化”的语境相合。"}, {"text": "国际象棋", "is_correct": false, "explanation": "语义：象棋是一种棋类游戏，句子讲的是国家之间的交流，与此不符。"}, {"text": "国际天气", "is_correct": false, "explanation": "语义：天气是自然现象，与“了解别人的文化”毫无关系。"}, {"text": "国际地震", "is_correct": false, "explanation": "语义：地震是自然灾害，与“了解别人的文化”毫无关系。"}], "explanations": {"国际交往": "国际交往指国家之间的交流往来，与“了解别人的文化”的语境相合。", "国际象棋": "语义：象棋是一种棋类游戏，句子讲的是国家之间的交流，与此不符。", "国际天气": "语义：天气是自然现象，与“了解别人的文化”毫无关系。", "国际地震": "语义：地震是自然灾害，与“了解别人的文化”毫无关系。"}, "sentence_index": 0, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和同事每天的国际交往都很多，中午常一起吃饭。", "explanation": "这里应该用〈人际交往〉。国际交往指国家与国家之间的往来，同事之间的交往要说人际交往。"}, {"text": "这个城市各区之间的国际交往很频繁。", "explanation": "这里应该用〈地区往来〉。国际交往指国家之间的往来，同一个城市的各区之间不能用它。"}, {"text": "这只猫每天的国际交往很多，常去邻居家串门。", "explanation": "这里应该用〈社交〉。国际交往只用于国家之间，猫与邻居之间的往来不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指国家之间的往来，句中“网络让……变得更方便”正适用于此。"}, {"text": "国际和平", "is_correct": false, "explanation": "语义：和平是一种状态，不能被网络变得更方便。"}, {"text": "国际压力", "is_correct": false, "explanation": "搭配：“压力”不能与“变得更方便”搭配，网络无法使压力变方便。"}, {"text": "国际天气", "is_correct": false, "explanation": "语义：天气是自然现象，网络不能让它变得更方便。"}], "explanations": {"国际交往": "国际交往指国家之间的往来，句中“网络让……变得更方便”正适用于此。", "国际和平": "语义：和平是一种状态，不能被网络变得更方便。", "国际压力": "搭配：“压力”不能与“变得更方便”搭配，网络无法使压力变方便。", "国际天气": "语义：天气是自然现象，网络不能让它变得更方便。"}, "sentence_index": 6, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小组的国际交往很顺利，每周都能完成任务。", "explanation": "这里应该用〈合作〉。国际交往指国家之间的往来，同一小组内的分工配合要说合作。"}, {"text": "他的国际交往很少，只跟两个亲戚见面。", "explanation": "这里应该用〈家庭来往〉。国际交往专指国家之间的往来，与亲戚之间的来往不能这样说。"}, {"text": "我们班的国际交往很多，每天一起上课、吃饭。", "explanation": "这里应该用〈同学交往〉。国际交往专指国家之间的往来，同班同学之间的交往要说同学交往。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们参加了一只国际交往，学到了很多东西。", "corrected_sentence": "我们参加了一次国际交往，学到了很多东西。", "error_description": "量词错误：“国际交往”是一次次的活动，计量应说“次”，“只”不能用于交往。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校组织了一次很国际交往，大家都很高兴。", "corrected_sentence": "学校组织了一次国际交往，大家都很高兴。", "error_description": "修饰语错误：“很”不能修饰“国际交往”这样的名词性短语，应直接说“一次国际交往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
