INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10946, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对事物或情况做出肯定或否定的认识、断定。", "primary_collocate": null, "pronunciation": "pàn duàn", "ipa": "pʰan˥˩ twan˥˩", "syllable_count": 2, "sentences": [{"text": "不要马上判断别人“懒”或“不专业”，也许只是他们的生活方式不同。", "target_word": "判断", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我们不能只看外表就判断一个人。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生根据检查结果判断他没有大病。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你怎么判断这条消息是真的还是假的？", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们判断下面的句子对不对。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从天空的颜色可以判断今天会下雨。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会判断形势，所以生意做得很好。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你根据这些数据判断一下结果。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察根据脚印判断小偷往北边跑了。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我还不能判断他说的话是不是真的。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "判断了", "label": "体标"}, {"form": "判断过", "label": "体标"}, {"form": "判断力", "label": "复合"}, {"form": "判断题", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事物或情况做出肯定或否定的认识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指对情况作出肯定或否定的认识，句中“不要马上……别人”正是对别人下结论。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热做饭，与评价别人是否懒惰无关。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽种植物，用来指对人的看法不合。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”针对房屋或物件，不能以人作为对象。"}], "explanations": {"判断": "判断指对情况作出肯定或否定的认识，句中“不要马上……别人”正是对别人下结论。", "煮": "语义：煮是加热做饭，与评价别人是否懒惰无关。", "种植": "语义：种植是栽种植物，用来指对人的看法不合。", "装修": "搭配：“装修”针对房屋或物件，不能以人作为对象。"}, "sentence_index": 0, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工匠们判断了一座小屋，三天就完工了。", "explanation": "这里应该用〈盖〉。判断是对事情作出认识，建造房屋要说盖。"}, {"text": "妈妈把那个苹果判断成了两半。", "explanation": "这里应该用〈切〉。判断是对情况作出认识，把苹果分成两半要说切。"}, {"text": "我把他的样子判断了下来。", "explanation": "这里应该用〈记〉。判断是对情况作出认识，把样子记下来要说记。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指对情况作出认识，“会……形势”正指对形势作出判断。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对器物，不能用于“形势”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫是清除脏物，与对形势的认识不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”针对具体表面，不能用于抽象的“形势”。"}], "explanations": {"判断": "判断指对情况作出认识，“会……形势”正指对形势作出判断。", "修理": "搭配：“修理”针对器物，不能用于“形势”。", "打扫": "语义：打扫是清除脏物，与对形势的认识不符。", "擦": "搭配：“擦”针对具体表面，不能用于抽象的“形势”。"}, "sentence_index": 6, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们判断了一下菜单，决定点哪几道菜。", "explanation": "这里应该用〈挑选〉。判断是对对错作出认识，从菜单中选菜要说挑选。"}, {"text": "图书馆的管理员判断了这本书的借阅次数。", "explanation": "这里应该用〈统计〉。判断是作出认识或结论，计算借阅次数要说统计。"}, {"text": "孩子们判断了一下小猫的名字。", "explanation": "这里应该用〈取〉。判断是对事情作出认识，给小猫起名字要说取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快判断了着问题的原因。", "corrected_sentence": "他很快判断了问题的原因。", "error_description": "体标错误：“了”和“着”不能同时用在同一个动词后；表示已完成的判断只用“了”，应说“判断了问题的原因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他判断了对这道题的答案。", "corrected_sentence": "他判断对了这道题的答案。", "error_description": "补语错误：结果补语“对”应紧跟动词，说“判断对了”，不能说“判断了对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勤快", "is_correct": true, "explanation": "勤快与懒是反义词，指肯劳动、爱做事。"}, {"text": "聪明", "is_correct": false, "explanation": "与懒不构成反义关系，聪明指智力高。"}, {"text": "漂亮", "is_correct": false, "explanation": "与懒不构成反义关系，漂亮指外貌好看。"}, {"text": "健康", "is_correct": false, "explanation": "与懒不构成反义关系，健康指身体状况良好。"}], "correct_answer": "勤快", "explanations": {"勤快": "勤快与懒是反义词，指肯劳动、爱做事。", "聪明": "与懒不构成反义关系，聪明指智力高。", "漂亮": "与懒不构成反义关系，漂亮指外貌好看。", "健康": "与懒不构成反义关系，健康指身体状况良好。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勤快", "is_correct": true, "explanation": "勤快与懒是反义词，指肯劳动、爱做事。"}, {"text": "热情", "is_correct": false, "explanation": "与懒不构成反义关系，热情指态度热烈。"}, {"text": "热闹", "is_correct": false, "explanation": "与懒不构成反义关系，热闹指场面喧闹。"}, {"text": "整洁", "is_correct": false, "explanation": "与懒不构成反义关系，整洁指干净利落。"}], "correct_answer": "勤快", "explanations": {"勤快": "勤快与懒是反义词，指肯劳动、爱做事。", "热情": "与懒不构成反义关系，热情指态度热烈。", "热闹": "与懒不构成反义关系，热闹指场面喧闹。", "整洁": "与懒不构成反义关系，整洁指干净利落。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "懒惰，不爱劳动或学习。", "primary_collocate": null, "pronunciation": "lǎn", "ipa": "lan˨˩˦", "syllable_count": 1, "sentences": [{"text": "打哈欠不是因为懒，是身体需要。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "不要马上判断别人“懒”或“不专业”，也许只是他们的生活方式不同。", "target_word": "懒", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "他太懒了，房间总是乱七八糟。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明很懒，作业常常不写。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥一点也不懒，每天早起跑步。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只猫又懒又胖，整天睡觉。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "勤快的人容易成功，懒的人什么也得不到。", "target_word": "懒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别这么懒，快起来帮妈妈做饭。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说他不是不聪明，只是有点懒。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很懒，从来不洗碗。", "target_word": "懒", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "懒惰", "label": "复合"}, {"form": "懒鬼", "label": "复合"}, {"form": "懒人", "label": "复合"}], "register": "中性", "sense_fingerprint": "人性格懒惰，不爱劳动学习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65b895df-cc40-4dc8-b88e-de07081c5f2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒 lǎn：不爱劳动、不愿做事，即本条的懒惰义。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是蓝色。"}, {"text": "拦", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是阻拦。"}, {"text": "烂", "is_correct": false, "explanation": "làn（第四声）与 lǎn（第三声）声调不同，意思是腐烂。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 lǎn 韵母不同（ang 与 an），意思是明朗。"}], "explanations": {"懒": "懒 lǎn：不爱劳动、不愿做事，即本条的懒惰义。", "蓝": "lán（第二声）与 lǎn（第三声）声调不同，意思是蓝色。", "拦": "lán（第二声）与 lǎn（第三声）声调不同，意思是阻拦。", "烂": "làn（第四声）与 lǎn（第三声）声调不同，意思是腐烂。", "朗": "lǎng 与 lǎn 韵母不同（ang 与 an），意思是明朗。"}, "sentence_index": null, "correct_answer": "懒"}, "level_3": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒指不爱劳动的性格。句意是打哈欠不是因为这种性格上的懒，是身体需要，只有“懒”符合。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“勤快”与“懒”意思相反，“不是因为勤快”与后文的语境不符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指智力，与打哈欠的生理原因无关，不能用来解释打哈欠。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描写体型，不能说明打哈欠的原因。"}], "explanations": {"懒": "懒指不爱劳动的性格。句意是打哈欠不是因为这种性格上的懒，是身体需要，只有“懒”符合。", "勤快": "语义：“勤快”与“懒”意思相反，“不是因为勤快”与后文的语境不符。", "聪明": "语义：“聪明”指智力，与打哈欠的生理原因无关，不能用来解释打哈欠。", "胖": "体貌：“胖”描写体型，不能说明打哈欠的原因。"}, "sentence_index": 0, "correct_answer": "懒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告写得很懒，错字特别多。", "explanation": "这里应该用〈马虎〉。懒形容人不爱做事的性格，不用来评价报告的质量。"}, {"text": "我的记忆很懒，昨天的事今天就忘了。", "explanation": "这里应该用〈差〉。懒形容人不想做事的习性，不能用来形容记忆力的好坏。"}, {"text": "今天的天气很懒，一会儿阴，一会儿晴。", "explanation": "这里应该用〈多变〉。懒形容人或动物不爱做事的习性，不用来描述天气的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒 lǎn：不爱劳动、不愿做事，即本条的懒惰义。"}, {"text": "栏", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是栏杆。"}, {"text": "篮", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是篮子或篮球的篮。"}, {"text": "兰", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是兰花。"}], "explanations": {"懒": "懒 lǎn：不爱劳动、不愿做事，即本条的懒惰义。", "栏": "lán（第二声）与 lǎn（第三声）声调不同，意思是栏杆。", "篮": "lán（第二声）与 lǎn（第三声）声调不同，意思是篮子或篮球的篮。", "兰": "lán（第二声）与 lǎn（第三声）声调不同，意思是兰花。"}, "sentence_index": null, "correct_answer": "懒"}, "level_3": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒与前句“勤快”构成对比，指不爱做事的人，“懒的人”最符合语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描写外貌，与前句讲的勤快与成功的对比无关。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”无法与“什么也得不到”形成对比，句意不通。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”与勤快与否无关，句子讲的是做事态度，不是家境。"}], "explanations": {"懒": "懒与前句“勤快”构成对比，指不爱做事的人，“懒的人”最符合语境。", "漂亮": "体貌：“漂亮”描写外貌，与前句讲的勤快与成功的对比无关。", "健康": "语义：“健康”无法与“什么也得不到”形成对比，句意不通。", "富有": "语义：“富有”与勤快与否无关，句子讲的是做事态度，不是家境。"}, "sentence_index": 6, "correct_answer": "懒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的反应很懒，老是听不懂我的话。", "explanation": "这里应该用〈迟钝〉。懒指不爱做事，不用来形容反应的快慢。"}, {"text": "他一上台就很懒，手心直冒汗。", "explanation": "这里应该用〈紧张〉。懒指不爱动的习性，不用来描述心理上的紧张。"}, {"text": "听到好消息，他很懒地跳了起来。", "explanation": "这里应该用〈兴奋〉。懒指不愿动，与“跳起来”的兴奋状态矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我懒去超市，就在家点外卖。", "corrected_sentence": "我懒得去超市，就在家点外卖。", "error_description": "“懒”后面漏了“得”。应说“懒得去超市”，表示不想做；“懒去”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一到周末，他就把懒起来了。", "corrected_sentence": "一到周末，他就懒起来了。", "error_description": "“懒”是形容词，不能放进“把”字结构，“把”前也没有需要提前的宾语。应去掉“把”，说“他就懒起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af16ae78-9ad3-4555-8654-f22afd99fb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "业余", "is_correct": true, "explanation": "反义：“业余”指不以此为职业、水平不够专门，与“专业”（水平高）相对。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线，与“专业”没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”说价格，与“专业”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地，与“专业”没有反义关系。"}], "correct_answer": "业余", "explanations": {"业余": "反义：“业余”指不以此为职业、水平不够专门，与“专业”（水平高）相对。", "明亮": "无关：“明亮”形容光线，与“专业”没有反义关系。", "便宜": "无关：“便宜”说价格，与“专业”没有反义关系。", "柔软": "无关：“柔软”形容质地，与“专业”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "业余", "is_correct": true, "explanation": "反义：“业余”指不以此为职业、水平不够专门，与“专业”（水平高）相对。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”形容清洁程度，与“专业”没有反义关系。"}, {"text": "寂寞", "is_correct": false, "explanation": "无关：“寂寞”形容心情，与“专业”没有反义关系。"}, {"text": "好吃", "is_correct": false, "explanation": "无关：“好吃”形容食物味道，与“专业”没有反义关系。"}], "correct_answer": "业余", "explanations": {"业余": "反义：“业余”指不以此为职业、水平不够专门，与“专业”（水平高）相对。", "干净": "无关：“干净”形容清洁程度，与“专业”没有反义关系。", "寂寞": "无关：“寂寞”形容心情，与“专业”没有反义关系。", "好吃": "无关：“好吃”形容食物味道，与“专业”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具有专门知识和技能、水平高的特点。", "primary_collocate": null, "pronunciation": "zhuān yè", "ipa": "ʈʂwan˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "不要马上判断别人“懒”或“不专业”，也许只是他们的生活方式不同。", "target_word": "专业", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这位医生很专业，大家都信他。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她回答问题的方式非常专业。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的服务很专业，我下次还来。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拍照很专业，朋友都找他帮忙。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的摄影技术还不够专业。", "target_word": "专业", "complexity_tier": "T3", "furigana": "lǎo shī shuō wǒ de shè yǐng jì shù hái bú gòu zhuān yè", "sentence_source": "generated"}, {"text": "这样做太不专业了，客人会不高兴的。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她处理这个问题很专业，大家都很放心。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是专业的歌手，但唱得很好。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一位专业的老师教我游泳。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業", "label": "繁体"}, {"form": "专业人士", "label": "复合"}], "register": "中性", "sense_fingerprint": "专业·形容词·具有专门知识和技能、水平高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "“不专业”指工作水平不够高，与“懒”同属对人工作表现的评价，符合“不要马上判断”的语境；这里的“专业”是被否定的对象。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，不能用来评价人的工作水平。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容身材，不能用来评价工作态度。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能用来评价人的工作能力。"}], "explanations": {"专业": "“不专业”指工作水平不够高，与“懒”同属对人工作表现的评价，符合“不要马上判断”的语境；这里的“专业”是被否定的对象。", "明亮": "搭配：“明亮”形容光线或眼神，不能用来评价人的工作水平。", "苗条": "体貌：“苗条”形容身材，不能用来评价工作态度。", "热闹": "搭配：“热闹”形容场面或气氛，不能用来评价人的工作能力。"}, "sentence_index": 0, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个笑话很专业，大家都笑了。", "explanation": "这里应该用〈幽默〉。“专业”形容技能或做事水平，不能用来形容笑话的风趣。"}, {"text": "今天天气很专业，适合出门。", "explanation": "这里应该用〈晴朗〉。“专业”只形容人的技能或做事水平，不能用来形容天气。"}, {"text": "这个孩子很专业，每天都在课堂上捣乱。", "explanation": "这里应该用〈调皮〉。“专业”形容技能或做事水平，不能用来形容小孩的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指业务水平高，与“太不……了”搭配，评价这样做的方式不够专业。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或颜色，不能用来评价做法。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”形容颜色，不能用来评价做法。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，与“这样做”的评价不相符。"}], "explanations": {"专业": "专业：指业务水平高，与“太不……了”搭配，评价这样做的方式不够专业。", "明亮": "搭配：“明亮”形容光线或颜色，不能用来评价做法。", "红": "语义：“红”形容颜色，不能用来评价做法。", "甜": "语义：“甜”指味道，与“这样做”的评价不相符。"}, "sentence_index": 6, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她听到这个消息很专业。", "explanation": "这里应该用〈开心〉。“专业”形容技能或做事水平，不能用来形容心情。"}, {"text": "这间房子很专业，装修得很漂亮。", "explanation": "这里应该用〈宽敞〉。“专业”形容人的技能或做事水平，不能用来形容房子的大小和样子。"}, {"text": "这碗面很专业，我吃得很香。", "explanation": "这里应该用〈好吃〉。“专业”形容技能或做事水平，不能用来评价食物的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的员工都专业，客户很满意。", "corrected_sentence": "这家公司的员工都很专业，客户很满意。", "error_description": "“专业”作谓语时前面要加程度副词“很”，应写成“都很专业”；“都专业”缺少程度副词，形容词直接作谓语不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她找了一位专业地老师学钢琴。", "corrected_sentence": "她找了一位专业的老师学钢琴。", "error_description": "“专业”修饰名词“老师”，应用“的”，写成“专业的老师”；“地”用于修饰动词或形容词，“专业地老师”不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推迟", "is_correct": true, "explanation": "反义：“推迟”表示把预定时间向后移，与“提前”相反。"}, {"text": "出发", "is_correct": false, "explanation": "无关：“出发”指动身，与“时间前移”这一义项没有反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "无关：“等待”指耐心等候，与“提前”的时间调整义没有对立关系。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与“提前”的时间义没有反义关系。"}], "correct_answer": "推迟", "explanations": {"推迟": "反义：“推迟”表示把预定时间向后移，与“提前”相反。", "出发": "无关：“出发”指动身，与“时间前移”这一义项没有反义关系。", "等待": "无关：“等待”指耐心等候，与“提前”的时间调整义没有对立关系。", "讨论": "无关：“讨论”指交换意见，与“提前”的时间义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推迟", "is_correct": true, "explanation": "反义：“推迟”表示把预定时间向后移，与“提前”相反。"}, {"text": "结束", "is_correct": false, "explanation": "无关：“结束”指事情到此为止，与“提前”的时间前移义没有反义关系。"}, {"text": "准备", "is_correct": false, "explanation": "无关：“准备”指事先做好安排，与“提前”的时间调整义没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "无关：“休息”指停下来恢复体力，与“提前”没有反义关系。"}], "correct_answer": "推迟", "explanations": {"推迟": "反义：“推迟”表示把预定时间向后移，与“提前”相反。", "结束": "无关：“结束”指事情到此为止，与“提前”的时间前移义没有反义关系。", "准备": "无关：“准备”指事先做好安排，与“提前”的时间调整义没有对立关系。", "休息": "无关：“休息”指停下来恢复体力，与“提前”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把预定的时间或日期向前移动。", "primary_collocate": null, "pronunciation": "tí qián", "ipa": "tʰi˧˥ tɕʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "为了赶上末班车，我们把聚会时间提前了一个小时。", "target_word": "提前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议提前到明天上午九点了。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板把会议提前了一个小时。", "target_word": "提前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的出发时间提前了两天。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司决定把放假时间提前一周。", "target_word": "提前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航班的起飞时间提前了半小时。", "target_word": "提前", "complexity_tier": "T3", "furigana": "háng bān de qǐ fēi shí jiān tí qián le bàn xiǎo shí", "sentence_source": "generated"}, {"text": "天气太冷，学校提前放寒假了。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的工资提前三天发给我们了。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有急事，我想把见面时间提前。", "target_word": "提前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时间提前了，大家都要早点来。", "target_word": "提前", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "提前了", "label": "体标"}], "register": "中性", "sense_fingerprint": "把预定的时间或日期向前移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提前", "is_correct": true, "explanation": "提前：把聚会时间向前移，正是“为了赶上末班车”所需要的调整。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：推迟是把时间向后移，与“为了赶上末班车”的目的相反。"}, {"text": "取消", "is_correct": false, "explanation": "搭配：“取消”针对整个活动，不能说“取消了一个小时”。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”针对事情或意见，与表示时间长短的“一个小时”不搭配。"}], "explanations": {"提前": "提前：把聚会时间向前移，正是“为了赶上末班车”所需要的调整。", "推迟": "语义：推迟是把时间向后移，与“为了赶上末班车”的目的相反。", "取消": "搭配：“取消”针对整个活动，不能说“取消了一个小时”。", "忽略": "语义：“忽略”针对事情或意见，与表示时间长短的“一个小时”不搭配。"}, "sentence_index": 0, "correct_answer": "提前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，我的成绩提前了十分。", "explanation": "这里应该用〈提高〉。“提前”只用于时间、日期的前移，成绩、水平等要用“提高”。"}, {"text": "这辆车的速度提前了一点。", "explanation": "这里应该用〈加快〉。“提前”只用于时间、日期的前移，速度的提升要说“加快”。"}, {"text": "这件衣服的价格提前了五十块。", "explanation": "这里应该用〈降低〉。“提前”只用于时间、日期，价格下调要用“降低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提前", "is_correct": true, "explanation": "提前：把放寒假的时间向前调，符合“天气太冷”的语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：天气太冷应当放假，“拒绝放寒假”与原因相悖。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“停止”多接活动、工作，一般不说“停止放寒假”。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对放寒假”与“天气太冷”的理由不合。"}], "explanations": {"提前": "提前：把放寒假的时间向前调，符合“天气太冷”的语境。", "拒绝": "语义：天气太冷应当放假，“拒绝放寒假”与原因相悖。", "停止": "搭配：“停止”多接活动、工作，一般不说“停止放寒假”。", "反对": "语义：“反对放寒假”与“天气太冷”的理由不合。"}, "sentence_index": 6, "correct_answer": "提前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司的人数提前了一百人。", "explanation": "这里应该用〈增加〉。“提前”只用于时间、日期，人数等数量要用“增加”。"}, {"text": "这家店的规模提前了一倍。", "explanation": "这里应该用〈扩大〉。“提前”只用于时间、日期，规模的增大要用“扩大”。"}, {"text": "今年的产量提前了一成。", "explanation": "这里应该用〈减少〉。“提前”只用于时间、日期，产量的下降要用“减少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考试的时间提前过一天。", "corrected_sentence": "考试的时间提前了一天。", "error_description": "错误：“提前过一天”；正确：“提前了一天”。“过”表示经历，时间已向前移动应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议提前着两个小时。", "corrected_sentence": "会议提前了两个小时。", "error_description": "错误：“提前着两个小时”；正确：“提前了两个小时”。“着”表示持续的状态，“提前”是一次性的动作，完成后应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
