INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用一定的工具或标准来测量长度、容量、重量等。", "primary_collocate": null, "pronunciation": "dù liàng", "ipa": "tu˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在全球化日益深化的今天，时间观念已不再仅仅是个体生活的度量工具，更成为跨文化交流中深层文化差异的显影剂。", "target_word": "度量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工人用尺子度量墙的长度。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要工具来度量这张桌子。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用绳子度量了院子的宽度。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把尺子可以度量三米以内的长度。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们度量教室的长和宽。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这根木头度量一下。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用手臂度量布的长度。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用什么办法度量水的重量呢？", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿出卷尺，开始度量房间的大小。", "target_word": "度量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度量衡", "label": "复合"}], "register": "中性", "sense_fingerprint": "度量：用工具或标准测量长度、容量、重量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "度量", "is_correct": true, "explanation": "「度量工具」指用来测量长短、容量的工具，与「个体生活的」搭配正确，符合句意。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭，「烹饪工具」与句中讲的时间观念无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳是水中运动，「游泳工具」与时间观念无关，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：「节日」不能修饰「工具」，「节日工具」说不通。"}], "explanations": {"度量": "「度量工具」指用来测量长短、容量的工具，与「个体生活的」搭配正确，符合句意。", "烹饪": "语义：烹饪是做饭，「烹饪工具」与句中讲的时间观念无关，句意不通。", "游泳": "语义：游泳是水中运动，「游泳工具」与时间观念无关，句意不通。", "节日": "搭配：「节日」不能修饰「工具」，「节日工具」说不通。"}, "sentence_index": 0, "correct_answer": "度量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用天平度量了院子的宽度。", "explanation": "天平只用于称重，不能测量宽度，测长度要用尺子等长度工具。"}, {"text": "他能度量出这两种酒的好坏。", "explanation": "这里应该用〈品评〉。度量用于长度、容量、重量等可以测量的东西，酒的好坏要靠品评。"}, {"text": "他度量了我的心情。", "explanation": "这里应该用〈揣度〉。度量只用于长度、容量、重量等可测量的东西，猜测别人的心思要用揣度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "度量", "is_correct": true, "explanation": "「度量一下」指用工具测量木头的长度，与句意相符。"}, {"text": "吞", "is_correct": false, "explanation": "语义：吞是咽下去，木头不能被吞，与句意不符。"}, {"text": "朗诵", "is_correct": false, "explanation": "搭配：朗诵的对象是文字或诗文，不能用来形容木头。"}, {"text": "吟唱", "is_correct": false, "explanation": "搭配：吟唱的对象是歌词或诗句，不能用于木头。"}], "explanations": {"度量": "「度量一下」指用工具测量木头的长度，与句意相符。", "吞": "语义：吞是咽下去，木头不能被吞，与句意不符。", "朗诵": "搭配：朗诵的对象是文字或诗文，不能用来形容木头。", "吟唱": "搭配：吟唱的对象是歌词或诗句，不能用于木头。"}, "sentence_index": 6, "correct_answer": "度量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他度量了朋友的好意。", "explanation": "这里应该用〈领会〉。度量只用于长度、容量、重量等可测量的东西，好意是抽象的，要用领会。"}, {"text": "他度量了那件古董的价值。", "explanation": "这里应该用〈估价〉。度量用于可测量的量，价值要用估价。"}, {"text": "他度量了那首歌动人的旋律。", "explanation": "这里应该用〈欣赏〉。度量用于长度、容量、重量等可测量的东西，旋律要靠聆听来欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用卷尺度量了这扇门的颜色。", "corrected_sentence": "工人用卷尺度量了这扇门的宽度。", "error_description": "错误：「度量」只用于长度、容量、重量等可测量的量，「颜色」不能用卷尺度量，应改为「宽度」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用天平度量了过这包糖的重量。", "corrected_sentence": "他用天平度量过这包糖的重量。", "error_description": "「过」与「了」不能同时用，应说「度量过」，不说「度量了过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
