INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10959, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "用于描述不同文化背景的人之间的交流、理解和互动。", "primary_collocate": null, "pronunciation": "kuà wén huà", "ipa": "kʰua˥˩ wən˧˥ xua˥˩", "syllable_count": 3, "sentences": [{"text": "在全球化日益深化的今天，时间观念已不再仅仅是个体生活的度量工具，更成为跨文化交流中深层文化差异的显影剂。", "target_word": "跨文化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "真正的跨文化能力，不在于强制统一时间尺度，而在于培养“时间敏感性”——理解不同文化如何编织其时间意义之网，并在全球化语境中协商出弹性共存的节奏。", "target_word": "跨文化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们学校开了一门跨文化交流课。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对跨文化交流很感兴趣。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国外工作，每天都有跨文化的经历。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是讲跨文化沟通的。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨文化学习让我认识了很多朋友。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做跨文化工作，要先了解对方的习惯。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的跨文化经验很丰富。", "target_word": "跨文化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跨文化交流需要耐心和尊重。", "target_word": "跨文化", "complexity_tier": "T3", "furigana": "kuà wén huà jiāo liú xū yào nài xīn hé zūn zhòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨文化交流", "label": "复合"}, {"form": "跨文化沟通", "label": "复合"}], "register": "中性", "sense_fingerprint": "跨文化：不同文化背景的人交流、理解和互动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd671e0-53f7-42b7-bb84-bc75686d43c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨文化", "is_correct": true, "explanation": "「跨文化交流」指不同文化背景的人之间的交流，与「深层文化差异」的语境相符。"}, {"text": "室内", "is_correct": false, "explanation": "语义：「室内交流」与文化差异无关，与句中的语境不协调。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：「夜间交流」说的是时间，与「深层文化差异」的语义不符。"}, {"text": "食用", "is_correct": false, "explanation": "搭配：「食用」不能修饰「交流」，「食用交流」说不通。"}], "explanations": {"跨文化": "「跨文化交流」指不同文化背景的人之间的交流，与「深层文化差异」的语境相符。", "室内": "语义：「室内交流」与文化差异无关，与句中的语境不协调。", "夜间": "语义：「夜间交流」说的是时间，与「深层文化差异」的语义不符。", "食用": "搭配：「食用」不能修饰「交流」，「食用交流」说不通。"}, "sentence_index": 0, "correct_answer": "跨文化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们正在修一条跨文化的公路。", "explanation": "这里应该用〈跨省〉。跨文化指不同文化背景的人之间的交流，修公路按地区连通要用跨省。"}, {"text": "她参加了一次跨文化的体检。", "explanation": "这里应该用〈例行〉。跨文化修饰交流、学习这类活动，体检属于医疗检查，不能用跨文化修饰。"}, {"text": "他每天的跨文化都很规律，早起晚睡。", "explanation": "这里应该用〈作息〉。跨文化指人与人之间的交流过程，人的日常起居要用作息来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨文化", "is_correct": true, "explanation": "「跨文化学习」指学习不同文化的活动，与「认识了很多朋友」的语境相符。"}, {"text": "铁制", "is_correct": false, "explanation": "语义：「铁制学习」不成立，学习不是金属制品，句意不通。"}, {"text": "冰冻", "is_correct": false, "explanation": "语义：「冰冻学习」与认识朋友的语境无关，句意不通。"}, {"text": "方形", "is_correct": false, "explanation": "体貌：「方形」描述形状，学习活动没有形状，与句意不符。"}], "explanations": {"跨文化": "「跨文化学习」指学习不同文化的活动，与「认识了很多朋友」的语境相符。", "铁制": "语义：「铁制学习」不成立，学习不是金属制品，句意不通。", "冰冻": "语义：「冰冻学习」与认识朋友的语境无关，句意不通。", "方形": "体貌：「方形」描述形状，学习活动没有形状，与句意不符。"}, "sentence_index": 6, "correct_answer": "跨文化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把跨文化的桌子搬到了教室里。", "explanation": "这里是把〈木制〉之类表示材质的意思用到了跨文化上。跨文化修饰的是交流、学习这类活动，不能修饰桌子。"}, {"text": "他每天跨文化地吃饭睡觉。", "explanation": "这里应该用〈按时〉。跨文化修饰交流、学习这类活动，不能修饰吃饭、睡觉；说作息规律要用“按时”。"}, {"text": "我想把跨文化放进冰箱里。", "explanation": "这里应该用〈食品〉。跨文化是抽象的交流活动，不能放进冰箱；能放进冰箱的是食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师用跨文化地方法教学。", "corrected_sentence": "老师用跨文化的方法教学。", "error_description": "「跨文化」修饰名词「方法」，中间要用「的」，不用「地」（「地」修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周都参加一本跨文化活动。", "corrected_sentence": "他们每周都参加一次跨文化活动。", "error_description": "活动的量词应用「次」，不用「本」（「本」用于书籍等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf1db7bd-d73c-42f3-a03b-50f946dbbbca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
