INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "显影剂是一种化学物质，用于将胶片上曝光过的影像显现出来。", "primary_collocate": null, "pronunciation": "xiǎn yǐng jì", "ipa": "ɕjɛn˨˩˦ iŋ˨˩˦ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "照相馆的师傅把显影剂倒进显影槽里。", "target_word": "显影剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片要放进显影剂里才会出现图像。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摄影师把底片泡在显影剂里。", "target_word": "显影剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶显影剂用完了，得再买一瓶。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冲洗胶卷时，显影剂的温度很重要。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在暗房里倒好了显影剂。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "显影剂太浓，照片会变得很黑。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么用显影剂冲洗底片。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "曝光后的胶片要先用显影剂处理。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暗房里的显影剂有一股刺鼻的气味。", "target_word": "显影剂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}, {"form": "顯影劑", "label": "繁体"}], "register": "专业", "sense_fingerprint": "冲洗胶片时使曝光后的潜影显现成可见图像的化学药剂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "显影剂", "is_correct": true, "explanation": "正确：显影剂是冲洗用的药剂，倒进显影槽后才能使潜影显现，符合句意。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "语义：洗衣粉用于去污，不是冲洗胶片用的药剂，不能倒进显影槽。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：“倒进”的对象须是液体药剂，公交车不能倒入显影槽。"}, {"text": "缝纫机", "is_correct": false, "explanation": "语义：缝纫机用于缝制衣物，与冲洗胶片的语境无关。"}], "explanations": {"显影剂": "正确：显影剂是冲洗用的药剂，倒进显影槽后才能使潜影显现，符合句意。", "洗衣粉": "语义：洗衣粉用于去污，不是冲洗胶片用的药剂，不能倒进显影槽。", "公交车": "搭配：“倒进”的对象须是液体药剂，公交车不能倒入显影槽。", "缝纫机": "语义：缝纫机用于缝制衣物，与冲洗胶片的语境无关。"}, "sentence_index": 0, "correct_answer": "显影剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "照片洗好后，要先用显影剂把图像固定下来。", "explanation": "这里应该用〈定影剂〉。显影剂使潜影显现，固定图像要用定影剂。"}, {"text": "这件衣服要用显影剂洗干净。", "explanation": "这里应该用〈洗涤剂〉。显影剂只让曝光后的影像显现，不能用来洗衣服，去污要用洗涤剂。"}, {"text": "这些旧照片泛黄了，要用显影剂漂白。", "explanation": "这里应该用〈漂白剂〉。显影剂只让潜影显现，不起漂白作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "显影剂", "is_correct": true, "explanation": "正确：显影剂太浓会使照片的影像过度显现，符合句意。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡的浓淡与照片变黑没有关系。"}, {"text": "洗发水", "is_correct": false, "explanation": "搭配：“照片会变得很黑”需要显影药剂作主语，洗发水不能充当。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁的浓度与照片影像无关。"}], "explanations": {"显影剂": "正确：显影剂太浓会使照片的影像过度显现，符合句意。", "咖啡": "语义：咖啡的浓淡与照片变黑没有关系。", "洗发水": "搭配：“照片会变得很黑”需要显影药剂作主语，洗发水不能充当。", "果汁": "语义：果汁的浓度与照片影像无关。"}, "sentence_index": 6, "correct_answer": "显影剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种显影剂能把布料上的颜色去掉。", "explanation": "这里应该用〈脱色剂〉。显影剂只让曝光后的影像显现，不能去掉布料上的颜色。"}, {"text": "装底片前，先在底片上涂一层显影剂，使它感光。", "explanation": "这里应该用〈感光剂〉。显影剂只能显现已曝光的影像，不能使底片感光。"}, {"text": "这瓶显影剂可以用来给白纸上色。", "explanation": "这里应该用〈颜料〉。显影剂用于显现影像，不用于给纸上色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冲洗底片时，我们要先显影剂。", "corrected_sentence": "冲洗底片时，我们要先用显影剂。", "error_description": "漏词错误：漏掉了动词“用”，应说“先用显影剂”，不能只说“先显影剂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我又买了一只显影剂。", "corrected_sentence": "我又买了一瓶显影剂。", "error_description": "量词错误：显影剂是液体，应用“瓶”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
