INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10961, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指人的思想、性格等在不自觉中受到别人或环境的影响而发生变化。", "primary_collocate": null, "pronunciation": "qián yí mò huà", "ipa": "tɕʰjɛn˧˥ i˧˥ mwo˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "不同社会对时间的理解，潜移默化地塑造着人们的守时性标准、社交期待乃至经济运作模式。", "target_word": "潜移默化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "父母的习惯会潜移默化地影响孩子。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个城市住久了，他潜移默化地变得爱早起。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好书对人的影响是潜移默化的。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师每天的做法，潜移默化地改变了我。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "环境对孩子的成长有潜移默化的作用。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年的朋友，潜移默化地让他变得开朗了。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的读书气氛，潜移默化地影响了她。", "target_word": "潜移默化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "语言学习也是潜移默化的过程，不能太急。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口音是在国外生活时潜移默化地形成的。", "target_word": "潜移默化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜移默化地", "label": "状语形式"}, {"form": "潜移默化的", "label": "定语形式"}], "register": "书面语", "sense_fingerprint": "思想、性格等在不知不觉中受到影响而逐渐改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10961, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜移默化", "is_correct": true, "explanation": "正确：“潜移默化地”表示在不知不觉中形成影响，符合句意。"}, {"text": "大张旗鼓", "is_correct": false, "explanation": "语义：“大张旗鼓”指公开张扬，与“不知不觉”的意思相反。"}, {"text": "明目张胆", "is_correct": false, "explanation": "语义：“明目张胆”指公然做事，不能用来说社会观念的渐进影响。"}, {"text": "一蹴而就", "is_correct": false, "explanation": "搭配：“一蹴而就”多修饰完成的动作，不修饰“塑造”这类长期过程。"}], "explanations": {"潜移默化": "正确：“潜移默化地”表示在不知不觉中形成影响，符合句意。", "大张旗鼓": "语义：“大张旗鼓”指公开张扬，与“不知不觉”的意思相反。", "明目张胆": "语义：“明目张胆”指公然做事，不能用来说社会观念的渐进影响。", "一蹴而就": "搭配：“一蹴而就”多修饰完成的动作，不修饰“塑造”这类长期过程。"}, "sentence_index": 0, "correct_answer": "潜移默化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气潜移默化地变冷了。", "explanation": "这里应该用〈逐渐〉。潜移默化指人的思想、性格在不知不觉中受影响，不用来描述天气变化。"}, {"text": "他潜移默化地想起了那件事。", "explanation": "这里应该用〈突然〉。潜移默化指慢慢受影响的过程，想起一件事是瞬间发生的，不能说成潜移默化。"}, {"text": "他潜移默化地离开了教室。", "explanation": "这里应该用〈悄悄〉。潜移默化说的是受影响的过程，不指离开时的隐蔽方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10961, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜移默化", "is_correct": true, "explanation": "正确：“潜移默化地”表示在不知不觉中改变，与“多年的朋友”相合。"}, {"text": "立竿见影", "is_correct": false, "explanation": "语义：“立竿见影”指效果立即显现，与“多年”的积累过程相矛盾。"}, {"text": "骤然", "is_correct": false, "explanation": "语义：“骤然”指突然发生，与“多年”的渐进过程不符。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”修饰瞬间的动作，不修饰“让他变得开朗”这类长期变化。"}], "explanations": {"潜移默化": "正确：“潜移默化地”表示在不知不觉中改变，与“多年的朋友”相合。", "立竿见影": "语义：“立竿见影”指效果立即显现，与“多年”的积累过程相矛盾。", "骤然": "语义：“骤然”指突然发生，与“多年”的渐进过程不符。", "猛然": "搭配：“猛然”修饰瞬间的动作，不修饰“让他变得开朗”这类长期变化。"}, "sentence_index": 6, "correct_answer": "潜移默化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收到信后他潜移默化地回复了。", "explanation": "这里应该用〈立即〉。潜移默化指慢慢地受影响，不指马上做出回应。"}, {"text": "他潜移默化地练了几个月的发音。", "explanation": "这里应该用〈刻意〉。潜移默化指不自觉的影响，有目的地练习要用〈刻意〉。"}, {"text": "听到消息，他潜移默化地哭了起来。", "explanation": "这里应该用〈一下子〉。潜移默化指慢慢在不自觉中受影响，哭出来是瞬间的反应，不能用潜移默化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10961, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些年，他潜移默化的养成了读书的习惯。", "corrected_sentence": "这些年，他潜移默化地养成了读书的习惯。", "error_description": "状语错误：“潜移默化”修饰动词“养成”要用“地”，不能用“的”，应说“潜移默化地养成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10961, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种变化是潜移默化地结果。", "corrected_sentence": "这种变化是潜移默化的结果。", "error_description": "修饰语错误：“潜移默化”修饰名词“结果”时要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
