INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10963, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对未来的事情抱着希望，等待它发生。", "primary_collocate": null, "pronunciation": "qī dài", "ipa": "tɕʰi˥ tai˥˩", "syllable_count": 2, "sentences": [{"text": "全家人期待着他平安归来。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很期待下个月的旅行。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们期待着春节快点儿到。", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都期待他能考上好大学。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直期待着和老朋友见面。", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影我期待了很久。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我期待你的回信。", "target_word": "期待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从来没期待过会得到这么大的礼物。", "target_word": "期待", "complexity_tier": "T3", "furigana": "tā cónglái méi qīdài guo huì dédào zhème dà de lǐwù.", "sentence_source": "generated"}, {"text": "我们都在期待明天的比赛。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师期待我们明年能进步更多。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "期待着", "label": "持续体"}, {"form": "期待过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对将来的好事抱有希望并等待它出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "正确：“期待”在此作动词，表示家人盼望他平安归来，符合句意。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”不能表示盼望，“体积着他平安归来”说不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地面的高度，与盼望他人归来无关。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，不能表示希望或等待。"}], "explanations": {"期待": "正确：“期待”在此作动词，表示家人盼望他平安归来，符合句意。", "体积": "搭配：“体积”不能表示盼望，“体积着他平安归来”说不通。", "海拔": "语义：“海拔”指地面的高度，与盼望他人归来无关。", "重量": "语义：“重量”指物体的轻重，不能表示希望或等待。"}, "sentence_index": 0, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很期待那段已经过去的童年。", "explanation": "这里应该用〈怀念〉。期待针对尚未发生的事，已经过去的往事要用“怀念”。"}, {"text": "周末我去医院期待生病的奶奶。", "explanation": "这里应该用〈看望〉。期待指盼望将来的好事，探望生病的人要用“看望”。"}, {"text": "我很期待那场即将到来的灾难。", "explanation": "这里应该用〈担心〉。期待表示盼望好事，不能用于灾难，表示忧虑要用“担心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "期待在此表示希望收到对方的回信，与句意相符。"}, {"text": "出现", "is_correct": false, "explanation": "配价：“出现”是不及物动词，不能带“你的回信”作宾语。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带宾语“你的回信”。"}, {"text": "流泪", "is_correct": false, "explanation": "搭配：“流泪”指哭泣，不能与“回信”搭配，句子无法成立。"}], "explanations": {"期待": "期待在此表示希望收到对方的回信，与句意相符。", "出现": "配价：“出现”是不及物动词，不能带“你的回信”作宾语。", "消失": "配价：“消失”是不及物动词，不能带宾语“你的回信”。", "流泪": "搭配：“流泪”指哭泣，不能与“回信”搭配，句子无法成立。"}, "sentence_index": 6, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直期待工作太辛苦。", "explanation": "这里应该用〈抱怨〉。期待表示盼望好事，不能用来表达对辛苦工作的不满。"}, {"text": "我很快就期待了那件事。", "explanation": "这里应该用〈遗忘〉。“很快就”暗示已经忘掉，而期待是对未来的希望，不能表示忘记过去的事。"}, {"text": "我们必须期待交通规则。", "explanation": "这里应该用〈遵守〉。期待是对未来事情的希望，不能用来表示服从规则，遵守规则要用“遵守”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我期待了下周的音乐会。", "corrected_sentence": "我期待下周的音乐会。", "error_description": "“了”表示已完成，而“下周的音乐会”尚未发生，二者矛盾，应去掉“了”，说“我期待下周的音乐会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他期待了地看着窗外。", "corrected_sentence": "他期待地看着窗外。", "error_description": "“了”不能插在动词与状语“地”之间。“期待地看着窗外”中“期待地”修饰“看”，应去掉“了”，说“他期待地看着窗外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
