INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体分成几个部分。", "primary_collocate": null, "pronunciation": "fēn gē", "ipa": "fən˥ kɤ˥", "syllable_count": 2, "sentences": [{"text": "西方主流文化，尤其是北欧与日耳曼语系国家，倾向于将时间视为一种线性、可分割、可“消费”的稀缺资源。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "小河把这座城市分割成两部分。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路把村子分割开了。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定分割这块土地。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把公司分割成三个部门。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速公路分割了老城区。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战后，大国分割了这片地区。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把时间分割成小块。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩分割了父亲留下的财产。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这堵墙把院子分割成两半。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分割了", "label": "体标"}, {"form": "分割过", "label": "体标"}, {"form": "分割线", "label": "复合"}], "register": "中性", "sense_fingerprint": "把土地、空间、时间等整体划分成几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b63813c-68c7-48fa-8360-f041b5f6ea4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10972, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分割", "is_correct": true, "explanation": "正确：“可分割”与后文“可消费”并列，说明时间可以被切分成部分。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”的对象是歌曲，不能说稀缺资源可以歌唱。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是生物的动作，无法用于线性的稀缺资源。"}, {"text": "饲养", "is_correct": false, "explanation": "配价：饲养要求以动物或生物作宾语，时间和资源不能被饲养。"}], "explanations": {"分割": "正确：“可分割”与后文“可消费”并列，说明时间可以被切分成部分。", "歌唱": "搭配：“歌唱”的对象是歌曲，不能说稀缺资源可以歌唱。", "呼吸": "语义：呼吸是生物的动作，无法用于线性的稀缺资源。", "饲养": "配价：饲养要求以动物或生物作宾语，时间和资源不能被饲养。"}, "sentence_index": 0, "correct_answer": "分割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这份喜悦和你分割。", "explanation": "这里应该用〈分享〉。分割指把一个整体切成几部分，与人共同享受快乐、喜悦要用分享。"}, {"text": "他用一句玩笑分割了紧张的气氛。", "explanation": "这里应该用〈打破〉。分割指把整体切成几部分，不能用于气氛；打破紧张的气氛要用“打破”。"}, {"text": "父母的反对分割了他们的恋情。", "explanation": "这里应该用〈拆散〉。分割不用于拆开两个人或两段感情，拆散两人的关系要用拆散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分割", "is_correct": true, "explanation": "正确：分割了这片地区，与“战后、大国”的语境一致。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭是抹去表面的灰尘或污渍，不能用于划分一片地区。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的宾语是植物或田地，不能与“分割地区”搭配。"}, {"text": "缝纫", "is_correct": false, "explanation": "语义：缝纫指用针线做衣物，与战后大国的政治语境完全不符。"}], "explanations": {"分割": "正确：分割了这片地区，与“战后、大国”的语境一致。", "擦拭": "语义：擦拭是抹去表面的灰尘或污渍，不能用于划分一片地区。", "浇灌": "搭配：“浇灌”的宾语是植物或田地，不能与“分割地区”搭配。", "缝纫": "语义：缝纫指用针线做衣物，与战后大国的政治语境完全不符。"}, "sentence_index": 6, "correct_answer": "分割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他突然分割了我的话，我一句也没听清。", "explanation": "这里应该用〈打断〉。分割指把整体切成几部分，中途插话截断别人说话要用打断。"}, {"text": "一场暴雨分割了小镇的电力供应。", "explanation": "这里应该用〈切断〉。分割强调把整体划分成部分，供应被中断应说切断。"}, {"text": "他难以分割那段感情。", "explanation": "这里应该用〈割舍〉。分割用于物理或空间上的划分，放弃一段感情要用割舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条界线把草场分割两块。", "corrected_sentence": "这条界线把草场分割成两块。", "error_description": "错误形式：分割两块。正确形式：分割成两块。把整体分成几部分时，“分割”后要用“成”引出结果，不能直接接数量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道裂缝把冰面分割了成好几块。", "corrected_sentence": "这道裂缝把冰面分割成了好几块。", "error_description": "错误形式：分割了成好几块。正确形式：分割成了好几块。结果补语“成”必须紧跟在“分割”之后，“了”放在“成”之后表示完成，不能放在“成”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecdaac6c-e131-43d3-92f5-dda6f5f80093') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
