INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10973, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在一定时期内，社会或经济活动中供给不足、需求旺盛，且难以替代的物品或资源。", "primary_collocate": null, "pronunciation": "xī quē zī yuán", "ipa": "ɕi⁵⁵ tɕʰɥe⁵⁵ tsɹ̩⁵⁵ ɥɛn³⁵", "syllable_count": 4, "sentences": [{"text": "当绿色空间与本地化食品生产成为稀缺资源时，其分配模式直接关联社会分层。", "target_word": "稀缺资源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "西方主流文化，尤其是北欧与日耳曼语系国家，倾向于将时间视为一种线性、可分割、可“消费”的稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "房价上涨，因为好地段是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "芯片短缺期间，光刻设备成了稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "furigana": "xī quē zī yuán", "sentence_source": "generated"}, {"text": "需求很大，供给不足，它就成了稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对公司来说，优秀的人才是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学研究怎样分配稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油很难找到替代品，所以是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春运期间，火车票成了稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在大城市，学区房也是稀缺资源。", "target_word": "稀缺资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "稀缺資源", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "经济学意义上供给不足、需求旺盛、难以替代的资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1532fc7-f679-448f-975d-e35ead7876dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10973, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺资源", "is_correct": true, "explanation": "正确：指供给不足、需求旺盛、难以替代的资源，符合“成为……时”所说的稀缺状态。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为需要分配的对象，与“分配模式”的语境冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语、随意的说法，与这句书面语的论述不相称。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是为教育付出的钱，不能与绿色空间、食品生产并列，作为被分配的对象。"}], "explanations": {"稀缺资源": "正确：指供给不足、需求旺盛、难以替代的资源，符合“成为……时”所说的稀缺状态。", "天气": "语义：天气是自然现象，不能作为需要分配的对象，与“分配模式”的语境冲突。", "玩意儿": "语域：“玩意儿”是口语、随意的说法，与这句书面语的论述不相称。", "学费": "语义：学费是为教育付出的钱，不能与绿色空间、食品生产并列，作为被分配的对象。"}, "sentence_index": 0, "correct_answer": "稀缺资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区雨水充沛，水就是稀缺资源。", "explanation": "这里应该用〈充足〉。稀缺资源指供给不足、需求旺盛的东西；雨水充沛时水的供应充足，不能说是稀缺资源。"}, {"text": "我们公司买了一颗稀缺资源。", "explanation": "这里应该用〈种〉。资源是抽象名词，不能用“颗”，“颗”多用于粒状、球状的小东西。"}, {"text": "这种矿泉水在超市随处可见，价格很低，它是稀缺资源。", "explanation": "这里应该用〈常见〉。稀缺资源指供给不足、难以替代的东西；随处可见、价格低廉的矿泉水不属于稀缺资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10973, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺资源", "is_correct": true, "explanation": "正确：经济学研究的对象是供给不足、需要分配的资源，“稀缺资源”正好符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是需要分配的资源，“分配颜色”不构成经济学研究的对象。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“分配”通常用于资源、财产、名额等，不能说分配“友谊”。"}, {"text": "废话", "is_correct": false, "explanation": "语义：“废话”没有价值，不是需要分配的对象，与经济学的语境冲突。"}], "explanations": {"稀缺资源": "正确：经济学研究的对象是供给不足、需要分配的资源，“稀缺资源”正好符合语境。", "颜色": "语义：颜色不是需要分配的资源，“分配颜色”不构成经济学研究的对象。", "友谊": "搭配：“分配”通常用于资源、财产、名额等，不能说分配“友谊”。", "废话": "语义：“废话”没有价值，不是需要分配的对象，与经济学的语境冲突。"}, "sentence_index": 6, "correct_answer": "稀缺资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在街上随手就能捡到一堆稀缺资源。", "explanation": "这里应该用〈废品〉。稀缺资源指供给不足、需求旺盛的东西；满街随手可捡的东西供应充足，不是稀缺资源。"}, {"text": "这家工厂每天都在大量生产稀缺资源，仓库里堆满了。", "explanation": "这里应该用〈产品〉。稀缺资源指供给不足、需求旺盛的东西；大量生产、堆满仓库的东西不会是稀缺的。"}, {"text": "食堂里的米饭随便吃，米饭是稀缺资源。", "explanation": "这里应该用〈普通〉。稀缺资源指供给不足、需求旺盛；随便吃的米饭供应充足，不属于稀缺资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司拥有一只稀缺资源。", "corrected_sentence": "这家公司拥有一种稀缺资源。", "error_description": "量词错误：“只”多用于动物或成对物品中的一个，“资源”应用“种”，正确说法是“一种稀缺资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在上海，好的学区房也稀缺资源。", "corrected_sentence": "在上海，好的学区房也是稀缺资源。", "error_description": "漏掉判断动词“是”：“稀缺资源”作谓语时要带“是”，应说“也是稀缺资源”，不能直接说“也稀缺资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3efeaae-98b1-4058-8d03-9b7bda897c88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
