INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的意识、思维和心理状态；也指事物的宗旨、主要意义或核心价值。", "primary_collocate": null, "pronunciation": "jīng shén", "ipa": "tɕiŋ˥ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "我们要学习他认真工作的精神。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间加班，让他的精神压力很大。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个活动的精神是帮助别人。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他身体不好，但是精神很坚强。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动不但对身体好，对精神也好。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要理解这个规定的精神，不能只看字面。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人助人为乐的精神让大家很感动。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐可以让人在精神上放松。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国人有很强的拼搏精神。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败以后，他的精神很低落。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神状态", "label": "复合"}, {"form": "精神压力", "label": "复合"}, {"form": "精神文明", "label": "复合"}], "register": "中性", "sense_fingerprint": "精神：人的心理状态，或规定、事业等的核心宗旨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“学习”的对象是精神、经验这类抽象的品质。“精神”指认真工作所体现的态度与作风，句意通顺。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“学习”的对象是品质或经验，不能说学习“收入”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是外形特征，与“认真工作”这种品质无关，不能被学习。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，无法作为可以学习的对象。"}], "explanations": {"精神": "“学习”的对象是精神、经验这类抽象的品质。“精神”指认真工作所体现的态度与作风，句意通顺。", "收入": "搭配：“学习”的对象是品质或经验，不能说学习“收入”。", "身材": "体貌：“身材”是外形特征，与“认真工作”这种品质无关，不能被学习。", "天气": "语义：“天气”是自然现象，无法作为可以学习的对象。"}, "sentence_index": 0, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一只很坚强的精神。", "explanation": "这里应该用〈种〉。精神是抽象的心理状态，量词要用〈种〉；〈只〉用于动物或单个器物。"}, {"text": "他的精神很大，能搬动那张桌子。", "explanation": "这里应该用〈力气〉。〈力气〉指身体的力量，精神是心理状态，不能用“很大”形容，也不能用来搬动东西。"}, {"text": "他精神很好使，一学就会。", "explanation": "这里应该用〈脑子〉。〈好使〉形容头脑灵活，只用于脑子，精神是心理状态，不说“好使”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“助人为乐”体现的是品德和精神，“精神”指这种心理状态与宗旨，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形特征，与“助人为乐”这一品德无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不是品德，不能让人“感动”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的外观，与人的品德无关，句子不通。"}], "explanations": {"精神": "“助人为乐”体现的是品德和精神，“精神”指这种心理状态与宗旨，句意通顺。", "身高": "体貌：“身高”是外形特征，与“助人为乐”这一品德无关。", "价格": "语义：“价格”指钱数，不是品德，不能让人“感动”。", "颜色": "语义：“颜色”是事物的外观，与人的品德无关，句子不通。"}, "sentence_index": 6, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的精神很苗条，穿什么都好看。", "explanation": "这里应该用〈身材〉。〈苗条〉形容体形，精神是心理状态，不能用来形容身材。"}, {"text": "他有一根低落的精神。", "explanation": "这里应该用〈种〉。〈根〉用于细长的东西，精神是抽象的心理状态，不能用〈根〉计量。"}, {"text": "他对妈妈的精神很深。", "explanation": "这里应该用〈感情〉。精神指心理状态，不用“深”来形容亲密关系，表达这一意思要用〈感情〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动让大家在精神得到了很大的鼓舞。", "corrected_sentence": "这次活动让大家在精神上得到了很大的鼓舞。", "error_description": "漏用“上”：表示心理方面要说“在精神上”，只说“在精神”不符合习惯。错误形式为“在精神得到”，正确形式为“在精神上得到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那种乐于助人精神让大家很感动。", "corrected_sentence": "那种乐于助人的精神让大家很感动。", "error_description": "漏用“的”：“乐于助人”修饰名词“精神”时要加“的”。错误形式为“乐于助人精神”，正确形式为“乐于助人的精神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
