INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指各种运输工具和道路、航线等构成的运输系统，也包括信息传递。", "primary_collocate": null, "pronunciation": "jiāo tōng", "ipa": "tɕjɑʊ˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "大家选择公交这种交通方式，是环保的好习惯。", "target_word": "交通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的交通很方便。", "target_word": "交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早上上班时，路上的交通很拥挤。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁让城市的交通快多了。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的交通不太方便，路又窄又远。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，交通容易堵塞。", "target_word": "交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府正在改善这个地区的交通。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，火车站的交通特别紧张。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近交通方便，有地铁也有公交。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的交通能让城市发展得更快。", "target_word": "交通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交通工具", "label": "复合"}, {"form": "交通事故", "label": "复合"}, {"form": "交通规则", "label": "复合"}], "register": "中性", "sense_fingerprint": "交通：运输工具与道路航线构成的运输系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcd5bd62-667b-408b-99e4-5d930ae38128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "正确：“交通”指运输系统，“交通方式”即出行的方法，此处指乘坐公交出行，语义通顺。"}, {"text": "道路", "is_correct": false, "explanation": "搭配：“道路”不能说“公交这种道路方式”，句意不通。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”是场所，不能说“公交这种车站方式”。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指人，不能填入“公交这种……方式”的空缺处。"}], "explanations": {"交通": "正确：“交通”指运输系统，“交通方式”即出行的方法，此处指乘坐公交出行，语义通顺。", "道路": "搭配：“道路”不能说“公交这种道路方式”，句意不通。", "车站": "搭配：“车站”是场所，不能说“公交这种车站方式”。", "乘客": "语义：“乘客”指人，不能填入“公交这种……方式”的空缺处。"}, "sentence_index": 0, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条交通很宽，车很少。", "explanation": "这里应该用〈道路〉。交通指运输系统，不指具体的路面，形容路面宽要用“道路”。"}, {"text": "这条交通每天有三班。", "explanation": "这里应该用〈航线〉。交通是运输系统的统称，不指一条具体的航线。"}, {"text": "我每天坐一只交通上班。", "explanation": "这里“交通”不能用量词“只”计量。若指具体工具，应说“一辆车”或“一种交通方式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "正确：“政府正在改善这个地区的交通”，“交通”指运输系统，可以被改善。"}, {"text": "酒量", "is_correct": false, "explanation": "语义：政府不会去改善个人的酒量，与“这个地区”的语境不符。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳不是“这个地区”的事物，与政府改善工作无关。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”一般说增加或减少，不说“改善饭量”。"}], "explanations": {"交通": "正确：“政府正在改善这个地区的交通”，“交通”指运输系统，可以被改善。", "酒量": "语义：政府不会去改善个人的酒量，与“这个地区”的语境不符。", "心跳": "语义：心跳不是“这个地区”的事物，与政府改善工作无关。", "饭量": "搭配：“饭量”一般说增加或减少，不说“改善饭量”。"}, "sentence_index": 6, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个车站的交通很快乐，人很多。", "explanation": "这里应该用〈人流〉。“交通”指运输系统，不能用“快乐”形容，说人多要用“人流”。"}, {"text": "这个交通很好用，很方便。", "explanation": "这里应该用〈导航〉。交通指运输系统，不指导航设备。"}, {"text": "我们昨天在路上遇到一座交通，很拥挤。", "explanation": "这里“交通”不能用量词“座”计量，“座”用于建筑、山等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路地交通很方便。", "corrected_sentence": "这条路的交通很方便。", "error_description": "结构助词错误：修饰名词“交通”应用“的”，不能用“地”（“地”用于修饰动词、形容词），应说“这条路的交通很方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位好的交通能让城市发展得更快。", "corrected_sentence": "好的交通能让城市更快发展。", "error_description": "量词错误：“位”用于人，不能计量交通这样的运输系统，应去掉量词，说“好的交通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92090941-8504-467c-8bd8-eb8dff2db2c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时刻表是列出交通工具（如火车、飞机、公交车）出发和到达时间的表格或列表。", "primary_collocate": null, "pronunciation": "shí kè biǎo", "ipa": "ʂɻ̩˧˥ kʰɤ˥˩ piɑʊ̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "会议准时开始，交通时刻表以秒为单位校准，个人的日程本上布满不可侵犯的时间区块——这种对时间的军事化管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "时刻表", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "请你看一下火车时刻表。", "target_word": "时刻表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张时刻表上有明天的航班。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站墙上贴着新的时刻表。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上查了公交车时刻表。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时刻表上写着，最后一班车十点出发。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雪，火车没有按时刻表到站。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把时刻表放进了书包里。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份时刻表每个月都会更新。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场的时刻表显示飞机会晚点。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张时刻表", "label": "量词（张）"}, {"form": "一份时刻表", "label": "量词（份）"}], "register": "中性", "sense_fingerprint": "时刻表：列出交通工具出发和到达时间的表格", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时刻表", "is_correct": true, "explanation": "“交通时刻表”指列出交通工具出发和到达时间的表格，可以按秒校准。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：“账本”是记账用的本子，不能以秒为单位校准。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：“菜单”列出菜品，与交通时间无关。"}, {"text": "药膏", "is_correct": false, "explanation": "语义：“药膏”是外用药，与交通时间无关。"}], "explanations": {"时刻表": "“交通时刻表”指列出交通工具出发和到达时间的表格，可以按秒校准。", "账本": "搭配：“账本”是记账用的本子，不能以秒为单位校准。", "菜单": "语义：“菜单”列出菜品，与交通时间无关。", "药膏": "语义：“药膏”是外用药，与交通时间无关。"}, "sentence_index": 0, "correct_answer": "时刻表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店墙上贴着新的时刻表。", "explanation": "这里应该用〈菜单〉。时刻表列的是交通工具的出发和到达时间，菜单才列菜品。"}, {"text": "商店墙上贴着新的时刻表。", "explanation": "这里应该用〈价目表〉。时刻表列的是时间，价目表列的是价格。"}, {"text": "老师翻开时刻表点名。", "explanation": "这里应该用〈名单〉。名单用于点名、登记人员，时刻表列的是交通工具的出发和到达时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时刻表", "is_correct": true, "explanation": "“时刻表”列出火车到站的时间，与“按……到站”相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”是做菜的步骤和用料，与火车到站无关。"}, {"text": "字帖", "is_correct": false, "explanation": "搭配：“按……到站”的依据应是行车安排，不能说按“字帖”。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：“乐谱”记录乐曲，与火车到站无关。"}], "explanations": {"时刻表": "“时刻表”列出火车到站的时间，与“按……到站”相符。", "菜谱": "语义：“菜谱”是做菜的步骤和用料，与火车到站无关。", "字帖": "搭配：“按……到站”的依据应是行车安排，不能说按“字帖”。", "乐谱": "语义：“乐谱”记录乐曲，与火车到站无关。"}, "sentence_index": 6, "correct_answer": "时刻表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生开了一张时刻表。", "explanation": "这里应该用〈药方〉。时刻表列的是交通工具的时间，药方才是医生开的用药单。"}, {"text": "考试成绩都写在时刻表上。", "explanation": "这里应该用〈成绩单〉。时刻表列的是交通时间，成绩单才记录考试分数。"}, {"text": "他付清了时刻表。", "explanation": "这里应该用〈账单〉。时刻表不是账目，付清的是账单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我时刻表上查了车次。", "corrected_sentence": "我在时刻表上查了车次。", "error_description": "漏词错误：动作的地点要用介词“在”引出，应说“在时刻表上查”，不能漏掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一只时刻表。", "corrected_sentence": "我买了一张时刻表。", "error_description": "量词错误：“时刻表”是纸张，量词应用“张”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
