INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "调整仪器或装置，使其符合标准或指定状态。", "primary_collocate": null, "pronunciation": "jiào zhǔn", "ipa": "tɕiɑʊ̯˥˩ ʈʂuən˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人用标准砝码校准了秤。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在校准这台机器。", "target_word": "校准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "使用前要先校准体重秤。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每天都要校准血压计。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用标准钟校准了手表。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台仪器需要每年校准一次。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验开始以前，老师校准了天平。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把温度计校准好了。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机的颜色没有校准，照片发黄。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我校准一下这把尺子。", "target_word": "校准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "校准了", "label": "体标（了）"}, {"form": "校准过", "label": "体标（过）"}, {"form": "校准好", "label": "结果补语（好）"}], "register": "中性", "sense_fingerprint": "校准：调整仪器或装置使其符合标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "校准", "is_correct": true, "explanation": "“校准”指调整仪器使其符合标准，与“用标准砝码”的句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”是烹饪动作，不能用来处理“秤”。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”用于食物，不能用来处理“秤”。"}, {"text": "打包", "is_correct": false, "explanation": "语义：“打包”是把东西包起来，与用标准砝码调整准确度无关。"}], "explanations": {"校准": "“校准”指调整仪器使其符合标准，与“用标准砝码”的句意相符。", "煮": "搭配：“煮”是烹饪动作，不能用来处理“秤”。", "烤": "搭配：“烤”用于食物，不能用来处理“秤”。", "打包": "语义：“打包”是把东西包起来，与用标准砝码调整准确度无关。"}, "sentence_index": 0, "correct_answer": "校准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士每天都要校准病人的血压。", "explanation": "这里应该用〈测量〉。校准指调整仪器使其准确，测量血压是对人体的测定。"}, {"text": "他每周都要校准孩子的作业。", "explanation": "这里应该用〈检查〉。校准用于仪器，检查作业要用检查。"}, {"text": "厨师用心校准了汤的味道。", "explanation": "这里应该用〈调〉。校准指调整仪器，汤的味道要用调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "校准", "is_correct": true, "explanation": "“校准”指调整仪器使其符合标准，与“实验……天平”相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能唱天平。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能吃天平。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”是烹饪方式，与仪器无关。"}], "explanations": {"校准": "“校准”指调整仪器使其符合标准，与“实验……天平”相符。", "唱": "搭配：“唱”的对象是歌曲，不能唱天平。", "吃": "搭配：“吃”的对象是食物，不能吃天平。", "煎": "语义：“煎”是烹饪方式，与仪器无关。"}, "sentence_index": 6, "correct_answer": "校准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真校准了文章。", "explanation": "这里应该用〈校对〉。校对用于文字，校准指调整仪器使其符合标准，不用于文章。"}, {"text": "老师认真校准了试卷。", "explanation": "这里应该用〈批改〉。批改用于作业、试卷，校准指调整仪器，不用于试卷。"}, {"text": "妈妈仔细校准好了衣服。", "explanation": "这里应该用〈缝〉。缝衣服是针线活，校准用于仪器，不用于衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我们校准了仪器。", "corrected_sentence": "明天我们校准仪器。", "error_description": "时态错误：“明天”指将来，“了”表示已完成，不能与将来时间搭配，应去掉“了”，说“明天我们校准仪器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "技术员把压力表校准了好。", "corrected_sentence": "技术员把压力表校准好了。", "error_description": "语序错误：结果补语“好”应紧接动词“校准”，“了”放在最后，应说“校准好了”，不能说“校准了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
