INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "按时间顺序安排好的要做的事情或活动的计划。", "primary_collocate": null, "pronunciation": "rì chéng", "ipa": "ʐʅ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "会议准时开始，交通时刻表以秒为单位校准，个人的日程本上布满不可侵犯的时间区块——这种对时间的军械化管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "日程", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "本周的日程已经排满了。", "target_word": "日程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把明天的日程发给我。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的日程很紧，没有时间见客人。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的日程安排得很满，每天都有活动。", "target_word": "日程", "complexity_tier": "T3", "furigana": "rì chéng", "sentence_source": "generated"}, {"text": "老师告诉我们会议日程有变化。", "target_word": "日程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他按照日程一站一站地参观。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看一下日程，下周三有空吗？", "target_word": "日程", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为天气不好，比赛日程改了。", "target_word": "日程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先确定日程，再订机票。", "target_word": "日程", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "日程表", "label": "复合"}, {"form": "日程安排", "label": "复合"}], "register": "中性", "sense_fingerprint": "日程：按时间顺序安排的事情或活动计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0316e5-c34c-466b-b987-b6779688b332') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "账本", "is_correct": false, "explanation": "语义：“账本”记录钱款，与句中的“时间区块”“时刻表”语境不合。"}, {"text": "日程", "is_correct": true, "explanation": "“个人的日程本”指记录每日安排的本子，与“时间区块”“时刻表”的语境相合。"}, {"text": "相册", "is_correct": false, "explanation": "搭配：“相册本上”不能布满“时间区块”，句意不通。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”记录菜式，与“军械化管理”的时间语境不相合。"}], "explanations": {"账本": "语义：“账本”记录钱款，与句中的“时间区块”“时刻表”语境不合。", "日程": "“个人的日程本”指记录每日安排的本子，与“时间区块”“时刻表”的语境相合。", "相册": "搭配：“相册本上”不能布满“时间区块”，句意不通。", "食谱": "语义：“食谱”记录菜式，与“军械化管理”的时间语境不相合。"}, "sentence_index": 0, "correct_answer": "日程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的日程有三公里长。", "explanation": "这里应该用〈全长〉。日程指按时间安排的事项，不能用来计量长度；河流的长度要说“全长”。"}, {"text": "我今天有一台日程要处理。", "explanation": "这里量词用错。日程要用〈项〉或〈个〉，〈台〉多用于机器设备，不能用于安排。"}, {"text": "他每天写日程记录心情。", "explanation": "这里应该用〈日记〉。写下心情和经历用日记；日程是要做的安排，不能用来记录心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时速", "is_correct": false, "explanation": "语义：“时速”是速度，不能作为参观的依据，句意不通。"}, {"text": "日程", "is_correct": true, "explanation": "“按照日程”指依照事先的安排，与“一站一站地参观”的语境相合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：参观的先后顺序与体重无关，句意不通。"}, {"text": "电量", "is_correct": false, "explanation": "搭配：“按照电量”不能决定参观的先后，搭配不当。"}], "explanations": {"时速": "语义：“时速”是速度，不能作为参观的依据，句意不通。", "日程": "“按照日程”指依照事先的安排，与“一站一站地参观”的语境相合。", "体重": "语义：参观的先后顺序与体重无关，句意不通。", "电量": "搭配：“按照电量”不能决定参观的先后，搭配不当。"}, "sentence_index": 6, "correct_answer": "日程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的日程有三千米高。", "explanation": "这里应该用〈海拔〉。日程指按时间安排的事项，不能用来计量高度；山的高度要说“海拔”。"}, {"text": "这个日程很香，大家都想闻一闻。", "explanation": "“香”形容气味，日程没有气味；形容安排的多少应说“排得很满”。"}, {"text": "会议前，秘书打印了一条日程。", "explanation": "量词用错。日程要用〈份〉或〈个〉；〈条〉用于路、消息等细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我们的一条新日程。", "corrected_sentence": "这是我们的一份新日程。", "error_description": "量词错误：“日程”应用“份”或“个”，不能用“条”（“条”用于路、消息等细长的事物）。正确说法：这是我们的一份新日程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秘书给每位同事发了一台日程。", "corrected_sentence": "秘书给每位同事发了一份日程。", "error_description": "量词错误：“日程”不能用“台”（“台”多用于机器设备）。正确说法：一份日程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
