INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10985, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "充满，遍布。", "primary_collocate": null, "pronunciation": "bù mǎn", "ipa": "pu˥˩ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "会议准时开始，交通时刻表以秒为单位校准，个人的日程本上布满不可侵犯的时间区块——这种对时间的军械化管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "布满", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天空布满了乌云，快下雨了。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上布满了汗水。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上布满了小小的裂缝。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的手上布满皱纹。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜空中布满着星星。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上布满石头，很难走。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上布满了灰尘，好久没人用了。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田野里布满了黄色的花。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖面上布满了落叶。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "布满了", "label": "体标"}, {"form": "布满着", "label": "体标"}, {"form": "布满过", "label": "体标"}], "register": "中性", "sense_fingerprint": "布满：东西遍布、充满某个地方或表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0316e5-c34c-466b-b987-b6779688b332') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10985, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“时间区块”，句意不通。"}, {"text": "布满", "is_correct": true, "explanation": "“布满”指时间区块密密地分布在本子上，与“不可侵犯的时间区块”的语境相合。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：“漂浮”指浮在液面上，与“日程本上”的纸面语境不合。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”的对象是人或景物，不能拍摄“时间区块”。"}], "explanations": {"吃": "搭配：“吃”不能接“时间区块”，句意不通。", "布满": "“布满”指时间区块密密地分布在本子上，与“不可侵犯的时间区块”的语境相合。", "漂浮": "语义：“漂浮”指浮在液面上，与“日程本上”的纸面语境不合。", "拍摄": "搭配：“拍摄”的对象是人或景物，不能拍摄“时间区块”。"}, "sentence_index": 0, "correct_answer": "布满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上布满了一颗星星。", "explanation": "这里应该用〈挂〉。布满指许多东西遍布某处，单颗星星只能说“挂着”。"}, {"text": "操场上布满了一辆车。", "explanation": "这里应该用〈停〉。布满指许多东西遍布某处，一辆车只能说“停着”。"}, {"text": "桌上布满了一本书。", "explanation": "这里应该用〈放〉。布满指许多东西遍布某处，只有一本书应说“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10985, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "种", "is_correct": false, "explanation": "语义：“种”的对象是植物，石头不能种。"}, {"text": "布满", "is_correct": true, "explanation": "“布满”指石头遍布路面，与“很难走”的语境相合。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不能喂石头。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”的对象是食物，“烤石头”搭配不当。"}], "explanations": {"种": "语义：“种”的对象是植物，石头不能种。", "布满": "“布满”指石头遍布路面，与“很难走”的语境相合。", "喂": "搭配：“喂”的对象是人或动物，不能喂石头。", "烤": "搭配：“烤”的对象是食物，“烤石头”搭配不当。"}, "sentence_index": 6, "correct_answer": "布满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里布满了一张桌子。", "explanation": "这里应该用〈摆〉。布满指许多东西遍布某处，一张桌子只能说“摆着”。"}, {"text": "他脸上布满了一道伤口。", "explanation": "这里应该用〈有〉。布满指许多东西遍布，一道伤口只能说“有”。"}, {"text": "墙上布满了一幅画。", "explanation": "这里应该用〈挂〉。墙上挂着一幅画；布满指许多东西遍布，不能用于一幅画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10985, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里布满在落叶。", "corrected_sentence": "院子里布满了落叶。", "error_description": "“布满”是动词，后面应直接带宾语“落叶”，“落叶”前不能加介词“在”。正确说法：院子里布满了落叶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10985, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙滩上很布满了脚印。", "corrected_sentence": "沙滩上布满了脚印。", "error_description": "“很”不能修饰动词“布满”，应去掉“很”。正确说法：沙滩上布满了脚印。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
