INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "划分出来的一块区域或一个段落。", "primary_collocate": null, "pronunciation": "qū kuài", "ipa": "tɕʰy˥ kʰuai˥˩", "syllable_count": 2, "sentences": [{"text": "会议准时开始，交通时刻表以秒为单位校准，每个人的日程表上都布满了一个个不可侵犯的区块，这种对时间的严格管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "区块", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他把一天分成几个区块，每个区块做一件事。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把周末上午划成一个区块，专门用来读书。", "target_word": "区块", "complexity_tier": "T3", "furigana": "wǒ bǎ zhōumò shàngwǔ huàchéng yí gè qūkuài, zhuānmén yònglái dúshū.", "sentence_source": "generated"}, {"text": "文章分成三个区块，每个区块讲一个问题。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日历上蓝色的区块是开会的时间。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周三晚上都留出一个区块来运动。", "target_word": "区块", "complexity_tier": "T3", "furigana": "tā měi zhōu sān wǎnshang dōu liúchū yí gè qūkuài lái yùndòng.", "sentence_source": "generated"}, {"text": "这个区块是办公区，旁边是休息区。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把网页上的新闻区块放在最上面。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把课表排成了几个区块，每个区块上一门课。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，绿色区块是公园，灰色区块是商店。", "target_word": "区块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "时间区块", "label": "复合"}, {"form": "區塊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划分出来的一块区域、时间段或内容段落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“区块”指划分出的一段时间，“布满一个个不可侵犯的区块”指日程里被划定的时段，与句意相合。"}, {"text": "方向", "is_correct": false, "explanation": "语义：日程表上不会“布满”方向，“一个个不可侵犯的方向”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：日程表上布满的不是颜色，“一个个不可侵犯的颜色”与句意不合。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”不能与“不可侵犯”搭配，也不能指日程中被划定的时段。"}], "explanations": {"区块": "“区块”指划分出的一段时间，“布满一个个不可侵犯的区块”指日程里被划定的时段，与句意相合。", "方向": "语义：日程表上不会“布满”方向，“一个个不可侵犯的方向”说不通。", "颜色": "语义：日程表上布满的不是颜色，“一个个不可侵犯的颜色”与句意不合。", "尺寸": "搭配：“尺寸”不能与“不可侵犯”搭配，也不能指日程中被划定的时段。"}, "sentence_index": 0, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个论坛里有五个区块，每个区块的帖子都很多。", "explanation": "这里应该用〈版块〉。版块指论坛中的分类栏目；“区块”指划分出的区域或段落，不用于论坛分类。"}, {"text": "他把这一天分成几条区块，每条区块做一件事。", "explanation": "这里应该用〈个〉。区块作为时段单位，量词用“个”；“条”用于长条形的事物。"}, {"text": "孩子把区块一块块堆起来。", "explanation": "这里应该用〈积木〉。积木是玩具块，可以一块块堆起来；“区块”指划分出的区域、时段或段落，不指玩具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区块", "is_correct": true, "explanation": "“区块”指划分出的一块区域，填入后与“办公区”“休息区”的分区语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“这个颜色是办公区”不成立，颜色不能指一处办公场所。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指时间点，不能是办公区，与句中的空间分区不合。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“是办公区”要求指地点的名词，“音乐”不能指地点，不搭配。"}], "explanations": {"区块": "“区块”指划分出的一块区域，填入后与“办公区”“休息区”的分区语境相合。", "颜色": "语义：“这个颜色是办公区”不成立，颜色不能指一处办公场所。", "时刻": "语义：“时刻”指时间点，不能是办公区，与句中的空间分区不合。", "音乐": "搭配：“是办公区”要求指地点的名词，“音乐”不能指地点，不搭配。"}, "sentence_index": 6, "correct_answer": "区块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "棋盘上画着一个个小区块，每个区块都能放一枚棋子。", "explanation": "这里应该用〈方格〉。方格指棋盘上的小格子；“区块”指划分出的一大片区域或段落，不用于一个个小格子。"}, {"text": "地图上，那双区块是公园，这双区块是商店。", "explanation": "这里应该用〈个〉。“双”用于成对的东西，如鞋袜；区块是单个划分单位，量词用“个”。"}, {"text": "工厂的流水线上装着一个个区块，工人一个个检查。", "explanation": "这里应该用〈零件〉。零件是机器的组成部分；“区块”不指单个机械零件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把下午划成一条区块，专门用来开会。", "corrected_sentence": "我们把下午划成一个区块，专门用来开会。", "error_description": "量词错误：“区块”的量词是“个”，“条”不能用来计量区块。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把周末分成了两条区块。", "corrected_sentence": "他把周末分成了两个区块。", "error_description": "量词错误：“区块”应搭配量词“个”，不说“两条区块”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
