INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10989, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指军队使用的各种武器、弹药、器材等装备的总称。", "primary_collocate": null, "pronunciation": "jūn xiè", "ipa": "tɕyn˥ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这些军械都是用来打仗的，必须严格管理。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里存放着大量军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队正在检查新运来的军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把军械运到了前线。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，国家减少了军械的生产。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军械要定期检查，才能保证安全。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在部队里负责管理军械。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批军械是从国外买来的。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里展出了古代的军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人抢走了我们的一些军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军械库", "label": "复合"}, {"form": "军械师", "label": "复合"}], "register": "书面", "sense_fingerprint": "军械：军队使用的武器、弹药、器材等装备的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0316e5-c34c-466b-b987-b6779688b332') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军械", "is_correct": true, "explanation": "军械（jūn xiè）指军队使用的武器和装备，是正确答案。"}, {"text": "军界", "is_correct": false, "explanation": "jiè（第四声）与 xiè（第四声）声母不同（j 与 x），意思是军队方面的人士或圈子。"}, {"text": "军校", "is_correct": false, "explanation": "xiào 与 xiè 韵母不同，意思是军事院校。"}, {"text": "军鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是军用的鞋。"}], "explanations": {"军械": "军械（jūn xiè）指军队使用的武器和装备，是正确答案。", "军界": "jiè（第四声）与 xiè（第四声）声母不同（j 与 x），意思是军队方面的人士或圈子。", "军校": "xiào 与 xiè 韵母不同，意思是军事院校。", "军鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是军用的鞋。"}, "sentence_index": null, "correct_answer": "军械"}, "level_3": {"options": [{"text": "军械", "is_correct": true, "explanation": "“用来打仗的”指向武器装备，“军械”正合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器用于演奏，不是用来打仗的装备，句意不通。"}, {"text": "厨具", "is_correct": false, "explanation": "语义：厨具用于烹饪，不能说“用来打仗的厨具”。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具用于居家摆设，与“用来打仗”的语境不符。"}], "explanations": {"军械": "“用来打仗的”指向武器装备，“军械”正合语境。", "乐器": "语义：乐器用于演奏，不是用来打仗的装备，句意不通。", "厨具": "语义：厨具用于烹饪，不能说“用来打仗的厨具”。", "家具": "语义：家具用于居家摆设，与“用来打仗”的语境不符。"}, "sentence_index": 0, "correct_answer": "军械"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在柜台上买了一把军械。", "explanation": "这里应该用〈枪〉。军械是各类装备的总称，不指某一件武器，买一件具体的武器要说“一把枪”。"}, {"text": "这家公司的办公军械很先进。", "explanation": "这里应该用〈设备〉。军械专指军队使用的武器装备，办公室里的器材应说“设备”。"}, {"text": "我们的仓库里放着一只军械。", "explanation": "这里应该用〈批〉。军械是成批的装备，常说“一批军械”；“只”多用于动物或成对的东西，不用于军械。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10989, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军械", "is_correct": true, "explanation": "军械指武器装备，“负责管理军械”符合部队的语境。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义：奶茶是饮品，部队里负责管理的不会是奶茶，与“部队”的语境不符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：部队里不会负责管理宠物，与军队的语境不符。"}, {"text": "草莓", "is_correct": false, "explanation": "搭配：“管理”一般不直接以“草莓”这类果实作宾语，在部队语境下也不成立。"}], "explanations": {"军械": "军械指武器装备，“负责管理军械”符合部队的语境。", "奶茶": "语义：奶茶是饮品，部队里负责管理的不会是奶茶，与“部队”的语境不符。", "宠物": "语义：部队里不会负责管理宠物，与军队的语境不符。", "草莓": "搭配：“管理”一般不直接以“草莓”这类果实作宾语，在部队语境下也不成立。"}, "sentence_index": 6, "correct_answer": "军械"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都喝一杯军械。", "explanation": "搭配不当：“喝”的对象应是饮料，军械是武器装备，不能喝。"}, {"text": "他今天穿了一件军械去上班。", "explanation": "这里应该用〈衣服〉。军械是武器装备，不能指身上穿的衣物。"}, {"text": "这块布是用军械做的，颜色很漂亮。", "explanation": "军械是武器装备，不是织布的原料，“用……做”的材料与“军械”的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只军械已经全部送到了边防。", "corrected_sentence": "这批军械已经全部送到了边防。", "error_description": "量词错误：军械是成批的装备，应说“这批军械”。“只”用于动物或成对的东西，不能用于军械。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战士们把军械擦很亮。", "corrected_sentence": "战士们把军械擦得很亮。", "error_description": "补语错误：“擦”后接程度补语“很亮”时要用“得”连接，应说“擦得很亮”，漏掉“得”就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指使某种做法或规则成为固定的制度。", "primary_collocate": null, "pronunciation": "zhì dù huà", "ipa": "ʈʂɻ̩˥˩ tu˥˩ xua˥˩", "syllable_count": 3, "sentences": [{"text": "水的分配通常由村落集体协商决定，依循季节、作物类型与土地面积进行动态调整，体现了高度制度化的资源管理逻辑。", "target_word": "制度化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "会议准时开始，交通时刻表以秒为单位校准，个人的日程本上布满不可侵犯的时间区块——这种对时间的机械化管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "制度化", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "最终，企业调整策略，将“核心工作时段”制度化，而非苛求分秒不差，既保障生产效率，又尊重文化惯性。", "target_word": "制度化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司想把这个做法制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校已经把周末检查制度化了。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项规定应该尽快制度化。", "target_word": "制度化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把垃圾分类制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作汇报很快就制度化了，每周一次。", "target_word": "制度化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他建议把每月开会制度化。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法制度化以后，大家都照着做。", "target_word": "制度化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "使做法或规则成为固定制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度化", "is_correct": true, "explanation": "制度化指使做法或规则成为固定制度，可修饰“高度…的资源管理逻辑”，与“依循季节调整”的规则性一致。"}, {"text": "个人化", "is_correct": false, "explanation": "语义：个人化与“由村落集体协商决定”的集体性相反，不能描述资源管理逻辑的特征。"}, {"text": "口语化", "is_correct": false, "explanation": "搭配：口语化只用于话语或文字，不能修饰“资源管理逻辑”。"}, {"text": "随意化", "is_correct": false, "explanation": "语义：随意化与“依循季节、作物类型……进行动态调整”的有章可循相反。"}], "explanations": {"制度化": "制度化指使做法或规则成为固定制度，可修饰“高度…的资源管理逻辑”，与“依循季节调整”的规则性一致。", "个人化": "语义：个人化与“由村落集体协商决定”的集体性相反，不能描述资源管理逻辑的特征。", "口语化": "搭配：口语化只用于话语或文字，不能修饰“资源管理逻辑”。", "随意化": "语义：随意化与“依循季节、作物类型……进行动态调整”的有章可循相反。"}, "sentence_index": 0, "correct_answer": "制度化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的零件应该制度化，每个尺寸都一样。", "explanation": "这里应该用〈标准化〉。制度化指把做法或规则固定成制度，零件尺寸的统一要用标准化。"}, {"text": "这块石头已经制度化了。", "explanation": "这里应该用〈风化〉。制度化指把做法或规则固定成制度，石头因自然侵蚀而变化要说风化。"}, {"text": "他的心情很制度化。", "explanation": "这里应该用〈平静〉。制度化不能形容人的心情，心情的状态要说平静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度化", "is_correct": true, "explanation": "制度化指把做法或规则固定下来，与“我们要把垃圾分类……”的意图相符。"}, {"text": "空洞化", "is_correct": false, "explanation": "语义：空洞化指失去实际内容，与把垃圾分类建立成长期做法的意图相反。"}, {"text": "随机化", "is_correct": false, "explanation": "搭配：“分类”需要按标准进行，不能与“随机化”搭配。"}, {"text": "无序化", "is_correct": false, "explanation": "语义：无序化与“制度化”追求固定秩序的意思相反。"}], "explanations": {"制度化": "制度化指把做法或规则固定下来，与“我们要把垃圾分类……”的意图相符。", "空洞化": "语义：空洞化指失去实际内容，与把垃圾分类建立成长期做法的意图相反。", "随机化": "搭配：“分类”需要按标准进行，不能与“随机化”搭配。", "无序化": "语义：无序化与“制度化”追求固定秩序的意思相反。"}, "sentence_index": 6, "correct_answer": "制度化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯茶我早就制度化了，你直接喝吧。", "explanation": "这里应该用〈泡好〉。制度化指把做法或规则固定成制度，一杯茶不能说制度化；说茶已经泡好要用〈泡好〉。"}, {"text": "他把计划制度化了三次。", "explanation": "这里应该用〈修改〉。制度化是把做法固定下来，计划反复变动时要说修改。"}, {"text": "我们已经制度化了这个问题。", "explanation": "这里应该用〈解决〉。问题要解决，不能说制度化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经把这个办法制度化。", "corrected_sentence": "我们已经把这个办法制度化了。", "error_description": "漏掉了“了”。“已经”表示已完成，句末要用“了”，应说“把这个办法制度化了”，不能说“把这个办法制度化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10991, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很快我们把这个流程制度化的，每周都做。", "corrected_sentence": "很快我们把这个流程制度化了，每周都做。", "error_description": "“了”误用为“的”。正确形式是“制度化了”，表示动作完成；“制度化的”不能结束把字句，应改为“制度化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
