INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指引导事物发展的方向或目标。", "primary_collocate": null, "pronunciation": "dǎo xiàng", "ipa": "tɑʊ̯˨˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "会议准时开始，交通时刻表以秒为单位校准，个人的日程本上布满不可侵犯的时间区块——这种对时间的军械化管理，反映出一种高度制度化与效率导向的社会逻辑。", "target_word": "导向", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司以客户需求为导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的政策要有清晰的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的考试导向影响学生的学习方法。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动有很好的社会导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "媒体应该给大家正确的价值导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务以质量为导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话给了我们学习的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的新政策有明显的环保导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的奖励制度有很强的结果导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "引导事物发展的方向或目标，如“结果导向”“市场导向”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c0316e5-c34c-466b-b987-b6779688b332') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10993, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导向", "is_correct": true, "explanation": "导向指引导事物发展的方向或目标，此处“效率导向”指以效率为目标的取向。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“效率颜色”不成立，颜色与“效率”的社会逻辑无关。"}, {"text": "分量", "is_correct": false, "explanation": "语义：分量指重量，不能与“效率”构成“……的社会逻辑”中的定语。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“效率”一般不与“温度”构成定中结构，语境也说不通。"}], "explanations": {"导向": "导向指引导事物发展的方向或目标，此处“效率导向”指以效率为目标的取向。", "颜色": "语义：“效率颜色”不成立，颜色与“效率”的社会逻辑无关。", "分量": "语义：分量指重量，不能与“效率”构成“……的社会逻辑”中的定语。", "温度": "搭配：“效率”一般不与“温度”构成定中结构，语境也说不通。"}, "sentence_index": 0, "correct_answer": "导向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项政策里有一只重要的导向。", "explanation": "这里应该用〈种〉。导向是抽象的引导，应说“一种导向”；“只”多用于动物或成对的东西，不能用于导向。"}, {"text": "他把导向装进了书包。", "explanation": "这里应该用〈课本〉。导向是抽象的指引，不是有形的物品，不能装进书包，装进书包的应是课本等实物。"}, {"text": "教室里放着一瓶导向。", "explanation": "这里不能用“瓶”。导向是抽象的引导，不是可以盛装的液体，应说“一种导向”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导向", "is_correct": true, "explanation": "“以……为导向”是固定用法，表示以质量为引导方向，与句意一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“以质量为颜色”不通，颜色与服务的指向无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“以质量为味道”不成立，味道不能作为服务的指向。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“以……为”后不接“脾气”，脾气也不能作为服务的目标。"}], "explanations": {"导向": "“以……为导向”是固定用法，表示以质量为引导方向，与句意一致。", "颜色": "语义：“以质量为颜色”不通，颜色与服务的指向无关。", "味道": "语义：“以质量为味道”不成立，味道不能作为服务的指向。", "脾气": "搭配：“以……为”后不接“脾气”，脾气也不能作为服务的目标。"}, "sentence_index": 6, "correct_answer": "导向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟表的导向转得很快。", "explanation": "这里应该用〈指针〉。导向指引导的作用，不指钟表上转动的东西；钟表上转动的针应说“指针”。"}, {"text": "他一直在吃导向，每天都很努力。", "explanation": "搭配不当：“吃”的对象是食物，导向是抽象的引导，不能吃。"}, {"text": "这家餐厅的导向很好吃。", "explanation": "导向是抽象的引导，不是食物，“好吃”的主语应是食物，这里用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校以培养能力为导向教育越来越受欢迎。", "corrected_sentence": "学校以培养能力为导向的教育越来越受欢迎。", "error_description": "定语位置错误：“以……为导向”修饰后面的“教育”时，中间要加“的”，漏掉“的”后面的名词就连不上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的服务以顾客满意导向。", "corrected_sentence": "这家店的服务以顾客满意为导向。", "error_description": "“以……为导向”的“为”不能省略，漏掉“为”就不成立，应说“以顾客满意为导向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0dd51db-3c3a-4cb2-b11a-a4fe275f2fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
