INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10997, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时制指语言中表达时间关系的语法范畴，比如“过去”“现在”“将来”。", "primary_collocate": null, "pronunciation": "shí zhì", "ipa": "ʂʅ˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "英语动词的形式会随着时制而变化。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的动词没有时制变化。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英语有过去、现在和将来三种时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天讲了英语的时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书用一章来解释时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语时，我常常搞错时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日语的时制和汉语不一样。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语不用动词变化表示时制，而用时间词。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文研究法语的时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能说说时制和时态有什么不同吗？", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "语言中表达过去、现在、将来的语法范畴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10997, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指语言中表达时间关系的语法范畴，是听到的词。"}, {"text": "食指", "is_correct": false, "explanation": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指」"}, {"text": "时事", "is_correct": false, "explanation": "「shì 与 zhì 声母不同（sh 与 zh），意思是时事新闻」"}, {"text": "十字", "is_correct": false, "explanation": "「zì 与 zhì 声母不同（z 与 zh），意思是十字形」"}, {"text": "石柱", "is_correct": false, "explanation": "「zhù 与 zhì 韵母不同（u 与 i），意思是石头做的柱子」"}], "explanations": {"时制": "时制指语言中表达时间关系的语法范畴，是听到的词。", "食指": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指」", "时事": "「shì 与 zhì 声母不同（sh 与 zh），意思是时事新闻」", "十字": "「zì 与 zhì 声母不同（z 与 zh），意思是十字形」", "石柱": "「zhù 与 zhì 韵母不同（u 与 i），意思是石头做的柱子」"}, "sentence_index": null, "correct_answer": "时制"}, "level_3": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指语言中表达时间关系的语法范畴，英语动词的形式随时制变化，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：动词的形式不会随天气变化，与语法无关。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：动词的形式不会随颜色变化，与语法无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：动词的形式不会随价格变化，与语法无关。"}], "explanations": {"时制": "时制指语言中表达时间关系的语法范畴，英语动词的形式随时制变化，与句意相符。", "天气": "语义：动词的形式不会随天气变化，与语法无关。", "颜色": "语义：动词的形式不会随颜色变化，与语法无关。", "价格": "语义：动词的形式不会随价格变化，与语法无关。"}, "sentence_index": 0, "correct_answer": "时制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要珍惜时制，不要虚度光阴。", "explanation": "这里应该用〈时间〉。时间可以珍惜，时制是语法范畴，不能珍惜。"}, {"text": "我们生活在快速变化的时制中。", "explanation": "这里应该用〈时代〉。时代指社会所处的历史阶段，时制只指语言里表达时间关系的语法范畴。"}, {"text": "这部电影的时制长达三个小时。", "explanation": "这里应该用〈时长〉。时长指事物持续的时间长短，电影片长要说时长；时制是语法范畴，不指片长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10997, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指语言中表达时间关系的语法范畴，是听到的词。"}, {"text": "十指", "is_correct": false, "explanation": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是十根手指」"}, {"text": "实事", "is_correct": false, "explanation": "「shì 与 zhì 声母不同（sh 与 zh），意思是实际的事情」"}, {"text": "石子", "is_correct": false, "explanation": "「zi（轻声）与 zhì（第四声）声母和声调都不同（z 与 zh），意思是小石头」"}, {"text": "市制", "is_correct": false, "explanation": "「shì（第四声）与 shí（第二声）声调不同，意思是旧式度量制度」"}], "explanations": {"时制": "时制指语言中表达时间关系的语法范畴，是听到的词。", "十指": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是十根手指」", "实事": "「shì 与 zhì 声母不同（sh 与 zh），意思是实际的事情」", "石子": "「zi（轻声）与 zhì（第四声）声母和声调都不同（z 与 zh），意思是小石头」", "市制": "「shì（第四声）与 shí（第二声）声调不同，意思是旧式度量制度」"}, "sentence_index": null, "correct_answer": "时制"}, "level_3": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指语言表达时间关系的语法范畴，与“日语的……和汉语不一样”的语法比较相符。"}, {"text": "国家", "is_correct": false, "explanation": "语义：“国家”指政治实体，不能作为语言的语法特征。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人体的温度，与语言的比较无关。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能和“语言的特点”搭配，不能拿来与汉语比较。"}], "explanations": {"时制": "时制指语言表达时间关系的语法范畴，与“日语的……和汉语不一样”的语法比较相符。", "国家": "语义：“国家”指政治实体，不能作为语言的语法特征。", "体温": "语义：“体温”指人体的温度，与语言的比较无关。", "价格": "搭配：“价格”不能和“语言的特点”搭配，不能拿来与汉语比较。"}, "sentence_index": 6, "correct_answer": "时制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段时制我过得很快乐。", "explanation": "这里应该用〈时期〉。时期指一段时间，时制是语法范畴，不能用来指一段时期。"}, {"text": "你是什么时制到的？", "explanation": "这里应该用〈时候〉。问具体时点要说“什么时候”，时制不指时间点。"}, {"text": "这首歌的时制很快。", "explanation": "这里应该用〈节奏〉。节奏用来形容音乐的快慢，时制不能用来形容歌曲的节奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10997, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "英语的时制有三只，分别是过去、现在和将来。", "corrected_sentence": "英语的时制有三种，分别是过去、现在和将来。", "error_description": "量词错误：“时制”是抽象的语法范畴，应用量词“种”，不能用“只”（“只”多用于小动物、鞋袜等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10997, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法语的时制有好几条，学起来不容易。", "corrected_sentence": "法语的时制有好几种，学起来不容易。", "error_description": "量词错误：“时制”应用量词“种”，“条”用于细长的事物，不能用于抽象的语法范畴。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
