INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10998, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刀等工具将物体断开或分离。", "primary_collocate": null, "pronunciation": "qiē gē", "ipa": "tɕʰie˥ kɤ˥", "syllable_count": 2, "sentences": [{"text": "工人用机器切割钢板。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地切割着木板。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀可以切割很硬的东西。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把大石头切割成四块。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "切割玻璃时要戴手套。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器每天切割一百块铁板。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用激光切割金属。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅用电锯切割木头。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钻石很硬，要用特别的工具切割。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门切割石头。", "target_word": "切割", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "切割了", "label": "体标"}, {"form": "切割着", "label": "体标"}, {"form": "切割过", "label": "体标"}, {"form": "切割机", "label": "复合"}], "register": "中性", "sense_fingerprint": "用刀等工具把物体断开或分离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "切割", "is_correct": true, "explanation": "切割指用工具把物体分开，与“用机器”和“钢板”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”需要用水或加热，不能用来加工钢板。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱钢板”。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”是用油加热食物，与机器加工钢板不符。"}], "explanations": {"切割": "切割指用工具把物体分开，与“用机器”和“钢板”相符。", "煮": "语义：“煮”需要用水或加热，不能用来加工钢板。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱钢板”。", "煎": "语义：“煎”是用油加热食物，与机器加工钢板不符。"}, "sentence_index": 0, "correct_answer": "切割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用遥控器切割频道。", "explanation": "这里应该用〈切换〉。换台是切换频道，切割指用工具把物体分开，不能用于频道。"}, {"text": "他一不小心把花瓶切割了。", "explanation": "这里应该用〈打破〉。切割是用工具把物体分开，花瓶是被打破的，不是用工具切开的。"}, {"text": "工人切割了一条隧道。", "explanation": "这里应该用〈挖掘〉。挖掘隧道是挖出通道，切割是把物体分成几段，不能用于挖隧道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切割", "is_correct": true, "explanation": "切割指用工具把物体分开，与“用激光”和“金属”相符。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的对象是文字，不能说“背诵金属”。"}, {"text": "叹息", "is_correct": false, "explanation": "配价：“叹息”是不及物动词，不能带宾语“金属”。"}, {"text": "吟唱", "is_correct": false, "explanation": "语义：“吟唱”是用声音诵读或唱诗，与激光加工金属不符。"}], "explanations": {"切割": "切割指用工具把物体分开，与“用激光”和“金属”相符。", "背诵": "搭配：“背诵”的对象是文字，不能说“背诵金属”。", "叹息": "配价：“叹息”是不及物动词，不能带宾语“金属”。", "吟唱": "语义：“吟唱”是用声音诵读或唱诗，与激光加工金属不符。"}, "sentence_index": 6, "correct_answer": "切割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用毛线切割了一条围巾。", "explanation": "这里应该用〈编织〉。编织是用线交织成物，切割是把物体分开，不能用来做围巾。"}, {"text": "工匠用砂纸切割木头。", "explanation": "这里应该用〈打磨〉。打磨是用砂纸使表面光滑，切割是把木头分开。"}, {"text": "妈妈用熨斗切割衣服。", "explanation": "这里应该用〈熨烫〉。熨烫是用熨斗把衣服弄平，切割是把物体分开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器能把铁板切割小块。", "corrected_sentence": "这台机器能把铁板切割成小块。", "error_description": "补语缺失：“切割”后要加结果补语“成”，应说“切割成小块”，不能直接说“切割小块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (10998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块板材切割很整齐。", "corrected_sentence": "这块板材切割得很整齐。", "error_description": "补语标记缺失：程度补语前要用“得”，应说“切割得很整齐”，不能说“切割很整齐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
