INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11001, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用纺织方法制成的材料或制品，如布料、绸缎等。", "primary_collocate": null, "pronunciation": "zhī wù", "ipa": "ʈʂʅ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服是用透气的织物做的。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物很软，适合做婴儿的衣服。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天最好选透气的织物做衣服。", "target_word": "织物", "complexity_tier": "T3", "furigana": "zhī wù", "sentence_source": "generated"}, {"text": "这块织物是用棉线织成的。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物洗了以后不会缩水。", "target_word": "织物", "complexity_tier": "T3", "furigana": "zhī wù", "sentence_source": "generated"}, {"text": "她在店里挑了一块红色的织物。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丝绸是一种很贵的织物。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种织物不容易起皱，出差带着很方便。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘的织物太薄，挡不住阳光。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天生产几千米织物，运到各地。", "target_word": "织物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块织物", "label": "量词"}, {"form": "一种织物", "label": "量词"}, {"form": "针织物", "label": "复合"}, {"form": "織物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "纺织而成的材料或制品，布料、绸缎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11001, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "织物", "is_correct": true, "explanation": "zhī wù：用纺织方法制成的布料，正是本词的意思。"}, {"text": "植物", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，植物指生长在土地上的生物，意思完全不同。"}, {"text": "失物", "is_correct": false, "explanation": "shī 与 zhī 声母不同（sh 与 zh），失物指丢失的东西。"}, {"text": "支付", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），支付指付钱。"}, {"text": "实务", "is_correct": false, "explanation": "shí 与 zhī 声母不同，声调也不同，实务指实际的业务工作。"}], "explanations": {"织物": "zhī wù：用纺织方法制成的布料，正是本词的意思。", "植物": "zhí（第二声）与 zhī（第一声）声调不同，植物指生长在土地上的生物，意思完全不同。", "失物": "shī 与 zhī 声母不同（sh 与 zh），失物指丢失的东西。", "支付": "fù 与 wù 声母不同（f 与 w），支付指付钱。", "实务": "shí 与 zhī 声母不同，声调也不同，实务指实际的业务工作。"}, "sentence_index": null, "correct_answer": "织物"}, "level_3": {"options": [{"text": "织物", "is_correct": true, "explanation": "织物是纺织成的布料，“透气的织物”可以用来做衣服，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头坚硬不透气，不能用来做衣服。"}, {"text": "砖块", "is_correct": false, "explanation": "语义：砖块是建筑材料，不能用来做衣服。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头坚硬，不能用来做衣服，与“透气”不符。"}], "explanations": {"织物": "织物是纺织成的布料，“透气的织物”可以用来做衣服，与句意相符。", "石头": "语义：石头坚硬不透气，不能用来做衣服。", "砖块": "语义：砖块是建筑材料，不能用来做衣服。", "木头": "语义：木头坚硬，不能用来做衣服，与“透气”不符。"}, "sentence_index": 0, "correct_answer": "织物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我穿了一件织物去上班。", "explanation": "这里应该用〈衣服〉。织物是做衣服的布料，属于材料，不指穿在身上的成品，不能说“一件织物”。"}, {"text": "我买了一只织物。", "explanation": "这里应该用〈块〉或〈种〉。“只”用于动物或成对的东西，织物这类布料不用“只”。"}, {"text": "这本书的织物很有意思。", "explanation": "这里应该用〈内容〉。织物是纺织成的布料或制品，不能指书的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11001, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "织物", "is_correct": true, "explanation": "zhī wù：用纺织方法制成的布料，正是本词的意思。"}, {"text": "职务", "is_correct": false, "explanation": "zhí（第二声）与 zhī（第一声）声调不同，职务指工作中的职位与责任。"}, {"text": "置物", "is_correct": false, "explanation": "zhì（第四声）与 zhī（第一声）声调不同，置物指放置物品，如置物架。"}, {"text": "事务", "is_correct": false, "explanation": "shì 与 zhī 声母和声调都不同，事务指日常的工作或业务。"}, {"text": "支吾", "is_correct": false, "explanation": "第二音节 wu 为轻声，与 wù（第四声）声调不同，支吾指言语含糊、躲闪。"}], "explanations": {"织物": "zhī wù：用纺织方法制成的布料，正是本词的意思。", "职务": "zhí（第二声）与 zhī（第一声）声调不同，职务指工作中的职位与责任。", "置物": "zhì（第四声）与 zhī（第一声）声调不同，置物指放置物品，如置物架。", "事务": "shì 与 zhī 声母和声调都不同，事务指日常的工作或业务。", "支吾": "第二音节 wu 为轻声，与 wù（第四声）声调不同，支吾指言语含糊、躲闪。"}, "sentence_index": null, "correct_answer": "织物"}, "level_3": {"options": [{"text": "织物", "is_correct": true, "explanation": "正确：丝绸本身是一种纺织成的布料，这里说的正是织物的一种。"}, {"text": "木材", "is_correct": false, "explanation": "语义：丝绸是纺织品，不是木材，“很贵的木材”与丝绸的类别不符。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：丝绸不是粮食，“一种很贵的粮食”说不通。"}, {"text": "石块", "is_correct": false, "explanation": "体貌：石块坚硬粗糙，与丝绸柔软光滑的质地不相符。"}], "explanations": {"织物": "正确：丝绸本身是一种纺织成的布料，这里说的正是织物的一种。", "木材": "语义：丝绸是纺织品，不是木材，“很贵的木材”与丝绸的类别不符。", "粮食": "语义：丝绸不是粮食，“一种很贵的粮食”说不通。", "石块": "体貌：石块坚硬粗糙，与丝绸柔软光滑的质地不相符。"}, "sentence_index": 6, "correct_answer": "织物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用织物织了一件毛衣。", "explanation": "这里应该用〈毛线〉。织物已经织成，不能再用来织东西；织毛衣要用毛线或纱线。"}, {"text": "我在一家织物工作，负责设计。", "explanation": "这里应该用〈纺织厂〉。织物指布料等纺织成品，不指工厂或公司，“在一家……工作”要用〈纺织厂〉。"}, {"text": "她是一名织物，负责检查产品。", "explanation": "这里应该用〈工人〉。织物是布料，指物品而不指人，指从事纺织的人应说“纺织工人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11001, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只织物很结实，可以做工作服。", "corrected_sentence": "这块织物很结实，可以做工作服。", "error_description": "量词错误：“织物”应该用“块”或“种”，“只”用于动物或成对的东西，不能修饰布料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11001, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块很软织物，适合做婴儿的衣服。", "corrected_sentence": "这块很软的织物，适合做婴儿的衣服。", "error_description": "的字缺失：“很软”修饰“织物”时中间要加“的”，应说“很软的织物”，不说“很软织物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
