INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人与人之间的社会关系或交往。", "primary_collocate": null, "pronunciation": "rén jì", "ipa": "ʐən˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "时间并非被切割的容器，而是流动的织物，人际互动的完整性优先于钟表的刻度。", "target_word": "人际", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的人际关系很好，朋友很多。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚到新公司，我的人际圈很小。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的人际交往需要真诚。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太会处理人际问题。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中的人际关系很重要。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会沟通能改善人际关系。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学是扩大人际圈的好机会。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人际交往中，别人说话时要认真听。", "target_word": "人际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太擅长人际交往，常常一个人在家。", "target_word": "人际", "complexity_tier": "T3", "furigana": "tā bú tài shàncháng rén jì jiāo wǎng， cháng cháng yí gè rén zài jiā。", "sentence_source": "generated"}], "morphological_forms": [{"form": "人际关系", "label": "复合"}, {"form": "人际交往", "label": "复合"}, {"form": "人際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人与人之间的社会关系或交往", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c60d06-3515-47fc-b463-2e1824a62f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人际", "is_correct": true, "explanation": "rén jì：人与人之间的社会关系或交往，正是本词的意思。"}, {"text": "人气", "is_correct": false, "explanation": "qì 与 jì 声母不同（q 与 j），人气指受欢迎的程度。"}, {"text": "人次", "is_correct": false, "explanation": "cì 与 jì 声母不同（c 与 j），人次是统计人数的计量单位。"}, {"text": "人士", "is_correct": false, "explanation": "shì 与 jì 声母不同（sh 与 j），人士指具有某种身份的人。"}], "explanations": {"人际": "rén jì：人与人之间的社会关系或交往，正是本词的意思。", "人气": "qì 与 jì 声母不同（q 与 j），人气指受欢迎的程度。", "人次": "cì 与 jì 声母不同（c 与 j），人次是统计人数的计量单位。", "人士": "shì 与 jì 声母不同（sh 与 j），人士指具有某种身份的人。"}, "sentence_index": null, "correct_answer": "人际"}, "level_3": {"options": [{"text": "人际", "is_correct": true, "explanation": "正确：“人际互动”指人与人之间的交往，符合整句在讲人际关系的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能互动，“天气互动”与句意无关。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头是坚硬的固体，没有互动的能力，与句中的“互动”不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能与人互动，“窗户互动”说不通。"}], "explanations": {"人际": "正确：“人际互动”指人与人之间的交往，符合整句在讲人际关系的语境。", "天气": "语义：天气不能互动，“天气互动”与句意无关。", "石头": "体貌：石头是坚硬的固体，没有互动的能力，与句中的“互动”不合。", "窗户": "语义：窗户是建筑部件，不能与人互动，“窗户互动”说不通。"}, "sentence_index": 0, "correct_answer": "人际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看在我们人际的份上，才帮了我这个忙。", "explanation": "这里应该用〈人情〉。“看在……的份上”说的是情面，人际指社会关系，不能这样用。"}, {"text": "我们的友谊很深，人际也很深。", "explanation": "这里应该用〈关系〉。人际指人与人之间关系的总体，不说“很深”；具体的关系才说深浅。"}, {"text": "这家公司的人际有五公斤，有很多员工。", "explanation": "“五公斤”是重量单位，人际是抽象的关系，没有重量，不能这样称量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "人际", "is_correct": true, "explanation": "rén jì：人与人之间的社会关系或交往，正是本词的意思。"}, {"text": "人机", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，人机指人与机器。"}, {"text": "人力", "is_correct": false, "explanation": "lì 与 jì 声母不同（l 与 j），人力指人的力量或劳动力。"}, {"text": "人事", "is_correct": false, "explanation": "shì 与 jì 声母不同（sh 与 j），人事指人员安排或人事工作。"}], "explanations": {"人际": "rén jì：人与人之间的社会关系或交往，正是本词的意思。", "人机": "jī（第一声）与 jì（第四声）声调不同，人机指人与机器。", "人力": "lì 与 jì 声母不同（l 与 j），人力指人的力量或劳动力。", "人事": "shì 与 jì 声母不同（sh 与 j），人事指人员安排或人事工作。"}, "sentence_index": null, "correct_answer": "人际"}, "level_3": {"options": [{"text": "人际", "is_correct": true, "explanation": "正确：“人际关系”指人与人之间的关系，与“改善”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“关系”搭配，“颜色关系”说不通。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是家具，不是关系，无法被“改善”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能说“改善窗户关系”。"}], "explanations": {"人际": "正确：“人际关系”指人与人之间的关系，与“改善”搭配自然。", "颜色": "搭配：“颜色”不能与“关系”搭配，“颜色关系”说不通。", "课桌": "语义：课桌是家具，不是关系，无法被“改善”。", "窗户": "语义：窗户是建筑部件，不能说“改善窗户关系”。"}, "sentence_index": 6, "correct_answer": "人际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的人际今年十八岁了。", "explanation": "这里应该用〈年龄〉。年龄说的是人的岁数，人际指人与人之间的关系，不能说“十八岁”。"}, {"text": "这锅汤的人际很热。", "explanation": "这里应该用〈温度〉。汤的冷热说的是温度，人际是关系，没有冷热之分。"}, {"text": "这件衣服的人际很贵，买不起。", "explanation": "这里应该用〈价格〉。“贵”说的是价格，人际没有价格，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的人际人际关系很简单，朋友不多。", "corrected_sentence": "她的人际关系很简单，朋友不多。", "error_description": "重复错误：“人际”多写了一次，应说“她的人际关系很简单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的人际得很广，朋友很多。", "corrected_sentence": "他的人际很广，朋友很多。", "error_description": "助词错误：“得”误加在“人际”和“很广”之间，应说“他的人际很广”，不说“他的人际得很广”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b12a7-913f-4083-93e1-62d9695b39ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
