INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物保持完整无缺的状态，所有组成部分都齐全、没有缺失。", "primary_collocate": null, "pronunciation": "wán zhěng xìng", "ipa": "wan˧˥ ʈʂəŋ˨˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "时间并非被切割的容器，而是流动的织物，人际互动的完整性优先于钟表的刻度。", "target_word": "完整性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "完整性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份文件缺了两页，完整性受到了影响。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查数据的完整性很重要。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修复古画时，要保护它的完整性。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古城墙保存完好，其完整性令专家叹服。", "target_word": "完整性", "complexity_tier": "T3", "furigana": "gǔ chéng qiáng bǎo cún wán hǎo, qí wán zhěng xìng lìng zhuān jiā tàn fú.", "sentence_source": "generated"}, {"text": "这个故事缺少结尾，完整性不够。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保证数据的完整性，我们每天都备份。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古学家很看重文物的完整性。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套茶具有十二件，完整性很高。", "target_word": "完整性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据完整性", "label": "复合"}, {"form": "完整性检查", "label": "复合"}], "register": "书面语", "sense_fingerprint": "事物各部分齐全、无缺失的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba713f93-d7fe-4309-b531-8a7d0486cb5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11003, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完整性", "is_correct": true, "explanation": "“人际互动的完整性”指互动中各部分齐全，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与人际互动和钟表的刻度无关，无法比较优先次序。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度与人际互动和钟表无关，这句话无法成立。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状指物体的外形，与人际互动和钟表的刻度无关，无法比较优先次序。"}], "explanations": {"完整性": "“人际互动的完整性”指互动中各部分齐全，符合语境。", "颜色": "语义：颜色与人际互动和钟表的刻度无关，无法比较优先次序。", "亮度": "语义：亮度与人际互动和钟表无关，这句话无法成立。", "形状": "语义：形状指物体的外形，与人际互动和钟表的刻度无关，无法比较优先次序。"}, "sentence_index": 0, "correct_answer": "完整性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯牛奶的完整性很稀。", "explanation": "这里应该用〈浓度〉。完整性指各部分齐全，说液体的浓淡要用浓度，不能说“很稀”。"}, {"text": "他跑步的完整性很快。", "explanation": "这里应该用〈速度〉。完整性指齐全无缺，不能用来形容快慢。"}, {"text": "这箱苹果的完整性很大。", "explanation": "这里应该用〈重量〉。完整性指齐全无缺，不能用来表示轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完整性", "is_correct": true, "explanation": "“缺少结尾，完整性不够”说明故事不够齐全，符合语境。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，与故事是否有结尾无关。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：湿度指空气的潮湿程度，与故事的内容无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“不够”不用来形容体重，也不能用来评价故事。"}], "explanations": {"完整性": "“缺少结尾，完整性不够”说明故事不够齐全，符合语境。", "音量": "语义：音量指声音的大小，与故事是否有结尾无关。", "湿度": "语义：湿度指空气的潮湿程度，与故事的内容无关。", "体重": "搭配：“不够”不用来形容体重，也不能用来评价故事。"}, "sentence_index": 6, "correct_answer": "完整性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地的完整性很大。", "explanation": "这里应该用〈面积〉。完整性指各部分齐全，不表示大小。"}, {"text": "这个水杯的完整性很大。", "explanation": "这里应该用〈容量〉。完整性不能用来表示能装多少。"}, {"text": "这件衣服的完整性很薄。", "explanation": "这里应该用〈厚度〉。完整性不能用来表示薄厚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请检查一下文件是完整性。", "corrected_sentence": "请检查一下文件的完整性。", "error_description": "“文件的完整性”中，“的”连接定语“文件”与中心语“完整性”，不能用“是”。应说“文件的完整性”，不说“文件是完整性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套书的完整性被受到了影响。", "corrected_sentence": "这套书的完整性受到了影响。", "error_description": "“受到”本身已表示被动，前面不能再加“被”。应说“完整性受到了影响”，不说“被受到了影响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
