INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11005, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钟表是用于显示时间的仪器，通常有指针或数字显示。", "primary_collocate": null, "pronunciation": "zhōng biǎo", "ipa": "tʂʊŋ˥ pjaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "时间并非被切割的容器，而是流动的织物，人际互动的完整性优先于钟表的刻度。", "target_word": "钟表", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店专门修理各种钟表。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷收藏了很多老钟表。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钟表的指针一直在慢慢转动。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钟表走得很准，一分钟也不差。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "瑞士以制造高级钟表闻名世界。", "target_word": "钟表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在店里看了很多钟表，没有买。", "target_word": "钟表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有钟表的时候，人们看太阳知道时间。", "target_word": "钟表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的钟表显示现在是八点。", "target_word": "钟表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对钟表的构造很感兴趣，常常拆开来看。", "target_word": "钟表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钟表店", "label": "复合"}, {"form": "钟表匠", "label": "复合"}, {"form": "鐘錶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "显示时间的仪器，有指针或数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钟表", "is_correct": true, "explanation": "正确：钟表上有刻度，“钟表的刻度”是通顺的说法。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事没有刻度，“优先于故事的刻度”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“刻度”属于量具或仪器，不与“歌曲”搭配。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，也没有刻度，句中说不通。"}], "explanations": {"钟表": "正确：钟表上有刻度，“钟表的刻度”是通顺的说法。", "故事": "语义：故事没有刻度，“优先于故事的刻度”说不通。", "歌曲": "搭配：“刻度”属于量具或仪器，不与“歌曲”搭配。", "空气": "语义：空气看不见，也没有刻度，句中说不通。"}, "sentence_index": 0, "correct_answer": "钟表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一把钟表，准备送给朋友。", "explanation": "量词错误：这里应该用〈块〉。“把”用于有柄的器具，钟表不用“把”计量。"}, {"text": "他买了一根钟表。", "explanation": "量词错误：这里应该用〈块〉。“根”用于细长条状的东西，钟表不能用“根”。"}, {"text": "这间房的墙上挂着一条钟表。", "explanation": "量词错误：这里应该用〈块〉。“条”用于细长或成条的事物，钟表不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钟表", "is_correct": true, "explanation": "正确：店里有钟表，可以看，也可以买，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是店里的商品，在店里看不到，也买不到。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“在店里看了很多……”后接的应是可以陈列的商品，“河流”不搭配。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不能在店里看，也不能购买，与“没有买”的语境矛盾。"}], "explanations": {"钟表": "正确：店里有钟表，可以看，也可以买，符合语境。", "天空": "语义：天空不是店里的商品，在店里看不到，也买不到。", "河流": "搭配：“在店里看了很多……”后接的应是可以陈列的商品，“河流”不搭配。", "云朵": "语义：云朵不能在店里看，也不能购买，与“没有买”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "钟表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士用钟表测量病人的体温。", "explanation": "这里应该用〈体温表〉。测体温要用体温表，钟表只用来看时间。"}, {"text": "他每个月都去抄钟表的读数，然后交水费。", "explanation": "这里应该用〈水表〉。抄表交费用的是计量水量的水表，钟表不计量水。"}, {"text": "这位摊主用钟表称一斤苹果。", "explanation": "这里应该用〈秤〉。称重要用秤，钟表不能用来称东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸修好了一张钟表。", "corrected_sentence": "我爸爸修好了一块钟表。", "error_description": "量词错误：“钟表”应使用量词“块”，“张”用于平面的东西，不能用来计量钟表。正确说法是“一块钟表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是爷爷的表钟，很有年头了。", "corrected_sentence": "这是爷爷的钟表，很有年头了。", "error_description": "语序错误：“钟表”两个字颠倒了，应说“钟表”，而不是“表钟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
