INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "量具或仪表上表示量值大小的标记线。", "primary_collocate": null, "pronunciation": "kè dù", "ipa": "kʰɤ˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "时间并非被切割的容器，而是流动的织物，人际互动的完整性优先于钟表的刻度。", "target_word": "刻度", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "量杯上的刻度很清楚。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "温度计的刻度从零度开始。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水加到一百毫升的刻度就可以了。", "target_word": "刻度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按照刻度读出体重数字。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子的刻度已经磨掉了。", "target_word": "刻度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位计上的刻度清楚地显示了河水的高低。", "target_word": "刻度", "complexity_tier": "T3", "furigana": "shuǐ wèi jì shàng de kè dù qīng chu de xiǎn shì le hé shuǐ de gāo dī。", "sentence_source": "generated"}, {"text": "看不清刻度，就没法准确测量。", "target_word": "刻度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仪表的刻度分得非常细。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秤的刻度模糊，所以称不准。", "target_word": "刻度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "刻度尺", "label": "复合"}, {"form": "刻度盘", "label": "复合"}, {"form": "刻度线", "label": "复合"}], "register": "中性", "sense_fingerprint": "量具或仪表上表示量值的标记线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刻度", "is_correct": true, "explanation": "正确：“钟表的刻度”指钟表上表示量值的标线，句中语境通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不表示量值，“优先于钟表的颜色”与句意不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是量值的标记，句中说的是计量或标示，不能用“味道”。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“钟表的”后接“歌词”不通，歌词与钟表不搭配。"}], "explanations": {"刻度": "正确：“钟表的刻度”指钟表上表示量值的标线，句中语境通顺。", "颜色": "语义：颜色不表示量值，“优先于钟表的颜色”与句意不符。", "味道": "语义：味道不是量值的标记，句中说的是计量或标示，不能用“味道”。", "歌词": "搭配：“钟表的”后接“歌词”不通，歌词与钟表不搭配。"}, "sentence_index": 0, "correct_answer": "刻度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "秤上的刻度会自己走到五公斤。", "explanation": "这里应该用〈指针〉。刻度是固定的标线，不会自己移动；会移动并指示读数的是指针。"}, {"text": "我用刻度打了一个电话。", "explanation": "这里应该用〈手机〉。刻度是量具上的标线，不能用来打电话；打电话要用手机。"}, {"text": "妈妈用刻度包了饺子。", "explanation": "这里应该用〈面皮〉。刻度是量具上的标线，不能用来包饺子；包饺子要用面皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刻度", "is_correct": true, "explanation": "正确：水位计上的刻度可以清楚地显示水位的高低，符合语境。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能显示水位的高低，与句意矛盾。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味无法显示水位的高低，句中说不通。"}, {"text": "花纹", "is_correct": false, "explanation": "搭配：“显示……高低”不搭配“花纹”，花纹只是装饰。"}], "explanations": {"刻度": "正确：水位计上的刻度可以清楚地显示水位的高低，符合语境。", "歌曲": "语义：歌曲不能显示水位的高低，与句意矛盾。", "气味": "语义：气味无法显示水位的高低，句中说不通。", "花纹": "搭配：“显示……高低”不搭配“花纹”，花纹只是装饰。"}, "sentence_index": 6, "correct_answer": "刻度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用刻度给朋友写了一封信。", "explanation": "这里应该用〈笔〉。刻度是量具上的标线，不能用来写字；写信要用笔。"}, {"text": "我用刻度煮了一锅粥。", "explanation": "这里应该用〈锅〉。刻度不能用来煮东西；煮粥要用锅。"}, {"text": "秤的刻度一直在慢慢转动。", "explanation": "这里应该用〈指针〉。刻度是固定的标线，不会转动；会转动的是指针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秤上有一把清楚的刻度。", "corrected_sentence": "秤上有一道清楚的刻度。", "error_description": "量词错误：“刻度”应使用量词“道”，“把”用于有柄的器具，不能用来计量标线。正确说法是“一道刻度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个秤的刻度分很细。", "corrected_sentence": "这个秤的刻度分得很细。", "error_description": "补语错误：“分得很细”中的“得”不可省略，应说“分得很细”，不能说“分很细”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
