INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11007, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商务指的是商业活动，包括贸易、谈判、合同等事务。", "primary_collocate": null, "pronunciation": "shāng wù", "ipa": "ʂɑŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "商务", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他这次出差是为了谈商务合作。", "target_word": "商务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责公司的对外商务。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商务谈判进行了三个小时。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次来北京是因为商务，不是旅游。", "target_word": "商务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经常乘飞机，因为商务繁忙。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司新开了商务部门。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商务活动结束后，我们一起吃了晚饭。", "target_word": "商务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她英语很好，适合做商务工作。", "target_word": "商务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方就商务条件交换了意见。", "target_word": "商务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "商务舱", "label": "复合"}, {"form": "商务英语", "label": "复合"}, {"form": "商務", "label": "繁体"}], "register": "正式", "sense_fingerprint": "商业活动事务，如贸易、谈判、合同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11007, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：商务，shāng wù，指商业活动和商业事务。"}, {"text": "上午", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。"}, {"text": "尚武", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。"}, {"text": "晌午", "is_correct": false, "explanation": "shǎng wu 与 shāng wù 声调不同（午读轻声），意思是中午，多用于口语。"}], "explanations": {"商务": "正确：商务，shāng wù，指商业活动和商业事务。", "上午": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。", "尚武": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。", "晌午": "shǎng wu 与 shāng wù 声调不同（午读轻声），意思是中午，多用于口语。"}, "sentence_index": null, "correct_answer": "商务"}, "level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“一场商务会面”指为商业事务而进行的见面，符合句子语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能说明会面的性质，“一场天气会面”说不通。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，与双方见面无关，句中不通。"}, {"text": "运动", "is_correct": false, "explanation": "搭配：“运动”后接“会面”不自然，一般不说“运动会面”。"}], "explanations": {"商务": "正确：“一场商务会面”指为商业事务而进行的见面，符合句子语境。", "天气": "语义：天气不能说明会面的性质，“一场天气会面”说不通。", "地震": "语义：地震是自然灾害，与双方见面无关，句中不通。", "运动": "搭配：“运动”后接“会面”不自然，一般不说“运动会面”。"}, "sentence_index": 0, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的商务很好吃。", "explanation": "这里应该用〈菜〉。商务指商业事务，不能用“好吃”来形容；形容好吃的应是菜。"}, {"text": "他在街上开了一家商务。", "explanation": "这里应该用〈商店〉。商务指商业活动，不指店铺，开店要说“商店”。"}, {"text": "这家店卖各种商务，价格很便宜。", "explanation": "这里应该用〈商品〉。商务指商业活动，不指所卖的货物，卖的东西要说“商品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“公司新开了商务部门”指公司新设了负责商业事务的部门，符合句意。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是昆虫，不能作为公司的部门名称，句中说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能作为公司的部门名称，句中说不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能作为公司的部门名称。"}], "explanations": {"商务": "正确：“公司新开了商务部门”指公司新设了负责商业事务的部门，符合句意。", "蚊子": "语义：蚊子是昆虫，不能作为公司的部门名称，句中说不通。", "月亮": "语义：月亮是天体，不能作为公司的部门名称，句中说不通。", "感冒": "语义：感冒是疾病，不能作为公司的部门名称。"}, "sentence_index": 6, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们中午吃了两个小时的商务。", "explanation": "这里应该用〈饭〉。商务指商业事务，不能作“吃”的对象，吃的应是饭。"}, {"text": "孩子们在院子里玩商务。", "explanation": "这里应该用〈游戏〉。商务指商业事务，不用来指孩子玩的游戏。"}, {"text": "商务笑了一整天。", "explanation": "这里应该用〈他〉。商务指商业事务，不能做“笑”的主语，应说“他笑了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他接了一个商务，下个月去上海。", "corrected_sentence": "他接了一项商务，下个月去上海。", "error_description": "量词错误：商务这类事务应说“一项商务”，“个”一般用于具体的人或物，不用于商务这类事务。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的商务谈判谈很顺利。", "corrected_sentence": "我们的商务谈判谈得很顺利。", "error_description": "补语错误：“谈”后接补语要用“得”引出，应说“谈得很顺利”，“谈很顺利”缺少“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
