INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指双方约定或偶然相遇，进行交谈或共同活动。", "primary_collocate": null, "pronunciation": "huì miàn", "ipa": "xweɪ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "会面", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "两位老板的会面安排在明天上午十点。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会面只谈了二十分钟，大家就走了。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理和客户的第一次会面很顺利。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的会面地点选在一家安静的茶馆。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年后的这次会面，让两位老人都哭了。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统和首相的会面持续了一个小时。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这次会面，他提前准备了很多资料。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会面结束后，两家公司签了合同。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的会面时间改到了下午三点。", "target_word": "会面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次会面", "label": "量词"}, {"form": "會面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会面：双方相遇并交谈或共同活动的一次事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会面", "is_correct": true, "explanation": "正确：“一场商务会面”指为商业事务而进行的见面，符合句子语境。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼与商务无关，“商务葬礼”不成立。"}, {"text": "演出", "is_correct": false, "explanation": "搭配：“商务”后接“演出”不自然，一般不说“商务演出”。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是私人仪式，与商务场景不符，句中不通。"}], "explanations": {"会面": "正确：“一场商务会面”指为商业事务而进行的见面，符合句子语境。", "葬礼": "语义：葬礼与商务无关，“商务葬礼”不成立。", "演出": "搭配：“商务”后接“演出”不自然，一般不说“商务演出”。", "婚礼": "语义：婚礼是私人仪式，与商务场景不符，句中不通。"}, "sentence_index": 0, "correct_answer": "会面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨晚在床上会面。", "explanation": "这里应该用〈睡觉〉。会面指双方见面，不指躺在床上休息。"}, {"text": "他把这块布会面了一下。", "explanation": "这里应该用〈缝〉。会面指人与人见面，不能用于缝布；缝布要用“缝”。"}, {"text": "我的电脑昨天会面了。", "explanation": "这里应该用〈坏〉。会面指人与人见面，不能用来说电脑出了故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会面", "is_correct": true, "explanation": "正确：“总统和首相的会面”指两人的见面，持续一个小时符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“持续了一个小时”不能用来描述感冒，二者不搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是场所，不是可以持续的事件，句中不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能作为持续事件的主语，句中不通。"}], "explanations": {"会面": "正确：“总统和首相的会面”指两人的见面，持续一个小时符合句意。", "感冒": "搭配：“持续了一个小时”不能用来描述感冒，二者不搭配。", "花园": "语义：花园是场所，不是可以持续的事件，句中不通。", "厨房": "语义：厨房是场所，不能作为持续事件的主语，句中不通。"}, "sentence_index": 6, "correct_answer": "会面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会面的颜色很漂亮。", "explanation": "这里应该用〈天空〉。会面指人与人见面，不指天空等物体的颜色。"}, {"text": "他用毛笔会面。", "explanation": "这里应该用〈写字〉。会面指见面，不能用毛笔进行，写字要用“写”。"}, {"text": "会面很亮。", "explanation": "这里应该用〈天〉。会面指两人见面，不能用来形容天色明亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们进行了一把很愉快的会面。", "corrected_sentence": "他们进行了一次很愉快的会面。", "error_description": "量词错误：“会面”计次用“次”，“把”用于有柄的器具，应说“进行了一次很愉快的会面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经会面着两次。", "corrected_sentence": "他们曾经会面过两次。", "error_description": "体貌错误：“着”表示动作持续，不能用于已经发生过的次数，应用“过”表示曾经发生过，说“会面过两次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事情突然发生，让人感到意外或难以应对。", "primary_collocate": null, "pronunciation": "tū rú qí lái", "ipa": "tʰu˥ ɻu˧˥ tɕʰi˧˥ laɪ˧˥", "syllable_count": 4, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "突如其来", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "突如其来的大雨让我们没带伞的人都湿透了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个突如其来的电话，让她吓了一跳。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的消息让大家都愣住了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对突如其来的变化，他一时不知道怎么办。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的停电，让教室一下子黑了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场突如其来的雨，把我们的计划都打乱了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的地震让全城的人都很害怕。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师突如其来的问题，让学生答不上来。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈突如其来的眼泪，让爸爸不知说什么好。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "突如其來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "突如其来：事情突然发生，令人意外、难以应对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突如其来", "is_correct": true, "explanation": "正确：突如其来形容事情突然发生、令人意外，与「家庭话题」突然出现、使会面延长的语境相符。"}, {"text": "循规蹈矩", "is_correct": false, "explanation": "搭配：「循规蹈矩」形容人守规矩，不能用来修饰话题。"}, {"text": "正式", "is_correct": false, "explanation": "搭配：「正式」多用于场合或文件，不宜修饰「家庭话题」。"}, {"text": "慢条斯理", "is_correct": false, "explanation": "语义：「慢条斯理」描写做事或说话不急不忙，与话题突然出现、打乱节奏的意思相悖。"}], "explanations": {"突如其来": "正确：突如其来形容事情突然发生、令人意外，与「家庭话题」突然出现、使会面延长的语境相符。", "循规蹈矩": "搭配：「循规蹈矩」形容人守规矩，不能用来修饰话题。", "正式": "搭配：「正式」多用于场合或文件，不宜修饰「家庭话题」。", "慢条斯理": "语义：「慢条斯理」描写做事或说话不急不忙，与话题突然出现、打乱节奏的意思相悖。"}, "sentence_index": 0, "correct_answer": "突如其来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们特意提前一周通知大家，这场突如其来的聚会很热闹。", "explanation": "这里应该用〈有计划〉。突如其来指事情毫无预告地发生，与「提前一周通知」相矛盾；事先安排好的活动应说有计划地进行。"}, {"text": "他把这份报告突如其来地一页一页写完了。", "explanation": "突如其来强调事情出乎意料地一下子发生，与「一页一页」逐步完成的过程相矛盾；表示逐步进行应用〈逐步〉。"}, {"text": "他是个突如其来的人，谁也猜不透他的想法。", "explanation": "突如其来只用来描述事情，不能形容人的性格；形容人行为难以捉摸应用〈古怪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突如其来", "is_correct": true, "explanation": "正确：突如其来说明雨来得突然，符合「打乱计划」的语境。"}, {"text": "悠闲", "is_correct": false, "explanation": "搭配：「悠闲」形容人的神态，不能修饰雨。"}, {"text": "慢吞吞", "is_correct": false, "explanation": "搭配：「慢吞吞」形容动作或人的速度，不能用来修饰雨。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：「晴朗」指天气好、无雨，与「雨」自相矛盾。"}], "explanations": {"突如其来": "正确：突如其来说明雨来得突然，符合「打乱计划」的语境。", "悠闲": "搭配：「悠闲」形容人的神态，不能修饰雨。", "慢吞吞": "搭配：「慢吞吞」形容动作或人的速度，不能用来修饰雨。", "晴朗": "语义：「晴朗」指天气好、无雨，与「雨」自相矛盾。"}, "sentence_index": 6, "correct_answer": "突如其来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都突如其来地哭一场。", "explanation": "突如其来指一次性出乎意料地发生，不能用于「每天都」这样反复出现的情况；表示经常、反复应用〈常常〉。"}, {"text": "这座城市突如其来地很美丽。", "explanation": "这里应该用〈一直〉。突如其来描述事情突然发生，不能修饰表示长期性质的「美丽」；表示一直如此应用〈一直〉。"}, {"text": "他把这件事想了很久，才突如其来地做出决定。", "explanation": "这里应该用〈慎重〉。突如其来指事情猝然发生、毫无准备，与「想了很久」的深思熟虑相矛盾；经过考虑的决定应说〈慎重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场突如其来地大风，把晾着的衣服都吹到了地上。", "corrected_sentence": "这场突如其来的大风，把晾着的衣服都吹到了地上。", "error_description": "错误：「突如其来地大风」；正确：「突如其来的大风」。突如其来修饰名词时要用「的」，「地」只用于动词前作状语，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里突如其来敲门声吓醒了整个宿舍。", "corrected_sentence": "夜里突如其来的敲门声吓醒了整个宿舍。", "error_description": "错误：「突如其来敲门声」；正确：「突如其来的敲门声」。突如其来修饰名词时，中间要加「的」，漏掉「的」不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
