INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话题是指谈话或讨论的主题。", "primary_collocate": null, "pronunciation": "huà tí", "ipa": "xwa˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "话题", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天气是人们见面时常说的话题。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天大家讨论的话题是环保。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们聊了很久，话题从工作转到了孩子。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题太难了，我不想多说。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢的话题是足球和历史。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影成了同学们最近的热门话题。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了一个话题，不再说考试的事。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，老师提出了一个新话题。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有共同话题，所以聊不下去。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个话题", "label": "量词"}, {"form": "热门话题", "label": "复合"}, {"form": "話題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "话题：谈话或讨论所围绕的主题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f195968-6b0c-4b2a-8e22-a822d564ee90') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话题", "is_correct": true, "explanation": "正确：「家庭话题」指家里人谈论的内容，突然出现的话题使会面延长，符合句意。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：「家庭木材」不成词，木材不能作为谈论的内容。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：「节拍」指节奏，不能成为使会面延长的谈论内容。"}, {"text": "证件", "is_correct": false, "explanation": "搭配：「证件」是证明身份的文件，不能与「家庭」构成可谈论的内容。"}], "explanations": {"话题": "正确：「家庭话题」指家里人谈论的内容，突然出现的话题使会面延长，符合句意。", "木材": "搭配：「家庭木材」不成词，木材不能作为谈论的内容。", "节拍": "语义：「节拍」指节奏，不能成为使会面延长的谈论内容。", "证件": "搭配：「证件」是证明身份的文件，不能与「家庭」构成可谈论的内容。"}, "sentence_index": 0, "correct_answer": "话题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有一个话题要解决，需要大家一起想办法。", "explanation": "这里应该用〈问题〉。话题指谈论的主题，不能说「解决」；要解决的事应用〈问题〉。"}, {"text": "这个话题的价钱很便宜，我们都买得起。", "explanation": "话题不是商品，没有价钱，这里应指〈商品〉，与「买得起」的语义不合。"}, {"text": "他一边聊天，一边打听这个话题的地址。", "explanation": "话题是抽象的谈论内容，没有地址；询问位置应指〈地点〉，这里与话题的语义不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话题", "is_correct": true, "explanation": "正确：「热门话题」指大家都在谈论的内容，符合「新电影成了……」的语境。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：「饮料」不能是大家谈论的对象，「热门饮料」与电影的语境矛盾。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：「座位」不能与「新电影」的热门程度相搭配。"}, {"text": "零食", "is_correct": false, "explanation": "语义：「零食」指小吃，句中指的是电影被大家议论，不符合语义。"}], "explanations": {"话题": "正确：「热门话题」指大家都在谈论的内容，符合「新电影成了……」的语境。", "饮料": "语义：「饮料」不能是大家谈论的对象，「热门饮料」与电影的语境矛盾。", "座位": "搭配：「座位」不能与「新电影」的热门程度相搭配。", "零食": "语义：「零食」指小吃，句中指的是电影被大家议论，不符合语义。"}, "sentence_index": 6, "correct_answer": "话题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个话题的颜色很漂亮，我们都很喜欢它。", "explanation": "话题是抽象的谈论内容，没有颜色；描述颜色应指〈物品〉，这里与话题的语义不合。"}, {"text": "我们把这个话题搬进了教室。", "explanation": "这里应该用〈讨论〉，并改掉「搬进」。话题是抽象的谈论内容，不能当作物品搬进教室；可改为「我们在教室里讨论这个话题」。"}, {"text": "我被这个话题骗了。", "explanation": "话题不会有意欺骗人，「骗」的主体应是人；这里应说〈误导〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一提起这张话题，大家就都笑了。", "corrected_sentence": "他一提起这个话题，大家就都笑了。", "error_description": "错误：「这张话题」；正确：「这个话题」。话题用量词「个」，不用「张」，「张」多用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一聊起这些话题们，就停不下来。", "corrected_sentence": "大家一聊起这些话题，就停不下来。", "error_description": "错误：「话题们」；正确：「话题」。「们」一般只加在指人的名词或代词后，话题不指人，不能加「们」；表示多个时用「这些」等数量词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f7505f7-c7aa-4e1c-be2a-f731873138c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩短", "is_correct": true, "explanation": "正确。缩短与延长在时间或长度上意思相反，是反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "保持指维持原状，与延长没有反义关系。"}, {"text": "固定", "is_correct": false, "explanation": "固定指使不变动，与延长不构成反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停下来歇一歇，不是延长的反义词。"}], "correct_answer": "缩短", "explanations": {"缩短": "正确。缩短与延长在时间或长度上意思相反，是反义关系。", "保持": "保持指维持原状，与延长没有反义关系。", "固定": "固定指使不变动，与延长不构成反义关系。", "休息": "休息指停下来歇一歇，不是延长的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩短", "is_correct": true, "explanation": "正确。缩短与延长在时间或长度上意思相反，是反义关系。"}, {"text": "维护", "is_correct": false, "explanation": "维护指保护使其完好，与延长没有反义关系。"}, {"text": "确认", "is_correct": false, "explanation": "确认指确定是真实的，与延长不构成反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理指使东西有秩序，与延长不是反义词。"}], "correct_answer": "缩短", "explanations": {"缩短": "正确。缩短与延长在时间或长度上意思相反，是反义关系。", "维护": "维护指保护使其完好，与延长没有反义关系。", "确认": "确认指确定是真实的，与延长不构成反义关系。", "整理": "整理指使东西有秩序，与延长不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "意思是增加时间或空间上的长度。", "primary_collocate": null, "pronunciation": "yán cháng", "ipa": "jɛn˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "延长", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "因为下大雨，比赛的时间延长了半个小时。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把假期延长到下个星期一。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店周末延长营业时间。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们把作文的交稿日期延长两天。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要把这条地铁线向北延长五公里。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说多运动能延长寿命。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议太重要了，经理把会议延长了一小时。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条跑道太短，要延长两百米。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保存食物时放进冰箱，可以延长保质期。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延长了", "label": "完成体"}, {"form": "延长过", "label": "经历体"}, {"form": "延长线", "label": "复合词"}], "register": "中性", "sense_fingerprint": "延长：增加时间或空间上的长度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。延长 yán cháng：增加时间或空间上的长度。"}, {"text": "绵长", "is_correct": false, "explanation": "mián（第二声）与 yán 声母不同（m/y），绵长意思是长而连续，不表示增加长度。"}, {"text": "羊肠", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。"}, {"text": "扬长", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。"}, {"text": "檐廊", "is_correct": false, "explanation": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}], "explanations": {"延长": "正确。延长 yán cháng：增加时间或空间上的长度。", "绵长": "mián（第二声）与 yán 声母不同（m/y），绵长意思是长而连续，不表示增加长度。", "羊肠": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。", "扬长": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。", "檐廊": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}, "sentence_index": null, "correct_answer": "延长"}, "level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“可能因一场家庭话题而延长”与后文“迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分”前后呼应。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消”指不再进行，与后文“迟到十分钟并不构成冒犯”所说会面仍在进行相矛盾。"}, {"text": "收缩", "is_correct": false, "explanation": "语义：“收缩”指变短、变小，与“自然延展”的方向相反。"}, {"text": "删减", "is_correct": false, "explanation": "搭配：“删减”多用于内容、篇幅、预算，不用于会面的时长。"}], "explanations": {"延长": "正确。“可能因一场家庭话题而延长”与后文“迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分”前后呼应。", "取消": "语义：“取消”指不再进行，与后文“迟到十分钟并不构成冒犯”所说会面仍在进行相矛盾。", "收缩": "语义：“收缩”指变短、变小，与“自然延展”的方向相反。", "删减": "搭配：“删减”多用于内容、篇幅、预算，不用于会面的时长。"}, "sentence_index": 0, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的房租延长了两成。", "explanation": "这里应该用〈提高〉。延长指时间或长度的增加，房租等价格的上涨要用提高。"}, {"text": "我这个月的体重延长了三公斤。", "explanation": "这里应该用〈增加〉。延长只用于时间或长度，体重等数量的增加要用增加。"}, {"text": "工厂把生产规模延长了一倍。", "explanation": "这里应该用〈扩大〉。延长针对时间或长度，生产规模等范围的增大要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“多运动能延长寿命”是常见的健康说法。"}, {"text": "缩短", "is_correct": false, "explanation": "语义：“多运动能缩短寿命”与“多运动能……”的好处正相反。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少寿命”说不通，多运动不会减少寿命。"}, {"text": "增进", "is_correct": false, "explanation": "搭配：“增进”多搭配健康、感情、了解，不说“增进寿命”。"}], "explanations": {"延长": "正确。“多运动能延长寿命”是常见的健康说法。", "缩短": "语义：“多运动能缩短寿命”与“多运动能……”的好处正相反。", "减少": "语义：“减少寿命”说不通，多运动不会减少寿命。", "增进": "搭配：“增进”多搭配健康、感情、了解，不说“增进寿命”。"}, "sentence_index": 6, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训延长了员工的技能。", "explanation": "这里应该用〈提升〉。延长指时间或长度，员工技能等能力的提高要用提升。"}, {"text": "运动延长了身体的免疫力。", "explanation": "这里应该用〈增强〉。免疫力等能力的加强要用增强，延长只用于时间或长度。"}, {"text": "冬天的寒流让气温延长了五度。", "explanation": "这里应该用〈降低〉。气温的下降要用降低，延长只用于时间或长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校决定把寒假延长二月底。", "corrected_sentence": "学校决定把寒假延长到二月底。", "error_description": "错误：“延长”后面漏了“到”。表示延长后的终点要用“延长到……”引出，不能直接接时间词，应为“延长到二月底”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂被生产线向东延长了三公里。", "corrected_sentence": "工厂把生产线向东延长了三公里。", "error_description": "语态错误：“被”使“工厂”成为被延长的对象，语义颠倒；应用“把”引出“生产线”，说“工厂把生产线向东延长了三公里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
