INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说或做让某人不开心、觉得不被尊重的事。", "primary_collocate": null, "pronunciation": "mào fàn", "ipa": "maʊ˥˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "冒犯", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "对不起，我不是故意冒犯你的。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在别人家里随便翻东西，会冒犯主人。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话太直，常常冒犯同事。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问女士的年龄可能会冒犯她。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是开玩笑，没有冒犯您的意思。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人大声说话，会冒犯他们。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话冒犯了在场的客人。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道这个习惯，结果冒犯了朋友。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在会议上打断别人说话，容易冒犯对方。", "target_word": "冒犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冒犯了", "label": "完成体"}, {"form": "冒犯过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "冒犯：言行让人觉得不被尊重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冒犯", "is_correct": true, "explanation": "正确。“构成冒犯”指迟到不会让人觉得不被尊重。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“构成”后接的须是性质或行为，“时间”不能被“构成”，句意不通。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”是冷热程度，不能被“构成”，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被“构成”，与“迟到”的评价无关，句意不通。"}], "explanations": {"冒犯": "正确。“构成冒犯”指迟到不会让人觉得不被尊重。", "时间": "语义：“构成”后接的须是性质或行为，“时间”不能被“构成”，句意不通。", "温度": "语义：“温度”是冷热程度，不能被“构成”，句意不通。", "天气": "语义：“天气”不能被“构成”，与“迟到”的评价无关，句意不通。"}, "sentence_index": 0, "correct_answer": "冒犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我冒犯了好成绩。", "explanation": "这里应该用〈取得〉。冒犯的对象只能是人，好成绩要用取得。"}, {"text": "我们在海边冒犯了很好的天气。", "explanation": "这里应该用〈享受〉。冒犯的对象是人，天气不能被冒犯，好天气要用享受。"}, {"text": "我的电话冒犯了同事的工作。", "explanation": "这里应该用〈打扰〉。冒犯指言行让人不快，干扰别人的工作要用打扰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒犯", "is_correct": true, "explanation": "正确。大声跟老人说话会让他们不舒服，甚至觉得不被尊重，这正是“冒犯”。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”表示敬重，与“大声说话”的语境不符。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”表示关心、帮助，与“大声说话”的语境相矛盾。"}, {"text": "理睬", "is_correct": false, "explanation": "搭配：“理睬”多用于回应别人的话或请求，不用于说明言行的后果。"}], "explanations": {"冒犯": "正确。大声跟老人说话会让他们不舒服，甚至觉得不被尊重，这正是“冒犯”。", "尊重": "语义：“尊重”表示敬重，与“大声说话”的语境不符。", "照顾": "语义：“照顾”表示关心、帮助，与“大声说话”的语境相矛盾。", "理睬": "搭配：“理睬”多用于回应别人的话或请求，不用于说明言行的后果。"}, "sentence_index": 6, "correct_answer": "冒犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他冒犯了老师的期望。", "explanation": "这里应该用〈辜负〉。冒犯指得罪人，没有达到别人的期望要用辜负。"}, {"text": "我们冒犯了三个小时。", "explanation": "这里应该用〈等待〉。冒犯的对象是人，表示时间的过去要用等待。"}, {"text": "他冒犯了交通规则。", "explanation": "这里应该用〈违反〉。冒犯针对人的感受，违反规则要用违反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的话冒犯了着老师，老师很不高兴。", "corrected_sentence": "他的话冒犯了老师，老师很不高兴。", "error_description": "错误：动态助词“了”与“着”不能叠用，应只用“了”，去掉“着”，应为“冒犯了老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不小心冒犯着一位老人。", "corrected_sentence": "我不小心冒犯了一位老人。", "error_description": "错误：“冒犯”是一次性完成的动作，应与表示完成的动态助词“了”搭配，不能用表示持续的“着”。应为“冒犯了一位老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
