INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活节奏指人们在日常生活中活动、工作和休息的速度与规律，有快有慢。", "primary_collocate": null, "pronunciation": "shēng huó jié zòu", "ipa": "ʂɤŋ˥ xuɔ˧˥ tɕjɛ˧˥ tsoʊ˥˩", "syllable_count": 4, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "生活节奏", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "大城市的生活节奏很快，人们总是匆匆忙忙。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，爷爷的生活节奏慢了下来。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚到这里，还不适应这里的生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇的生活节奏很慢，大家喜欢聊天喝茶。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想放慢生活节奏，每天早睡早起。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出生后，我们的生活节奏全变了。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅行让我换了一种生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加班太多会打乱你的生活节奏。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们不用赶时间，生活节奏轻松多了。", "target_word": "生活节奏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活节奏：日常活动、工作、休息的速度与规律", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活节奏", "is_correct": true, "explanation": "正确：生活节奏指日常活动的快慢和规律，与“自然延展”相配。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的温度，不能“自然延展”，句意不通。"}, {"text": "会议室", "is_correct": false, "explanation": "语义：会议室是场所，没有快慢规律，不能“延展”。"}, {"text": "商务礼仪", "is_correct": false, "explanation": "语义：礼仪是行为规范，不存在“自然延展”的说法，句意不通。"}], "explanations": {"生活节奏": "正确：生活节奏指日常活动的快慢和规律，与“自然延展”相配。", "体温": "语义：“体温”是身体的温度，不能“自然延展”，句意不通。", "会议室": "语义：会议室是场所，没有快慢规律，不能“延展”。", "商务礼仪": "语义：礼仪是行为规范，不存在“自然延展”的说法，句意不通。"}, "sentence_index": 0, "correct_answer": "生活节奏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的舞蹈很有生活节奏，每个动作都很有力量。", "explanation": "这里应该用〈节奏感〉。节奏感指音乐或舞蹈的节拍感；生活节奏指人日常活动的快慢规律，不用来形容舞蹈。"}, {"text": "这首歌的生活节奏很快，听起来很激动。", "explanation": "这里应该用〈节拍〉。节拍指音乐的拍子，生活节奏指人日常做事的快慢规律，不能用来形容歌曲。"}, {"text": "他迈着稳健的生活节奏走进会场。", "explanation": "这里应该用〈步伐〉。步伐指走路的脚步；生活节奏是日常活动的快慢规律，不能用来描述走路的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活节奏", "is_correct": true, "explanation": "正确：“全变了”指日常节奏随孩子出生而改变，与句意吻合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体形特征，孩子出生后不会全部改变。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，孩子出生不会让它全变。"}, {"text": "血型", "is_correct": false, "explanation": "语义：血型是遗传的生理特征，不会因孩子出生而变。"}], "explanations": {"生活节奏": "正确：“全变了”指日常节奏随孩子出生而改变，与句意吻合。", "身高": "体貌：身高是人的体形特征，孩子出生后不会全部改变。", "学历": "语义：学历指受教育的程度，孩子出生不会让它全变。", "血型": "语义：血型是遗传的生理特征，不会因孩子出生而变。"}, "sentence_index": 6, "correct_answer": "生活节奏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这个月的生活节奏增加了三公斤。", "explanation": "这里应该用〈体重〉。体重指人身体的重量，可以说“增加了三公斤”；生活节奏是日常活动的快慢规律，不能用公斤计量。"}, {"text": "每个月的生活节奏只剩下两百块。", "explanation": "这里应该用〈生活费〉。生活费是日常开销的钱，可以说“只剩下两百块”；生活节奏不是钱，不能这样说。"}, {"text": "这次考试的生活节奏很大。", "explanation": "这里应该用〈难度〉。难度指题目的难易程度，可以说“很大”；生活节奏不能用来描述考试的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快就适合了城市的生活节奏。", "corrected_sentence": "他很快就适应了城市的生活节奏。", "error_description": "动词错误：说人对生活节奏的适应应用“适应”，“适合”指东西符合某种需要或条件，不能用来说人适应生活节奏。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们喜欢轻松地生活节奏。", "corrected_sentence": "他们喜欢轻松的生活节奏。", "error_description": "结构助词错误：形容词“轻松”修饰名词“生活节奏”时应用“的”，不能用“地”，应为“轻松的生活节奏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
