INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "伸展；扩大；延伸。", "primary_collocate": null, "pronunciation": "yán zhǎn", "ipa": "jɛn˧˥ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "一场商务会面可能因一场突如其来的家庭话题而延长，迟到十分钟并不构成冒犯，反而是生活节奏自然延展的一部分。", "target_word": "延展", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条小路一直延展到山脚下。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠向远方延展，看不到边。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山脉向北延展到了草原。", "target_word": "延展", "complexity_tier": "T3", "furigana": "zhè zuò shān mài xiàng běi yán zhǎn dào le cǎo yuán", "sentence_source": "generated"}, {"text": "铁路从城里延展到海边。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草地向两边延展开去。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火势延展到了河对岸。", "target_word": "延展", "complexity_tier": "T3", "furigana": "huǒ shì yán zhǎn dào le hé duì àn", "sentence_source": "generated"}, {"text": "远处的山脉延展着，像一条长龙。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市正向东边延展。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片森林一直延展到了湖边。", "target_word": "延展", "complexity_tier": "T3", "furigana": "zhè piàn sēn lín yì zhí yán zhǎn dào le hú biān", "sentence_source": "generated"}], "morphological_forms": [{"form": "延展了", "label": "体标（了）"}, {"form": "延展着", "label": "体标（着）"}, {"form": "延展过", "label": "体标（过）"}, {"form": "延展性", "label": "复合"}], "register": "书面", "sense_fingerprint": "空间向远处伸展、延伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d9bb8a0-2fb4-492b-b06f-f728b9c20361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“自然延展的一部分”指生活节奏自然地向外伸展，前文说迟到是正常节奏的延伸。"}, {"text": "中断", "is_correct": false, "explanation": "语义：“中断”是停止、断开，与句中“反而是…的一部分”所说的正常节奏相矛盾。"}, {"text": "压缩", "is_correct": false, "explanation": "搭配：“压缩”多用于篇幅、时间、开支，不说生活节奏被压缩成某个部分。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指不动、不前进，句中强调节奏的自然推进，不能说停滞的一部分。"}], "explanations": {"延展": "正确。“自然延展的一部分”指生活节奏自然地向外伸展，前文说迟到是正常节奏的延伸。", "中断": "语义：“中断”是停止、断开，与句中“反而是…的一部分”所说的正常节奏相矛盾。", "压缩": "搭配：“压缩”多用于篇幅、时间、开支，不说生活节奏被压缩成某个部分。", "停滞": "语义：“停滞”指不动、不前进，句中强调节奏的自然推进，不能说停滞的一部分。"}, "sentence_index": 0, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议原定两小时，现在延展了一小时。", "explanation": "这里应该用〈延长〉。延展指空间或范围向外伸展，时间的增加要用延长。"}, {"text": "这座城市的人口延展了三成。", "explanation": "这里应该用〈增加〉。人口、数量的增长要用增加，延展指空间的伸展，不说人口延展。"}, {"text": "这次长谈让两人的情谊延展了不少。", "explanation": "这里应该用〈加深〉。情谊、感情的深化要用加深，延展指空间或范围的伸展，不用于描述情谊的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9131968b-50ad-44ae-aaf8-39f2098b163a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“火势延展到了河对岸”指火势向外伸展，与句意一致。"}, {"text": "收缩", "is_correct": false, "explanation": "语义：“收缩”指缩小，火势不能收缩到河对岸，与句中向外伸展的意思相反。"}, {"text": "退", "is_correct": false, "explanation": "语义：“退”是后退、撤回，与火势向对岸扩展的方向相反，句子意思不通。"}, {"text": "冻结", "is_correct": false, "explanation": "搭配：“冻结”多用于水流、资金等，不说火势冻结到河对岸。"}], "explanations": {"延展": "正确。“火势延展到了河对岸”指火势向外伸展，与句意一致。", "收缩": "语义：“收缩”指缩小，火势不能收缩到河对岸，与句中向外伸展的意思相反。", "退": "语义：“退”是后退、撤回，与火势向对岸扩展的方向相反，句子意思不通。", "冻结": "搭配：“冻结”多用于水流、资金等，不说火势冻结到河对岸。"}, "sentence_index": 6, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语水平延展得很快。", "explanation": "这里应该用〈提高〉。水平、能力的上升要用提高，延展用于空间或范围的伸展。"}, {"text": "他用刀把这块布延展成了几段。", "explanation": "这里应该用〈切开〉。把布切成几段要用切开，延展指物体拉长或展开，不表示分割。"}, {"text": "这家图书馆的藏书延展到了五万册。", "explanation": "这里应该用〈扩充〉。藏书、内容的增添要用扩充，延展指空间向外伸展，不说数量延展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9131968b-50ad-44ae-aaf8-39f2098b163a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草原向西延展河边。", "corrected_sentence": "这片草原向西延展到河边。", "error_description": "错误：“延展河边”，正确：“延展到河边”。“延展”后要接表示终点的“到”，漏掉“到”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9131968b-50ad-44ae-aaf8-39f2098b163a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市向东延展很远。", "corrected_sentence": "这座城市向东延展得很远。", "error_description": "错误：“延展很远”，正确：“延展得很远”。“延展”后接表示程度的补语，要用“得”连接，漏掉“得”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9131968b-50ad-44ae-aaf8-39f2098b163a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
