INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物、行为或人身上的小缺点或小毛病。", "primary_collocate": null, "pronunciation": "xiá cī", "ipa": "ɕjä˧˥ tsʰɨ˥", "syllable_count": 2, "sentences": [{"text": "在这些文化语境中，守时性并非道德瑕疵，而是被重新定义为“情境依存”的行为。", "target_word": "瑕疵", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这篇文章有一个小瑕疵。", "target_word": "瑕疵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的计划几乎没有瑕疵。", "target_word": "瑕疵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一点小瑕疵不影响整体效果。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她总是盯着别人的瑕疵。", "target_word": "瑕疵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方案的最大瑕疵是时间太短。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师指出了我作文里的几处瑕疵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再好的人也会有一些小瑕疵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然有瑕疵，但整个故事很感人。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先找出合同里的瑕疵，再签字。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处瑕疵", "label": "量词"}, {"form": "瑕疵品", "label": "复合"}], "register": "书面", "sense_fingerprint": "瑕疵：事物、行为或人身上的小缺点、小毛病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瑕疵", "is_correct": true, "explanation": "正确：“道德瑕疵”指品行上的小缺点，与“并非”形成对照，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“道德”修饰行为或品质，不修饰价格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与道德评价无关，不能说道德天气。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于道德评价的范围，句意不通。"}], "explanations": {"瑕疵": "正确：“道德瑕疵”指品行上的小缺点，与“并非”形成对照，句意通顺。", "价格": "搭配：“道德”修饰行为或品质，不修饰价格。", "天气": "语义：天气与道德评价无关，不能说道德天气。", "颜色": "语义：颜色不属于道德评价的范围，句意不通。"}, "sentence_index": 0, "correct_answer": "瑕疵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话的瑕疵很快，大家都跟不上。", "explanation": "这里应该用〈语速〉。语速指说话的快慢，可以说“很快”；瑕疵是东西上的小缺点，不能用来形容说话的快慢。"}, {"text": "他的瑕疵偏低，要多补充营养。", "explanation": "这里应该用〈血压〉。血压指血液对血管壁的压力，可以说“偏低”；瑕疵不能用来说人的血压。"}, {"text": "屋里的瑕疵太低了，我们多穿了一件衣服。", "explanation": "这里应该用〈温度〉。温度指冷热程度，可以说“太低”；瑕疵是小缺点，不能用来描述屋里的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瑕疵", "is_correct": true, "explanation": "正确：“几处瑕疵”指作文里的小毛病，与“指出”搭配，句意通顺。"}, {"text": "字数", "is_correct": false, "explanation": "搭配：“几处”计量位置，字数不能用“处”来数。"}, {"text": "灯光", "is_correct": false, "explanation": "语义：作文里没有可以“指出几处灯光”的内容，句意不通。"}, {"text": "节拍", "is_correct": false, "explanation": "语义：节拍是音乐的拍子，作文中不存在可以指出的节拍。"}], "explanations": {"瑕疵": "正确：“几处瑕疵”指作文里的小毛病，与“指出”搭配，句意通顺。", "字数": "搭配：“几处”计量位置，字数不能用“处”来数。", "灯光": "语义：作文里没有可以“指出几处灯光”的内容，句意不通。", "节拍": "语义：节拍是音乐的拍子，作文中不存在可以指出的节拍。"}, "sentence_index": 6, "correct_answer": "瑕疵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座工地昨天发生了一起瑕疵，幸好没有人受伤。", "explanation": "这里应该用〈事故〉。“发生”搭配事故；瑕疵指物品或工作上的小缺陷，不能“发生”。"}, {"text": "他在比赛中犯了一个瑕疵，最后输掉了比赛。", "explanation": "这里应该用〈失误〉。“犯”搭配错误、失误；瑕疵是小缺陷，不能“犯”。"}, {"text": "医生说他得了一种瑕疵，需要住院治疗。", "explanation": "这里应该用〈疾病〉。“得”搭配疾病；瑕疵不是病，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章有很多瑕疵们，需要修改。", "corrected_sentence": "这篇文章有很多瑕疵，需要修改。", "error_description": "词尾错误：“瑕疵”是抽象名词，不能加“们”表示复数；应说“很多瑕疵”，不说“瑕疵们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这面墙上有一位小瑕疵，需要补漆。", "corrected_sentence": "这面墙上有一处小瑕疵，需要补漆。", "error_description": "量词错误：“位”只用于人，“瑕疵”应用量词“处”，说“一处小瑕疵”，不能用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
