INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11019, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情境指在某个时间、地点或条件下，人物所处的具体环境或状态。", "primary_collocate": null, "pronunciation": "qíng jìng", "ipa": "tɕʰiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在这些文化语境中，守时性并非道德瑕疵，而是被重新定义为“情境依存”的行为。", "target_word": "情境", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请根据情境选择合适的说法。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在购物情境中，我们常用这些句子。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一句话在不同情境里，意思可能不同。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生想象一个餐厅情境，然后表演对话。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看情境再决定要不要打招呼。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个情境发生在一个下雨的晚上。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快就适应了新的工作情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试情境让她特别紧张。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本里的图画给出了每个对话的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要看情境，开玩笑也要分场合。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "书面语", "sense_fingerprint": "特定时间、地点或条件下人所处的具体环境与状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '397a99f4-7813-4bc2-8e8d-66e04969afa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11019, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "情境", "is_correct": true, "explanation": "情境：此处指判断守时是否失礼所依托的具体条件，与“具体”搭配。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮品，不能作为判断守时是否失礼的依据。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件是书面材料，不能作为判断守时是否失礼的依据。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，与判断守时是否失礼的依据无关。"}], "explanations": {"情境": "情境：此处指判断守时是否失礼所依托的具体条件，与“具体”搭配。", "咖啡": "语义：咖啡是饮品，不能作为判断守时是否失礼的依据。", "文件": "语义：文件是书面材料，不能作为判断守时是否失礼的依据。", "雨伞": "语义：雨伞是物品，与判断守时是否失礼的依据无关。"}, "sentence_index": 0, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的情境很潮湿。", "explanation": "这里应该用〈气候〉。气候指一地长期的天气状况，情境不能用来形容地区的湿度。"}, {"text": "这件衣服的情境很时尚。", "explanation": "这里应该用〈款式〉。款式指衣服的样式，情境指人所处的环境或状态，不能用来形容衣服的样子。"}, {"text": "这本书的情境很贵。", "explanation": "这里应该用〈价格〉。价格指商品的售价，情境指人所处的环境或状态，不能用来说书的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11019, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "情境", "is_correct": true, "explanation": "情境：此处指事件发生时的具体条件，与“发生在一个下雨的晚上”相合。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的物品，不能“发生”在某个晚上。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴用品，不是可以“发生”的事情。"}, {"text": "大玩意儿", "is_correct": false, "explanation": "语义：“大玩意儿”指大型物件，不能“发生”在某个晚上；且语域偏口语。"}], "explanations": {"情境": "情境：此处指事件发生时的具体条件，与“发生在一个下雨的晚上”相合。", "钱包": "语义：钱包是装钱的物品，不能“发生”在某个晚上。", "手套": "语义：手套是穿戴用品，不是可以“发生”的事情。", "大玩意儿": "语义：“大玩意儿”指大型物件，不能“发生”在某个晚上；且语域偏口语。"}, "sentence_index": 6, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的情境很硬。", "explanation": "这里应该用〈口感〉。口感指食物吃起来的软硬和质地，情境指人所处的环境或状态，不能用来形容蛋糕的软硬。"}, {"text": "我们买了一个新的情境，放在客厅里。", "explanation": "这里应该用〈沙发〉。沙发是供人坐的家具，情境指人所处的环境或状态，不是可以买来放在客厅的东西。"}, {"text": "这个冰箱的情境能装很多东西。", "explanation": "这里应该用〈容量〉。容量指能盛放的多少，情境指人所处的环境或状态，不能用来说冰箱能装多少东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11019, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司给他安排了一场陌生的工作情境。", "corrected_sentence": "公司给他安排了一个陌生的工作情境。", "error_description": "量词错误。“场”多用于比赛、演出等事件，不能用来修饰“情境”。此处应说“一个陌生的工作情境”，用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11019, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前经历着这种情境。", "corrected_sentence": "他以前经历过这种情境。", "error_description": "体貌错误。“以前”指已经完成的经历，应用“过”，说“经历过这种情境”；“着”表示动作持续，与“以前”不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aba9b977-9c6a-4780-927e-2733c92d52a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。“独立”与“依存”意思相反，指不依赖他人或他物而存在。"}, {"text": "寻找", "is_correct": false, "explanation": "无关：“寻找”指去找东西或人，与相互依赖没有对立关系。"}, {"text": "制造", "is_correct": false, "explanation": "无关：“制造”指做出产品或东西，与相互依赖没有对立关系。"}, {"text": "拜访", "is_correct": false, "explanation": "无关：“拜访”指去看望别人，与相互依赖没有对立关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确。“独立”与“依存”意思相反，指不依赖他人或他物而存在。", "寻找": "无关：“寻找”指去找东西或人，与相互依赖没有对立关系。", "制造": "无关：“制造”指做出产品或东西，与相互依赖没有对立关系。", "拜访": "无关：“拜访”指去看望别人，与相互依赖没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。“独立”与“依存”意思相反，指不依赖他人或他物而存在。"}, {"text": "挑选", "is_correct": false, "explanation": "无关：“挑选”指选择，与相互依赖没有对立关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”指修复损坏的东西，与相互依赖没有对立关系。"}, {"text": "翻译", "is_correct": false, "explanation": "无关：“翻译”指转换语言，与相互依赖没有对立关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确。“独立”与“依存”意思相反，指不依赖他人或他物而存在。", "挑选": "无关：“挑选”指选择，与相互依赖没有对立关系。", "修理": "无关：“修理”指修复损坏的东西，与相互依赖没有对立关系。", "翻译": "无关：“翻译”指转换语言，与相互依赖没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指相互依赖、依靠对方才能存在或发展。", "primary_collocate": null, "pronunciation": "yī cún", "ipa": "i˥ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "在这些文化语境中，守时性并非道德瑕疵，而是被重新定义为与情境相互依存的行为。", "target_word": "依存", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "人和自然相互依存。", "target_word": "依存", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两家公司互相依存，谁也离不开谁。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "动物和植物之间的依存关系很密切。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些小鱼依存于珊瑚生活。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市和农村在经济上相互依存。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国经济的依存程度越来越高。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林和河流互相依存着，缺一不可。", "target_word": "依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司与客户之间是一种依存关系。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们像两棵树，根连着根，彼此依存。", "target_word": "依存", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "依存着", "label": "体标"}, {"form": "相互依存", "label": "复合"}, {"form": "依存关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "依存：双方相互依赖，彼此靠对方才能存在或发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。依存（yī cún）：双方相互依赖，彼此靠对方才能存在或发展。"}, {"text": "一群", "is_correct": false, "explanation": "q 与 c 声母不同（qún / cún），意思是一群，不是依存。"}, {"text": "一寸", "is_correct": false, "explanation": "cùn 与 cún 声调不同，意思是一寸长度，与“依存”不同。"}, {"text": "遗存", "is_correct": false, "explanation": "yí 与 yī 声调不同（yí cún），意思是遗留下来的东西，与“依存”不同。"}, {"text": "一村", "is_correct": false, "explanation": "cūn 与 cún 声调不同，指一个村子，与“依存”不同。"}], "explanations": {"依存": "正确。依存（yī cún）：双方相互依赖，彼此靠对方才能存在或发展。", "一群": "q 与 c 声母不同（qún / cún），意思是一群，不是依存。", "一寸": "cùn 与 cún 声调不同，意思是一寸长度，与“依存”不同。", "遗存": "yí 与 yī 声调不同（yí cún），意思是遗留下来的东西，与“依存”不同。", "一村": "cūn 与 cún 声调不同，指一个村子，与“依存”不同。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。“与情境相互依存”指行为与情境彼此依赖，符合“依存”相互依赖的意思。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，不能表示行为与情境之间的依赖关系。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”指身体发热，与“情境”和“行为”的定义无关，句子不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”是日常活动，不能表示行为与情境之间的相互关系，句子不通。"}], "explanations": {"依存": "正确。“与情境相互依存”指行为与情境彼此依赖，符合“依存”相互依赖的意思。", "讨厌": "语义：“讨厌”表示厌恶，不能表示行为与情境之间的依赖关系。", "发烧": "语义：“发烧”指身体发热，与“情境”和“行为”的定义无关，句子不通。", "吃饭": "语义：“吃饭”是日常活动，不能表示行为与情境之间的相互关系，句子不通。"}, "sentence_index": 0, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依存于母亲的怀里，撒娇地不肯起来。", "explanation": "这里应该用〈依偎〉（依偎在母亲怀里）。依存指生存上相互依赖，不表示身体亲昵地靠近。"}, {"text": "这棵藤蔓依存在墙上，慢慢往上爬。", "explanation": "这里应该用〈依附〉（依附在墙上）。依存强调相互依赖的生存关系，不表示植物攀附在物体上。"}, {"text": "他依存于规定办事，从不擅自做主。", "explanation": "这里应该用〈依照〉（依照规定办事）。依存表示相互依赖，不表示遵照规定行事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。“两国经济的依存程度”指两国经济相互依赖的程度，符合“依存”的定义。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是人的心理活动，不能用来描述国家经济之间的依赖程度。"}, {"text": "叹气", "is_correct": false, "explanation": "配价：“叹气”是不及物动词，不能带“程度”这类修饰语，说“叹气程度”不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是体育活动，与经济依赖无关，句子语义不通。"}], "explanations": {"依存": "正确。“两国经济的依存程度”指两国经济相互依赖的程度，符合“依存”的定义。", "嫉妒": "语义：“嫉妒”是人的心理活动，不能用来描述国家经济之间的依赖程度。", "叹气": "配价：“叹气”是不及物动词，不能带“程度”这类修饰语，说“叹气程度”不通。", "游泳": "语义：“游泳”是体育活动，与经济依赖无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们两人依存在一起聊天，很开心。", "explanation": "这里应该用〈交谈〉（聊天）。依存表示生存上相互依赖，不用于描述闲聊的愉快。"}, {"text": "他全部的希望依存于孩子身上。", "explanation": "这里应该用〈寄托〉（寄托在孩子身上）。依存表示生存上离不开，不表示把希望交付给别人。"}, {"text": "孩子依存了奶奶照看，我们放心出门了。", "explanation": "这里应该用〈托付〉（托付给奶奶照看）。依存后接人须用“于”，且不表示把孩子交给别人照看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国的经济互相依存在。", "corrected_sentence": "两国的经济互相依存。", "error_description": "多出“在”：“依存”后不能接“在”，应说“互相依存”；表示依赖的对象才用“于”，如“依存于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个物种依存彼此而生存。", "corrected_sentence": "这两个物种依存于彼此而生存。", "error_description": "错误：“依存”带对象时要用“于”引出，此处“依存彼此”应为“依存于彼此”；但“互相依存”“彼此依存”本身不带宾语，不需要“于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "正确。“忽视”与“注重”意思相反，指不予重视。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指闲逛，与重视或忽视没有关系。"}, {"text": "烧水", "is_correct": false, "explanation": "无关：“烧水”指加热水，与重视或忽视没有关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”指发出歌声，与重视或忽视没有关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "正确。“忽视”与“注重”意思相反，指不予重视。", "散步": "无关：“散步”指闲逛，与重视或忽视没有关系。", "烧水": "无关：“烧水”指加热水，与重视或忽视没有关系。", "唱歌": "无关：“唱歌”指发出歌声，与重视或忽视没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "正确。“忽视”与“注重”意思相反，指不予重视。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指收拾、理顺，与重视或忽视没有关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指搬动物品，与重视或忽视没有关系。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”指看，与重视或忽视没有关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "正确。“忽视”与“注重”意思相反，指不予重视。", "整理": "无关：“整理”指收拾、理顺，与重视或忽视没有关系。", "搬运": "无关：“搬运”指搬动物品，与重视或忽视没有关系。", "观看": "无关：“观看”指看，与重视或忽视没有关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指特别关注或重视某人或某事。", "primary_collocate": null, "pronunciation": "zhù zhòng", "ipa": "ʈʂu˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "人们更注重关系的建立与维系，而非严格遵循抽象的时间契约。", "target_word": "注重", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师很注重学习习惯。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们公司注重产品质量。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小就注重锻炼身体。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家学校不只注重成绩，也注重品德。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父母很注重孩子的教育。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做生意要注重信誉，不能骗人。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买东西时更注重价格，不太看牌子。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生一直注重病人的感受。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一向注重礼貌，见人先打招呼。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "注重了", "label": "体标"}, {"form": "注重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "注重：特别关注、重视某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f3f14-cd74-4703-8299-71abdc569da6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重关系的建立与维系”指把重心放在关系上，符合“特别关注、重视”的意思。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与句子强调关系本身的价值相反，句子语义不通。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指放弃，与“建立与维系”关系的语境相反。"}, {"text": "模仿", "is_correct": false, "explanation": "搭配：“模仿”的对象是行为或样子，不能说“模仿关系的建立与维系”。"}], "explanations": {"注重": "正确。“注重关系的建立与维系”指把重心放在关系上，符合“特别关注、重视”的意思。", "讨厌": "语义：“讨厌”表示厌恶，与句子强调关系本身的价值相反，句子语义不通。", "抛弃": "语义：“抛弃”指放弃，与“建立与维系”关系的语境相反。", "模仿": "搭配：“模仿”的对象是行为或样子，不能说“模仿关系的建立与维系”。"}, "sentence_index": 0, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过马路时，他注重了一下红绿灯。", "explanation": "这里应该用〈留意〉。注重指长期看重某方面，不能用于过马路时瞬间看一眼红绿灯的动作。"}, {"text": "走路时要注重一下台阶，别摔倒。", "explanation": "这里应该用〈当心〉。提醒别人小心脚下要说“当心”；注重指长期看重，不用于这种短暂的提醒。"}, {"text": "他注重窗外下雨了，忘了收衣服。", "explanation": "这里应该用〈留意〉（留意到窗外下雨）。注重表示长期看重某方面，不表示瞬间注意到外界的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重信誉”指特别看重信誉，与“不能骗人”的语境一致。"}, {"text": "欺骗", "is_correct": false, "explanation": "搭配：“欺骗”的对象是人，不能说“欺骗信誉”。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”指失去某物，与“做生意要”的积极要求相反，句子语义不通。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表示不满，不能用来描述做生意时对信誉的态度，句子不通。"}], "explanations": {"注重": "正确。“注重信誉”指特别看重信誉，与“不能骗人”的语境一致。", "欺骗": "搭配：“欺骗”的对象是人，不能说“欺骗信誉”。", "丢失": "语义：“丢失”指失去某物，与“做生意要”的积极要求相反，句子语义不通。", "抱怨": "语义：“抱怨”表示不满，不能用来描述做生意时对信誉的态度，句子不通。"}, "sentence_index": 6, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直注重窗外的鸟飞走了，忘了上课。", "explanation": "这里应该用〈发现〉（发现鸟飞走了）。注重表示看重某事，不能用来表示察觉某个动作已经发生。"}, {"text": "他注重了这道数学题一下，就想出了答案。", "explanation": "这里应该用〈看〉（看了一下这道数学题）。注重表示长期看重，不用于短暂地看一眼。"}, {"text": "他常常注重看星空，直到深夜。", "explanation": "这里应该用〈仰望〉。注重是看重某方面，不能直接带“看”这类动作动词表示抬头观看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司一直注重了产品的质量。", "corrected_sentence": "这家公司一直注重产品的质量。", "error_description": "“了”与“一直”表示的持续状态不宜搭配，应去掉“了”，说“一直注重产品的质量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师了注重礼貌。", "corrected_sentence": "这位老师很注重礼貌。", "error_description": "语序错误：“了”是动态助词，不能放在动词“注重”之前；程度副词“很”应放在动词前修饰它，说“这位老师很注重礼貌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7aa4f8e-1625-4992-b8d3-2a8d93671f30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "反义：「抽象」指不具体、脱离实际，「具体」指可以感知、落到实处，二者是反义词。"}, {"text": "柔软", "is_correct": false, "explanation": "「柔软」形容质地不硬，与「抽象」没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "「明亮」形容光线或颜色，与「抽象」没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "「迅速」形容速度快，与「抽象」没有反义关系。"}], "correct_answer": "具体", "explanations": {"具体": "反义：「抽象」指不具体、脱离实际，「具体」指可以感知、落到实处，二者是反义词。", "柔软": "「柔软」形容质地不硬，与「抽象」没有反义关系。", "明亮": "「明亮」形容光线或颜色，与「抽象」没有反义关系。", "迅速": "「迅速」形容速度快，与「抽象」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "反义：「抽象」指不具体、脱离实际，「具体」指可以感知、落到实处，二者是反义词。"}, {"text": "沉重", "is_correct": false, "explanation": "「沉重」形容分量大或心情压抑，与「抽象」没有反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "「清脆」形容声音清亮爽利，与「抽象」没有反义关系。"}, {"text": "宽阔", "is_correct": false, "explanation": "「宽阔」形容空间或面积大，与「抽象」没有反义关系。"}], "correct_answer": "具体", "explanations": {"具体": "反义：「抽象」指不具体、脱离实际，「具体」指可以感知、落到实处，二者是反义词。", "沉重": "「沉重」形容分量大或心情压抑，与「抽象」没有反义关系。", "清脆": "「清脆」形容声音清亮爽利，与「抽象」没有反义关系。", "宽阔": "「宽阔」形容空间或面积大，与「抽象」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指概念、理论、想法等不具体、脱离实际事物，难以理解。", "primary_collocate": null, "pronunciation": "chōu xiàng", "ipa": "ʈʂʰou˥ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "人们更注重关系的建立与维系，而非严格遵循抽象的时间契约。", "target_word": "抽象", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "它在微观层面演示了可持续生活的可行性，将抽象的环保理念转化为每日可操作的仪式。", "target_word": "抽象", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个概念太抽象了，我听不懂。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片解释抽象的数学问题。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一理论过于抽象，多数读者难以理解。", "target_word": "抽象", "complexity_tier": "T3", "furigana": "chōuxiàng", "sentence_source": "generated"}, {"text": "爱和自由都是抽象的概念。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请举一个例子，别说得这么抽象。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子还小，很难理解抽象的道理。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽象的理论需要用例子来说明。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢用抽象的词说话，大家都不明白。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽象化", "label": "复合"}, {"form": "抽象思维", "label": "复合"}], "register": "书面语", "sense_fingerprint": "概念、理论等不具体、脱离实际事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba713f93-d7fe-4309-b531-8a7d0486cb5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "正确：「抽象的时间契约」指不落到具体安排上的约定，与前文“注重关系”形成对比，符合语境。"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：「湿润」描述物体或空气的状态，不能修饰“时间契约”。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：「瘦小」形容人或物的体形，用来修饰“时间契约”句意不通。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：「高兴」表示情绪，不能用来描述一份契约的性质。"}], "explanations": {"抽象": "正确：「抽象的时间契约」指不落到具体安排上的约定，与前文“注重关系”形成对比，符合语境。", "湿润": "搭配：「湿润」描述物体或空气的状态，不能修饰“时间契约”。", "瘦小": "体貌：「瘦小」形容人或物的体形，用来修饰“时间契约”句意不通。", "高兴": "语义：「高兴」表示情绪，不能用来描述一份契约的性质。"}, "sentence_index": 0, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的零件很抽象，工人要花很久才能装好。", "explanation": "这里应该用〈复杂〉。抽象指概念、理论不具体，机器零件是看得见的实物，形容它们结构多、难装要说复杂。"}, {"text": "这份申请表很抽象，要填十几页，每页都要签字。", "explanation": "这里应该用〈繁琐〉。抽象指概念、理论不具体，申请表是具体的表格，形容手续多、填写麻烦要说繁琐。"}, {"text": "这张木桌很抽象，四条腿都很结实。", "explanation": "这里应该用〈朴素〉。抽象指看不见的概念、理论，木桌是有形的实物，形容它造型简单、不加装饰要说朴素。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "正确：「别说得这么抽象」指说话的方式不具体，与前句“请举一个例子”的要求相呼应。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：「宽敞」形容空间大，不能用来形容说话的方式。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材或体积，用来修饰说话方式句意不通。"}, {"text": "湿冷", "is_correct": false, "explanation": "语义：「湿冷」描述天气或身体的感受，与说话的方式无关。"}], "explanations": {"抽象": "正确：「别说得这么抽象」指说话的方式不具体，与前句“请举一个例子”的要求相呼应。", "宽敞": "搭配：「宽敞」形容空间大，不能用来形容说话的方式。", "高大": "体貌：「高大」形容身材或体积，用来修饰说话方式句意不通。", "湿冷": "语义：「湿冷」描述天气或身体的感受，与说话的方式无关。"}, "sentence_index": 6, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很抽象，喝起来太咸了。", "explanation": "这里应该用〈咸〉。抽象指不具体、脱离实物的概念，汤是可以品尝的实物，形容味道过重要说咸。"}, {"text": "这匹马很抽象，跑起来又快又稳。", "explanation": "这里应该用〈矫健〉。抽象指不具体、难以看清，马是有形的动物，形容跑得快而稳要说矫健。"}, {"text": "这份报告的数据很抽象，每一项都标注了具体金额。", "explanation": "这里应该用〈精确〉。抽象指脱离具体事物，句中每一项都标注了具体金额，形容数据的确切程度要说精确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个概念很抽象化，初学者不容易理解。", "corrected_sentence": "这个概念很抽象，初学者不容易理解。", "error_description": "“抽象”是形容词，可直接受“很”修饰，应说“很抽象”。“抽象化”是动词，不能再接“很”，说“很抽象化”是错误用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个概念讲很抽象，学生都听不懂。", "corrected_sentence": "他把这个概念讲得很抽象，学生都听不懂。", "error_description": "错误形式是“讲很抽象”，正确形式是“讲得很抽象”。动词与补语之间要用“得”连接，不能直接接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1697b85-2e0f-4e53-8d0e-b40ae68bea44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。"}, {"text": "信任", "is_correct": false, "explanation": "“信任”指相信对方可靠，与“误解”不构成反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指自然现象，与“误解”没有反义关系。"}, {"text": "友谊", "is_correct": false, "explanation": "“友谊”指朋友之间的情感，与“误解”不构成反义关系。"}], "correct_answer": "理解", "explanations": {"理解": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。", "信任": "“信任”指相信对方可靠，与“误解”不构成反义关系。", "天气": "“天气”指自然现象，与“误解”没有反义关系。", "友谊": "“友谊”指朋友之间的情感，与“误解”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。"}, {"text": "历史", "is_correct": false, "explanation": "“历史”指过去发生的事情，与“误解”没有反义关系。"}, {"text": "礼貌", "is_correct": false, "explanation": "“礼貌”指待人有礼节，与“误解”不构成反义关系。"}, {"text": "爱好", "is_correct": false, "explanation": "“爱好”指喜欢做的事，与“误解”没有反义关系。"}], "correct_answer": "理解", "explanations": {"理解": "正确。“误解”与“理解”构成反义：误解是想错，理解是正确领会。", "历史": "“历史”指过去发生的事情，与“误解”没有反义关系。", "礼貌": "“礼貌”指待人有礼节，与“误解”不构成反义关系。", "爱好": "“爱好”指喜欢做的事，与“误解”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对别人的言行或事情真相产生错误的理解或判断。", "primary_collocate": null, "pronunciation": "wù jiě", "ipa": "wu˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种差异，在跨国合作中常引发误解：一方视对方为不负责任，另一方则认为前者冷酷机械。", "target_word": "误解", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他们沟通不够，所以产生了误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们见面谈一谈，就能消除这个误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个误解让两个朋友很长时间不说话。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的一句话造成了很大的误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师解释了半天，终于澄清了这个误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为语言不同，他们之间常有误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对不起，这是一场误解，我没有生气。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国领导人见面，是为了减少误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你听我解释，这只是个小误解。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "場", "label": "量词"}, {"form": "誤解", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：对他人言行或事实真相的错误理解，如产生误解、消除误解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确答案。误解指对别人的言行或事情真相产生错误的理解。"}, {"text": "无解", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。"}, {"text": "误写", "is_correct": false, "explanation": "xiě 与 jiě 声母不同（x 与 j），意思是写错。"}, {"text": "无界", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有界限。"}], "explanations": {"误解": "正确答案。误解指对别人的言行或事情真相产生错误的理解。", "无解": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。", "误写": "xiě 与 jiě 声母不同（x 与 j），意思是写错。", "无界": "wú（第二声）与 wù（第四声）声调不同，意思是没有界限。"}, "sentence_index": null, "correct_answer": "误解"}, "level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。“引发误解”符合上句：双方对同一差异作出相反判断，属于错误理解。"}, {"text": "赞扬", "is_correct": false, "explanation": "语义：“赞扬”是正面评价，与“一方视对方为不负责任”的负面判断相冲突。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“引发”多接事件、矛盾或情绪，“友谊”通常说“增进”或“加深”，不说“引发友谊”。"}, {"text": "灵感", "is_correct": false, "explanation": "语义：“灵感”指创作中的突发想法，与双方因差异产生的负面判断无关，放入句子不通。"}], "explanations": {"误解": "正确。“引发误解”符合上句：双方对同一差异作出相反判断，属于错误理解。", "赞扬": "语义：“赞扬”是正面评价，与“一方视对方为不负责任”的负面判断相冲突。", "友谊": "搭配：“引发”多接事件、矛盾或情绪，“友谊”通常说“增进”或“加深”，不说“引发友谊”。", "灵感": "语义：“灵感”指创作中的突发想法，与双方因差异产生的负面判断无关，放入句子不通。"}, "sentence_index": 0, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台仪器的测量误解很小，结果很可靠。", "explanation": "这里应该用〈误差〉。误差指测量或计算结果与真实数值的偏离，可以描述仪器数据；“误解”指对别人言行的错误理解，不能用来形容测量结果。"}, {"text": "这则广告误解了很多顾客，许多人都上了当。", "explanation": "这里应该用〈误导〉。误导指使人产生错误认识，主语可以是广告、宣传；“误解”指当事人自己把言行或事实想错，广告不能误解顾客。"}, {"text": "司机误解了一只猫，差点把它撞伤。", "explanation": "这里应该用〈误伤〉。误伤指不慎伤害到人或动物，是行为上的伤害；“误解”的对象是人的言行或事情真相，不能用于猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。语言不同容易造成误解。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指身体的轻重，不能说“之间常有体重”。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“之间常有”多接关系或情感，不接“礼物”。"}, {"text": "美食", "is_correct": false, "explanation": "搭配：“之间常有”不接“美食”这类可以具体享用的事物。"}], "explanations": {"误解": "正确。语言不同容易造成误解。", "体重": "搭配：“体重”指身体的轻重，不能说“之间常有体重”。", "礼物": "搭配：“之间常有”多接关系或情感，不接“礼物”。", "美食": "搭配：“之间常有”不接“美食”这类可以具体享用的事物。"}, "sentence_index": 6, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他误解了一面墙，撞得额头都红了。", "explanation": "这里应该用〈误撞〉。误撞指不小心撞到，是动作上的失误；“误解”针对言语或事情真相，不能用于墙。"}, {"text": "他误解了那个路口，车一直开到了河边。", "explanation": "这里应该用〈认错〉。认错指把地点或人辨认错了；“误解”针对言语或事情的理解，不能用于路口。"}, {"text": "孩子误解了一颗糖，吃下去闹了肚子。", "explanation": "这里应该用〈误食〉。误食指吃错东西，是行为上的失误；“误解”针对言语或事情的理解，不能用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "只要双方坐下来说清楚，误解地就能消除。", "corrected_sentence": "只要双方坐下来说清楚，误解就能消除。", "error_description": "结构助词错误：“误解”是名词，后面不能加结构助词“地”（“地”用于修饰动词或形容词前）。应写成“误解就能消除”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们之间有一只误解，现在已经消除了。", "corrected_sentence": "我们之间有一个误解，现在已经消除了。", "error_description": "量词错误：“误解”的量词应用“个”。“只”用于动物或成对器官中的一个，不能用于“误解”。应写成“一个误解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负责任", "is_correct": true, "explanation": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物美观，与“不负责任”没有反义关系。"}, {"text": "冷静", "is_correct": false, "explanation": "“冷静”指情绪稳定，不是“不负责任”的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”指待人积极友好，与“不负责任”不构成反义关系。"}], "correct_answer": "负责任", "explanations": {"负责任": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。", "漂亮": "“漂亮”形容外貌或事物美观，与“不负责任”没有反义关系。", "冷静": "“冷静”指情绪稳定，不是“不负责任”的反义词。", "热情": "“热情”指待人积极友好，与“不负责任”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负责任", "is_correct": true, "explanation": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“不负责任”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指智力或反应快，与“不负责任”不构成反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "“辛苦”指劳累，与“不负责任”没有反义关系。"}], "correct_answer": "负责任", "explanations": {"负责任": "正确。“不负责任”与“负责任”构成反义：一个指不尽责，一个指尽责。", "高兴": "“高兴”形容心情愉快，与“不负责任”没有反义关系。", "聪明": "“聪明”指智力或反应快，与“不负责任”不构成反义关系。", "辛苦": "“辛苦”指劳累，与“不负责任”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容一个人做事马虎，不愿意为自己的行为或承诺承担应有的责任。", "primary_collocate": null, "pronunciation": "bù fù zé rèn", "ipa": "pu˥˩ fu˥˩ tsɤ˧˥ ɻən˥˩", "syllable_count": 4, "sentences": [{"text": "这种差异，在跨国合作中常引发误解：一方视对方为不负责任，另一方则认为前者冷酷机械。", "target_word": "不负责任", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他总是迟到，是个不负责任的人。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把孩子一个人留在家里，太不负责任了。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事马虎，对工作不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不认真检查就交给客户，这样做很不负责任。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应帮我改报告，结果一天都没动，真是不负责任。", "target_word": "不负责任", "complexity_tier": "T3", "furigana": "tā dāyìng bāng wǒ gǎi bàogào, jiéguǒ yì tiān dōu méi dòng, zhēnshi bù fù zé rèn.", "sentence_source": "generated"}, {"text": "说好了要帮忙，却突然不来，真不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不负责任的话让大家很生气。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机喝了酒还开车，这种做法不负责任。", "target_word": "不负责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，丢下工作就走是不负责任的行为。", "target_word": "不负责任", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不負責任", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容词：做事马虎，不肯为自己的行为或承诺负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不负责任", "is_correct": true, "explanation": "正确。“视对方为不负责任”表达一方对对方做事态度的负面判断，与误解的语境相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：“潮湿”形容空气或物体含水分多，不用来评价人的做事态度或品性。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势或坡度很大，不用来形容人的态度或品性。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音粗涩，不用来形容人的态度或品性。"}], "explanations": {"不负责任": "正确。“视对方为不负责任”表达一方对对方做事态度的负面判断，与误解的语境相符。", "潮湿": "搭配：“潮湿”形容空气或物体含水分多，不用来评价人的做事态度或品性。", "陡峭": "搭配：“陡峭”形容地势或坡度很大，不用来形容人的态度或品性。", "沙哑": "搭配：“沙哑”形容声音粗涩，不用来形容人的态度或品性。"}, "sentence_index": 0, "correct_answer": "不负责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师对学生很不负责任，要求很高。", "explanation": "这里应该用〈严厉〉。严厉形容对人要求高、态度严肃；“不负责任”形容做事不尽责，二者不能替换。"}, {"text": "这位店员对顾客很不负责任，总是笑着接待。", "explanation": "这里应该用〈热情〉。热情形容待人友好、积极；“不负责任”指对工作不尽责，与“笑着接待”的语境矛盾。"}, {"text": "这位医生做事很不负责任，每个病人都仔细检查。", "explanation": "这里应该用〈认真〉。认真形容做事专心细致；“不负责任”是贬义，与“仔细检查”的语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不负责任", "is_correct": true, "explanation": "正确。“说好了要帮忙，却突然不来”正是对做事不尽责的批评，“真不负责任”语气连贯。"}, {"text": "体贴", "is_correct": false, "explanation": "语义：“体贴”是称赞，与“却突然不来”的指责语气相矛盾。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”是积极情绪，与“说好了却突然不来”的语境不合。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或事物惹人喜爱，与“却突然不来”的指责语气不合。"}], "explanations": {"不负责任": "正确。“说好了要帮忙，却突然不来”正是对做事不尽责的批评，“真不负责任”语气连贯。", "体贴": "语义：“体贴”是称赞，与“却突然不来”的指责语气相矛盾。", "高兴": "语义：“高兴”是积极情绪，与“说好了却突然不来”的语境不合。", "可爱": "语义：“可爱”形容人或事物惹人喜爱，与“却突然不来”的指责语气不合。"}, "sentence_index": 6, "correct_answer": "不负责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消防员遇到危险很不负责任，马上冲了上去。", "explanation": "这里应该用〈勇敢〉。勇敢形容不怕危险、敢于面对；“不负责任”指对事情不尽责，与“马上冲上去”的语境不符。"}, {"text": "妈妈对我很不负责任，每天都细心照顾我。", "explanation": "这里应该用〈温柔〉。温柔形容对人态度柔和；“不负责任”是批评做事态度，与“细心照顾”的语境矛盾。"}, {"text": "他对同学很不负责任，从不炫耀自己。", "explanation": "这里应该用〈谦虚〉。谦虚形容不自满、不夸耀；“不负责任”是贬义评价，与“从不炫耀”的品行描述不一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个不负责任地司机让大家很生气。", "corrected_sentence": "那个不负责任的司机让大家很生气。", "error_description": "结构助词错误：“不负责任”修饰名词“司机”，应用“的”，写成“不负责任的司机”。“地”用于修饰动词，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工作做很不负责任，结果客户很不满意。", "corrected_sentence": "他工作做得很不负责任，结果客户很不满意。", "error_description": "补语标记错误：动词后带程度补语，要用“得”引出，应写成“做得很不负责任”。“做很不负责任”缺少“得”，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
