INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指相对的两个方面中的另外一方，常用于法律、合同、对立关系等语境。", "primary_collocate": null, "pronunciation": "lìng yī fāng", "ipa": "liŋ˥˩ i˥ faŋ˥", "syllable_count": 3, "sentences": [{"text": "这种差异，在跨国合作中常引发误解：一方视对方为不负责任，另一方则认为前者冷酷机械。", "target_word": "另一方", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "合同上写着，另一方必须按时付款。", "target_word": "另一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方不同意，另一方也不能签字。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官先听了一方，再听另一方的话。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "双方签合同时，另一方要求加一条。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一方交货，另一方付钱，这是买卖的规矩。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谈判中，一方让了步，另一方却不满意。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离婚时，一方想要孩子，另一方也想要。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一方违反了合同，另一方可以要求赔偿。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场官司，原告说完了，轮到另一方发言了。", "target_word": "另一方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：相对两方中的另一方，多用于合同、法律、谈判等对立关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524b76e-1a79-47e4-a085-bd4ad66e3a29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另一方", "is_correct": true, "explanation": "与前文的“一方”相对，指另外一方，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘坐交通工具的人，与跨国合作中相对的另一方无关，放入句中不通。"}, {"text": "双方", "is_correct": false, "explanation": "语义：“双方”已包括前文的“一方”，不能与“一方”并列对举。"}, {"text": "对家", "is_correct": false, "explanation": "语域：“对家”多用于牌局、游戏等口语语境，与这段书面的合作叙述不合。"}], "explanations": {"另一方": "与前文的“一方”相对，指另外一方，符合句意。", "乘客": "语义：“乘客”指乘坐交通工具的人，与跨国合作中相对的另一方无关，放入句中不通。", "双方": "语义：“双方”已包括前文的“一方”，不能与“一方”并列对举。", "对家": "语域：“对家”多用于牌局、游戏等口语语境，与这段书面的合作叙述不合。"}, "sentence_index": 0, "correct_answer": "另一方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有两个朋友，另一方在北京工作。", "explanation": "这里应该用〈另一个〉。“另一方”指相对的两方中的一方，多用于对立的双方，不用来指两个一般的朋友。"}, {"text": "他左手拿着书，另一方拿着笔。", "explanation": "这里应该用〈另一只手〉。“另一方”指相对的两方中的人或团体，不用来指身体的另一侧。"}, {"text": "他同时收到两封信，另一方写得很短。", "explanation": "这里应该用〈另一封〉。“另一方”指相对的两方中的人或团体，不用来指信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另一方", "is_correct": true, "explanation": "与前文让了步的“一方”相对，指另外一方，符合句意。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”只是旁观的人，不是谈判中的当事一方，不能与“一方让了步”对举。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”只负责传达话语，不是谈判的当事一方，与句中的对峙关系不合。"}, {"text": "冤家", "is_correct": false, "explanation": "语域：“冤家”是口语词，多指冤仇对头或亲昵的人，与书面的谈判叙述不合。"}], "explanations": {"另一方": "与前文让了步的“一方”相对，指另外一方，符合句意。", "观众": "语义：“观众”只是旁观的人，不是谈判中的当事一方，不能与“一方让了步”对举。", "翻译": "语义：“翻译”只负责传达话语，不是谈判的当事一方，与句中的对峙关系不合。", "冤家": "语域：“冤家”是口语词，多指冤仇对头或亲昵的人，与书面的谈判叙述不合。"}, "sentence_index": 6, "correct_answer": "另一方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕我吃了一半，另一方留给你。", "explanation": "这里应该用〈另一半〉。“另一方”指相对的两方中的人或团体，不指同一样东西的另一部分。"}, {"text": "这张纸的另一方写满了字。", "explanation": "这里应该用〈另一面〉。“另一方”指相对的两方中的人或团体，不用来指纸张的一面。"}, {"text": "我白天在公司上班，另一方的时间我在家学习。", "explanation": "这里应该用〈另一段时间〉。“另一方”指相对的两方中的人或团体，不指一天之中的时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谈判破裂后，一个另一方选择了起诉。", "corrected_sentence": "谈判破裂后，另一方选择了起诉。", "error_description": "数量词重复：“另一方”本身已含“另一”，前面不能再加“一个”。应直接说“另一方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议上，双方各执一词，另一方地却保持沉默。", "corrected_sentence": "会议上，双方各执一词，另一方却保持沉默。", "error_description": "结构助词错误：“另一方”是名词，名词后不加“地”（“地”用于修饰动词、形容词）。应写成“另一方却保持沉默”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11035, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温柔", "is_correct": true, "explanation": "温柔与“冷酷”构成反义，形容性情或声音柔和，与冷硬相对。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆形容声音清亮利落，与“冷酷”不构成反义。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮形容声音大而清晰，与“冷酷”不构成反义。"}, {"text": "沙哑", "is_correct": false, "explanation": "沙哑形容声音粗涩，与“冷酷”不构成反义。"}], "correct_answer": "温柔", "explanations": {"温柔": "温柔与“冷酷”构成反义，形容性情或声音柔和，与冷硬相对。", "清脆": "清脆形容声音清亮利落，与“冷酷”不构成反义。", "响亮": "响亮形容声音大而清晰，与“冷酷”不构成反义。", "沙哑": "沙哑形容声音粗涩，与“冷酷”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (11035, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和与“冷酷”相对，形容态度平和、不苛刻，构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与“冷酷”不构成反义。"}, {"text": "松软", "is_correct": false, "explanation": "松软形容质地柔软，与“冷酷”不构成反义。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，与“冷酷”不构成反义。"}], "correct_answer": "温和", "explanations": {"温和": "温和与“冷酷”相对，形容态度平和、不苛刻，构成反义。", "明亮": "明亮形容光线或颜色，与“冷酷”不构成反义。", "松软": "松软形容质地柔软，与“冷酷”不构成反义。", "整齐": "整齐形容排列有序，与“冷酷”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4de3497-1c82-451f-b029-dd10cdee55f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
